			name = "Vale das Provações",
			short = "O Vale das Provações fica cercado de paredões no sul de Durotar, uma bacia de terra calcinada onde todo jovem orc começa a vida que a Horda lhe reservou.",
			full = "O Vale das Provações fica cercado de paredões no sul de Durotar, uma bacia de terra calcinada onde todo jovem orc começa a vida que a Horda lhe reservou. Os que fracassam não são carregados para fora. São deixados onde caem, para torrar ao sol até que o deserto termine o que a provação começou.\n\nNo coração do vale fica O Covil, uma caverna aberta na encosta do penhasco e equipada com os confortos simples de uma vida dedicada ao serviço. Anciãos cuidam dele, ensinando aos jovens suas vocações e encaminhando-os a suas provas.\n\nAo norte, uma modesta sequência de cavernas naturais ficava vazia nos penhascos. Desde então, algo se infiltrou nelas. Demônios da Lâmina Ardente agora se aninham ali, espalhando-se pelo próprio vale, e sua presença deu peso a velhos boatos de que o Conselho das Sombras encontrou algum apoio na região. Os demônios são fracos, mas não ficam em suas cavernas, e a mácula que carregam começou a se espalhar para além da pedra que antes a continha.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Trials",
		},
	},
	-- Mulgore: 18 subzones
	[1412] = {
		["baeldun digsite"] = {
			name = "Sítio de Escavação de Bael'Dun",
			short = "A expedição de Bael'Dun abriu sua pedreira no limite oeste de Mulgore, cravando picaretas na encosta da montanha.",
			full = "A expedição de Bael'Dun abriu sua pedreira no limite oeste de Mulgore, cravando picaretas na encosta da montanha. Sua escavação foi declarada uma afronta à Mãe Terra e, quando as palavras não bastaram para fazê-los recuar, a tribo Casco Sangrento tomou e quebrou as ferramentas dos invasores para expulsá-los.\n\nOs anões continuaram a cavar mesmo assim, ignorando os avisos recebidos, e seu trabalho imprudente despertou a ira dos espíritos da terra. A pedreira continua lá, uma cicatriz aberta no solo de Mulgore.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Digsite",
		},
		["bloodhoof village"] = {
			name = "Aldeia Casco Sangrento",
			short = "A Aldeia Casco Sangrento fica junto às águas do Lago da Ferradura, nas planícies de Mulgore, e leva o nome da tribo que a chama de lar.",
			full = "A Aldeia Casco Sangrento fica junto às águas do Lago da Ferradura, nas planícies de Mulgore, e leva o nome da tribo que a chama de lar. Aqui os kodos selvagens das planícies são domados e treinados até ficarem calmos o bastante para levar um cavaleiro, e a aldeia é conhecida por esse trabalho tanto quanto por qualquer outra coisa.\n\nBaine Casco Sangrento zela pela aldeia, cuidando de sua proteção. Zarlman Duas Luas cuida da vida espiritual da tribo Casco Sangrento, o ancião que fala pelos ancestrais e pela Mãe Terra para os que vivem ali e os que estão de passagem.",
			source = "https://warcraft.wiki.gg/wiki/Bloodhoof_Village",
		},
		["brambleblade ravine"] = {
			name = "Ravina da Lâmina Espinhenta",
			short = "A Ravina da Lâmina Espinhenta corta o limite nordeste da Chapada Nuvem Vermelha, lar dos javaturnos Bristleback.",
			full = "A Ravina da Lâmina Espinhenta corta o limite nordeste da Chapada Nuvem Vermelha, lar dos javaturnos Bristleback. No fundo da ravina, numa grande cabana, vive seu chefe, Sharptusk Thornmantle, cuja liderança atraiu ataques dos taurens destinados a acabar com os saques dos javaturnos na origem.",
			source = "https://warcraft.wiki.gg/wiki/Brambleblade_Ravine",
		},
		["camp narache"] = {
			name = "Aldeia Narache",
			short = "A Aldeia Narache fica no limite norte da Chapada Nuvem Vermelha, um pequeno círculo de tendas pertencente à tribo Vento do Falcão, no sul de Mulgore.",
			full = "A Aldeia Narache fica no limite norte da Chapada Nuvem Vermelha, um pequeno círculo de tendas pertencente à tribo Vento do Falcão, no sul de Mulgore. Bravos feridos descansam na tenda principal e, em torno do centro da aldeia, os instrutores da tribo formam um círculo silencioso, prestando suas homenagens à Grande Mãe Vento do Falcão.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Narache",
		},
		["golden plains"] = {
			name = "Planícies Douradas",
			short = "As Planícies Douradas, uma bacia de capim verde ondulante a sudeste do Penhasco do Trovão, são estimadas na terra natal dos taurens e valorizadas como território de caça.",
			full = "As Planícies Douradas, uma bacia de capim verde ondulante a sudeste do Penhasco do Trovão, são estimadas na terra natal dos taurens e valorizadas como território de caça. Grandes manadas de kodos se reúnem aqui para pastar e, em algum lugar no capim, dizem, a famosa Arra'chea faz sua morada.",
			source = "https://warcraft.wiki.gg/wiki/Golden_Plains",
		},
		["kodo rock"] = {
			name = "Rocha dos Kodos",
			short = "A Rocha dos Kodos se ergue discretamente entre a Aldeia Narache e a Ravina da Lâmina Espinhenta, fácil de passar despercebida a menos que se esteja prestando muita atenção, pois só pode ser vista de perto.",
			full = "A Rocha dos Kodos se ergue discretamente entre a Aldeia Narache e a Ravina da Lâmina Espinhenta, fácil de passar despercebida a menos que se esteja prestando muita atenção, pois só pode ser vista de perto.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Rock",
		},
		["palemane rock"] = {
			name = "Rochedo Jubalba",
			short = "O Rochedo Jubalba é uma caverna escavada fundo na encosta da montanha no oeste de Mulgore, lar dos gnolls da tribo Jubalba.",
			full = "O Rochedo Jubalba é uma caverna escavada fundo na encosta da montanha no oeste de Mulgore, lar dos gnolls da tribo Jubalba. Eles ocupam tanto a caverna quanto um acampamento do lado de fora, e partem rapidamente para a violência, atacando qualquer um que se aproxime demais de seu território.",
			source = "https://warcraft.wiki.gg/wiki/Palemane_Rock",
		},
		["ravaged caravan"] = {
			name = "Caravana Devastada",
			short = "Na margem nordeste do Lago da Ferradura ardem os destroços de uma caravana da Empreendimentos S.A., que ainda lançam fumaça negra no céu de Mulgore.",
			full = "Na margem nordeste do Lago da Ferradura ardem os destroços de uma caravana da Empreendimentos S.A., que ainda lançam fumaça negra no céu de Mulgore. Ela transportava suprimentos para a mineração do Supervisor Geringonça quando os taurens, cansados de goblins circulando por suas terras, caíram sobre ela.\n\nOs sobreviventes nunca abandonaram os destroços. Ainda ocupam o monte fumegante e sua carga chamuscada, repelindo qualquer um que se aproxime.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Caravan",
		},
		["red cloud mesa"] = {
			name = "Chapada Nuvem Vermelha",
			short = "A Chapada Nuvem Vermelha é uma extensão de planícies onduladas no alto dos penhascos do sul de Mulgore, conhecida por sua beleza tranquila e aberta.",
			full = "A Chapada Nuvem Vermelha é uma extensão de planícies onduladas no alto dos penhascos do sul de Mulgore, conhecida por sua beleza tranquila e aberta. É aqui que os jovens taurens provam seu valor, pegando em armas contra os javaturnos Bristleback, que ocupam a Ravina da Lâmina Espinhenta a nordeste.\n\nA Aldeia Narache, no noroeste da chapada, é o último terreno seguro da chapada. Do cemitério a oeste da aldeia, uma trilha sobe até o topo da Chapada Vista-longa.",
			source = "https://warcraft.wiki.gg/wiki/Red_Cloud_Mesa",
		},
		["red rocks"] = {
			name = "Rochedo Vermelho",
			short = "O arenito vermelho do Rochedo Vermelho se ergue no nordeste de Mulgore, um lugar onde o mundo do Penhasco do Trovão fica para trás e algo mais silencioso toma seu lugar.",
			full = "O arenito vermelho do Rochedo Vermelho se ergue no nordeste de Mulgore, um lugar onde o mundo do Penhasco do Trovão fica para trás e algo mais silencioso toma seu lugar. Aqui os taurens entregam seus mortos honrados à Mãe Terra e ao Pai Céu pela chama purificadora. Nem todo tauren caído é trazido para cá; somente os mais valorosos recebem este descanso, os guerreiros que fundaram e defenderam o Penhasco do Trovão, aqueles que deram a vida por suas tribos e seus chefes. É também para onde os jovens bravos vêm completar sua passagem para a vida adulta, de pé entre as pedras para ouvir as vozes de seus ancestrais no vento.\n\nA sacralidade do lugar não o manteve a salvo. Um bando de javaturnos Bristleback forçou a entrada no Rochedo Vermelho e profanou o solo sagrado com sua presença, um ato que despertou profunda raiva entre os taurens do Penhasco do Trovão, que prezam muito este lugar.",
			source = "https://warcraft.wiki.gg/wiki/Red_Rocks",
		},
		["rolling plains"] = {
			name = "Morros Ondulantes",
			short = "Os Morros Ondulantes se abrem ao sul da Aldeia Casco Sangrento, estendendo-se até a fronteira dos Sertões. Lobos e pumas se movem pelo capim ao lado de kodos e passadores.",
			full = "Os Morros Ondulantes se abrem ao sul da Aldeia Casco Sangrento, estendendo-se até a fronteira dos Sertões. Lobos e pumas se movem pelo capim ao lado de kodos e passadores.\n\nAo contrário do resto de Mulgore, as planícies não são isoladas: batedores centauros encontraram uma passagem por aqui e percorrem terras onde nenhum outro centauro pisa. Nos confins do leste, um ninho de harpias Ventofúria se instalou.",
			source = "https://warcraft.wiki.gg/wiki/Rolling_Plains",
		},
		["stonebull lake"] = {
			name = "Lago da Ferradura",
			short = "O Lago da Ferradura contorna a Aldeia Casco Sangrento por três lados, uma longa ferradura de água fresca. Suas águas fervilham de peixes, e linhas são lançadas nelas durante muitas horas tranquilas.",
			full = "O Lago da Ferradura contorna a Aldeia Casco Sangrento por três lados, uma longa ferradura de água fresca. Suas águas fervilham de peixes, e linhas são lançadas nelas durante muitas horas tranquilas. Onde o lago se estreita, uma ponte atravessa a passagem, levando a estrada que liga a Aldeia Casco Sangrento ao Penhasco do Trovão.",
			source = "https://warcraft.wiki.gg/wiki/Stonebull_Lake",
		},
		["thunderhorn water well"] = {
			name = "Poço Chifre Troante",
			short = "O poço fica no campo aberto de Mulgore, ao longo da estrada norte entre o Penhasco do Trovão e a Aldeia Casco Sangrento.",
			full = "O poço fica no campo aberto de Mulgore, ao longo da estrada norte entre o Penhasco do Trovão e a Aldeia Casco Sangrento. A Empreendimentos S.A. chegou a tomá-lo, na esperança de cortar a água dos taurens, mas os taurens a expulsaram e o recuperaram.",
			source = "https://warcraft.wiki.gg/wiki/Thunderhorn_Water_Well",
		},
		["venture co mine"] = {
			name = "Mina da Empreendimentos S.A.",
			short = "A mina penetra fundo nos penhascos do leste de Mulgore, com três entradas: o portão principal, a pé, uma face do penhasco e um pequeno acampamento madeireiro mais além.",
			full = "A mina penetra fundo nos penhascos do leste de Mulgore, com três entradas: o portão principal, a pé, uma face do penhasco e um pequeno acampamento madeireiro mais além. Ela não deveria estar ali. Os taurens negaram à Empreendimentos S.A. os direitos de mineração em sua terra natal, e a companhia simplesmente começou a cavar mesmo assim, com o Supervisor Geringonça à frente da operação e o conselho consultivo do Magnata Razdunk pressionando-o a se expandir ainda mais, para a extração de madeira, enviando novos retalhadores e matéria-prima para uma serraria que devoraria a madeira de Mulgore.\n\nOs taurens não deixaram a intrusão passar. Uma caravana de suprimentos de mineração que seguia sob escolta pela margem norte do Lago da Ferradura foi encontrada pelos Vanguardeiros, que caíram sobre ela e queimaram o que puderam, deixando os destroços para trás na suposição de que o fogo havia arruinado tudo o que valesse a pena levar. Não havia. Mais tarde, sucateiros da Empreendimentos S.A. foram vistos revirando as cinzas, recolhendo o que as chamas haviam poupado.\n\nEssa descoberta marcou a mina para a retaliação, um aviso desferido contra a operação de Geringonça pela recusa da companhia em deixar a terra dos taurens em paz.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Mine",
		},
		["wildmane water well"] = {
			name = "Poço Juba Agreste",
			short = "O Poço Juba Agreste fica ao norte do Penhasco do Trovão, o mais setentrional dos poços sagrados dos taurens. Harpias Ventofúria tomaram o terreno ao redor, e o poço está contaminado, à espera de purificação.",
			full = "O Poço Juba Agreste fica ao norte do Penhasco do Trovão, o mais setentrional dos poços sagrados dos taurens. Harpias Ventofúria tomaram o terreno ao redor, e o poço está contaminado, à espera de purificação.",
			source = "https://warcraft.wiki.gg/wiki/Wildmane_Water_Well",
		},
		["windfury ridge"] = {
			name = "Serra Ventofúria",
			short = "A Serra Ventofúria leva o nome das harpias que se aninham em suas alturas, criaturas ferozes que mergulham sobre qualquer um que se aproxime demais, matando ou carregando os desavisados.",
			full = "A Serra Ventofúria leva o nome das harpias que se aninham em suas alturas, criaturas ferozes que mergulham sobre qualquer um que se aproxime demais, matando ou carregando os desavisados. Pumas e lobos também rondam as colinas ao redor.\n\nAinda assim, as penas brilhantes das harpias são valorizadas pelos taurens do Penhasco do Trovão, que as usam em casamentos e banquetes.",
			source = "https://warcraft.wiki.gg/wiki/Windfury_Ridge",
		},
		["winterhoof water well"] = {
			name = "Poço Casco Invernal",
			short = "O Poço Casco Invernal fica na borda dos Morros Ondulantes, no sul de Mulgore. Anos depois da Terceira Guerra, a Empreendimentos S.A. o tomou e envenenou suas águas para cortar o abastecimento dos taurens.",
			full = "O Poço Casco Invernal fica na borda dos Morros Ondulantes, no sul de Mulgore. Anos depois da Terceira Guerra, a Empreendimentos S.A. o tomou e envenenou suas águas para cortar o abastecimento dos taurens. Mull Chifre Troante fabrica totens para purificar a contaminação, mas o poço ainda não está limpo.",
			source = "https://warcraft.wiki.gg/wiki/Winterhoof_Water_Well",
		},
	},
	-- Sertões: 31 subzones
	[1413] = {
		["agamagor"] = {
			name = "Agama'gor",
			short = "Agama'gor fica ao norte da estrada que segue para o oeste a partir do Acampamento Taurajo, um labirinto de espinheiros tomado pelos javaturnos Bristleback.",
			full = "Agama'gor fica ao norte da estrada que segue para o oeste a partir do Acampamento Taurajo, um labirinto de espinheiros tomado pelos javaturnos Bristleback. Seus mortos deixam para trás lascas de sangue seco, prendas que o exilado Mangletooth valoriza e pelas quais troca seus próprios favores estranhos.",
			source = "https://warcraft.wiki.gg/wiki/Agama'gor",
		},
		["bael modan"] = {
			name = "Bael Modan",
			short = "A fortaleza de pedra da Bastilha Bael'Dun se ergue onde antes ficava uma aldeia tauren Agulha de Pedra.",
			full = "A fortaleza de pedra da Bastilha Bael'Dun se ergue onde antes ficava uma aldeia tauren Agulha de Pedra. Sob ela, escavadores anões cavam em direção a um antigo complexo titânico, uma instalação de pesquisa soterrada desde antes de os próprios taurens pisarem neste chão, com suas relíquias ainda em grande parte intocadas na escuridão.\n\nOs anões chegaram com explosivos, detonando uma terra que a tribo Agulha de Pedra considerava sagrada. A escavação dilacerou a terra e, com ela, dilacerou os taurens: a maior parte da tribo foi morta ou dispersa das terras que guardara por gerações. Sua antiga aldeia hoje jaz revirada pelas máquinas escavadeiras dos anões. Gann Agulha de Pedra, que ainda percorre as estradas próximas, tentou resolver a questão como um chefe falando com outro, conversando em vez de lutar. Os anões não quiseram abrir mão da escavação. Ele trocou a diplomacia pela guerra, buscando qualquer força que pudesse encontrar para expulsá-los.",
			source = "https://warcraft.wiki.gg/wiki/Bael_Modan",
		},
		["baeldun keep"] = {
			name = "Bastilha Bael'Dun",
			short = "A Bastilha Bael'Dun se ergue acima do sítio de escavação de Bael Modan, no sul dos Sertões. O General Twinbraid a comanda, defendendo a bastilha e seus anões contra os taurens e orcs das planícies ao redor.",
			full = "A Bastilha Bael'Dun se ergue acima do sítio de escavação de Bael Modan, no sul dos Sertões. O General Twinbraid a comanda, defendendo a bastilha e seus anões contra os taurens e orcs das planícies ao redor.",
			source = "https://warcraft.wiki.gg/wiki/Bael'dun_Keep",
		},
		["blackthorn ridge"] = {
			name = "Serra de Abrunhal",
			short = "Espinhos tomam o vale ao norte do Urzal dos Tuscos, dominado pelos javaturnos Crinavalha. Na serra vive Salma, uma xamã. Abaixo de seu acampamento há uma lagoa de água límpida e pura em meio aos espinhos.",
			full = "Espinhos tomam o vale ao norte do Urzal dos Tuscos, dominado pelos javaturnos Crinavalha. Na serra vive Salma, uma xamã. Abaixo de seu acampamento há uma lagoa de água límpida e pura em meio aos espinhos.",
			source = "https://warcraft.wiki.gg/wiki/Blackthorn_Ridge",
		},
		["boulder lode mine"] = {
			name = "Mina Veio do Pedregulho",
			short = "A Mina Veio do Pedregulho fica nos Sertões, com túneis escorados por madeira orc e decorados com estandartes da Horda, relíquias desbotadas de quem primeiro abriu estes poços na rocha.",
			full = "A Mina Veio do Pedregulho fica nos Sertões, com túneis escorados por madeira orc e decorados com estandartes da Horda, relíquias desbotadas de quem primeiro abriu estes poços na rocha. Essa posse não existe mais. A Empreendimentos S.A. ocupa a mina, com goblins fervilhando nas galerias onde antes trabalhavam orcs.\n\nChegou ao Mestre Portuário Caruncho a notícia de que um dos mineiros de lá havia rompido um veio e arrancado uma esmeralda gigante. O mestre portuário a queria tanto que prometeu uma parte do lucro a quem estivesse disposto a entrar e tirá-la das mãos da Empreendimentos S.A.",
			source = "https://warcraft.wiki.gg/wiki/Boulder_Lode_Mine",
		},
		["bramblescar"] = {
			name = "Espinheira",
			short = "Os javaturnos Crinavalha dominam a Espinheira. Do outro lado da estrada, em Agama'gor, ficam os Bristleback, e entre as duas tribos só existe guerra.",
			full = "Os javaturnos Crinavalha dominam a Espinheira. Do outro lado da estrada, em Agama'gor, ficam os Bristleback, e entre as duas tribos só existe guerra. Quem se aproximar demais do covil dos Crinavalha não vai precisar provocar os javaturnos para ser atacado.",
			source = "https://warcraft.wiki.gg/wiki/Bramblescar",
		},
		["camp taurajo"] = {
			name = "Acampamento Taurajo",
			short = "O Acampamento Taurajo fica nos Sertões, perto do desfiladeiro que leva a Mulgore. Oferece descanso e provisões a quem vem da Aldeia Casco Sangrento antes de seguir rumo à terra natal dos taurens.",
			full = "O Acampamento Taurajo fica nos Sertões, perto do desfiladeiro que leva a Mulgore. Oferece descanso e provisões a quem vem da Aldeia Casco Sangrento antes de seguir rumo à terra natal dos taurens.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Taurajo",
		},
		["crossroads"] = {
			name = "A Encruzilhada",
			short = "A Encruzilhada fica onde as estradas se encontram: a trilha norte-sul que desce da Estrada do Ouro e o longo caminho leste-oeste que vai de Vila Catraca até a Cordilheira das Torres de Pedra.",
			full = "A Encruzilhada fica onde as estradas se encontram: a trilha norte-sul que desce da Estrada do Ouro e o longo caminho leste-oeste que vai de Vila Catraca até a Cordilheira das Torres de Pedra. É um lugar feito pelo cruzamento mais do que por qualquer coisa construída ali: poucas hospedagens, nenhuma grande muralha, apenas tendas, barracas e comerciantes gritando uns por cima dos outros para vender o que têm.\n\nAlém do limite do povoado fica um cemitério, simples e silencioso diante do barulho da praça de comércio às suas costas. É aqui que a Horda vem prestar homenagem a seus mortos, assim como o Morro da Sentinela serve ao mesmo propósito para a Aliança.",
			source = "https://warcraft.wiki.gg/wiki/Crossroads",
		},
		["dreadmist den"] = {
			name = "Covil de Brumedo",
			short = "Uma névoa vermelho-escura paira eternamente sobre o Morro de Brumedo, envolvendo-o em penumbra. Lá dentro, cultistas da Lâmina Ardente ocupam o Covil de Brumedo, guardando a Semente Demoníaca, um artefato que valorizam acima de tudo.",
			full = "Uma névoa vermelho-escura paira eternamente sobre o Morro de Brumedo, envolvendo-o em penumbra. Lá dentro, cultistas da Lâmina Ardente ocupam o Covil de Brumedo, guardando a Semente Demoníaca, um artefato que valorizam acima de tudo. A própria névoa parece proteger seu culto aos demônios dos olhares de fora.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Den",
		},
		["dreadmist peak"] = {
			name = "Morro de Brumedo",
			short = "A noroeste da Encruzilhada, o Morro de Brumedo se ergue nos Sertões, com o cume sufocado por uma neblina vermelha, resíduo de uma antiga maldição demoníaca.",
			full = "A noroeste da Encruzilhada, o Morro de Brumedo se ergue nos Sertões, com o cume sufocado por uma neblina vermelha, resíduo de uma antiga maldição demoníaca. Cultistas da Lâmina Ardente se instalaram no alto dele, guardando a Semente Demoníaca dentro do Covil de Brumedo, mais abaixo.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmist_Peak",
		},
		["dry hills"] = {
			name = "Montes Áridos",
			short = "Os Montes Áridos se erguem verdes contra a poeira dos Sertões, contrafortes que sobem em direção à Cordilheira das Torres de Pedra.",
			full = "Os Montes Áridos se erguem verdes contra a poeira dos Sertões, contrafortes que sobem em direção à Cordilheira das Torres de Pedra. As harpias Witchwing dominam este território e ficaram ousadas, atacando caravanas ao longo do trecho norte da Estrada do Ouro antes de desaparecer de volta no verde.",
			source = "https://warcraft.wiki.gg/wiki/Dry_Hills",
		},
		["far watch post"] = {
			name = "Posto Remoto",
			short = "O Posto Remoto fica logo a oeste da ponte que liga Durotar aos Sertões, pouco mais que uma torre de vigia, uma toca orc e uma fileira de catapultas, com um cercado de lobos e seus dois peões um pouco ao sul.",
			full = "O Posto Remoto fica logo a oeste da ponte que liga Durotar aos Sertões, pouco mais que uma torre de vigia, uma toca orc e uma fileira de catapultas, com um cercado de lobos e seus dois peões um pouco ao sul. Não é um posto confortável, mas necessário, que protege as caravanas com destino a Durotar e segura a linha tanto contra a Aliança quanto contra os javaturnos.",
			source = "https://warcraft.wiki.gg/wiki/Far_Watch_Post",
		},
		["field of giants"] = {
			name = "Campo dos Gigantes",
			short = "O Campo dos Gigantes se estende pelo sul dos Sertões, amplo e aberto, onde manadas de lagartos-trovão e kodos se movem juntas em números que poucas outras terras conseguem igualar.",
			full = "O Campo dos Gigantes se estende pelo sul dos Sertões, amplo e aberto, onde manadas de lagartos-trovão e kodos se movem juntas em números que poucas outras terras conseguem igualar.\n\nA Estrada do Ouro atravessa estas planícies com seu trecho sul, menos segura aqui do que no norte. Torres de vigia se erguiam ao longo dela para proteger as caravanas de passagem; agora estão vazias, abandonadas ao vento e ao capim.\n\nA Horda não desistiu deste território, embora seu domínio sobre ele seja tênue. Numa serra ao longo da borda sul do Campo vive a xamã Salma, longe de qualquer acampamento ou encruzilhada. Não muito longe caminha Gann Agulha de Pedra, remoendo uma velha mágoa: sua tribo foi expulsa da aldeia quando anões vieram cavar a terra em busca de ruínas titânicas em terras vizinhas ao seu lar. Essa escavação se tornou Bael Modan, e Gann não esqueceu o quanto ela custou a seu povo.",
			source = "https://warcraft.wiki.gg/wiki/Field_of_Giants",
		},
		["forgotten pools"] = {
			name = "Os Charcos Esquecidos",
			short = "Os Charcos Esquecidos ficam ao norte da estrada oeste que sai da Encruzilhada, o mais setentrional dos oásis espalhados pelo norte dos Sertões.",
			full = "Os Charcos Esquecidos ficam ao norte da estrada oeste que sai da Encruzilhada, o mais setentrional dos oásis espalhados pelo norte dos Sertões. Suas margens continuam verdes, rodeadas de Cogumelos Carregados que não se encontram em nenhum outro lugar, e suas águas guardam peixes desviantes diferentes de qualquer outro pescado nos Sertões.\n\nCentauros Kolkar percorrem a beira da água ao lado das tartarugas e dos animais que se abrigam ali.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Pools",
		},
		["fray island"] = {
			name = "Ilha da Peleja",
			short = "A Ilha da Peleja é pequena e seca, ao largo da costa leste dos Sertões.",
			full = "A Ilha da Peleja é pequena e seca, ao largo da costa leste dos Sertões.\n\nA ilha serve de campo de treinamento para guerreiros de todas as raças e credos, reunidos ali sob o comando de Klannoc Macleod.",
			source = "https://warcraft.wiki.gg/wiki/Fray_Island",
		},
		["gold road"] = {
			name = "Estrada do Ouro",
			short = "A Estrada do Ouro se estende entre a Paliçada Mor'shan e a Grande Fenda, e seu trecho sul, além da ponte que marca a travessia, é conhecido separadamente como Estrada do Ouro Sul.",
			full = "A Estrada do Ouro se estende entre a Paliçada Mor'shan e a Grande Fenda, e seu trecho sul, além da ponte que marca a travessia, é conhecido separadamente como Estrada do Ouro Sul.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Road",
		},
		["groldom farm"] = {
			name = "Fazenda Grol'dom",
			short = "A Fazenda Grol'dom é uma das criações de porcos que se instalaram nos anos seguintes à fundação de Orgrimmar, com seus cercados sob ataques constantes dos Saqueadores Crinavalha.",
			full = "A Fazenda Grol'dom é uma das criações de porcos que se instalaram nos anos seguintes à fundação de Orgrimmar, com seus cercados sob ataques constantes dos Saqueadores Crinavalha.",
			source = "https://warcraft.wiki.gg/wiki/Grol'dom_Farm",
		},
		["lushwater oasis"] = {
			name = "Oásis das Águas Claras",
			short = "A água se acumula onde a Grande Fenda desce, e feras selvagens descem por entre as árvores para bebê-la. Centauros Kolkar esperam por elas entre as raízes, caçando os animais atraídos pelos lagos.",
			full = "A água se acumula onde a Grande Fenda desce, e feras selvagens descem por entre as árvores para bebê-la. Centauros Kolkar esperam por elas entre as raízes, caçando os animais atraídos pelos lagos.\n\nSob o oásis fica a entrada da Caverna Ululante, um lugar de que se fala como amaldiçoado. O que se agita lá embaixo não vem à tona, mas seu nome ainda paira sobre a água.\n\nOs peixes daqui são diferentes de todos os outros encontrados nos Sertões.",
			source = "https://warcraft.wiki.gg/wiki/Lushwater_Oasis",
		},
		["merchant coast"] = {
			name = "Costa dos Mercadores",
			short = "A Costa dos Mercadores leva o nome do comércio que passa por ela, econômico e constante, nas mãos dos goblins de Vila Catraca.",
			full = "A Costa dos Mercadores leva o nome do comércio que passa por ela, econômico e constante, nas mãos dos goblins de Vila Catraca.\n\nO litoral sul pertence aos Flibusteiros dos Mares do Sul. Entre eles está o Barão Longshore, que certa vez roubou uma carga valiosa de Gasganete e a enterrou antes de ser capturado, deixando a fortuna perdida em algum lugar ao longo da praia.",
			source = "https://warcraft.wiki.gg/wiki/Merchant_Coast",
		},
		["morshan base camp"] = {
			name = "Campo-base Mor'shan",
			short = "O Campo-base Mor'shan fica ao sul da fronteira com o Vale Gris, perto da Paliçada Mor'shan, uma das maiores posses da Horda nos Sertões.",
			full = "O Campo-base Mor'shan fica ao sul da fronteira com o Vale Gris, perto da Paliçada Mor'shan, uma das maiores posses da Horda nos Sertões. Os Pioneiros do Brado Guerreiro têm sua base aqui, vigiando a estrada que leva ao norte, para a floresta disputada mais além.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Base_Camp",
		},
		["morshan rampart"] = {
			name = "Paliçada Mor'shan",
			short = "A Paliçada Mor'shan fica onde a Estrada do Ouro segue para o norte, saindo dos Sertões, erguida como muralha contra o avanço da Aliança a partir do Vale Gris.",
			full = "A Paliçada Mor'shan fica onde a Estrada do Ouro segue para o norte, saindo dos Sertões, erguida como muralha contra o avanço da Aliança a partir do Vale Gris. É uma obra rústica, feita para a guerra: trincheiras e torres de vigia destinadas a segurar uma linha contra forças que avançam do norte.",
			source = "https://warcraft.wiki.gg/wiki/Mor'shan_Rampart",
		},
		["raptor grounds"] = {
			name = "Terra dos Raptores",
			short = "Os raptores Sunscale que enchem este pequeno vale são diferentes de todos os outros dos Sertões. Demonstram uma astúcia antinatural, construindo cabanas rústicas e fabricando ferramentas com garras que nada deveriam saber de ofícios.",
			full = "Os raptores Sunscale que enchem este pequeno vale são diferentes de todos os outros dos Sertões. Demonstram uma astúcia antinatural, construindo cabanas rústicas e fabricando ferramentas com garras que nada deveriam saber de ofícios.\n\nMais estranha ainda é sua fome por qualquer coisa brilhante ou desconhecida, que os levou a atacar povoados da Horda próximos, arrastando o que quer que lhes chame a atenção.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Grounds",
		},
		["ratchet"] = {
			name = "Vila Catraca",
			short = "Vila Catraca fica na costa leste dos Sertões, uma cidade portuária goblin que mantém um comércio intenso com a Angra do Butim e o Barão Rezingada, do outro lado do mar.",
			full = "Vila Catraca fica na costa leste dos Sertões, uma cidade portuária goblin que mantém um comércio intenso com a Angra do Butim e o Barão Rezingada, do outro lado do mar. Gasganete a fundou com as moedas que Thrall lhe pagou pela construção de Orgrimmar, e ela se encheu de contrabandistas e de todos os outros que os lugares respeitáveis haviam rejeitado.\n\nEssa indiferença quase lhe custou caro. O culto da Lâmina Ardente trabalhou em silêncio para jogar Orgrimmar e Theramore uma contra a outra, provocando incidentes marítimos perto do porto de Vila Catraca que nenhum dos lados entendeu como outra coisa senão provocação. Marinheiros orcs e humanos que haviam dividido seu cais em paz começaram a brigar em suas ruas e, quando o leão de chácara Muzzlecrank prendeu os capitães Klatt e Joq, a Fortaleza da Guardanorte tomou isso como prova de que os orcs se preparavam para a guerra. Vila Catraca virou a base de um exército da Horda que se aprontava para marchar contra eles. Só quando a mão da Lâmina Ardente no caso veio à tona foi que Thrall cancelou a luta antes que ela começasse.",
			source = "https://warcraft.wiki.gg/wiki/Ratchet",
		},
		["shrine of the fallen warrior"] = {
			name = "Altar do Guerreiro Caído",
			short = "Uma trilha gasta sobe uma colina a oeste da Encruzilhada e termina num altar a um guerreiro caído. Nenhum nome está gravado ali, nenhum estandarte o assinala.",
			full = "Uma trilha gasta sobe uma colina a oeste da Encruzilhada e termina num altar a um guerreiro caído. Nenhum nome está gravado ali, nenhum estandarte o assinala. A colina guarda seu silêncio, e o caminho até o alto é o único sinal de que alguém ainda se lembra.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Fallen_Warrior",
		},
		["sludge fen"] = {
			name = "Charco de Lodo",
			short = "O Charco de Lodo nem sempre foi uma ferida na terra. Um dia, ali havia um lago de água azul cristalina, antes que a Empreendimentos S.A. chegasse e erguesse uma plataforma de petróleo sobre ele.",
			full = "O Charco de Lodo nem sempre foi uma ferida na terra. Um dia, ali havia um lago de água azul cristalina, antes que a Empreendimentos S.A. chegasse e erguesse uma plataforma de petróleo sobre ele. O que resta agora é um lamaçal de resíduos industriais, explorado sob os olhos de um supervisor goblin que responde pela operação perante a Companhia.\n\nA plataforma atraiu rivais tanto quanto poluiu a água. O Sindicato dos Engenhoqueiros de Vila Catraca, pressionado pelo Diretor Riddlevox a igualar os retalhadores mais novos da Empreendimentos S.A., desistiu de tentar construir melhor que eles e preferiu simplesmente roubar o projeto. O goblin Cobogó mandou Wizzlecrank tomar uma das máquinas do charco e trazê-la de volta a Vila Catraca. Wizzlecrank só conseguiu subir no retalhador antes de descobrir que não tinha chave para movê-lo, e ficou preso em território inimigo até que o resgate chegasse e a máquina pudesse ser conduzida para fora debaixo do nariz dos trabalhadores da Companhia.",
			source = "https://warcraft.wiki.gg/wiki/Sludge_Fen",
		},
		["southern gold road"] = {
			name = "Estrada do Ouro Sul",
			short = "A Estrada do Ouro Sul leva o nome das caravanas que a percorrem.",
			full = "A Estrada do Ouro Sul leva o nome das caravanas que a percorrem. Ela vai do Grande Elevador, no limite sul dos Sertões, para o norte até a ponte que une as duas metades dos Sertões, onde passa a ser simplesmente a Estrada do Ouro.\n\nComerciantes vêm de longe por este caminho: de Geringontzan, em Tanaris, de Auberdine, na Costa Negra, de Refúgio Noturno, ao norte. Todos seguem a mesma estrada, atraídos pelo mesmo comércio que lhe deu o nome.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Gold_Road",
		},
		["southfury river"] = {
			name = "Rio Furiaustral",
			short = "O Furiaustral nasce no alto do Monte Hyjal, despejando-se de um lago de montanha numa queda que despenca trovejante nas terras baixas.",
			full = "O Furiaustral nasce no alto do Monte Hyjal, despejando-se de um lago de montanha numa queda que despenca trovejante nas terras baixas. Dali ele corre largo e veloz, cortando a terra em duas: marca onde o Vale Gris dá lugar a Azshara e, mais ao sul, onde terminam os Sertões e começa Durotar. Na foz, o rio se lança numa última cascata no Grande Mar, logo a nordeste do porto goblin de Vila Catraca.\n\nTrês pontes cruzam seu curso: uma ligando Azshara ao Vale Gris, outra levando os viajantes a Orgrimmar e outra unindo Durotar aos Sertões. Logo ao norte da mais ocidental delas, um único trecho de água toca as quatro terras ao mesmo tempo, o único lugar onde o Vale Gris, Azshara, Durotar e os Sertões se encontram.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["stagnant oasis"] = {
			name = "O Oásis Estagnado",
			short = "O Oásis Estagnado é uma porção de água parada e esverdeada entre a Costa dos Mercadores e a Estrada do Ouro. Centauros Kolkar acampam em suas bordas, e dizem que sua presença e seu vigor vêm das próprias águas estagnadas.",
			full = "O Oásis Estagnado é uma porção de água parada e esverdeada entre a Costa dos Mercadores e a Estrada do Ouro. Centauros Kolkar acampam em suas bordas, e dizem que sua presença e seu vigor vêm das próprias águas estagnadas. Os kodos que vagam por aqui são fracos e solitários, ao contrário das grandes manadas do Campo dos Gigantes ao sul, e presas muito mais fáceis. Peixes desviantes nadam sob a superfície, apreciados quando cozidos, enquanto tartarugas-mordedoras do oásis espreitam no lodo ao lado deles.",
			source = "https://warcraft.wiki.gg/wiki/Stagnant_Oasis",
		},
		["thorn hill"] = {
			name = "Morro dos Espinhos",
			short = "O Morro dos Espinhos fica na face norte de um cume entre a Encruzilhada e Durotar, com as encostas apinhadas de javaturnos da tribo Crinavalha.",
			full = "O Morro dos Espinhos fica na face norte de um cume entre a Encruzilhada e Durotar, com as encostas apinhadas de javaturnos da tribo Crinavalha. Desta altura, eles atacam as caravanas da Horda que passam pela região, atraindo a fúria dos que guardam as estradas lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Thorn_Hill",
		},
		["tidus stair"] = {
			name = "Escadaria de Tidus",
			short = "A Escadaria de Tidus se ergue acima da Costa dos Mercadores como uma série de amplos terraços de pedra, empilhados como a escadaria de um gigante com vista para o mar.",
			full = "A Escadaria de Tidus se ergue acima da Costa dos Mercadores como uma série de amplos terraços de pedra, empilhados como a escadaria de um gigante com vista para o mar. Islen Vidente da Água e Mahren Vidente do Céu, dois taurens, passam o tempo nestas saliências, lançando suas linhas nas ondas e conversando com os espíritos que habitam a água lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Tidus_Stair",
		},
		["wailing caverns"] = {
			name = "Caverna Ululante",
			short = "A Caverna Ululante leva o nome do próprio som do lugar: vapor irrompendo por fendas na rocha, levado pela escuridão em longos gritos lamentosos.",
			full = "A Caverna Ululante leva o nome do próprio som do lugar: vapor irrompendo por fendas na rocha, levado pela escuridão em longos gritos lamentosos.\n\nFoi o druida elfo noturno Naralex quem a encontrou e quem lhe deu seu propósito. Sob a savana corriam cursos d'água que afloravam em outros lugares como os oásis espalhados pelos Sertões, e Naralex acreditava que, se unisse essas águas ao próprio Sonho Esmeralda, poderia derramar aquela vitalidade verde de volta na terra ressequida lá em cima. Ele levou seus discípulos para dentro da caverna e entrou em meditação, abrindo-se como um canal entre o Sonho e o mundo desperto.\n\nEm vez disso, o Pesadelo Esmeralda o tomou. Naralex não conseguiu despertar. Através de seu corpo aberto e adormecido, a corrupção do Pesadelo se derramou pela caverna, contaminando as águas, retorcendo os animais em estranhas formas desviantes e levando a maioria de seus discípulos à loucura; os que restaram se tornaram os Druidas da Presa.\n\nNaralex ainda dorme ali, e os Druidas da Presa defendem a caverna contra qualquer um que tente despertá-lo.",
			source = "https://warcraft.wiki.gg/wiki/Wailing_Caverns",
		},
	},
	-- Montanhas de Alterac: 5 subzones
	[1416] = {
		["dalaran"] = {
			name = "Dalaran",
			short = "Dalaran surgiu como uma cidade de magos, fundada depois das Guerras Trolls por magos do Império Arathoriano, e tornou-se uma nação por si só.",
			full = "Dalaran surgiu como uma cidade de magos, fundada depois das Guerras Trolls por magos do Império Arathoriano, e tornou-se uma nação por si só. Seu povo não respondia a coroa alguma além do Kirin Tor, o círculo de elite dos mais poderosos conjuradores do mundo, governado pelo Conselho dos Seis. Em seu coração ficava a Cidadela Violeta, santuário e refúgio dos que estudavam o arcano, e nenhuma cidade fora das terras élficas de Quel'Thalas reunia tamanha concentração de poder mágico. Até os magos altos elfos de Quel'Thalas, em seu orgulho, curvavam-se à soberania do Kirin Tor.\n\nEssa soberania foi quebrada pelo fogo. Quando o Flagelo avançou contra Dalaran, seu povo foi expulso do próprio reino, e o próprio Archimonde reduziu a cidade a ruínas, dispersando os membros sobreviventes do Kirin Tor por Azeroth.\n\nOs sobreviventes não deixaram sua cidade continuar morta. Voltaram aos destroços e começaram a reconstruí-la, erguendo uma vasta cúpula mágica para proteger seu coração partido de novos danos.",
			source = "https://warcraft.wiki.gg/wiki/Dalaran",
		},
		["dandreds fold"] = {
			name = "Nicho de Dandred",
			short = "Uma pequena fazenda com sua casa senhorial fica no limite oeste das Terras Altas, onde o terreno encontra a Costa da Bruma e um porto se abre para o Espelho de Lordaeron.",
			full = "Uma pequena fazenda com sua casa senhorial fica no limite oeste das Terras Altas, onde o terreno encontra a Costa da Bruma e um porto se abre para o Espelho de Lordaeron.\n\nAqui vive Aliden, e com ele sua amante Elysa. Ela usa um colar que um dia pertenceu a Taretha Foxton.",
			source = "https://warcraft.wiki.gg/wiki/Dandred's_Fold",
		},
		["lordamere internment camp"] = {
			name = "Campo de Internação de Lordaeron",
			short = "O Campo de Internação de Lordaeron fica numa colina acima da Cratera de Dalaran, o único campo de internação erguido nas Montanhas de Alterac, mantido sob a vigilância das forças dalaranianas.",
			full = "O Campo de Internação de Lordaeron fica numa colina acima da Cratera de Dalaran, o único campo de internação erguido nas Montanhas de Alterac, mantido sob a vigilância das forças dalaranianas.\n\nAqui, a caminho de Dalaran, o Príncipe Arthas Menethil e Lady Jaina Proudmore certa vez passaram despercebidos pelas patrulhas e torres de vigia sob o manto da noite para ver os orcs mantidos lá dentro. O que viram os dividiu. Jaina olhou para as orcs e seus bebês e sentiu sua certeza vacilar em dúvida e remorso. Arthas não sentiu nada disso e sustentou que os campos eram necessários de qualquer maneira. Nenhum dos dois foi visto. Partiram por onde vieram, e o desacordo entre eles partiu junto.\n\nA Diretora Belamoore comanda a guarnição agora, estudando os Artefatos de Pedra-sangue trazidos a ela por Kegan Darkmar e seus companheiros.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Internment_Camp",
		},
		["ruins of alterac"] = {
			name = "Ruínas de Alterac",
			short = "Muralhas partidas sobem as encostas das Montanhas de Alterac onde antes havia uma cidade, com o palácio meio de pé, a igreja e a prefeitura desabadas sobre si mesmas e o portão construído ao estilo do próprio portão de Ventobravo.",
			full = "Muralhas partidas sobem as encostas das Montanhas de Alterac onde antes havia uma cidade, com o palácio meio de pé, a igreja e a prefeitura desabadas sobre si mesmas e o portão construído ao estilo do próprio portão de Ventobravo.\n\nSua ruína veio do próprio rei. Durante a Segunda Guerra, o Rei Aiden Perenolde se tornou traidor, unindo-se à Horda orc contra seus irmãos humanos. Soldados alteracianos foram encontrados lutando ao lado dos orcs, e um campo de prisioneiros perto da cidade mantinha cidadãos de Dalaran em cativeiro. Quando a verdade veio à tona, os outros reinos humanos marcharam sobre Alterac em retaliação. O povo fugiu ou foi expulso de suas casas, e o Rei Terenas Menethil II de Lordaeron declarou lei marcial na cidade, derrubando Perenolde e acorrentando-o.\n\nA cidade nunca mais se reergueu. Os ogros Esmagaterra, liderados por Mug'thol, instalaram-se nas ruas vazias e no palácio, enquanto os remanescentes dispersos do antigo povo alteraciano ficaram com as aldeias periféricas mais além. Carroças de carne destroçadas ainda jazem perto da muralha norte e do portão, e os cemitérios dentro e fora das muralhas, a fazenda soterrada pela neve e as balistas despedaçadas entre os escombros continuam como foram deixados.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Alterac",
		},
		["uplands"] = {
			name = "As Terras Altas",
			short = "As Terras Altas um dia alimentaram um reino. Suas colinas eram o celeiro de Alterac, grãos e pastagens para a antiga nação.",
			full = "As Terras Altas um dia alimentaram um reino. Suas colinas eram o celeiro de Alterac, grãos e pastagens para a antiga nação.\n\nEssa nação se partiu. As Terras Altas não passaram a coroa alguma, mas à Camarilha, que em nenhum outro lugar das montanhas tem domínio mais firme. O Barão Vardus comanda seus acampamentos aqui, senhor das sobras de terra de um reino partido.\n\nNos confins mais a oeste fica o Nicho de Dandred, um nome que sobreviveu ao que quer que um dia tenha significado.",
			source = "https://warcraft.wiki.gg/wiki/Uplands",
		},
	},
	-- Planalto Arathi: 19 subzones
	[1417] = {
		["boulderfist hall"] = {
			name = "Forte Punho de Pedra",
			short = "O Forte Punho de Pedra fica no sul do Planalto Arathi, perto da Ponte Thandol e da Aldeia Cascasseca, um monte de pedra fortificado por mãos de ogros.",
			full = "O Forte Punho de Pedra fica no sul do Planalto Arathi, perto da Ponte Thandol e da Aldeia Cascasseca, um monte de pedra fortificado por mãos de ogros. Na caverna maior, em seu coração, reina Kor'gresh Coldrage, chefe do clã Punho de Pedra.\n\nDesde então, os ogros avançaram pelas colinas ao redor, reforçando ainda mais suas defesas.",
			source = "https://warcraft.wiki.gg/wiki/Boulderfist_Hall",
		},
		["bouldergor"] = {
			name = "Pedre'gor",
			short = "Ao norte da Bastilha de Stromgarde, a colina de Pedre'gor se ergue partida e acidentada. Os ogros Punho de Pedra ocupam seu monte aqui, e trolls da floresta Cascasseca rondam as encostas ao lado deles.",
			full = "Ao norte da Bastilha de Stromgarde, a colina de Pedre'gor se ergue partida e acidentada. Os ogros Punho de Pedra ocupam seu monte aqui, e trolls da floresta Cascasseca rondam as encostas ao lado deles. Na face leste fica o Círculo dos Elementos, e logo ao sul da colina há um par de fazendas.",
			source = "https://warcraft.wiki.gg/wiki/Boulder'gor",
		},
		["circle of east binding"] = {
			name = "Círculo de União Oriental",
			short = "A Pedra de União Oriental vigia os confins do leste do Planalto Arathi, perto da Ruína do Martelo, marcando um dos Círculos de União espalhados pela região.",
			full = "A Pedra de União Oriental vigia os confins do leste do Planalto Arathi, perto da Ruína do Martelo, marcando um dos Círculos de União espalhados pela região. Elementais da água ainda guardam a pedra, presos ao lugar como se cumprissem alguma velha tarefa inacabada.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_East_Binding",
		},
		["circle of inner binding"] = {
			name = "Círculo de União Interno",
			short = "O Círculo de União Interno fica no sul do Planalto Arathi, perto da Bastilha de Stromgarde, guardado por elementais da terra. Aqui repousa a Pedra de União Interna, a mais forte das pedras.",
			full = "O Círculo de União Interno fica no sul do Planalto Arathi, perto da Bastilha de Stromgarde, guardado por elementais da terra. Aqui repousa a Pedra de União Interna, a mais forte das pedras.\n\nPor meio de seu fragmento, Myzrael encontrou uma forma de falar com os mortais.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Inner_Binding",
		},
		["circle of outer binding"] = {
			name = "Círculo de União Externo",
			short = "O Círculo de União Externo fica perto da Ponta do Refúgio, no Planalto Arathi. Em seu centro fica a Pedra de União Externa, sempre guardada por elementais do ar.",
			full = "O Círculo de União Externo fica perto da Ponta do Refúgio, no Planalto Arathi. Em seu centro fica a Pedra de União Externa, sempre guardada por elementais do ar.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_Outer_Binding",
		},
		["circle of west binding"] = {
			name = "Círculo de União Ocidental",
			short = "O Círculo de União Ocidental fica no oeste do Planalto Arathi, perto da Muralha de Thoradin. Ali repousa a Pedra de União Ocidental, guardada por elementais do fogo que nunca a deixam sem vigilância.",
			full = "O Círculo de União Ocidental fica no oeste do Planalto Arathi, perto da Muralha de Thoradin. Ali repousa a Pedra de União Ocidental, guardada por elementais do fogo que nunca a deixam sem vigilância.",
			source = "https://warcraft.wiki.gg/wiki/Circle_of_West_Binding",
		},
		["dabyries farmstead"] = {
			name = "Fazenda dos Dabyrie",
			short = "Nos confins do norte do Planalto Arathi fica a Fazenda dos Dabyrie, mantida por Kenata Dabyrie e seus filhos Fardel e Marcel, cidadãos de Stromgarde e leais à Aliança.",
			full = "Nos confins do norte do Planalto Arathi fica a Fazenda dos Dabyrie, mantida por Kenata Dabyrie e seus filhos Fardel e Marcel, cidadãos de Stromgarde e leais à Aliança. Uma milícia vigia os campos, pois a família tem inimigos.",
			source = "https://warcraft.wiki.gg/wiki/Dabyrie's_Farmstead",
		},
		["drowned reef"] = {
			name = "Recife dos Afogados",
			short = "Sob a baía ao largo do litoral sul do Planalto Arathi jaz uma cidade élfica submersa, antiga e arruinada. Ela não está mais vazia: os nagas Daggerspine a tomaram, governados pelo Príncipe Nazjak.",
			full = "Sob a baía ao largo do litoral sul do Planalto Arathi jaz uma cidade élfica submersa, antiga e arruinada. Ela não está mais vazia: os nagas Daggerspine a tomaram, governados pelo Príncipe Nazjak.\n\nO recife acima já tragou muitos navios, entre eles o Maiden's Folly e o Spirit of Silverpine. Dizem que os Daggerspine conseguem virar as próprias marés da baía, atraindo para as pedras as tripulações que acham ter encontrado um porto seguro na Enseada de Faldir.",
			source = "https://warcraft.wiki.gg/wiki/Drowned_Reef",
		},
		["drywhisker gorge"] = {
			name = "Garganta Seca",
			short = "A Garganta Seca corta as montanhas do leste do Planalto Arathi, a nordeste da Ruína do Martelo. Em seu final há uma caverna, lar dos kobolds da Garganta Seca, aliados dos gigantes que dividem este planalto.",
			full = "A Garganta Seca corta as montanhas do leste do Planalto Arathi, a nordeste da Ruína do Martelo. Em seu final há uma caverna, lar dos kobolds da Garganta Seca, aliados dos gigantes que dividem este planalto.\n\nLá no fundo, depois das galerias, repousa um fragmento de pedra no qual está aprisionada uma parte da essência da Princesa Myzrael. Os kobolds o guardam com ferocidade, junto com as partículas reunidas nas profundezas da caverna, embora nenhum deles pareça saber o que o fragmento realmente contém.",
			source = "https://warcraft.wiki.gg/wiki/Drywhisker_Gorge",
		},
		["faldirs cove"] = {
			name = "Enseada de Faldir",
			short = "A Enseada de Faldir leva o nome de Faldir, que teria marcado este lugar quando ele e seus seguidores partiram.",
			full = "A Enseada de Faldir leva o nome de Faldir, que teria marcado este lugar quando ele e seus seguidores partiram.\n\nMuito tempo depois, os Saqueadores de Aguanegra vieram em busca de um tesouro élfico que estaria nas águas próximas. Os capitães Tripaço e Nabrava levaram três navios para a enseada, mas uma maré estranha se ergueu contra eles, provocada por nagas que guardavam ruínas submersas sob o recife, e dois dos três navios afundaram. Apenas o Harbinger chegou à praia, e sua tripulação se viu presa na baía, incapaz de partir até que os nagas fossem expulsos e os diários de navegação fossem recuperados dos naufrágios lá embaixo.\n\nMais tarde, dois engenheiros gnomos, o Doutor Medeixo e o Professor Bruzundanga, construíram um dispositivo para procurar gemas élficas que estariam calcificadas nas pedras do Recife dos Afogados.\n\nA enseada ainda carrega as cicatrizes dessa história submersa: recife, naufrágio e ruína, tudo falando de navios que jamais deveriam ter afundado e de um tesouro que o mar não devolveu.",
			source = "https://warcraft.wiki.gg/wiki/Faldir's_Cove",
		},
		["goshek farm"] = {
			name = "Fazenda Go'Shek",
			short = "A Fazenda Go'Shek fica no leste do Planalto Arathi, perto da Aldeia Cascasseca.",
			full = "A Fazenda Go'Shek fica no leste do Planalto Arathi, perto da Aldeia Cascasseca. Depois da Terceira Guerra, Renegados e orcs vindos da Ruína do Martelo tomaram a fazenda para seus próprios fins: os orcs tiravam suprimentos dela, e os Renegados transformaram seus campos e anexos em campo de testes para uma alquimia de tipo mais sombrio.\n\nOs agentes da Aliança Quae e Kinelory vieram investigar o que estava acontecendo aqui. Com ajuda, abateram um mensageiro Renegado a caminho da Serraria Tarren antes que ele pudesse entregar sua mensagem e vasculharam a própria fazenda, onde encontraram as anotações de um Boticário Jorell. Sua pesquisa apontava para algo novo e terrível tomando forma: mais uma praga em preparação.\n\nOs Peões de Guerra da Ruína do Martelo ocupam a fazenda agora.",
			source = "https://warcraft.wiki.gg/wiki/Go'Shek_Farm",
		},
		["hammerfall"] = {
			name = "Ruína do Martelo",
			short = "O chão da Ruína do Martelo se lembra do que já foi. Depois da Segunda Guerra, a Aliança de Lordaeron construiu aqui um de seus maiores campos de internação, confinando orcs capturados atrás de suas muralhas.",
			full = "O chão da Ruína do Martelo se lembra do que já foi. Depois da Segunda Guerra, a Aliança de Lordaeron construiu aqui um de seus maiores campos de internação, confinando orcs capturados atrás de suas muralhas. Ele não continuou sendo uma prisão. O Chefe Guerreiro Thrall e Orgrim Martelo da Perdição lideraram a Horda contra o campo para libertar seu povo e, no caos dessa libertação, enquanto Thrall cobria a retirada, um cavaleiro em carga cravou uma lança nas costas de Orgrim com tanta força que ela atravessou sua armadura de um lado ao outro. Martelo da Perdição morreu ali, no chão que viera libertar.\n\nDepois da Terceira Guerra, a Horda voltou às ruínas e ergueu uma base avançada entre elas, dando-lhe o nome de Ruína do Martelo em honra ao Chefe Guerreiro que caíra ao tomá-la. Ela se tornou mais que um posto avançado: um refúgio para os que sentiam não ter mais lugar no mundo, com suas cabanas espirituais, estábulos, forja e grande salão erguidos onde antes ficavam as muralhas do campo de internação.",
			source = "https://warcraft.wiki.gg/wiki/Hammerfall",
		},
		["northfold manor"] = {
			name = "Casa Grande do Norte",
			short = "Depois da queda de Stromgarde, a Casa Grande do Norte passou para as mãos da Camarilha, que fez dela um posto avançado no Planalto Arathi.",
			full = "Depois da queda de Stromgarde, a Casa Grande do Norte passou para as mãos da Camarilha, que fez dela um posto avançado no Planalto Arathi.\n\nPara cá veio o xamã troll Tor'gan, atraído por algo errado no ar. Seguindo o rastro até a casa, encontrou vestígios de invocação demoníaca ainda agarrados ao lugar e, ao se aproximar, seu próprio sangue começou a ferver com uma fúria que não era inteiramente sua. No chão, encontrou um amuleto de pedra-sangue, usado para invocar demônios, embora aquele já estivesse esgotado de poder. Suspeitando que os negócios da Camarilha fossem além do banditismo, ele procurou outros amuletos desse tipo para descobrir a verdade sobre suas intenções.",
			source = "https://warcraft.wiki.gg/wiki/Northfold_Manor",
		},
		["refuge pointe"] = {
			name = "Ponta do Refúgio",
			short = "Quando a capital de Stromgarde caiu em ruínas durante a Terceira Guerra, a maior parte de seu povo fugiu para o sul, pelo Planalto Arathi. Mas os remanescentes do exército de Stromgarde não quiseram ir com eles.",
			full = "Quando a capital de Stromgarde caiu em ruínas durante a Terceira Guerra, a maior parte de seu povo fugiu para o sul, pelo Planalto Arathi. Mas os remanescentes do exército de Stromgarde não quiseram ir com eles. Ficaram, determinados a recuperar o que fora perdido, e foi aqui, na Ponta do Refúgio, que fizeram sua resistência.\n\nO posto avançado se tornou a sede da guerra da Aliança no Planalto, com seus soldados empenhados em retomar a Bastilha de Stromgarde e garantir os recursos que pudessem para a causa da Aliança. Essa dedicação exclusiva deixou pouco espaço para qualquer outra coisa. Quando a Ponte Thandol sofreu um duro ataque dos Ferro Negro e seus anões mandaram pedir ajuda para retomar Dun Modr e a própria ponte, a Capitã Nélia não pôde dispor de uma única alma. Stromgarde havia caído, disse ela, e até que fosse retomada, cada espada e cada mão na Ponta do Refúgio pertenciam somente a essa causa. A honra e o dever os prendiam ao Planalto, disse ela ao mensageiro, e Trançalonga, o Austero, teria que se virar sem eles.",
			source = "https://warcraft.wiki.gg/wiki/Refuge_Pointe",
		},
		["stromgarde keep"] = {
			name = "Bastilha de Stromgarde",
			short = "Stromgarde já foi Strom, berço do primeiro reino humano, capital do Império Arathoriano.",
			full = "Stromgarde já foi Strom, berço do primeiro reino humano, capital do Império Arathoriano. Quando a Horda orc chegou aos Reinos do Leste, ela ainda era uma potência dentro da Aliança de Lordaeron, com seu nome intacto mesmo depois da Segunda Guerra.\n\nA cidade foi saqueada depois da Terceira Guerra e ficou em pedaços. Hoje está dividida em três: a bastilha interna, ocupada pela Camarilha; o distrito dos magos, arruinado e tomado pelos ogros Punho de Pedra com a ajuda dos trolls Cascasseca; e o último quarteirão ainda defendido pelos militares de Stromgarde, de onde o Príncipe Galen Matatroll comanda o que resta de seu povo.",
			source = "https://warcraft.wiki.gg/wiki/Stromgarde_Keep",
		},
		["thandol span"] = {
			name = "Ponte Thandol",
			short = "Dois grandes arcos de pedra atravessam o vão entre o Pantanal e o Planalto Arathi, erguidos por mãos anãs e guardados por três gerações pela linhagem Sidermar.",
			full = "Dois grandes arcos de pedra atravessam o vão entre o Pantanal e o Planalto Arathi, erguidos por mãos anãs e guardados por três gerações pela linhagem Sidermar. Foram construídos depois da Guerra dos Três Martelos, quando Altaforja buscou manter a boa-fé com seus parentes Martelo Feroz do Ninho da Águia, e as pontes se tornaram ao mesmo tempo estrada e símbolo entre os dois reinos anões, levando um comércio que enriquecia a ambos.\n\nAs pontes eram capazes de suportar o peso de exércitos inteiros e já serviram como a principal rota comercial entre anões e humanos. Foi aqui que Anduin Lothar expulsou o que restava da Velha Horda de Lordaeron, de volta para Khaz Modan, forçando-a a atravessar a Ponte derrotada.\n\nAgora a Ponte está marcada por cicatrizes. Um complô dos Ferro Negro, tramado por Kam Deepfury e Balgaras, o Imundo, causou graves danos às pontes, e as forças anãs lutam para manter o que resta e retomar a cidade vizinha de Dun Modr. Muitos anões morreram nos combates, entre eles Sully Balloo, Ebenezer Rustlocke e o irmão de Trançalonga, o Austero.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thoradins wall"] = {
			name = "Muralha de Thoradin",
			short = "O Rei Thoradin ergueu esta muralha para conter os trolls amani, nos tempos em que Strom ainda era jovem e Arathor mal havia conquistado a terra para a humanidade.",
			full = "O Rei Thoradin ergueu esta muralha para conter os trolls amani, nos tempos em que Strom ainda era jovem e Arathor mal havia conquistado a terra para a humanidade. Por gerações, ela foi uma sentinela firme, uma linha destinada a proteger a humanidade das incursões dos trolls.\n\nSéculos depois, a muralha ainda está de pé, mas muito danificada, com suas pedras quebradas e sua longa vigília reduzida a ruínas.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["tower of arathor"] = {
			name = "Torre de Arathor",
			short = "A Torre de Arathor fica no distrito dos magos da Bastilha de Stromgarde, batizada em homenagem ao antigo Império de Arathor, do qual o reino herdou sua linhagem.",
			full = "A Torre de Arathor fica no distrito dos magos da Bastilha de Stromgarde, batizada em homenagem ao antigo Império de Arathor, do qual o reino herdou sua linhagem.\n\nO Arquimago Trelane estudou entre suas paredes e ali construiu uma defesa entrelaçada na própria torre, adormecida até ser despertada por uma gema encantada. Quando a Camarilha e os ogros Punho de Pedra cercaram Stromgarde, Trelane tentou defender a torre com sua criação, mas não foi o bastante. Ele fugiu da cidade, e a torre caiu junto com ela. Os ogros Punho de Pedra tomaram o distrito para si, e o ogro-magi Ruul Onestone passou a habitar seus salões.\n\nTrelane nunca deixou de pensar no que havia deixado para trás: seu filactério, seu orbe, uma ágata de brasa trabalhada por suas próprias mãos. Ele recorreu a seu antigo aprendiz, o Arquimago Malin, para recuperá-los dos ogros que agora ocupavam a torre. Chegou a Malin a notícia de que os pertences do velho mestre haviam sido encontrados, escondidos em baús nos salões que um dia ele chamara de seus.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Arathor",
		},
		["witherbark village"] = {
			name = "Aldeia Cascasseca",
			short = "A Aldeia Cascasseca fica ao redor de um pequeno lago no sudeste do Planalto Arathi, lar dos trolls da tribo Cascasseca. Atrás da aldeia fica uma grande caverna onde os líderes da tribo costumam ser encontrados.",
			full = "A Aldeia Cascasseca fica ao redor de um pequeno lago no sudeste do Planalto Arathi, lar dos trolls da tribo Cascasseca. Atrás da aldeia fica uma grande caverna onde os líderes da tribo costumam ser encontrados.\n\nOs Cascasseca fizeram causa comum com os ogros Punho de Pedra vizinhos, uma aliança voltada contra Stromgarde e a Ruína do Martelo. Juntos, trolls e ogros ocupam uma parte da própria Stromgarde, arrancada de seus antigos senhores.\n\nEssa força fez dos Cascasseca um povo marcado, caçado tanto pela Aliança quanto pela Horda, que desejavam vê-los extintos. Entre os que enfrentaram esse acerto de contas, Nimar, o Matador, foi apontado como o mais perigoso, um guerreiro que, ao morrer, levou muitos de seus inimigos consigo.",
			source = "https://warcraft.wiki.gg/wiki/Witherbark_Village",
		},
	},
	-- Ermos: 17 subzones
	[1418] = {
		["agmonds end"] = {
			name = "Ruína de Agmundo",
			short = "O sítio de escavação no centro-sul dos Ermos leva o nome do anão que morreu ali.",
			full = "O sítio de escavação no centro-sul dos Ermos leva o nome do anão que morreu ali. Agmundo veio para quebrar pedras e encontrou os troggs que já haviam tomado o terreno; eles acabaram com ele onde estava, e o sítio foi abandonado a eles.",
			source = "https://warcraft.wiki.gg/wiki/Agmond's_End",
		},
		["angor fortress"] = {
			name = "Fortaleza Angor",
			short = "Os anões Ferro Negro mantêm a Fortaleza Angor como sua sede nos Ermos, de onde dirigem suas escavações rumo a Uldaman.",
			full = "Os anões Ferro Negro mantêm a Fortaleza Angor como sua sede nos Ermos, de onde dirigem suas escavações rumo a Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Angor_Fortress",
		},
		["apocryphans rest"] = {
			name = "Descanso do Apócrifo",
			short = "Os ossos do Descanso do Apócrifo se espalham pelos Ermos ao sul de Karrath, o esqueleto de um dragão tombado e deixado para branquear no calor seco.",
			full = "Os ossos do Descanso do Apócrifo se espalham pelos Ermos ao sul de Karrath, o esqueleto de um dragão tombado e deixado para branquear no calor seco. Urubus fazem ninhos e caçam entre as costelas agora, os únicos que reivindicam a grande carcaça como lar.",
			source = "https://warcraft.wiki.gg/wiki/Apocryphan's_Rest",
		},
		["camp boff"] = {
			name = "Acampamento Barf",
			short = "O Acampamento Barf é o acampamento sudeste dos ogros Arrota-pó, um dos quatro, ao lado dos acampamentos Cang, Kosh e Wurg. Poucos ogros o guardam.",
			full = "O Acampamento Barf é o acampamento sudeste dos ogros Arrota-pó, um dos quatro, ao lado dos acampamentos Cang, Kosh e Wurg. Poucos ogros o guardam.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Boff",
		},
		["camp cagg"] = {
			name = "Acampamento Cang",
			short = "O Acampamento Cang é um dos lares dos ogros Arrota-pó, que compartilham esse nome com outros três acampamentos espalhados pelas redondezas.",
			full = "O Acampamento Cang é um dos lares dos ogros Arrota-pó, que compartilham esse nome com outros três acampamentos espalhados pelas redondezas.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Cagg",
		},
		["camp kosh"] = {
			name = "Acampamento Kosh",
			short = "O Acampamento Kosh fica no limite norte do território Arrota-pó, vigiando as estradas áridas que serpenteiam rumo a Karrath e descem para a Garganta Abrasadora.",
			full = "O Acampamento Kosh fica no limite norte do território Arrota-pó, vigiando as estradas áridas que serpenteiam rumo a Karrath e descem para a Garganta Abrasadora. As caravanas que atravessam os Ermos temem este trecho, pois os ogros de Kosh caem sobre elas por qualquer coisa que carreguem.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Kosh",
		},
		["camp wurg"] = {
			name = "Acampamento Wurg",
			short = "O Acampamento Wurg é um dos lares dos ogros Arrota-pó, parentes dos ogros do Acampamento Cang, do Acampamento Barf e do Acampamento Kosh.",
			full = "O Acampamento Wurg é um dos lares dos ogros Arrota-pó, parentes dos ogros do Acampamento Cang, do Acampamento Barf e do Acampamento Kosh.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Wurg",
		},
		["dustbelch grotto"] = {
			name = "Gruta Arrota-pó",
			short = "No sudoeste dos Ermos se ergue um grande monte de terra e pedra, escavado por dentro e tomado pelos ogros Arrota-pó.",
			full = "No sudoeste dos Ermos se ergue um grande monte de terra e pedra, escavado por dentro e tomado pelos ogros Arrota-pó. A Gruta Arrota-pó é seu lar, um labirinto de túneis e câmaras onde o clã fez seu covil em meio à terra rachada e calcinada pelo sol ao redor.",
			source = "https://warcraft.wiki.gg/wiki/Dustbelch_Grotto",
		},
		["dustbowl"] = {
			name = "Terrasseca",
			short = "A Terrasseca fica entre Karrath e o Vale das Presas, uma extensão de chão rachado e árido no noroeste dos Ermos. Coiotes e urubus a percorrem, e elementais de rocha se agitam entre as pedras.",
			full = "A Terrasseca fica entre Karrath e o Vale das Presas, uma extensão de chão rachado e árido no noroeste dos Ermos. Coiotes e urubus a percorrem, e elementais de rocha se agitam entre as pedras. Pouco cresce aqui além de cactos e algumas árvores teimosas. O Acampamento Wurg fica nesta vastidão.",
			source = "https://warcraft.wiki.gg/wiki/Dustbowl",
		},
		["dustwind gulch"] = {
			name = "Ravina de Sopravento",
			short = "Os ventos varrem a Ravina de Sopravento até que nada macio fique de pé, apenas pedra e os ossos secos da ravina. Ela fica a oeste da Ravina Lethlor, um corte de terra estéril nos Ermos onde a poeira nunca assenta por muito tempo.",
			full = "Os ventos varrem a Ravina de Sopravento até que nada macio fique de pé, apenas pedra e os ossos secos da ravina. Ela fica a oeste da Ravina Lethlor, um corte de terra estéril nos Ermos onde a poeira nunca assenta por muito tempo.",
			source = "https://warcraft.wiki.gg/wiki/Dustwind_Gulch",
		},
		["hammertoes digsite"] = {
			name = "Sítio de Escavação do Pé-de-malho",
			short = "O Sítio de Escavação do Pé-de-malho fica no norte dos Ermos, com suas trincheiras agora silenciosas, sem os mineiros que um dia trabalharam nelas.",
			full = "O Sítio de Escavação do Pé-de-malho fica no norte dos Ermos, com suas trincheiras agora silenciosas, sem os mineiros que um dia trabalharam nelas. O próprio Pé-de-malho abandonou o sítio e, em seu lugar, um bando de Ferro Negro se instalou, provavelmente a mesma força que avançou sobre Uldaman.",
			source = "https://warcraft.wiki.gg/wiki/Hammertoe's_Digsite",
		},
		["kargath"] = {
			name = "Karrath",
			short = "Karrath está sozinha em Khaz Modan, o único posto avançado que a Horda mantém naquela terra, batizada em homenagem a Kargath Carpunhal, chefe do clã Mão Despedaçada.",
			full = "Karrath está sozinha em Khaz Modan, o único posto avançado que a Horda mantém naquela terra, batizada em homenagem a Kargath Carpunhal, chefe do clã Mão Despedaçada.\n\nPor ordem do próprio Chefe Guerreiro Thrall, a Força Expedicionária de Karrath parte vez após vez pelos Ermos inclementes. Seu verdadeiro propósito é abrir uma rota pela Garganta Abrasadora até a Montanha Rocha Negra, para que a Horda possa atacar Rend Mão Negra, Chefe Guerreiro da Horda Negra, em sua própria fortaleza. Esse caminho atravessa terras que os anões Ferro Negro consideram suas, e assim a Horda se viu de novo em guerra com eles, não por plano, mas pelo simples fato da terra que precisava atravessar.\n\nO outro valor de Karrath é mais fácil de ver: é a dobradiça entre o norte e o sul, o ponto onde a estrada que vem da Ruína do Martelo e da Cidade Baixa encontra a estrada que desce para Grom'gol, a Angra do Butim e Pedregal.",
			source = "https://warcraft.wiki.gg/wiki/Kargath",
		},
		["lethlor ravine"] = {
			name = "Ravina Lethlor",
			short = "A Ravina Lethlor corta larga e escarpada o leste dos Ermos, com o fundo assombrado por dragonetes e dracos da revoada negra.",
			full = "A Ravina Lethlor corta larga e escarpada o leste dos Ermos, com o fundo assombrado por dragonetes e dracos da revoada negra. Espalhados pela ravina erguem-se obeliscos cristalinos, estranhos e deliberados em meio à rocha e ao fogo dos dragões.",
			source = "https://warcraft.wiki.gg/wiki/Lethlor_Ravine",
		},
		["makers terrace"] = {
			name = "Terraço do Criador",
			short = "Diante da entrada de Uldaman, a terra foi descascada em cortes amplos e deliberados, uma cicatriz de escavação deixada a céu aberto.",
			full = "Diante da entrada de Uldaman, a terra foi descascada em cortes amplos e deliberados, uma cicatriz de escavação deixada a céu aberto. Os anões Ferro Negro ocupam o Terraço agora, vigiando as escavações e a estrada que desce para os lugares soterrados lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Maker's_Terrace",
		},
		["mirage flats"] = {
			name = "Chapada da Ilusão",
			short = "A Chapada da Ilusão fica a leste da Gruta Arrota-pó, nos Ermos. Pouco resta dela além de uma terra de ninguém, reivindicada apenas por urubus gigantes, patriarcas espreitadores da serra e coiotes raivosos dos penhascos.",
			full = "A Chapada da Ilusão fica a leste da Gruta Arrota-pó, nos Ermos. Pouco resta dela além de uma terra de ninguém, reivindicada apenas por urubus gigantes, patriarcas espreitadores da serra e coiotes raivosos dos penhascos.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Flats",
		},
		["uldaman"] = {
			name = "Uldaman",
			short = "Nas profundezas das montanhas de Khaz Modan fica Uldaman, uma vasta e antiga câmara erguida pelos guardiões titânicos em eras remotas.",
			full = "Nas profundezas das montanhas de Khaz Modan fica Uldaman, uma vasta e antiga câmara erguida pelos guardiões titânicos em eras remotas. Anões de Altaforja chegaram a escavá-la, abrindo caminho por suas câmaras soterradas antes da Terceira Guerra, mas desde então a câmara caiu nas mãos dos troggs e dos Ferro Negro, que agora cavam sua pedra em busca de quaisquer riquezas terrenas que ela ainda guarde.\n\nUldaman continua rica em vestígios daquela era forjada pelos titãs, e os que se arriscam em suas profundezas ainda encontram artefatos enterrados nela, lentamente desenterrados por arqueólogos e aventureiros da Liga dos Exploradores que continuam a vasculhar a ruína.",
			source = "https://warcraft.wiki.gg/wiki/Uldaman",
		},
		["valley of fangs"] = {
			name = "Vale das Presas",
			short = "O Vale das Presas corta estreito entre duas paredes de pedra nos Ermos, tomado por lobos e pumas cujos dentes dão nome ao lugar.",
			full = "O Vale das Presas corta estreito entre duas paredes de pedra nos Ermos, tomado por lobos e pumas cujos dentes dão nome ao lugar.\n\nNele acampa Martek, o Exilado, expulso de onde quer que um dia tenha pertencido, ao lado de Bertolezo e Jazzrik.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Fangs",
		},
	},
	-- Barreira do Inferno: 7 subzones
	[1419] = {
		["dark portal"] = {
			name = "Portal Negro",
			short = "A criação do portal foi uma traição desde o primeiro golpe. Gul'dan e o mago humano Medivh, este possuído pelo Titã Sombrio Sargeras, abriram juntos a fenda.",
			full = "A criação do portal foi uma traição desde o primeiro golpe. Gul'dan e o mago humano Medivh, este possuído pelo Titã Sombrio Sargeras, abriram juntos a fenda. Em Draenor, os pedreiros orcs que construíram sua moldura de pedra foram assassinados por bruxos para preparar o selo final, e quase todos os prisioneiros draeneis ainda em poder da Horda foram levados até sua base e tiveram a vida drenada num único instante, para dar a Gul'dan o poder de ligar os dois mundos. Por esse portal a Horda se despejou sobre Ventobravo e deu início à Primeira Guerra e, na guerra seguinte, ele alimentou Azeroth com orcs e ogros sem fim, enquanto os pântanos ao redor coalhavam no deserto vermelho-sangue mais tarde chamado de Barreira do Inferno.\n\nAo fim da guerra, o arquimago Khadgar e seus companheiros magos despedaçaram a estrutura do lado de Azeroth para impedir a retirada da Horda, numa explosão tão violenta que destruiu também a moldura em Draenor. Khadgar ergueu depois a Bastilha de Etergarde para vigiar as ruínas, embora a fenda entre os mundos jamais tenha sido realmente selada, e demônios voltariam a atravessá-la nos anos seguintes.",
			source = "https://warcraft.wiki.gg/wiki/Dark_Portal",
		},
		["dreadmaul post"] = {
			name = "Posto Malhorrendo",
			short = "O Posto Malhorrendo é um monte erguido pelo clã de ogros Malhorrendo, que atravessou de Draenor para Azeroth e nunca se afastou muito do Portal Negro.",
			full = "O Posto Malhorrendo é um monte erguido pelo clã de ogros Malhorrendo, que atravessou de Draenor para Azeroth e nunca se afastou muito do Portal Negro. Eles ainda ocupam o terreno.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Post",
		},
		["garrison armory"] = {
			name = "Armaria da Guarnição",
			short = "No solo marcado da Barreira do Inferno, mineiros da Aliança trabalham na Armaria da Guarnição, arrancando minérios da terra para a Bastilha de Etergarde.",
			full = "No solo marcado da Barreira do Inferno, mineiros da Aliança trabalham na Armaria da Guarnição, arrancando minérios da terra para a Bastilha de Etergarde. O que recolhem é enviado para Ventobravo e, em troca, a bastilha recebe os outros suprimentos de que precisa para resistir naquele lugar arrasado.",
			source = "https://warcraft.wiki.gg/wiki/Garrison_Armory",
		},
		["nethergarde keep"] = {
			name = "Bastilha de Etergarde",
			short = "A Bastilha de Etergarde fica num alto penhasco acima da única estrada que entra na Barreira do Inferno, com muralhas erguidas para vigiar uma cicatriz no mundo que ninguém queria ver aberta de novo.",
			full = "A Bastilha de Etergarde fica num alto penhasco acima da única estrada que entra na Barreira do Inferno, com muralhas erguidas para vigiar uma cicatriz no mundo que ninguém queria ver aberta de novo.\n\nO Arquimago Khadgar pediu sua construção nos anos que se seguiram à Segunda Guerra, quando o primeiro Portal Negro jazia destruído e as terras natais dos orcs além dele haviam definhado em ruínas. A Aliança de Lordaeron pagou por ela, alguns reinos com mais boa vontade que outros, e a Guilda dos Pedreiros a ergueu sob o comando de Edwin VanCleef. O Kirin Tor a guarneceu depois, trabalhando para conter a mácula que escapava da ferida do portal e ameaçava se espalhar pelas terras além.\n\nKhadgar continuou sendo seu senhor até que os clãs de Ner'zhul reconstruíram o Portal Negro do lado de Draenor e sitiaram a bastilha. Khadgar e seus companheiros Turalyon, Danath Matatroll, Alleria Correventos e Kurdran Martelo Feroz lideraram a Aliança através do portal para derrotar a Horda lá, e depois ficaram do outro lado para selá-lo, para que a ruína de Draenor não os seguisse até em casa. Por vinte anos depois disso, o portal permaneceu em silêncio.",
			source = "https://warcraft.wiki.gg/wiki/Nethergarde_Keep",
		},
		["rise of the defiler"] = {
			name = "Cerro do Profanador",
			short = "O Cerro do Profanador se ergue no meio da Barreira do Inferno, um trecho escarpado de montanha partida. Aqui habita o grande demônio Razelikh, cuja presença basta para dar nome ao lugar.",
			full = "O Cerro do Profanador se ergue no meio da Barreira do Inferno, um trecho escarpado de montanha partida. Aqui habita o grande demônio Razelikh, cuja presença basta para dar nome ao lugar.",
			source = "https://warcraft.wiki.gg/wiki/Rise_of_the_Defiler",
		},
		["serpents coil"] = {
			name = "Cavernas Serpeantes",
			short = "As Cavernas Serpeantes são um sistema de cavernas sinuosas no leste da Barreira do Inferno, com a entrada marcada por construções orcs incendiadas, restos da Segunda Guerra.",
			full = "As Cavernas Serpeantes são um sistema de cavernas sinuosas no leste da Barreira do Inferno, com a entrada marcada por construções orcs incendiadas, restos da Segunda Guerra. Muito depois do fim daquela guerra, as cavernas se tornaram o abrigo de algo mais sombrio: cultistas entregues à adoração de Kirith, o Maldito.\n\nPara dentro desse labirinto veio o Arquimago Allistarj, que pôs seus Juramentados das Sombras para trabalhar lá de dentro. Perto da entrada, um baú guarda um amuleto com seu nome.",
			source = "https://warcraft.wiki.gg/wiki/Serpent's_Coil",
		},
		["tainted scar"] = {
			name = "Rasgo Infecto",
			short = "O Rasgo Infecto já fez parte do Lamaçal Negro, antes que a corrupção do Portal Negro sangrasse sobre ele e deixasse o chão seco, sem árvores e vermelho como sangue.",
			full = "O Rasgo Infecto já fez parte do Lamaçal Negro, antes que a corrupção do Portal Negro sangrasse sobre ele e deixasse o chão seco, sem árvores e vermelho como sangue. Nenhuma água corre ali agora. Feras demoníacas rondam um solo que já não se lembra do que crescia nele.\n\nDepois da batalha no Monte Hyjal, o senhor ered'ruin Kazzak recolheu ao Rasgo o que restava das forças da Legião Ardente em Azeroth, fazendo dele seu território. Pôs seu tenente Razelikh, o Profanador, no comando, encarregando-o de manter a terra segura. O próprio Kazzak permaneceu ali depois, e sua presença bastava para marcar o Rasgo como território da Legião, anos depois de Hyjal ter sido disputado e vencido em outro lugar.\n\nUm velho bruxo humano, Daio, o Decrépito, chegou ao Rasgo muito tempo depois e fez morada junto a seu altar. Ali, entre os demônios que a terra já gerava, ele praticava seus rituais sem ser perturbado e acolhia jovens recrutas, ensinando-lhes as artes infernais num lugar já entregue à energia vil.",
			source = "https://warcraft.wiki.gg/wiki/Tainted_Scar",
		},
	},
	-- Clareiras de Tirisfal: 28 subzones
	[1420] = {
		["agamand family crypt"] = {
			name = "Cripta da Família Agamand",
			short = "Ao norte dos Moinhos dos Agamand, os mortos da família Agamand um dia repousaram nesta cripta. O Capitão Dargol, um lacaio do Flagelo, tomou o lugar para si e despertou cada cadáver e cada espírito que havia lá dentro.",
			full = "Ao norte dos Moinhos dos Agamand, os mortos da família Agamand um dia repousaram nesta cripta. O Capitão Dargol, um lacaio do Flagelo, tomou o lugar para si e despertou cada cadáver e cada espírito que havia lá dentro. Agora a poeira paira densa nas passagens escuras, e os mortos vingativos atacam qualquer um que entre sem ser convidado.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Family_Crypt",
		},
		["agamand mills"] = {
			name = "Moinhos dos Agamand",
			short = "Os moinhos de vento dos Agamand um dia giraram para uma das famílias mais ricas de Tirisfal. Quando o Flagelo veio para o norte, Gregor Agamand se recusou a fugir.",
			full = "Os moinhos de vento dos Agamand um dia giraram para uma das famílias mais ricas de Tirisfal. Quando o Flagelo veio para o norte, Gregor Agamand se recusou a fugir. Fortificou os moinhos, abasteceu-os para resistir a um cerco e convenceu os próprios trabalhadores da família a ficar e lutar ao lado deles.\n\nDeveria ter resistido. Não resistiu, porque a traição veio de dentro dos muros. Devlin, o filho mais novo dos Agamand, voltou-se contra o próprio sangue e ajudou o Flagelo, e a guarnição não conseguiu segurar a linha diante dos ataques que se seguiram. Com o tempo, a praga levou o resto da família de qualquer forma, e os Agamand que haviam morrido defendendo seu lar se ergueram de novo como mortos sem mente dentro dele.\n\nOs moinhos de vento ainda estão de pé nas terras altas do norte de Tirisfal, e a família que os construiu agora serve à mesma hoste que os destruiu.",
			source = "https://warcraft.wiki.gg/wiki/Agamand_Mills",
		},
		["balnir farmstead"] = {
			name = "Fazenda dos Balnir",
			short = "A Fazenda dos Balnir fica a nordeste da capital arruinada, com as cercas quebradas e os estábulos vazios, a não ser pelo Flagelo que vaga por ali.",
			full = "A Fazenda dos Balnir fica a nordeste da capital arruinada, com as cercas quebradas e os estábulos vazios, a não ser pelo Flagelo que vaga por ali.\n\nA família Balnir um dia administrou esta terra, criando os grandes cavalos brancos que a casa real de Lordaeron montava. No dia em que a Capital caiu, o Flagelo veio atrás da fazenda e matou a família inteira, deixando para trás apenas seu solo assombrado.\n\nAs bocas-de-leão que um dia foram cultivadas no jardim da fazenda ainda crescem selvagens ali, e chegou aos vivos a notícia de que a corrupção das Terras Pestilentas pode ter se infiltrado nelas. Os membros do Flagelo que escapam do Baluarte se reúnem em grande número em torno da fazenda arruinada.",
			source = "https://warcraft.wiki.gg/wiki/Balnir_Farmstead",
		},
		["brightwater lake"] = {
			name = "Lago Águas Claras",
			short = "O Lago Águas Claras fica a nordeste de Montalvo, e suas águas guardam uma grande ilha no centro, onde hoje fica o Refúgio de Tertuliano.",
			full = "O Lago Águas Claras fica a nordeste de Montalvo, e suas águas guardam uma grande ilha no centro, onde hoje fica o Refúgio de Tertuliano.",
			source = "https://warcraft.wiki.gg/wiki/Brightwater_Lake",
		},
		["brill"] = {
			name = "Montalvo",
			short = "Montalvo já foi uma cidade comum no reino de Lordaeron, pertencente à família Barov, com os Agamand mantendo uma casa senhorial própria dentro de seus limites.",
			full = "Montalvo já foi uma cidade comum no reino de Lordaeron, pertencente à família Barov, com os Agamand mantendo uma casa senhorial própria dentro de seus limites. Sua normalidade terminou no dia em que Kel'Thuzad chegou. Ainda vivo na época, o necromante escolheu Montalvo como o lugar para testar pela primeira vez a praga da morte-vida, e o sucesso dessa infestação foi tão completo que o encorajou a pressionar o Lich Rei a lançar a invasão de Lordaeron antes da hora. Os mortos das Clareiras de Tirisfal eram mais do que a terra conseguia enterrar como devia; o grande cemitério fora das muralhas de Montalvo é a resposta a esse excedente. Os próprios defensores da cidade não conseguiram mantê-la, e os sobreviventes que restaram fugiram para se juntar ao Príncipe Arthas Menethil enquanto ele caçava a origem da corrupção que varria o norte.\n\nMontalvo não ficou em silêncio. Anos depois, os Renegados a tomaram, e o Magistrado Sevren agora governa o que a praga um dia levou. Velhos rancores também persistem aqui: Eurico Palhares, que um dia serviu à família Agamand, ainda busca seus restos, ossos entregues não por misericórdia, mas por vingança por uma morte da qual ele os culpa.",
			source = "https://warcraft.wiki.gg/wiki/Brill",
		},
		["brill town hall"] = {
			name = "Prefeitura de Montalvo",
			short = "A Prefeitura é a construção mais imponente de Montalvo. De seu púlpito, o Magistrado Sevren fala pela cidade, pondo os mortos de Tirisfal a trabalhar em suas tarefas.",
			full = "A Prefeitura é a construção mais imponente de Montalvo. De seu púlpito, o Magistrado Sevren fala pela cidade, pondo os mortos de Tirisfal a trabalhar em suas tarefas. Poucos salões como este, em qualquer lugar, estão nas mãos dos Renegados como este está, sinal de quão firmemente Montalvo lhes pertence.",
			source = "https://warcraft.wiki.gg/wiki/Brill_Town_Hall",
		},
		["bulwark"] = {
			name = "O Baluarte",
			short = "O Baluarte fica onde as Clareiras de Tirisfal encontram as Terras Pestilentas Ocidentais, a linha que os Renegados mantêm contra o Flagelo que ainda se concentra a leste.",
			full = "O Baluarte fica onde as Clareiras de Tirisfal encontram as Terras Pestilentas Ocidentais, a linha que os Renegados mantêm contra o Flagelo que ainda se concentra a leste. Aqui, os defensores Renegados e a Aurora Argêntea deixaram de lado suas diferenças diante desse inimigo comum, vigiando juntos a fronteira e enviando combatentes para o leste para atacar os lacaios do Lich Rei.\n\nAo contrário do resto de Tirisfal, este trecho não se parece em nada com as Clareiras: uma névoa pestilenta paira sobre ele, tingindo o céu do mesmo cinza-amarelado doentio das Terras Pestilentas Ocidentais mais além.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["cold hearth manor"] = {
			name = "Casarão Lar Glacial",
			short = "O Casarão Lar Glacial um dia fez jus ao nome pelo calor de sua lareira e pela fartura de seus campos. A Praga da Morte-vida acabou com isso.",
			full = "O Casarão Lar Glacial um dia fez jus ao nome pelo calor de sua lareira e pela fartura de seus campos. A Praga da Morte-vida acabou com isso. Todos os que viviam ou trabalhavam aqui morreram na doença, e o solo fértil se tornou estéril, com suas fileiras tomadas por mortos sem mente do Flagelo que ainda cambaleiam por ali.\n\nOs Renegados tomaram a casa da fazenda para si e fazem negócios com os viajantes da estrada próxima.",
			source = "https://warcraft.wiki.gg/wiki/Cold_Hearth_Manor",
		},
		["crusader outpost"] = {
			name = "Guarita dos Cruzados",
			short = "Uma torre de observação se ergue nas colinas do leste das Clareiras de Tirisfal, ocupada pela Cruzada Escarlate.",
			full = "Uma torre de observação se ergue nas colinas do leste das Clareiras de Tirisfal, ocupada pela Cruzada Escarlate. De sua altura, eles vigiam a estrada que segue para o sul pelas clareiras, prontos para flanquear qualquer força que ouse marchar sobre o Monastério Escarlate mais além. O Capitão Vachon comanda aqui.",
			source = "https://warcraft.wiki.gg/wiki/Crusader_Outpost",
		},
		["deathknell"] = {
			name = "Plangemortis",
			short = "Plangemortis fica num vale estreito e bem guardado, e é aqui que os Renegados recém-erguidos abrem os olhos pela primeira vez para o mundo que lhes foi dado.",
			full = "Plangemortis fica num vale estreito e bem guardado, e é aqui que os Renegados recém-erguidos abrem os olhos pela primeira vez para o mundo que lhes foi dado.\n\nAo contrário das outras posses dos mortos-vivos rebeldes da Rainha Banshee, que mantiveram os nomes que tinham quando eram cidades dos vivos, Plangemortis recebeu um nome inteiramente novo, adequado ao que acontece ali, e não ao que um dia existiu ali. Ninguém mais se lembra por quê.\n\nA sobrevivência aqui é uma luta diária, e o ouro é a coisa mais escassa de todas. A noroeste da aldeia fica uma mina rica em metal, mas ela foi tomada por aranhas, e os mortos de Plangemortis saem vez após vez para tentar limpá-la, para que o minério lá embaixo possa finalmente ser extraído. Necroguardas de Elite montam guarda ao longo das bordas do vale, a única coisa entre os frágeis novos mortos e o Flagelo e a Cruzada Escarlate, que acabariam com eles pela segunda vez.",
			source = "https://warcraft.wiki.gg/wiki/Deathknell",
		},
		["faols rest"] = {
			name = "Repouso de Faol",
			short = "A sudoeste do Monastério Escarlate, no leste das Clareiras de Tirisfal, fica um pedaço de terra um dia cuidado por enlutados: o Repouso de Faol, o túmulo do Arcebispo Alonsus Faol.",
			full = "A sudoeste do Monastério Escarlate, no leste das Clareiras de Tirisfal, fica um pedaço de terra um dia cuidado por enlutados: o Repouso de Faol, o túmulo do Arcebispo Alonsus Faol.\n\nFaol foi reverenciado em vida, e sua morte, algum tempo antes da chegada do Flagelo, atraiu enlutados a este lugar.\n\nO túmulo que ele deixou já não recebe visitas. Os enlutados que antes vinham se foram, e o terreno está abandonado, quase esquecido.",
			source = "https://warcraft.wiki.gg/wiki/Faol's_Rest",
		},
		["gallows end tavern"] = {
			name = "Taberna Finda Forca",
			short = "A Taberna Finda Forca fica em Montalvo, com um nome que é um eco sombrio da cidade a que serve.",
			full = "A Taberna Finda Forca fica em Montalvo, com um nome que é um eco sombrio da cidade a que serve. Sob seu assoalho, os porões não guardam barris dignos de nota: um Zelote Escarlate capturado e um Montanhista anão são mantidos ali, prisioneiros dos Renegados.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_End_Tavern",
		},
		["garrens haunt"] = {
			name = "Sítio dos Garren",
			short = "O Sítio dos Garren já foi uma fazenda farta no norte das Clareiras de Tirisfal, com campos amplos e silos cheios. A Praga da Morte-vida acabou com isso.",
			full = "O Sítio dos Garren já foi uma fazenda farta no norte das Clareiras de Tirisfal, com campos amplos e silos cheios. A Praga da Morte-vida acabou com isso. Quando o Flagelo varreu a região na Flagelação de Lordaeron, Garren e sua família foram massacrados onde viviam, e a própria terra ficou cinzenta e sem vida ao redor de seu lar arruinado.\n\nO que restou de pé foi tomado pelos gnolls Couro-podre, liderados por Maggot Eye, que tomaram a casa e o celeiro para si e atacavam sem hesitar qualquer um que se aproximasse demais.\n\nA fazenda nunca se recuperou. Está abandonada, com os campos vazios e a família extinta, e só os gnolls restam para responder por quem a ocupa agora.",
			source = "https://warcraft.wiki.gg/wiki/Garren's_Haunt",
		},
		["gunthers retreat"] = {
			name = "Refúgio de Tertuliano",
			short = "Numa ilha do Lago Águas Claras fica o Refúgio de Tertuliano, tomado pelo lich Renegado Tertuliano Arcanus e seus lacaios zumbis.",
			full = "Numa ilha do Lago Águas Claras fica o Refúgio de Tertuliano, tomado pelo lich Renegado Tertuliano Arcanus e seus lacaios zumbis. Ao largo de sua margem sudoeste, numa ilhota nua e sem nome, fica um estranho marco conhecido apenas como a Mesa de Jantar de Lillith.",
			source = "https://warcraft.wiki.gg/wiki/Gunther's_Retreat",
		},
		["night webs hollow"] = {
			name = "Vale Teia da Noite",
			short = "O Vale Teia da Noite é um pequeno vale atravessado por uma antiga mina de ouro, ambos tomados por aranhas. As jovens vagam pelo vale aberto, enquanto as Aranhas Teia da Noite adultas ocupam os túneis mais escuros da mina.",
			full = "O Vale Teia da Noite é um pequeno vale atravessado por uma antiga mina de ouro, ambos tomados por aranhas. As jovens vagam pelo vale aberto, enquanto as Aranhas Teia da Noite adultas ocupam os túneis mais escuros da mina.\n\nOs Renegados recém-erguidos vêm até aqui para testar do que seus corpos ainda são capazes, abatendo as aranhas jovens do lado de fora antes de se arriscarem na própria mina.\n\nEm seu recanto mais profundo fica a Matriarca Teia da Noite, mãe do enxame acima dela.",
			source = "https://warcraft.wiki.gg/wiki/Night_Web's_Hollow",
		},
		["nightmare vale"] = {
			name = "Vale do Pesadelo",
			short = "A oeste da Torre de Vigia Escarlate, nas Clareiras de Tirisfal, fica um vale em ruínas. Suas árvores definharam, e os animais que antes viviam entre elas foram devorados por cães das trevas e enormes morcegos-vampiros.",
			full = "A oeste da Torre de Vigia Escarlate, nas Clareiras de Tirisfal, fica um vale em ruínas. Suas árvores definharam, e os animais que antes viviam entre elas foram devorados por cães das trevas e enormes morcegos-vampiros. Entre esses caçadores voa Ressan, o Agulhador, um raro morcego branco diferente dos demais.",
			source = "https://warcraft.wiki.gg/wiki/Nightmare_Vale",
		},
		["north coast"] = {
			name = "Costa Norte",
			short = "A Costa Norte se estende onde as Clareiras de Tirisfal encontram o Grande Mar, entregue agora aos murlocs e às criaturas da água.",
			full = "A Costa Norte se estende onde as Clareiras de Tirisfal encontram o Grande Mar, entregue agora aos murlocs e às criaturas da água. Desde a Praga da Morte-vida, o litoral ficou escuro e frio, e a maré deixa criaturas marinhas mortas apodrecendo na beira da água.",
			source = "https://warcraft.wiki.gg/wiki/North_Coast",
		},
		["ruins of lordaeron"] = {
			name = "Ruínas de Lordaeron",
			short = "Acima da cidade soterrada, o palácio de Lordaeron ainda está de pé, com seus salões abertos para o céu e seus jardins em ruínas. Aqui morreu o grande reino da Aliança, e aqui seus fantasmas nunca partiram de todo.",
			full = "Acima da cidade soterrada, o palácio de Lordaeron ainda está de pé, com seus salões abertos para o céu e seus jardins em ruínas. Aqui morreu o grande reino da Aliança, e aqui seus fantasmas nunca partiram de todo.\n\nFoi Arthas Menethil quem pôs fim a ele. O príncipe voltou para casa à frente de um exército erguido contra seu próprio povo, recebido por estes portões com sinos e aplausos antes que alguém entendesse no que ele havia se transformado. Encontrou seu pai, o Rei Terenas, à sua espera na sala do trono e o matou ali mesmo. De pé sobre o corpo, pronunciou palavras que ainda ecoam naquela sala para quem se demora ali: que o reino cairia e que, de suas cinzas, uma nova ordem surgiria para abalar o mundo. Não era bravata. Em poucos dias, a cidade e seu povo foram massacrados, e Lordaeron passou a pertencer ao Flagelo.\n\nDizem que quem ainda caminha pelo pátio pode ouvir o que a pedra se lembra: vozes abafadas, o repicar dos sinos de boas-vindas, um murmúrio vindo da sala do trono que nunca se apaga de todo. Os que conseguem ver além do véu dizem que os cidadãos de Lordaeron ainda caminham por ali, sem saber que seu reino já não existe.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
		["scarlet monastery"] = {
			name = "Monastério Escarlate",
			short = "Sob a Cruzada, o Antigo Monastério se tornou quartel e prisão. A Inquisidora Whitemane e Renault Mograine fizeram dele sua sede, e sua capela se tornou um lugar de julgamento, além de oração.",
			full = "Sob a Cruzada, o Antigo Monastério se tornou quartel e prisão. A Inquisidora Whitemane e Renault Mograine fizeram dele sua sede, e sua capela se tornou um lugar de julgamento, além de oração.\n\nAntes de ser uma fortaleza, o Antigo Monastério era uma catedral da Igreja da Luz Sagrada, repleta de bibliotecas onde os paladinos treinavam. O próprio Alexandros Mograine passou meses ali na juventude, rezando e estudando antes mesmo de empunhar uma lâmina.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Monastery",
		},
		["scarlet watch post"] = {
			name = "Posto da Vigília Escarlate",
			short = "O Posto da Vigília Escarlate monta guarda sobre o acesso que o Monastério Escarlate não consegue defender sozinho. O Capitão Melrache comanda aqui, defendendo o posto contra qualquer um que queira atacar sem ser visto o flanco exposto do monastério.",
			full = "O Posto da Vigília Escarlate monta guarda sobre o acesso que o Monastério Escarlate não consegue defender sozinho. O Capitão Melrache comanda aqui, defendendo o posto contra qualquer um que queira atacar sem ser visto o flanco exposto do monastério.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Watch_Post",
		},
		["shadow grave"] = {
			name = "Sepulcro Sombrio",
			short = "O Sepulcro Sombrio fica no alto da encosta, dentro dos Túmulos de Plangemortis, no alto das montanhas de Tirisfal. Uma trilha gasta desce serpenteando de sua entrada até Plangemortis, lá embaixo.",
			full = "O Sepulcro Sombrio fica no alto da encosta, dentro dos Túmulos de Plangemortis, no alto das montanhas de Tirisfal. Uma trilha gasta desce serpenteando de sua entrada até Plangemortis, lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Grave",
		},
		["solliden farmstead"] = {
			name = "Fazenda dos Solliden",
			short = "As plantações de abóbora dos Solliden são um dos poucos pedaços de terra em Tirisfal onde a vida antiga não foi engolida pela praga ou pela morte-vida.",
			full = "As plantações de abóbora dos Solliden são um dos poucos pedaços de terra em Tirisfal onde a vida antiga não foi engolida pela praga ou pela morte-vida. Enquanto a região ao redor caiu diante do Flagelo e depois dos Renegados que dele se ergueram, os fazendeiros daqui ainda trabalham suas fileiras, mantidos a salvo sob a vigilância da Cruzada Escarlate na vizinha Paliçada Escarlate.\n\nEssa proteção fez da Fazenda dos Solliden uma raridade. Os fazendeiros não confiam em ninguém que não seja Escarlate, rechaçando os Renegados como abominações da praga que quase os levou, e desconfiam também da Aliança, cujos estandartes poderiam arrastá-los para uma guerra da qual até agora escaparam por se manterem pequenos e esquecidos.\n\nÉ essa quietude que os Renegados não conseguem deixar em paz. O Necroguarda Simério vigia a Fazenda dos Solliden não pelo que ela é agora, mas pelo que pode vir a ser: fazendeiros pacíficos hoje, arrendatários armados da Aliança amanhã, um ponto de apoio numa terra que os Renegados pretendem manter.",
			source = "https://warcraft.wiki.gg/wiki/Solliden_Farmstead",
		},
		["stillwater pond"] = {
			name = "Lagoa das Águas Paradas",
			short = "Antes da praga, a Lagoa das Águas Paradas era um lugar onde os vivos podiam ser jovens.",
			full = "Antes da praga, a Lagoa das Águas Paradas era um lugar onde os vivos podiam ser jovens. Famílias das clareiras vinham fazer piquenique em suas margens, e crianças pequenas demais para se arriscar nas águas mais fundas do Lago Águas Claras aprendiam a nadar aqui.\n\nEssa água agora é cinzenta. Os peixes sob a superfície são apenas ossos que ainda nadam, como se ninguém lhes tivesse dito para parar. Mortos-vivos errantes e feras selvagens passam pela margem, e o cão das trevas Bayne ronda a beira da água, alimentando-se de qualquer coisa desavisada o bastante para se demorar ali.\n\nQuando os Renegados começaram a reerguer Montalvo de suas ruínas, guerreiros Escarlates já patrulhavam a margem da Lagoa das Águas Paradas.",
			source = "https://warcraft.wiki.gg/wiki/Stillwater_Pond",
		},
		["terrace of repose"] = {
			name = "Terraço do Repouso",
			short = "Logo ao norte do Monastério Escarlate fica um terreno que a praga jamais tocou. Sebes verdes crescem aqui, e uma fonte corre límpida em vez de estagnada, ao contrário do resto das Clareiras de Tirisfal.",
			full = "Logo ao norte do Monastério Escarlate fica um terreno que a praga jamais tocou. Sebes verdes crescem aqui, e uma fonte corre límpida em vez de estagnada, ao contrário do resto das Clareiras de Tirisfal. A Cruzada Escarlate cuida dele, mantendo vivo este pequeno terraço como prova de que algo puro ainda pode resistir em meio à praga.",
			source = "https://warcraft.wiki.gg/wiki/Terrace_of_Repose",
		},
		["venomweb vale"] = {
			name = "Vale Veneracnídeo",
			short = "O Vale Veneracnídeo já foi verde, repleto de cervos e coelhos, antes de se tornar o que é hoje: um vale tomado por aranhas venenosas, lideradas pela rara e mortal Sri'skulk, cujas teias substituíram o capim e deram nome ao vale.",
			full = "O Vale Veneracnídeo já foi verde, repleto de cervos e coelhos, antes de se tornar o que é hoje: um vale tomado por aranhas venenosas, lideradas pela rara e mortal Sri'skulk, cujas teias substituíram o capim e deram nome ao vale. Cães das trevas rondam o norte, perto do Acampamento Escarlate, comandado pelo Tenente Sanders.",
			source = "https://warcraft.wiki.gg/wiki/Venomweb_Vale",
		},
		["whispering gardens"] = {
			name = "Jardins Murmurantes",
			short = "Na colina ao sul do Monastério Escarlate, travou-se certa vez uma batalha entre os homens que viriam a formar a Cruzada Escarlate e uma hoste do Flagelo.",
			full = "Na colina ao sul do Monastério Escarlate, travou-se certa vez uma batalha entre os homens que viriam a formar a Cruzada Escarlate e uma hoste do Flagelo. Muitos caíram dos dois lados. No crepúsculo, seus espíritos ainda se demoram ali, murmurando como sussurros tênues entre as pedras silenciosas do jardim.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Gardens",
		},
		["whispering shore"] = {
			name = "Praia Sibilante",
			short = "A Praia Sibilante fica no oeste das Clareiras de Tirisfal, ao norte da Fazenda dos Solliden. Os pescadores um dia preferiam suas águas calmas e sua pesca farta.",
			full = "A Praia Sibilante fica no oeste das Clareiras de Tirisfal, ao norte da Fazenda dos Solliden. Os pescadores um dia preferiam suas águas calmas e sua pesca farta.\n\nEssa fartura acabou. Murlocs tomaram a praia, atacando qualquer um que se aproxime, e a água ficou fria e escura.",
			source = "https://warcraft.wiki.gg/wiki/Whispering_Shore",
		},
	},
	-- Floresta de Pinhaprata: 22 subzones
	[1421] = {
		["ambermill"] = {
			name = "Lenhâmbar",
			short = "Lenhâmbar já foi uma cidade madeireira sem importância, cortando madeira a sudoeste do Espelho de Lordaeron, na Floresta de Pinhaprata.",
			full = "Lenhâmbar já foi uma cidade madeireira sem importância, cortando madeira a sudoeste do Espelho de Lordaeron, na Floresta de Pinhaprata.\n\nO Flagelo e a Legião Ardente mudaram o valor da cidade. O Kirin Tor de Dalaran, reconstruindo-se depois da própria ruína, ocupou a cidade e, por um tempo, Lenhâmbar se tornou algo que nunca havia sido: um foco de verdadeira resistência humana na Floresta de Pinhaprata, sustentado pela magia de Dalaran.\n\nOs Renegados não deixaram isso passar sem vigilância. Seus Sicários descobriram, por meio de um prisioneiro, que os magos guardam ali documentos sobre a situação da própria Dalaran. As serrarias, os estábulos e a prefeitura continuam nas mãos do Kirin Tor, enquanto espiões agem contra eles das sombras da floresta.",
			source = "https://warcraft.wiki.gg/wiki/Ambermill",
		},
		["berens peril"] = {
			name = "Cilada de Beren",
			short = "Nas colinas a sudoeste de Lenhâmbar fica a Cilada de Beren.",
			full = "Nas colinas a sudoeste de Lenhâmbar fica a Cilada de Beren. Anos depois da Terceira Guerra, batedores Renegados levaram ao Sacerdote Sombrio Allister a notícia de que mortos-vivos haviam se reunido ali em segredo, concentrando-se para um ataque contra o Sepulcro. Os mortos-vivos serviam ao necromante Thule Ravenclaw, que escolhera o lugar para reunir seus servos sem ser visto, perto o bastante para ameaçar o Sepulcro e longe o bastante da estrada para passar despercebido.",
			source = "https://warcraft.wiki.gg/wiki/Beren's_Peril",
		},
		["dawning isles"] = {
			name = "Ilhas da Aurora",
			short = "As Ilhas da Aurora um dia se erguiam suaves e baixas das águas cristalinas do Espelho de Lordaeron, ilhotas tranquilas que os problemas não tocavam. A Praga da Morte-vida mudou isso.",
			full = "As Ilhas da Aurora um dia se erguiam suaves e baixas das águas cristalinas do Espelho de Lordaeron, ilhotas tranquilas que os problemas não tocavam. A Praga da Morte-vida mudou isso. Suas árvores adoeceram, e murlocs e monstros do brejo tomaram as ilhotas. Os monstros do brejo já se foram, mas os murlocs Barbatana Vil se reproduziram sem controle e agora dominam as ilhas por completo.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Isles",
		},
		["dead field"] = {
			name = "Campo Morto",
			short = "O Campo Morto está abandonado no norte da Floresta de Pinhaprata, com os campos apodrecidos e seus antigos moradores esquecidos.",
			full = "O Campo Morto está abandonado no norte da Floresta de Pinhaprata, com os campos apodrecidos e seus antigos moradores esquecidos. O que se sabe é o que o tomou desde então: os gnolls Couro-podre, presos ao serviço do Flagelo, que fizeram da fazenda arruinada sua base, com seus números crescendo numa concentração que sugere algum ataque ainda sendo preparado aqui.\n\nOs Renegados atacaram a fazenda mais de uma vez, na esperança de derrotar os gnolls antes que eles possam agir. Todas as tentativas fracassaram. Sempre que os Couro-podre são ameaçados, uma banshee atende a seu chamado, um espírito chamado Nightlash que comanda os gnolls como se fossem seus, surgindo do nada para defendê-los.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Field",
		},
		["decrepit ferry"] = {
			name = "Campos Apodrecidos",
			short = "A balsa, hoje em ruínas nos Campos Apodrecidos, um dia levava o comércio até a Ilha de Fenris, onde um lorde e sua família mantinham sua casa senhorial, pagando ao balseiro algumas moedas por viagem.",
			full = "A balsa, hoje em ruínas nos Campos Apodrecidos, um dia levava o comércio até a Ilha de Fenris, onde um lorde e sua família mantinham sua casa senhorial, pagando ao balseiro algumas moedas por viagem.\n\nEntão o Flagelo desceu sobre Lordaeron. O balseiro foi morto onde trabalhava, e sua balsa, despedaçada.\n\nAgora carniçais, guerreiros esqueléticos e gnolls Couro-podre assombram o cais arruinado, e a travessia está abandonada, perigosa para qualquer um que não seja forte.",
			source = "https://warcraft.wiki.gg/wiki/Decrepit_Ferry",
		},
		["deep elem mine"] = {
			name = "Mina Elenfunda",
			short = "A Mina Elenfunda fica na Floresta de Pinhaprata. Arugal deixou sua magia se espalhar por ela, e os worgens fizeram da mina seu covil, liderados por Grimson, o Pálido, que um dia foi o encarregado ali.",
			full = "A Mina Elenfunda fica na Floresta de Pinhaprata. Arugal deixou sua magia se espalhar por ela, e os worgens fizeram da mina seu covil, liderados por Grimson, o Pálido, que um dia foi o encarregado ali.\n\nDalar Tessalba buscava a morte de Grimson, para que os Renegados pudessem tomar a mina como recurso próprio, em nome de Varimathras.",
			source = "https://warcraft.wiki.gg/wiki/Deep_Elem_Mine",
		},
		["fenris isle"] = {
			name = "Ilha de Fenris",
			short = "A Ilha de Fenris fica no meio do Espelho de Lordaeron, parte de um anel partido de terra firme que ela divide com as Ilhas da Aurora, e é considerada, de modo vago, parte da Floresta de Pinhaprata.",
			full = "A Ilha de Fenris fica no meio do Espelho de Lordaeron, parte de um anel partido de terra firme que ela divide com as Ilhas da Aurora, e é considerada, de modo vago, parte da Floresta de Pinhaprata.\n\nAntes da Terceira Guerra, a ilha abrigava o Castelo Fenris, um posto militar de Lordaeron. Quando o Flagelo varreu a terra, o castelo caiu. Seu povo fugiu ou foi morto onde estava, e a ilha ficou vazia.\n\nNesse vazio chegaram os gnolls Couro-podre, que tomaram o castelo abandonado como seu covil. Seu senhor era Thule Ravenclaw, lembrado como traiçoeiro até mesmo entre gnolls, que governa os Couro-podre e, por meio deles, toda a Ilha de Fenris, mantendo o castelo que reivindicou e também a balsa dos Campos Apodrecidos, ali perto.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Isle",
		},
		["fenris keep"] = {
			name = "Castelo Fenris",
			short = "O Castelo Fenris fica no centro do Espelho de Lordaeron, sobre a Ilha de Fenris, na Floresta de Pinhaprata, e um dia abrigou uma parte considerável das forças militares de Lordaeron.",
			full = "O Castelo Fenris fica no centro do Espelho de Lordaeron, sobre a Ilha de Fenris, na Floresta de Pinhaprata, e um dia abrigou uma parte considerável das forças militares de Lordaeron.\n\nQuando o Flagelo varreu a terra, o castelo caiu junto com ela. Para a ruína veio Thule Ravenclaw, um jovem mago que um dia pertenceu ao Kirin Tor, que se aliou ao Flagelo e submeteu os gnolls da ilha à sua vontade, transformando-os nos Couro-podre. Com essa tribo às suas costas, fez-se senhor do Castelo Fenris, e os Couro-podre caem sobre qualquer um que se aproxime de seu senhor.",
			source = "https://warcraft.wiki.gg/wiki/Fenris_Keep",
		},
		["greymane wall"] = {
			name = "Muralha Greymane",
			short = "O Rei Genn Greymane ergueu sua muralha antes da Terceira Guerra, cansado de ver o dinheiro guilneano gasto com os campos de internação de orcs e desgastado pelas desavenças que dividiam os reis da Aliança de Lordaeron.",
			full = "O Rei Genn Greymane ergueu sua muralha antes da Terceira Guerra, cansado de ver o dinheiro guilneano gasto com os campos de internação de orcs e desgastado pelas desavenças que dividiam os reis da Aliança de Lordaeron. Voltou seu reino para dentro, isolando Guilnéas de Lordaeron e do mundo além das montanhas.\n\nA muralha resistiu à Praga da Morte-vida, mas a um preço. Enquanto o Flagelo varria Lordaeron, refugiados fugiram para o sul e acamparam diante dos portões, e durante anos os portões não se abriram. Os refugiados pereceram ali, sem resposta.",
			source = "https://warcraft.wiki.gg/wiki/Greymane_Wall",
		},
		["ivar patch"] = {
			name = "Plantação do Ivar",
			short = "A Plantação do Ivar já foi uma fazenda que valia a pena ter, com fileiras carregadas de abóboras e uma casa cheia de empregados que trabalhavam nos campos para um homem chamado Ivar.",
			full = "A Plantação do Ivar já foi uma fazenda que valia a pena ter, com fileiras carregadas de abóboras e uma casa cheia de empregados que trabalhavam nos campos para um homem chamado Ivar. Era um bom sustento, até que a Praga da Morte-vida desceu sobre Lordaeron e o tirou dele.\n\nIvar não simplesmente morreu. Ele se ergueu, e o mesmo aconteceu com sua família e com cada empregado que havia trabalhado em sua terra, todos transformados em carniçais apodrecidos que agora caem sobre qualquer um que se aproxime. O próprio Ivar se ergueu como algo pior, lembrado agora como Ivar, o Imundo.\n\nTrês sicários enviados para o norte para avaliar o perigo foram surpreendidos aqui pelos carniçais, e Ivar, o Imundo, feriu um deles, Quintino Yorick, antes que Quintino e sua parente Rane se entrincheirassem dentro da velha casa de Ivar.",
			source = "https://warcraft.wiki.gg/wiki/Ivar_Patch",
		},
		["lordamere lake"] = {
			name = "Espelho de Lordaeron",
			short = "O Espelho de Lordaeron se estende sob a sombra de reinos que um dia chamaram suas margens de lar.",
			full = "O Espelho de Lordaeron se estende sob a sombra de reinos que um dia chamaram suas margens de lar. Lordaeron se erguia em sua margem norte, e é muito provável que o lago tenha recebido o nome daquela grande cidade, ela própria batizada em homenagem ao velho Lordain. Dalaran e Alterac também prosperavam ao redor de suas águas nos tempos em que a Aliança de Lordaeron unia os reinos humanos.\n\nEssa era passou, e o que resta é uma fronteira. O lago agora fica entre as posses dos Renegados nas Clareiras de Tirisfal e na Floresta de Pinhaprata e as disputadas Montanhas de Alterac, separando os mortos dos vivos.\n\nEm seu coração fica a Ilha de Fenris, com seu castelo ocupado pelos gnolls Couro-podre sob o comando de Thule Ravenclaw.\n\nA leste da Ilha de Fenris, entre as pequenas Ilhas da Aurora, os murlocs Barbatana Vil fizeram sua reivindicação, tomando-as por completo.",
			source = "https://warcraft.wiki.gg/wiki/Lordamere_Lake",
		},
		["maldens orchard"] = {
			name = "Horto dos Maldonado",
			short = "As árvores do Horto dos Maldonado ficaram escuras e sempre-verdes, com seus frutos pendendo sem colheita estação após estação. O próprio Maldonado há muito se foi, expulso de seu lar quando o Flagelo desceu sobre Lordaeron.",
			full = "As árvores do Horto dos Maldonado ficaram escuras e sempre-verdes, com seus frutos pendendo sem colheita estação após estação. O próprio Maldonado há muito se foi, expulso de seu lar quando o Flagelo desceu sobre Lordaeron.\n\nAgora o horto pertence aos lobos, que se entocam em grande número entre as árvores e ao redor do único chalé pequeno que ainda está de pé ali. Foi nisso que o Sicário Orlando McKree se meteu, enviado para explorar o horto durante um reconhecimento do norte da floresta. Os lobos o encurralaram antes que ele fosse muito longe, e ele se entrincheirou dentro do chalé abandonado, preso ali por dias, até que outros agentes Renegados o ajudaram a escapar e voltar para seus parceiros, que o esperavam.",
			source = "https://warcraft.wiki.gg/wiki/Malden's_Orchard",
		},
		["north tides hollow"] = {
			name = "Atracadouro da Maré do Norte",
			short = "O Atracadouro da Maré do Norte fica logo ao norte do Sepulcro, na Floresta de Pinhaprata. É um dos muitos redutos dos worgens Lunafúria, servos do Arquimago Arugal.",
			full = "O Atracadouro da Maré do Norte fica logo ao norte do Sepulcro, na Floresta de Pinhaprata. É um dos muitos redutos dos worgens Lunafúria, servos do Arquimago Arugal. Aqui eles erguem acampamentos rústicos, com nada além do mínimo necessário para a sobrevivência, abrigo suficiente para criaturas que vivem de dentes e força.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Hollow",
		},
		["north tides run"] = {
			name = "Costa da Maré do Norte",
			short = "O litoral noroeste da Floresta de Pinhaprata, onde a praia encontra o frio Grande Mar, leva o nome de Costa da Maré do Norte.",
			full = "O litoral noroeste da Floresta de Pinhaprata, onde a praia encontra o frio Grande Mar, leva o nome de Costa da Maré do Norte. Meio afundado nos baixios jaz um navio destroçado da Horda, com o casco assentado na arrebentação, a marca mais visível deste trecho da costa.",
			source = "https://warcraft.wiki.gg/wiki/North_Tide's_Run",
		},
		["olsens farthing"] = {
			name = "Miséria de Olsen",
			short = "A Miséria de Olsen ficava à beira das rotas comerciais que atravessavam a Floresta de Pinhaprata, uma fazenda produtiva cujos campos alimentavam o movimento de passagem.",
			full = "A Miséria de Olsen ficava à beira das rotas comerciais que atravessavam a Floresta de Pinhaprata, uma fazenda produtiva cujos campos alimentavam o movimento de passagem.\n\nA Terceira Guerra acabou com isso. Em poucos anos, a fazenda estava em ruínas.",
			source = "https://warcraft.wiki.gg/wiki/Olsen's_Farthing",
		},
		["pyrewood village"] = {
			name = "Vilarejo Lenhardente",
			short = "O Vilarejo Lenhardente fica na borda da Floresta de Pinhaprata, um aglomerado de humanos que sobreviveu à primeira chegada do Flagelo durante a Terceira Guerra.",
			full = "O Vilarejo Lenhardente fica na borda da Floresta de Pinhaprata, um aglomerado de humanos que sobreviveu à primeira chegada do Flagelo durante a Terceira Guerra. Ao norte fica uma bastilha que um dia pertenceu ao Barão Silverlaine, guardada pelo paladino Comandante Springvale e pelo Punho de Prata. Silverlaine e seus homens foram massacrados pelos worgens do Arquimago Arugal, que tomou a bastilha para si e a rebatizou de Bastilha da Presa Negra. De lá, Arugal voltou sua loucura contra o próprio Lenhardente, amaldiçoando seu povo para que toda noite se transformasse em worgens Lunafúria babando de fúria, que atacam qualquer um que cruze seu caminho, apenas para despertar humanos outra vez ao amanhecer.\n\nApesar disso, o vilarejo ainda abre suas portas aos viajantes durante o dia, com seu povo preso à maldição que Arugal lançou sobre ele, sem fim à vista.",
			source = "https://warcraft.wiki.gg/wiki/Pyrewood_Village",
		},
		["sepulcher"] = {
			name = "O Sepulcro",
			short = "O Sepulcro fica acima do litoral de Lordaeron, nas colinas do oeste da Floresta de Pinhaprata, onde uma estrada um dia cruzava um cemitério simples, cujas criptas não marcavam nada além de um local de descanso para os mortos.",
			full = "O Sepulcro fica acima do litoral de Lordaeron, nas colinas do oeste da Floresta de Pinhaprata, onde uma estrada um dia cruzava um cemitério simples, cujas criptas não marcavam nada além de um local de descanso para os mortos.\n\nDepois da Terceira Guerra, os Renegados tomaram o velho cemitério e o converteram em base de operações, transformando um lugar feito para os mortos em outro a serviço dos imortos.\n\nA escolha veio da necessidade. Os worgens rondavam ao sul, o Flagelo ainda dominava terras a leste, e o Kirin Tor vigiava a sudeste. Cercados por quase todos os lados, os Renegados encontraram no Sepulcro um dos poucos lugares de Pinhaprata onde a Horda podia ficar em segurança.",
			source = "https://warcraft.wiki.gg/wiki/Sepulcher",
		},
		["shadowfang keep"] = {
			name = "Bastilha da Presa Negra",
			short = "A Bastilha da Presa Negra fica num alto penhasco acima do Vilarejo Lenhardente. Um dia pertenceu ao Barão Silverlaine, um lorde de Guilnéas, até que o Flagelo desceu sobre Lordaeron e o Arquimago Real Arugal buscou uma forma de detê-lo.",
			full = "A Bastilha da Presa Negra fica num alto penhasco acima do Vilarejo Lenhardente. Um dia pertenceu ao Barão Silverlaine, um lorde de Guilnéas, até que o Flagelo desceu sobre Lordaeron e o Arquimago Real Arugal buscou uma forma de detê-lo. Valendo-se das pesquisas do mago Ur, e com a bênção do Rei Genn Greymane, mas contra o conselho do Kirin Tor, Arugal invocou os worgens. Eles repeliram a maré de mortos-vivos e depois se voltaram contra a própria Guilnéas, devastando a Muralha Greymane antes de se espalhar livres por Pinhaprata. Caíram sobre a bastilha e mataram o Barão Silverlaine e toda a sua casa.\n\nArugal, destroçado pelo que havia libertado, não fugiu. Chamou os worgens de seus filhos, tomou a bastilha para si e a rebatizou de Presa Negra. Em comunhão com um mestre a quem servia no Culto do Lobo, espalhou a maldição pela floresta, até que o próprio Vilarejo Lenhardente foi transformado, com seu povo humano de dia e fera à noite, governado por um conselho que respondia somente a ele.",
			source = "https://warcraft.wiki.gg/wiki/Shadowfang_Keep",
		},
		["shining strand"] = {
			name = "Margem Brilhante",
			short = "A Margem Brilhante se estende ao longo do Espelho de Lordaeron, desde a capital de Lordaeron, ao norte, até as colinas acidentadas que separam a Floresta de Pinhaprata das Montanhas de Alterac.",
			full = "A Margem Brilhante se estende ao longo do Espelho de Lordaeron, desde a capital de Lordaeron, ao norte, até as colinas acidentadas que separam a Floresta de Pinhaprata das Montanhas de Alterac.\n\nA tribo de murlocs Barbatana Vil encheu a margem de povoados, e os viajantes que não conhecem o litoral aprenderam a temê-lo. O falecido Boticário Berard escreveu em seu diário sobre um item raro que se podia obter dos Barbatana Vil, um Tumor Endurecido, e especulou que ele poderia ser transformado numa nova praga.",
			source = "https://warcraft.wiki.gg/wiki/Shining_Strand",
		},
		["skittering dark"] = {
			name = "Penumbra Furtiva",
			short = "A mina conhecida como Penumbra Furtiva foi tomada pelas aranhas Teia-ligeira, com suas teias cobrindo madeiras quebradas e ferramentas enferrujadas.",
			full = "A mina conhecida como Penumbra Furtiva foi tomada pelas aranhas Teia-ligeira, com suas teias cobrindo madeiras quebradas e ferramentas enferrujadas. Lá no fundo se esconde a Matriarca Teia-ligeira, uma aranha que cresceu até se tornar monstruosa, governando o enxame de uma escuridão que nunca abandona. Do lado de fora, a rara Krethis, a Tecelã das Sombras, às vezes espreita sozinha entre as rochas.\n\nCasulos se espalham pelo chão, prendendo worgens, lobos e ursos, além de orcs arrastados de um naufrágio na praia a oeste.",
			source = "https://warcraft.wiki.gg/wiki/Skittering_Dark",
		},
		["south tides run"] = {
			name = "Costa da Maré do Sul",
			short = "A Costa da Maré do Sul se estende pelo litoral sudoeste da Floresta de Pinhaprata, onde a terra encontra o Grande Mar.",
			full = "A Costa da Maré do Sul se estende pelo litoral sudoeste da Floresta de Pinhaprata, onde a terra encontra o Grande Mar.",
			source = "https://warcraft.wiki.gg/wiki/South_Tide's_Run",
		},
		["valgans field"] = {
			name = "Sítio do Valgan",
			short = "O Sítio do Valgan fica entre as fazendas desoladas do norte da Floresta de Pinhaprata, a oeste da Margem Brilhante e ao norte de um pequeno rio.",
			full = "O Sítio do Valgan fica entre as fazendas desoladas do norte da Floresta de Pinhaprata, a oeste da Margem Brilhante e ao norte de um pequeno rio. Leva o nome de um fazendeiro que foi morto ou expulso da terra quando o Flagelo varreu Pinhaprata. Em seus dias melhores, a fazenda tinha vista para o Espelho de Lordaeron, uma paisagem digna do nome que um dia teve.\n\nA fazenda está vazia agora, uma ruína do que já foi, embora Nightlash possa às vezes ser vista pelo lugar.",
			source = "https://warcraft.wiki.gg/wiki/Valgan's_Field",
		},
	},
	-- Terras Pestilentas Ocidentais: 18 subzones
	[1422] = {
		["bulwark"] = {
			name = "O Baluarte",
			short = "O Baluarte fica onde as Clareiras de Tirisfal encontram as Terras Pestilentas Ocidentais, a linha que os Renegados mantêm contra o Flagelo que ainda se concentra a leste.",
			full = "O Baluarte fica onde as Clareiras de Tirisfal encontram as Terras Pestilentas Ocidentais, a linha que os Renegados mantêm contra o Flagelo que ainda se concentra a leste. Aqui, os defensores Renegados e a Aurora Argêntea deixaram de lado suas diferenças diante desse inimigo comum, vigiando juntos a fronteira e enviando combatentes para o leste para atacar os lacaios do Lich Rei.\n\nAo contrário do resto de Tirisfal, este trecho não se parece em nada com as Clareiras. Uma névoa pestilenta paira sobre ele, tingindo o céu do mesmo cinza-amarelado doentio das Terras Pestilentas Ocidentais mais além.",
			source = "https://warcraft.wiki.gg/wiki/Bulwark",
		},
		["caer darrow"] = {
			name = "Castro das Flechas",
			short = "Na ilha do Lago das Flechas ficava uma fortaleza erguida por mãos humanas há muito tempo, que guardava uma antiga pedra rúnica dos altos elfos.",
			full = "Na ilha do Lago das Flechas ficava uma fortaleza erguida por mãos humanas há muito tempo, que guardava uma antiga pedra rúnica dos altos elfos. Durante a Segunda Guerra, a Horda tomou a ilha e saqueou a fortaleza, despedaçando a pedra rúnica para forjar os Altares das Tempestades, por meio dos quais Gul'dan infundiu magia nos ogros de sua Horda.\n\nA fortaleza foi reconstruída e se tornou a sede da Casa Barov. À medida que os anos se aproximavam da guerra, os Barov passaram a temer perder o que décadas haviam construído para eles e fizeram um pacto com Kel'Thuzad, mestre da Seita dos Malditos. Sob a mansão, as catacumbas se tornaram Scolomântia, uma escola de necromancia, e os próprios criados da família foram entregues como cobaias para uma praga da morte-vida. Em meio ano, a doença escapou e matou todos na ilha. Suas vítimas não simplesmente morreram: ergueram-se como fantasmas, condenadas a reviver seus momentos finais, e ainda vagam hoje pelos salões arruinados de Castro das Flechas.",
			source = "https://warcraft.wiki.gg/wiki/Caer_Darrow",
		},
		["chillwind camp"] = {
			name = "Acampamento Ventogelante",
			short = "O Acampamento Ventogelante fica no portão sul das Terras Pestilentas Ocidentais, onde as montanhas de Alterac dão lugar ao chão envenenado. É o último lugar onde um viajante da Aliança pode pisar e ainda chamar a terra de limpa.",
			full = "O Acampamento Ventogelante fica no portão sul das Terras Pestilentas Ocidentais, onde as montanhas de Alterac dão lugar ao chão envenenado. É o último lugar onde um viajante da Aliança pode pisar e ainda chamar a terra de limpa.\n\nUm pequeno contingente da Aurora Argêntea o ocupa, com apenas um punhado de tropas e especialistas. O que falta ao acampamento em números sobra em ousadia: seu pessoal trava uma guerra de guerrilha contra o reduto do Flagelo em Andorhal e contra os caldeirões da praga que semeiam a morte na terra, contando com mercenários dispostos a atacar e desaparecer em vez de manter terreno que não conseguem segurar.\n\nJovens e promissores Cavaleiros do Punho de Prata foram enviados para cá pelo Lorde Grayson Quebrassombra para lutar ao lado do Comandante Ashlam Punhobom contra o Flagelo na região.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Camp",
		},
		["dalsons tears"] = {
			name = "Lágrimas de Dalson",
			short = "O Pomar dos Dalson um dia deu frutos para uma família que lhe emprestou o nome. Agora as árvores estão nas Terras Pestilentas Ocidentais sob um nome que lembra o luto em vez da colheita: Lágrimas de Dalson.",
			full = "O Pomar dos Dalson um dia deu frutos para uma família que lhe emprestou o nome. Agora as árvores estão nas Terras Pestilentas Ocidentais sob um nome que lembra o luto em vez da colheita: Lágrimas de Dalson.\n\nO Flagelo tomou a fazenda e a transformou numa ferida na terra. Em seu centro, instalou um grande caldeirão que não parou desde então, lançando doença no ar, vigiado pelo Senhor do Caldeirão Malvinious e pelos mortos pestilentos que o servem.\n\nOs Dalson nunca partiram. A Sra. Dalson ainda vaga pela propriedade, um esqueleto errante que remexe o chão que um dia cuidou quando era mulher. Seu marido não morreu ao lado dela. Foi trancado na latrina e deixado ali, e o que ele se tornou naquela escuridão trancada já não era um homem, mas um carniçal.",
			source = "https://warcraft.wiki.gg/wiki/Dalson's_Tears",
		},
		["darrowmere lake"] = {
			name = "Lago das Flechas",
			short = "As águas do Lago das Flechas ainda guardam a memória da Segunda Guerra, quando o lago ficou apinhado de velas.",
			full = "As águas do Lago das Flechas ainda guardam a memória da Segunda Guerra, quando o lago ficou apinhado de velas. A maioria dos navios que ancoravam aqui ostentava as cores da frota Proudmore e, antes do incêndio de Quel'Thalas, o Grão-almirante enviou vários deles através destas águas para levar Turalyon, Alleria Correventos e seu exército rumo a Stratholme. Turalyon pensou em seguir navegando até a própria Quel'Thalas, mas Alleria o advertiu de que os elfos jamais deixariam navios humanos subirem seu rio, e por isso a frota rumou para Stratholme. Foi nessa mesma guerra que Zul'jin e seu bando foram encurralados nas margens do lago e o senhor da guerra troll foi capturado.\n\nNo centro do lago fica a cidade insular de Castro das Flechas, vazia agora, que um dia pertenceu à Casa Barov. Sob as pedras da cidade fica Scolomântia, onde a Seita dos Malditos trabalha entre seus mortos-vivos, uma escuridão que repousa sob a quietude submersa da ilha.",
			source = "https://warcraft.wiki.gg/wiki/Darrowmere_Lake",
		},
		["felstone field"] = {
			name = "Campo Pedravil",
			short = "O Campo Pedravil um dia alimentou os vivos. Isso acabou quando o Flagelo passou por ele e não o deixou voltar a ser uma fazenda.",
			full = "O Campo Pedravil um dia alimentou os vivos. Isso acabou quando o Flagelo passou por ele e não o deixou voltar a ser uma fazenda.\n\nNo coração do campo, o Flagelo instalou um grande caldeirão, que não parou de trabalhar desde então. Vapor jorra dele sem parar, carregado de doença. O Senhor do Caldeirão Bilemaw monta guarda sobre ele, com feiticeiros esqueléticos, esfoladores esqueléticos e carniçais babando ao seu lado, para que nada vivo possa se aproximar e sair ileso.\n\nNo canto nordeste, a velha casa ainda está de pé, e Janice Pedravil ainda se mantém nela, demorando-se no chão que antes dava as colheitas de sua família.",
			source = "https://warcraft.wiki.gg/wiki/Felstone_Field",
		},
		["gahrrons withering"] = {
			name = "Aridez de Garrão",
			short = "A fazenda no limite leste das Terras Pestilentas Ocidentais pertenceu a Del Garrão e, em seus dias melhores, era conhecida como Vicejo de Garrão, um lugar de plantio e crescimento.",
			full = "A fazenda no limite leste das Terras Pestilentas Ocidentais pertenceu a Del Garrão e, em seus dias melhores, era conhecida como Vicejo de Garrão, um lugar de plantio e crescimento. Nada cresce ali agora. O Flagelo tomou os campos e instalou um grande caldeirão em seu centro, e o caldeirão nunca para de trabalhar, lançando no ar um vapor carregado de doença até que o próprio chão parece adoecer. O Senhor do Caldeirão Soulwrath monta guarda sobre ele com outros oficiais do Flagelo, e os vapores invocaram coisas que não deveriam caminhar: Visões Assombrosas vagando pelas fileiras arruinadas, Mortes Lamuriantes e Espectros Famintos que não respondem a nenhum senhor além de sua fome.",
			source = "https://warcraft.wiki.gg/wiki/Gahrron's_Withering",
		},
		["hearthglen"] = {
			name = "Amparo",
			short = "Amparo fica ao norte de Andorhal, com suas muralhas fechadas em torno de uma bastilha, uma torre de magos, um moinho e uma mina, a imagem da ordem numa região em ruínas.",
			full = "Amparo fica ao norte de Andorhal, com suas muralhas fechadas em torno de uma bastilha, uma torre de magos, um moinho e uma mina, a imagem da ordem numa região em ruínas. Por anos, manteve essa ordem sob Tirion Fordring, Lorde de Mardenforte, até que ele ajudou o orc Eitrigg e foi banido por traição. Com o tempo, seu filho Taelan assumiu seu lugar como Lorde de Mardenforte.\n\nMais tarde, Amparo abrigou os remanescentes da Ordem do Punho de Prata, que aceitaram a oferta de refúgio de Taelan depois da queda da Capital. De suas muralhas, os paladinos conquistaram vitórias nos anos seguintes, até que a ordem foi distorcida na Cruzada Escarlate e tomou a cidade para si.",
			source = "https://warcraft.wiki.gg/wiki/Hearthglen",
		},
		["mardenholde keep"] = {
			name = "Bastilha Mardenforte",
			short = "A Bastilha Mardenforte está no coração de Amparo desde antes da lembrança da maioria dos que percorrem seus salões, com suas muralhas intactas mesmo nos dias mais sombrios da invasão orc de Lordaeron.",
			full = "A Bastilha Mardenforte está no coração de Amparo desde antes da lembrança da maioria dos que percorrem seus salões, com suas muralhas intactas mesmo nos dias mais sombrios da invasão orc de Lordaeron. Por anos, foi a sede de Tirion Fordring, e ali, numa sala de conselho dominada por uma grande mesa de carvalho e por um mapa que retratava Amparo até sua menor estrada, o paladino se reunia com seus conselheiros para tratar dos assuntos do reino. Acusado de traição por ajudar o orc Eitrigg, Tirion foi excomungado e banido, e Mardenforte passou, com o tempo, a seu próprio filho, Taelan.\n\nDepois da Flagelação de Lordaeron, Taelan concedeu aos Cavaleiros do Punho de Prata sobreviventes um lar em Amparo. Chegou a estas muralhas a notícia de que Alexandros Mograine estava morto, e a suspeita de traição dividiu a ordem: Maximiliano Tyrosus levou seus seguidores embora para fundar a Aurora Argêntea, enquanto os que ficaram adotaram o nome de Cruzada Escarlate, e Mardenforte se tornou seu bastião, com Taelan elevado a Grão-lorde.",
			source = "https://warcraft.wiki.gg/wiki/Mardenholde_Keep",
		},
		["northridge lumber camp"] = {
			name = "Madeireira Beiranorte",
			short = "A Madeireira Beiranorte fica no norte das Terras Pestilentas Ocidentais, perto de Amparo, com as encostas desnudadas pela extração de madeira da Cruzada Escarlate.",
			full = "A Madeireira Beiranorte fica no norte das Terras Pestilentas Ocidentais, perto de Amparo, com as encostas desnudadas pela extração de madeira da Cruzada Escarlate. A Cruzada opera a serraria para obter madeira, um suprimento que tanto a Aliança quanto a Horda têm motivos para querer ver arruinado.\n\nAntes da Terceira Guerra, a serraria pertencia à família de Nataniel Dumah, que trabalhava a terra até que a guerra e a praga a expulsaram. A família de Guel Levine também trabalhou aqui um dia.",
			source = "https://warcraft.wiki.gg/wiki/Northridge_Lumber_Camp",
		},
		["ruins of andorhal"] = {
			name = "Ruínas de Andorhal",
			short = "Andorhal jaz em ruínas no coração das Terras Pestilentas Ocidentais, com suas casas destroçadas espalhadas por terreno aberto.",
			full = "Andorhal jaz em ruínas no coração das Terras Pestilentas Ocidentais, com suas casas destroçadas espalhadas por terreno aberto. O que resta é dominado por Araj, o Invocador, um lich de poder considerável, e pelos mortos que o servem: carniçais se arrastando entre as pedras caídas, esqueletos montando sentinela onde antes ficavam os guardas, banshees cujos gritos ecoam sobre as ruínas e abominações cambaleando entre os destroços das casas.\n\nAraj continua no centro de tudo, presidindo uma cidade que nunca mais se reergueu.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Andorhal",
		},
		["scholomance"] = {
			name = "Scolomântia",
			short = "Numa elevação acima da cidade abandonada de Castro das Flechas fica a mansão que um dia foi a sede da Casa Barov, uma família cujo alcance ia de Castro das Flechas a Montalvo, a Costa Sul e à Serraria Tarren.",
			full = "Numa elevação acima da cidade abandonada de Castro das Flechas fica a mansão que um dia foi a sede da Casa Barov, uma família cujo alcance ia de Castro das Flechas a Montalvo, a Costa Sul e à Serraria Tarren. Por décadas, governaram com conforto, mas, à medida que os anos se aproximavam da guerra, os Barov se tornaram amargos e gananciosos, sem aceitar que a morte pusesse fim ao que haviam construído. Então fizeram um pacto com Kel'Thuzad, mestre da Seita dos Malditos, para manter sua fortuna e suas terras além do limite da vida mortal.\n\nEm seis meses, a fortaleza havia apodrecido em algo completamente diferente. Acólitos da Seita estudavam a arte do necromante enquanto os próprios criados da família eram entregues como experimentos vivos para uma praga da morte-vida. Antes que Uther, o Arauto da Luz, pudesse fazer uma visita marcada à mansão, uma doença gerada em seus salões foi libertada sobre a própria Castro das Flechas. Não deixou ninguém vivo e condenou suas vítimas a vagar depois como fantasmas.\n\nOs próprios Barov se ergueram de novo como mortos-vivos, ainda presos aos salões que haviam vendido. Agora o necromante mortal Mestre das Trevas Gandling atua como diretor, tendo sucedido Araj, o Invocador, que por sua vez sucedera Kel'Thuzad.",
			source = "https://warcraft.wiki.gg/wiki/Scholomance",
		},
		["sorrow hill"] = {
			name = "Colina do Pesar",
			short = "A Colina do Pesar servia a Andorhal em dias mais amenos, um lugar para os mortos da cidade, ricos e pobres, enterrados sob criptas e lápides simples.",
			full = "A Colina do Pesar servia a Andorhal em dias mais amenos, um lugar para os mortos da cidade, ricos e pobres, enterrados sob criptas e lápides simples. Essa paz terminou quando veio a Praga da Morte-vida. Enquanto o Flagelo se lançava vez após vez contra Andorhal, a colina se encheu mais depressa do que conseguia comportar: covas apressadas e sem identificação ainda marcam o chão onde os defensores caíram. Com o tempo, os sobreviventes pararam de enterrar seus mortos, com medo de que a praga erguesse seus entes queridos contra eles, e cavaram uma vala comum ao sul do cemitério para queimar os corpos.\n\nO último ato da cidade foi o mais triste. Quando Arthas abateu o Lorde Uther, o povo que restava em Andorhal ergueu um grande túmulo no alto da colina e depositou nele o corpo destroçado do paladino antes de abandonar seu lar para sempre. Há quem diga que a colina leva o nome apenas por causa desse túmulo.\n\nOs Caldeirões da Praga próximos não pouparam os próprios mortos da colina. Soldados e moradores se ergueram de suas covas, montando guarda sobre os túmulos que um dia ocuparam.",
			source = "https://warcraft.wiki.gg/wiki/Sorrow_Hill",
		},
		["thondroril river"] = {
			name = "Rio Thondroril",
			short = "O Rio Thondroril divide as Terras Pestilentas Ocidentais das Orientais. Nasce bem ao norte, perto do Túnel Terrorteia, e corre para o sul até desaguar no Lago das Flechas, continuando depois como Rio das Flechas.",
			full = "O Rio Thondroril divide as Terras Pestilentas Ocidentais das Orientais. Nasce bem ao norte, perto do Túnel Terrorteia, e corre para o sul até desaguar no Lago das Flechas, continuando depois como Rio das Flechas.\n\nSuas margens pertencem à praga. Larvas e morcegos-vampiros enchem o chão úmido, ursos pestilentos e aranhas espreitam nos baixios, e tartarugas-mordedoras se escondem onde a correnteza diminui.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["uthers tomb"] = {
			name = "Tumba de Uther",
			short = "A Tumba de Uther fica na Colina do Pesar, o único lugar das Terras Pestilentas Ocidentais onde a Luz ainda resiste à morte da terra.",
			full = "A Tumba de Uther fica na Colina do Pesar, o único lugar das Terras Pestilentas Ocidentais onde a Luz ainda resiste à morte da terra.\n\nUther, o Arauto da Luz, um dia defendeu Andorhal contra o Flagelo, ao lado do Sábio Truthbearer e de Ballador, o Brilhante, com os Cavaleiros do Punho de Prata às suas costas. Foi Arthas Menethil quem pôs fim a essa resistência, lançando seu exército de mortos-vivos contra a cidade e abatendo Truthbearer, Ballador e o próprio Uther.\n\nO que Arthas deixou para trás, os próprios soldados de Uther recolheram. Levaram seu corpo para o sul das ruínas de Andorhal e ergueram uma tumba sobre ele. Sua lápide o mostra como era em vida, com um tomo da Luz numa mão e seu martelo de guerra na outra, e palavras gravadas na língua comum na pedra memorial diante dela.\n\nO Sumo Sacerdote Thel'danis ainda cuida da tumba, como seu zelador e guardião. O túmulo é sagrado para os que seguem a Luz, um dos poucos lugares das Terras Pestilentas onde essa devoção ainda significa alguma coisa.",
			source = "https://warcraft.wiki.gg/wiki/Uther's_Tomb",
		},
		["weeping cave"] = {
			name = "Caverna das Lágrimas",
			short = "A Caverna das Lágrimas fica a oeste do Rio Thondroril, com suas cavidades repletas de monstros do brejo e gosmas nascidos da terra pestilenta. Colossos apodrecidos e horrores em decomposição cambaleiam pela escuridão.",
			full = "A Caverna das Lágrimas fica a oeste do Rio Thondroril, com suas cavidades repletas de monstros do brejo e gosmas nascidos da terra pestilenta. Colossos apodrecidos e horrores em decomposição cambaleiam pela escuridão. Mais fundo ainda, dizem que um elemental chamado Casca raramente vem à tona, uma coisa estranha e inquietante de se ver.",
			source = "https://warcraft.wiki.gg/wiki/Weeping_Cave",
		},
		["writhing haunt"] = {
			name = "O Antro Repelente",
			short = "O Antro Repelente já foi terra de cultivo, cuidada para o sustento dos vivos. Esse propósito acabou.",
			full = "O Antro Repelente já foi terra de cultivo, cuidada para o sustento dos vivos. Esse propósito acabou. O Flagelo tomou os campos e instalou em seu centro um grande caldeirão, que não parou de trabalhar desde então: um jorro constante de vapor carregado de doença rolando pelos sulcos onde antes cresciam as plantações.\n\nO caldeirão não fica sem guarda. O Senhor do Caldeirão Razarch vigia sobre ele, com Carniçais Putrefatos, Carniçais Congelantes e Zumbis Fétidos movendo-se ao seu redor, presos ao lugar como seus guardiões.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Haunt",
		},
	},
	-- Terras Pestilentas Orientais: 28 subzones
	[1423] = {
		["blackwood lake"] = {
			name = "Lago Bosquenero",
			short = "As águas do Lago Bosquenero correm imundas, infestadas de elementais da água corrompidos que se enroscam no lodo. Antigos anais de Vila das Flechas afirmam que o leito do lago guarda a cabeça de Horgus, o Devastador, afundada em algum ponto daquela escuridão.",
			full = "As águas do Lago Bosquenero correm imundas, infestadas de elementais da água corrompidos que se enroscam no lodo. Antigos anais de Vila das Flechas afirmam que o leito do lago guarda a cabeça de Horgus, o Devastador, afundada em algum ponto daquela escuridão.\n\nAntes da praga, uma cidade chamada Bosquenero ficava aqui, lar do Grão-marechal Othmar Garithos. Nada resta dela agora além do lago que leva seu nome.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Lake",
		},
		["browman mill"] = {
			name = "Engenho Assombrado",
			short = "Stephen Browman cortava madeira no engenho ao norte da Capela Esperança da Luz. O Flagelo o matou como a todos os que a praga tocou e depois o ergueu como um carniçal preso a seu serviço.",
			full = "Stephen Browman cortava madeira no engenho ao norte da Capela Esperança da Luz. O Flagelo o matou como a todos os que a praga tocou e depois o ergueu como um carniçal preso a seu serviço. Ele nunca partiu. Agora monta guarda dentro das paredes que um dia foram suas.\n\nO engenho está apinhado de esqueletos, banshees e abominações, mais guarnição que ruína, e nada nele convida alguém a se demorar.",
			source = "https://warcraft.wiki.gg/wiki/Browman_Mill",
		},
		["corins crossing"] = {
			name = "Cruzamento de Corin",
			short = "O Cruzamento de Corin fica onde se encontram as estradas para Andorhal, Vila das Flechas, Stratholme e a Manopla de Tyr, entre a Fenda Infectis e o Lago Mereldar.",
			full = "O Cruzamento de Corin fica onde se encontram as estradas para Andorhal, Vila das Flechas, Stratholme e a Manopla de Tyr, entre a Fenda Infectis e o Lago Mereldar. Antes uma cidade de encruzilhada comum, tinha uma prefeitura e uma forja de ferreiro.\n\nAgora o Flagelo enche suas ruas por completo e, entre os mortos, movem-se coisas que não podem ser vistas de forma alguma: Servos Invisíveis, que enxergam através da furtividade como se ela não existisse. Não existe caminho silencioso pelo Cruzamento de Corin.",
			source = "https://warcraft.wiki.gg/wiki/Corin's_Crossing",
		},
		["crown guard tower"] = {
			name = "Torre da Coroa",
			short = "A Torre da Coroa vigia as Terras Pestilentas Orientais como uma de suas torres de observação. A invasão de Lordaeron pelo Flagelo devastou a região, e a torre ainda carrega suas cicatrizes, um marco silencioso das terras mortas.",
			full = "A Torre da Coroa vigia as Terras Pestilentas Orientais como uma de suas torres de observação. A invasão de Lordaeron pelo Flagelo devastou a região, e a torre ainda carrega suas cicatrizes, um marco silencioso das terras mortas.",
			source = "https://warcraft.wiki.gg/wiki/Crown_Guard_Tower",
		},
		["darrowshire"] = {
			name = "Vila das Flechas",
			short = "Vila das Flechas já foi uma aldeia de respeito, até que a Terceira Guerra trouxe o Flagelo a seus portões. Um senhor carniçal chamado Horgus, o Devastador, liderou o ataque, ao lado do cavaleiro da morte Marduque Lagonero.",
			full = "Vila das Flechas já foi uma aldeia de respeito, até que a Terceira Guerra trouxe o Flagelo a seus portões. Um senhor carniçal chamado Horgus, o Devastador, liderou o ataque, ao lado do cavaleiro da morte Marduque Lagonero. Os defensores da aldeia reagiram com algum sucesso no início, mas a maré virou e, no fim, todos eles foram massacrados.\n\nA morte não foi o fim deles. Os caídos se ergueram de novo como carniçais, presos ao serviço do mesmo Flagelo que os matou, com seus espíritos aprisionados na carne apodrecida que um dia foi deles.\n\nA própria Vila das Flechas agora está silenciosa e destroçada, vazia a não ser por fantasmas e lembranças.",
			source = "https://warcraft.wiki.gg/wiki/Darrowshire",
		},
		["eastwall gate"] = {
			name = "Portão da Muralha Leste",
			short = "O Portão da Muralha Leste é a entrada lateral de Stratholme, abrindo-se diretamente para a Praça dos Anciãos, perto da Capela de Alonsus, onde Aurius ocupa seu posto.",
			full = "O Portão da Muralha Leste é a entrada lateral de Stratholme, abrindo-se diretamente para a Praça dos Anciãos, perto da Capela de Alonsus, onde Aurius ocupa seu posto.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Gate",
		},
		["eastwall tower"] = {
			name = "Torre da Muralha Leste",
			short = "A Torre da Muralha Leste fica nas Terras Pestilentas Orientais, uma torre de observação que um dia vigiava a terra para Lordaeron. O Flagelo varreu o reino, e a torre ainda carrega suas cicatrizes, vigiando terras mortas.",
			full = "A Torre da Muralha Leste fica nas Terras Pestilentas Orientais, uma torre de observação que um dia vigiava a terra para Lordaeron. O Flagelo varreu o reino, e a torre ainda carrega suas cicatrizes, vigiando terras mortas.",
			source = "https://warcraft.wiki.gg/wiki/Eastwall_Tower",
		},
		["fungal vale"] = {
			name = "Vale Fungi",
			short = "Ao norte do Sítio dos Marris e da Torre da Coroa fica o Vale Fungi, um chão que ficou roxo-escuro sob uma névoa turva.",
			full = "Ao norte do Sítio dos Marris e da Torre da Coroa fica o Vale Fungi, um chão que ficou roxo-escuro sob uma névoa turva. Aqui a Praga da Morte-vida se enraizou mais fundo, e o Flagelo e a Seita dos Malditos circulam livremente pela corrupção, tratando o vale inteiramente como seu.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Vale",
		},
		["infectis scar"] = {
			name = "Fenda Infectis",
			short = "Perto do Cruzamento de Corin, a espada rúnica do cavaleiro da morte Marduque Lagonero se despedaçou contra o escudo de um capitão anão. Ele ficou com o punho e jogou a lâmina arruinada de lado, como algo sem valor.",
			full = "Perto do Cruzamento de Corin, a espada rúnica do cavaleiro da morte Marduque Lagonero se despedaçou contra o escudo de um capitão anão. Ele ficou com o punho e jogou a lâmina arruinada de lado, como algo sem valor. Mas ela afundou na terra, e o chão se abriu sob ela, enchendo-se de água escura.\n\nO que resta é antinatural de cabo a rabo, ao contrário da vizinha Cicatriz Pestilenta, um mero desfiladeiro natural.",
			source = "https://warcraft.wiki.gg/wiki/Infectis_Scar",
		},
		["lake mereldar"] = {
			name = "Lago Mereldar",
			short = "As águas do Lago Mereldar estão carregadas de praga ao sul do Cruzamento de Corin, com elementais da água corrompidos se movendo sob a superfície.",
			full = "As águas do Lago Mereldar estão carregadas de praga ao sul do Cruzamento de Corin, com elementais da água corrompidos se movendo sob a superfície. Em sua margem ficam as ruínas de uma velha casa, além de um barraco e uma balsa que um dia serviram a uma fazenda hoje abandonada.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mereldar",
		},
		["lights hope chapel"] = {
			name = "Capela Esperança da Luz",
			short = "Sob as montanhas a leste das Terras Pestilentas fica uma capela muito mais antiga que a ruína ao seu redor, um dos lugares sagrados mais antigos e reverenciados que a Igreja da Luz Sagrada já ergueu.",
			full = "Sob as montanhas a leste das Terras Pestilentas fica uma capela muito mais antiga que a ruína ao seu redor, um dos lugares sagrados mais antigos e reverenciados que a Igreja da Luz Sagrada já ergueu.\n\nOs paladinos que se recusaram a seguir o caminho que a Cruzada Escarlate estava tomando se retiraram para as Terras Pestilentas Orientais e fizeram desta capela sua base, chamando a si mesmos de Aurora Argêntea. O Lorde Raymond George os liderou primeiro; quando ele morreu, o Lorde Maximiliano Tyrosus assumiu seu lugar. Ao contrário da Cruzada Escarlate, eles não rejeitavam ninguém por causa da raça.\n\nEmbora a Aurora Argêntea se mantenha à parte da Cruzada Escarlate, a capela continua sendo território neutro, onde as duas ainda se encontram para conversar.",
			source = "https://warcraft.wiki.gg/wiki/Light's_Hope_Chapel",
		},
		["marris stead"] = {
			name = "Sítio dos Marris",
			short = "O Sítio dos Marris fica numa crista baixa acima da estrada principal da região, uma propriedade rural que um dia pertenceu a Nathanos Marris.",
			full = "O Sítio dos Marris fica numa crista baixa acima da estrada principal da região, uma propriedade rural que um dia pertenceu a Nathanos Marris. Seu primo Stephon viveu aqui por um tempo, e sabia-se que Sylvana Correventos visitava Nathanos sob este teto.\n\nLibertado pela Rainha Banshee depois que ela ergueu os Renegados na Cidade Baixa, Nathanos voltou ao lar que havia perdido e, por ordem dela, fez dele seu novamente. Daqui, ele atraiu soldados da Horda para a luta contra o Flagelo e a Cruzada Escarlate, que ainda infestam as Terras Pestilentas, e reuniu relíquias da batalha de Vila das Flechas, guardando-as dentro do sítio por motivos que não contou a ninguém.",
			source = "https://warcraft.wiki.gg/wiki/Marris_Stead",
		},
		["mazraalor"] = {
			name = "Mazra'Alor",
			short = "No coração de Zul'Mashar se ergue Mazra'Alor, um zigurate de pedras empilhadas que domina as terras arruinadas ao redor.",
			full = "No coração de Zul'Mashar se ergue Mazra'Alor, um zigurate de pedras empilhadas que domina as terras arruinadas ao redor. A tribo Mossflayer ainda o ocupa, com seus caçadores das sombras vigiando de suas alturas o povoado troll lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Mazra'Alor",
		},
		["northdale"] = {
			name = "Vilarejo do Norte",
			short = "O Vilarejo do Norte é uma cidade em ruínas ao norte da Capela Esperança da Luz, na fronteira de Quel'Thalas. Aqui Taelan Fordring renunciou à Ordem do Punho de Prata em favor da Cruzada Escarlate.",
			full = "O Vilarejo do Norte é uma cidade em ruínas ao norte da Capela Esperança da Luz, na fronteira de Quel'Thalas. Aqui Taelan Fordring renunciou à Ordem do Punho de Prata em favor da Cruzada Escarlate.\n\nBanshees e vigias invisíveis assombram os destroços agora. O lago próximo abriga elementais da água corrompidos. Nada vivo resta.",
			source = "https://warcraft.wiki.gg/wiki/Northdale",
		},
		["northpass tower"] = {
			name = "Torre do Passo Norte",
			short = "A Torre do Passo Norte é a mais setentrional das torres de vigia das Terras Pestilentas Orientais e marca a estrada que segue rumo às Terras Fantasmas de Quel'Thalas.",
			full = "A Torre do Passo Norte é a mais setentrional das torres de vigia das Terras Pestilentas Orientais e marca a estrada que segue rumo às Terras Fantasmas de Quel'Thalas. O Flagelo varreu Lordaeron, e a torre ainda carrega suas cicatrizes.",
			source = "https://warcraft.wiki.gg/wiki/Northpass_Tower",
		},
		["noxious glade"] = {
			name = "Clareira Nociva",
			short = "A Clareira Nociva fica no alto de uma colina ao norte da Capela Esperança da Luz, mais contaminada pela praga do que o resto das Terras Pestilentas ao redor.",
			full = "A Clareira Nociva fica no alto de uma colina ao norte da Capela Esperança da Luz, mais contaminada pela praga do que o resto das Terras Pestilentas ao redor. O ar é pesado, de um verde doentio, e o chão foi manchado de um roxo-escuro onde nada verde consegue crescer.\n\nO Flagelo fez da clareira seu território: um caldeirão da praga, um matadouro e alguns zigurates se erguem no chão envenenado, e criaturas do Flagelo circulam por ali em grande número.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Glade",
		},
		["pestilent scar"] = {
			name = "Cicatriz Pestilenta",
			short = "A Cicatriz Pestilenta é um desfiladeiro profundo nas arrasadas Terras Pestilentas Orientais, provavelmente um lago que secou quando a Praga da Morte-vida atacou.",
			full = "A Cicatriz Pestilenta é um desfiladeiro profundo nas arrasadas Terras Pestilentas Orientais, provavelmente um lago que secou quando a Praga da Morte-vida atacou. Hoje está quase toda seca, uma ferida na terra, e suas profundezas abrigam gosmas nascidas da antiga corrupção.",
			source = "https://warcraft.wiki.gg/wiki/Pestilent_Scar",
		},
		["plaguewood"] = {
			name = "Bosque Pestilento",
			short = "As árvores ao sul de Stratholme um dia foram verdes e tranquilas, um bosque não muito diferente da Floresta de Elwynn, com uma pequena aldeia aninhada perto do arco de pedra em sua borda.",
			full = "As árvores ao sul de Stratholme um dia foram verdes e tranquilas, um bosque não muito diferente da Floresta de Elwynn, com uma pequena aldeia aninhada perto do arco de pedra em sua borda. Foi aqui que o Sargento Morigan, um soldado lordaeronense nascido naquela aldeia, percebeu pela primeira vez o grão envenenado vindo de Andorhal fazendo seu mal na terra, quando Kel'Thuzad começou seu trabalho. Seu aviso chegou tarde demais para o reino, e a mesma estrada que ele vigiava foi a que o Príncipe Arthas percorreu mais tarde a caminho de Stratholme.\n\nO que restou depois já não era uma floresta. O próprio solo ficou esponjoso sob os pés, e cogumelos e fungos incharam até o tamanho de árvores, elevando-se sobre o que restava do antigo bosque. Eles exalam um gás marrom-escuro não muito diferente dos vapores que sobem dos caldeirões da praga do Flagelo, embora ninguém saiba dizer ao certo se o fungo simplesmente cresce em solo envenenado ou se o Flagelo o cultiva para espalhar ainda mais sua doença. Foi por essa transformação que o bosque recebeu seu novo nome.",
			source = "https://warcraft.wiki.gg/wiki/Plaguewood",
		},
		["quellithien lodge"] = {
			name = "Abrigo Quel'Lithien",
			short = "O Abrigo Quel'Lithien era um acampamento dos Andarilhos perto de Quel'Thalas, um lugar de calor e acolhida. Lor'themar Theron se lembrava dele assim de suas próprias visitas, recebido calorosamente pelos compatriotas que o chamavam de lar.",
			full = "O Abrigo Quel'Lithien era um acampamento dos Andarilhos perto de Quel'Thalas, um lugar de calor e acolhida. Lor'themar Theron se lembrava dele assim de suas próprias visitas, recebido calorosamente pelos compatriotas que o chamavam de lar. O abrigo guardava vários documentos élficos, alguns relativos à família real e à General-patrulheira de Luaprata. Na época da Segunda Guerra, Renthar Hawkspear liderava os caçadores de lá.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Lithien_Lodge",
		},
		["scarlet base camp"] = {
			name = "Base de Operações Escarlate",
			short = "Na margem leste do Lago Mereldar, não muito longe do bastião religioso da Manopla de Tyr, a Base de Operações Escarlate se ergue atrás de suas barricadas, com as defesas reforçadas contra o que quer que venha.",
			full = "Na margem leste do Lago Mereldar, não muito longe do bastião religioso da Manopla de Tyr, a Base de Operações Escarlate se ergue atrás de suas barricadas, com as defesas reforçadas contra o que quer que venha.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Base_Camp",
		},
		["scarlet basilica"] = {
			name = "Basílica Escarlate",
			short = "A Basílica Escarlate fica dentro da Manopla de Tyr, a sede suprema da fé da Cruzada Escarlate, ligada à abadia próxima e ao distante Monastério Escarlate, nas Clareiras de Tirisfal.",
			full = "A Basílica Escarlate fica dentro da Manopla de Tyr, a sede suprema da fé da Cruzada Escarlate, ligada à abadia próxima e ao distante Monastério Escarlate, nas Clareiras de Tirisfal. O Lorde Cruzado Valdelmar a comanda, com uma devoção absoluta à causa da Cruzada.",
			source = "https://warcraft.wiki.gg/wiki/Scarlet_Basilica",
		},
		["stratholme"] = {
			name = "Stratholme",
			short = "A ruína de Stratholme começou com grãos. Carregamentos de Andorhal, infectados em segredo pela Seita dos Malditos, foram assados em pães e comidos por uma população que nunca soube que estava morrendo.",
			full = "A ruína de Stratholme começou com grãos. Carregamentos de Andorhal, infectados em segredo pela Seita dos Malditos, foram assados em pães e comidos por uma população que nunca soube que estava morrendo. O Príncipe Arthas Menethil chegou com Uther, o Arauto da Luz, e Jaina Proudmore e encontrou a praga já se alastrando. Acreditando que a única misericórdia que restava era uma morte limpa, em vez de uma lenta transformação em mortos-vivos, Arthas ordenou que a cidade fosse incendiada. Uther e Jaina se recusaram e retiraram seus homens. Arthas não. O fogo varreu as ruas, e quase todas as almas de Stratholme foram mortas antes que o senhor do medo Mal'Ganis, que Arthas viera matar, escapasse rindo, deixando o príncipe a queimar o que restava.\n\nNão foi o bastante. Os mortos se ergueram mesmo assim, e a cidade se tornou a capital do Flagelo em Lordaeron, governada primeiro pelo lich Kel'Thuzad e depois pelo cavaleiro da morte Barão Rivendare.\n\nStratholme ainda arde.",
			source = "https://warcraft.wiki.gg/wiki/Stratholme",
		},
		["terrordale"] = {
			name = "Várzea do Medo",
			short = "A Várzea do Medo fica na borda do Bosque Pestilento, com as ruas esvaziadas e entregues ao Flagelo e a animais pestilentos. Apenas o mercador Augustus, o Pirado, e o caçador de fantasmas Egan ainda se demoram entre as ruínas.",
			full = "A Várzea do Medo fica na borda do Bosque Pestilento, com as ruas esvaziadas e entregues ao Flagelo e a animais pestilentos. Apenas o mercador Augustus, o Pirado, e o caçador de fantasmas Egan ainda se demoram entre as ruínas.\n\nA cidade é assombrada. Espíritos percorrem suas vielas e, em certos lugares, a própria Várzea do Medo parece vacilar, com o mundo físico se curvando sob o peso do reino que existe além dele, como se o chão se lembrasse de algum velho tormento que não consegue soltar.\n\nFoi essa inquietação que atraiu o Lorde Grayson Quebrassombra, que viu nos espíritos uma provação adequada para paladinos que buscavam provar ser dignos do julgamento e do sacrifício, um passo rumo aos corcéis reservados aos verdadeiramente merecedores. O que os espíritos foram em vida não ficou registrado, apenas que seu tormento era real o bastante para distorcer a cidade ao redor deles.",
			source = "https://warcraft.wiki.gg/wiki/Terrordale",
		},
		["terrorweb tunnel"] = {
			name = "Túnel Terrorteia",
			short = "O túnel atravessa a montanha a noroeste da Várzea do Medo e segue para o sul até encontrar o Rio Thondroril.",
			full = "O túnel atravessa a montanha a noroeste da Várzea do Medo e segue para o sul até encontrar o Rio Thondroril. Demônios da cripta nerubianos lotam a passagem inteira e, entre eles, espreita algo pior: um Supervisor Nerubiano, muito mais mortal que seus semelhantes.\n\nNa boca do túnel, junto ao rio, Tirion Fordring monta guarda, encarando a escuridão da passagem a partir da luz do lado de fora.",
			source = "https://warcraft.wiki.gg/wiki/Terrorweb_Tunnel",
		},
		["thondroril river"] = {
			name = "Rio Thondroril",
			short = "O Rio Thondroril divide as Terras Pestilentas Ocidentais das Orientais. Nasce bem ao norte, perto do Túnel Terrorteia, e corre para o sul até desaguar no Lago das Flechas, continuando depois como Rio das Flechas.",
			full = "O Rio Thondroril divide as Terras Pestilentas Ocidentais das Orientais. Nasce bem ao norte, perto do Túnel Terrorteia, e corre para o sul até desaguar no Lago das Flechas, continuando depois como Rio das Flechas.\n\nSuas margens pertencem à praga. Larvas e morcegos-vampiros enchem o chão úmido, ursos pestilentos e aranhas espreitam nos baixios, e tartarugas-mordedoras se escondem onde a correnteza diminui.",
			source = "https://warcraft.wiki.gg/wiki/Thondroril_River",
		},
		["tyrs hand"] = {
			name = "Manopla de Tyr",
			short = "A Manopla de Tyr é uma cidade humana fortificada, um dos últimos redutos dos vivos contra o Flagelo na região.",
			full = "A Manopla de Tyr é uma cidade humana fortificada, um dos últimos redutos dos vivos contra o Flagelo na região. Seus arredores estão em condições muito melhores que o resto das Terras Pestilentas, embora as árvores e a vegetação ainda apodreçam.\n\nA cidade está entre os locais sagrados mais antigos e reverenciados da Igreja da Luz, construída quase inteiramente de igrejas e coroada pela Basílica Escarlate e pela abadia fortificada.\n\nQuando o Flagelo chegou e o Leste se tornou as Terras Pestilentas, a Manopla de Tyr não caiu. Sob o comando do Lorde Valdelmar, resistiu a ataques diários, protegida primeiro pelos Cavaleiros do Punho de Prata e depois pela Cruzada Escarlate, enviando suprimentos e reforços a outras posses Escarlates, com relatórios diários trazidos de Stratholme por mensageiros que precisavam abrir caminho à força pelas estradas tomadas pela praga.",
			source = "https://warcraft.wiki.gg/wiki/Tyr's_Hand",
		},
		["undercroft"] = {
			name = "Chácara Secreta",
			short = "A Chácara Secreta é uma cripta no sudoeste das Terras Pestilentas Orientais, lar de trolls mortos-vivos liderados por Zaeldarr, o Proscrito, um troll atroz reerguido.",
			full = "A Chácara Secreta é uma cripta no sudoeste das Terras Pestilentas Orientais, lar de trolls mortos-vivos liderados por Zaeldarr, o Proscrito, um troll atroz reerguido. Daqui, ele ataca a vala comum da Aurora Argêntea na Capela Esperança da Luz, roubando corpos para si.",
			source = "https://warcraft.wiki.gg/wiki/Undercroft",
		},
		["zulmashar"] = {
			name = "Zul'Mashar",
			short = "Zul'Mashar já foi a capital da tribo Mossflayer, trolls da floresta do nordeste das Terras Pestilentas Orientais.",
			full = "Zul'Mashar já foi a capital da tribo Mossflayer, trolls da floresta do nordeste das Terras Pestilentas Orientais. Longas guerras contra os humanos de Lordaeron deixaram as terras da tribo em desordem, e a praga da morte-vida que se seguiu trouxe uma ruína ainda mais profunda. A cidade que um dia governou aqui é agora uma sombra de sua antiga glória.\n\nSeu zigurate, Mazra'Alor, ainda se ergue no coração da cidade, ocupado agora pelo Senhor da Guerra Thresh'jin e por Zul'Brin Warpbranch. Mas o próprio povo Mossflayer está sendo transformado em segredo pela praga, e Zul'Mashar corre o risco de se tornar nada mais que um bastião dos mortos-vivos.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Mashar",
		},
	},
	-- Contraforte de Eira dos Montes: 29 subzones
	[1424] = {
		["azurelode mine"] = {
			name = "Mina Veioazul",
			short = "A Mina Veioazul fica no extremo sudoeste do Contraforte de Eira dos Montes, numa colina que um dia foi considerada parte de Guilnéas, antes que a Muralha Greymane se erguesse e isolasse o reino do mundo.",
			full = "A Mina Veioazul fica no extremo sudoeste do Contraforte de Eira dos Montes, numa colina que um dia foi considerada parte de Guilnéas, antes que a Muralha Greymane se erguesse e isolasse o reino do mundo.\n\nA mina pertence à Aliança, explorada por mineiros sob a vigilância de guardas, e seu ferro abastece os arsenais da Aliança.",
			source = "https://warcraft.wiki.gg/wiki/Azurelode_Mine",
		},
		["chillwind point"] = {
			name = "Morro do Ventogelante",
			short = "O Morro do Ventogelante leva o nome do vento gelado que desce das Terras Pestilentas Ocidentais, afunilando-se pela ravina lá embaixo. A elevação é coroada por uma antiga ruína troll, tudo o que resta dos que a ergueram.",
			full = "O Morro do Ventogelante leva o nome do vento gelado que desce das Terras Pestilentas Ocidentais, afunilando-se pela ravina lá embaixo. A elevação é coroada por uma antiga ruína troll, tudo o que resta dos que a ergueram. O passo um dia pertenceu ao reino de Lordaeron. O troll da selva Bath'rah, o Vigia dos Ventos, habita a ruína agora.",
			source = "https://warcraft.wiki.gg/wiki/Chillwind_Point",
		},
		["corrahns dagger"] = {
			name = "Adaga de Corrahn",
			short = "A Adaga de Corrahn é o segundo dos quatro dedos de Eira dos Montes. A Camarilha ocupa esta colina.",
			full = "A Adaga de Corrahn é o segundo dos quatro dedos de Eira dos Montes. A Camarilha ocupa esta colina.",
			source = "https://warcraft.wiki.gg/wiki/Corrahn's_Dagger",
		},
		["crushridge hold"] = {
			name = "Bastilha Esmagaterra",
			short = "A Bastilha Esmagaterra se ergue perto das Ruínas de Alterac, uma caverna escavada num monte de terra.",
			full = "A Bastilha Esmagaterra se ergue perto das Ruínas de Alterac, uma caverna escavada num monte de terra. Ao seu redor, os ogros Esmagaterra ergueram seus acampamentos, numerosos e de temperamento brutal, dominando as encostas acima da cidade arruinada lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Crushridge_Hold",
		},
		["darrow hill"] = {
			name = "Monte das Flechas",
			short = "O Monte das Flechas fica no norte do Contraforte de Eira dos Montes, abaixo de Terralta.",
			full = "O Monte das Flechas fica no norte do Contraforte de Eira dos Montes, abaixo de Terralta. Leões-da-montanha e cervos percorrem seus campos abertos, e na Caverna do Pé da Serra os yetis fizeram seu covil, entre veios de granito de Alterac que atravessam a rocha.",
			source = "https://warcraft.wiki.gg/wiki/Darrow_Hill",
		},
		["dun garok"] = {
			name = "Dun Garok",
			short = "Dun Garok fica nas colinas do Contraforte de Eira dos Montes, uma fortaleza anã sob o comando do Capitão Monteferro.",
			full = "Dun Garok fica nas colinas do Contraforte de Eira dos Montes, uma fortaleza anã sob o comando do Capitão Monteferro. Sua guarnição protege os humanos de Eira dos Montes e vigia a Mina Veioazul, uma presença que os Renegados não toleram e que os levou a oferecer ouro a quem se infiltrasse na fortaleza e passasse seus anões a fio de espada.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Garok",
		},
		["durnholde keep"] = {
			name = "Forte do Desterro",
			short = "O Forte do Desterro está em ruínas a leste da Serraria Tarren, com o quartel e a torre dos magos desabados sobre si mesmos e a arena em silêncio.",
			full = "O Forte do Desterro está em ruínas a leste da Serraria Tarren, com o quartel e a torre dos magos desabados sobre si mesmos e a arena em silêncio. Um dia foi a sede do sistema de internação de orcs criado depois da Segunda Guerra, governado pelo Tenente-general Aedelas Blackmoore, um beberrão egocêntrico que usava o campo para promover a si mesmo.\n\nFoi Blackmoore quem encontrou um bebê orc entre os corpos dos pais assassinados e o levou para o forte, dando-lhe o nome de Thrall. O menino foi criado e educado ali, amamentado por uma mulher humana cuja filha, Taretha Foxton, se tornou próxima dele. Blackmoore espancou o menino e o fez lutar na arena por anos, aproveitando-se de sua força para subir de posto. Taretha escrevia para ele em segredo, e ele respondia, até que finalmente lhe disse que pretendia fugir. Ela criou a distração que lhe permitiu escapar, encontrou-o além das muralhas e lhe deu provisões antes que ele partisse.\n\nEle voltou, anos depois, à frente dos orcs livres que havia reunido. Thrall sitiou o Forte do Desterro, matou Blackmoore em combate singular e invocou o Espírito da Terra para arrasar a fortaleza por completo. O que resta atraiu desde então a Camarilha, que reivindica estas ruínas como suas.",
			source = "https://warcraft.wiki.gg/wiki/Durnholde_Keep",
		},
		["eastern strand"] = {
			name = "Praia Oriental",
			short = "A Praia Oriental se estende pelo litoral sudeste do Contraforte de Eira dos Montes, com sua contraparte mais a oeste, ao longo do mesmo litoral.",
			full = "A Praia Oriental se estende pelo litoral sudeste do Contraforte de Eira dos Montes, com sua contraparte mais a oeste, ao longo do mesmo litoral. Este trecho de areia pertence aos nagas Daggerspine, que dominam as praias e as águas rasas mais além.",
			source = "https://warcraft.wiki.gg/wiki/Eastern_Strand",
		},
		["gallows corner"] = {
			name = "Canto da Forca",
			short = "No Canto da Forca, onde as estradas se encontram nas Montanhas de Alterac, perto dos salões arruinados de Alterac, uma torre de observação está destroçada e vazia.",
			full = "No Canto da Forca, onde as estradas se encontram nas Montanhas de Alterac, perto dos salões arruinados de Alterac, uma torre de observação está destroçada e vazia. Os ogros Esmagaterra dominam agora o cruzamento, rondando as pedras ao redor dos restos da torre, e nada mais se move ali.",
			source = "https://warcraft.wiki.gg/wiki/Gallows'_Corner",
		},
		["gavins naze"] = {
			name = "Promontório de Gavin",
			short = "O Promontório de Gavin é a última das quatro colinas de Eira dos Montes, e a mais bem guardada.",
			full = "O Promontório de Gavin é a última das quatro colinas de Eira dos Montes, e a mais bem guardada.\n\nLeões-da-montanha percorrem esta colina, entre eles Araga, marcada por sua coloração incomum.",
			source = "https://warcraft.wiki.gg/wiki/Gavin's_Naze",
		},
		["growless cave"] = {
			name = "Caverna Rugido",
			short = "Nas Montanhas de Alterac, uma caverna abriga yetis da montanha, e Skhowl costuma ser encontrado logo na entrada.",
			full = "Nas Montanhas de Alterac, uma caverna abriga yetis da montanha, e Skhowl costuma ser encontrado logo na entrada. Lá no fundo fica a Chama de Uzel, uma pira erguida pelo humano Helcular para o ritual que o transformaria num lich. A carne queimada sobre ela atrai até a entrada o poderoso yeti Frostmaw.",
			source = "https://warcraft.wiki.gg/wiki/Growless_Cave",
		},
		["headland"] = {
			name = "Terralta",
			short = "Terralta é um dos dedos de terra que se estendem por Eira dos Montes.",
			full = "Terralta é um dos dedos de terra que se estendem por Eira dos Montes.\n\nNa encosta do penhasco daqui, Araga descansa entre seus filhotes.",
			source = "https://warcraft.wiki.gg/wiki/Headland",
		},
		["hillsbrad fields"] = {
			name = "Campos de Eira dos Montes",
			short = "Os Campos de Eira dos Montes se estendem férteis e cultivados pelo oeste do Contraforte de Eira dos Montes, alimentando Costa Sul e também a cidade de Eira dos Montes.",
			full = "Os Campos de Eira dos Montes se estendem férteis e cultivados pelo oeste do Contraforte de Eira dos Montes, alimentando Costa Sul e também a cidade de Eira dos Montes. Pomares de maçã, plantações de abóbora e gado pastando cobrem a terra, e a Mina Veioazul ainda é trabalhada pelo povo da cidade.\n\nNo início da Segunda Guerra, Martelo da Perdição voltou seus exércitos contra Eira dos Montes e mandou destruí-la numa demonstração macabra, que deveria servir de aviso aos reinos humanos. Ela foi reconstruída depois da guerra e continua povoada, um dos poucos cantos da antiga Lordaeron que não ficaram em ruínas nem foram engolidos pela Cruzada Escarlate; seus guardas ainda usam o tabardo de seu reino, e o Magistrado Ardelado governa da prefeitura, com o Conselho de Eira dos Montes e o escrivão Horrace Whitesteed ao seu lado.\n\nAgora os campos estão de novo ameaçados, pelas forças da Alta-executora Darthalia na Serraria Tarren. Camponeses e fazendeiros suportam os ataques, mas muitos revidam contra os mortos-vivos com emboscadas próprias, armados pelo ferreiro Verringtan e seus aprendizes.",
			source = "https://warcraft.wiki.gg/wiki/Hillsbrad_Fields",
		},
		["misty shore"] = {
			name = "Costa da Bruma",
			short = "A Costa da Bruma se estende ao longo do Espelho de Lordaeron, entre o Nicho de Dandred e Dalaran. Tartarugas se movem devagar por seus baixios.",
			full = "A Costa da Bruma se estende ao longo do Espelho de Lordaeron, entre o Nicho de Dandred e Dalaran. Tartarugas se movem devagar por seus baixios.\n\nDois membros da Cruzada Escarlate ocupam esta margem, atacando qualquer um que se aproxime demais, como se o próprio chão precisasse de guarda.\n\nDo outro lado da água, é possível ver as Ilhas da Aurora, com o Castelo Fenris despontando sombrio e tênue através da névoa.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Shore",
		},
		["nethander stead"] = {
			name = "Sítio de Nethander",
			short = "O Sítio de Nethander fica logo a leste de Costa Sul, com os campos abandonados há muito tempo e tomados pelos gnolls Mudsnout, o único lugar onde sua tribo é encontrada.",
			full = "O Sítio de Nethander fica logo a leste de Costa Sul, com os campos abandonados há muito tempo e tomados pelos gnolls Mudsnout, o único lugar onde sua tribo é encontrada. Cogumelos brancos gigantes chamados Flores Mudsnout crescem selvagens ali, um dia procurados pelo Boticário Lindolfo para seu mortal Elixir da Agonia.",
			source = "https://warcraft.wiki.gg/wiki/Nethander_Stead",
		},
		["purgation isle"] = {
			name = "Ilha da Purgação",
			short = "Uma espiral de pedra se ergue ao sul do litoral de Eira dos Montes, coroada por um cemitério e pelos restos destroçados de uma torre de observação. Antes da Primeira Guerra, a Ilha da Purgação pertencia a Kul Tiraz.",
			full = "Uma espiral de pedra se ergue ao sul do litoral de Eira dos Montes, coroada por um cemitério e pelos restos destroçados de uma torre de observação. Antes da Primeira Guerra, a Ilha da Purgação pertencia a Kul Tiraz.\n\nO que veio depois é incerto, mas os mortos não descansam. Dezenas de espíritos vagam pela ilha, humanos e anões, paladinos e sacerdotes, monges e magos, almas condenadas presas às suas pedras.",
			source = "https://warcraft.wiki.gg/wiki/Purgation_Isle",
		},
		["ravenholdt manor"] = {
			name = "Mansão de Corvoforte",
			short = "A Mansão de Corvoforte fica isolada do mundo de propósito.",
			full = "A Mansão de Corvoforte fica isolada do mundo de propósito. Acessível apenas por uma trilha estreita e sinuosa que sobe de um platô a noroeste do Forte do Desterro, serpenteando pelas montanhas e por uma pequena caverna antes de se abrir para a propriedade, a mansão não é um lugar em que se tropeça por acaso. Forasteiros não são bem-vindos aqui, e os que servem ao Lorde Jorach Corvoforte garantem que continue assim.\n\nA mansão é propriedade dele, com telhados alaranjados no velho estilo de Alterac, cujo reino dominava esta terra antes da Primeira Guerra.\n\nNos anos que se passaram, a Camarilha tem vagado por esta parte das terras altas, e Corvoforte resiste a essa praga por trás de sua trilha oculta e de seus portões guardados.",
			source = "https://warcraft.wiki.gg/wiki/Ravenholdt_Manor",
		},
		["slaughter hollow"] = {
			name = "Antro do Massacre",
			short = "Nas profundezas das Montanhas de Alterac, os ogros Esmagaterra fizeram seu lar no Antro do Massacre, um monte afundado nas colinas.",
			full = "Nas profundezas das Montanhas de Alterac, os ogros Esmagaterra fizeram seu lar no Antro do Massacre, um monte afundado nas colinas. Pouco mais se sabe do lugar além dos ogros que o ocupam, mas o nome já diz o que espera quem se aproximar demais.",
			source = "https://warcraft.wiki.gg/wiki/Slaughter_Hollow",
		},
		["soferas naze"] = {
			name = "Promontório de Sofera",
			short = "O Promontório de Sofera se ergue como um dos quatro dedos de Eira dos Montes. A Camarilha ocupa a colina, vigiando o terreno lá embaixo.",
			full = "O Promontório de Sofera se ergue como um dos quatro dedos de Eira dos Montes. A Camarilha ocupa a colina, vigiando o terreno lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Sofera's_Naze",
		},
		["southpoint tower"] = {
			name = "Torre do Sul",
			short = "A Torre do Sul fica no extremo oeste do Contraforte de Eira dos Montes, logo ao sul da estrada que segue rumo à Floresta de Pinhaprata.",
			full = "A Torre do Sul fica no extremo oeste do Contraforte de Eira dos Montes, logo ao sul da estrada que segue rumo à Floresta de Pinhaprata. A cantaria é velha e rachada, um posto de observação deixado em ruínas, embora a torre em si nunca tenha sido derrubada nos combates que passaram por aqui. Perto dali, sem identificação, outra torre se ergue entre a Serraria Tarren e Costa Sul, também poupada da destruição que varreu o resto do contraforte.",
			source = "https://warcraft.wiki.gg/wiki/Southpoint_Tower",
		},
		["strahnbrad"] = {
			name = "Strahnbrad",
			short = "Strahnbrad fica no contraforte nordeste das Montanhas de Alterac, com sua prefeitura e sua ferraria agora vazias.",
			full = "Strahnbrad fica no contraforte nordeste das Montanhas de Alterac, com sua prefeitura e sua ferraria agora vazias. Um dia pertenceu ao Reino de Alterac e, depois da Segunda Guerra, passou para as mãos de Lordaeron.\n\nA ruína da cidade começou pouco antes da Terceira Guerra, quando orcs Rocha Negra desceram sobre ela para capturar escravos a serem sacrificados à Legião Ardente. Strahnbrad tinha apenas um punhado de soldados para defendê-la, mas a notícia chegou a tempo aos Cavaleiros do Punho de Prata. Uther, o Arauto da Luz, cavalgou à frente para tentar deter o ataque, enquanto o Príncipe Arthas Menethil foi enviado para defender a própria cidade. Arthas não chegou a tempo. Dean, Joe, Mike, Scott e muitos outros foram mortos antes que ele alcançasse Strahnbrad, e os defensores que restavam se juntaram a ele para derrotar os orcs e matar o Mestre de Escravos que liderara o ataque. A Aliança venceu a batalha, mas o povo de Strahnbrad já não existia.\n\nA Camarilha tomou depois a cidade arruinada para si, usando-a como fortaleza para dominar as Montanhas de Alterac, e manteve o orc Gol'dir prisioneiro numa de suas celas, obrigando-o a carregar e cavar como escravo.",
			source = "https://warcraft.wiki.gg/wiki/Strahnbrad",
		},
		["tarren mill"] = {
			name = "Serraria Tarren",
			short = "A Serraria Tarren já foi uma simples cidade lordaeronense entre as pradarias abaixo das Montanhas de Alterac.",
			full = "A Serraria Tarren já foi uma simples cidade lordaeronense entre as pradarias abaixo das Montanhas de Alterac. Nos primeiros dias da Segunda Guerra, arqueiros altos elfos de Luaprata, enviados ao sul para ver com os próprios olhos a ameaça orc, caíram numa emboscada perto da cidade e foram arrastados para um campo de prisioneiros próximo. O Rei Terenas enviou soldados da Aliança para libertá-los, e o resgate foi bem-sucedido. Foi esse sucesso que levou o Conselho de Luaprata a unir os exércitos de Quel'Thalas à Aliança de Lordaeron.\n\nA Serraria Tarren não permaneceu em mãos humanas. Os Renegados a tomaram com o tempo e a deixaram como deixaram suas outras posses: uma igreja, casas espalhadas, pomares apodrecidos, tudo de pé, mas nada inteiro. Daqui os Renegados travam sua guerra contra as forças da Aliança de Costa Sul e Dun Garok, e o terreno entre a Serraria Tarren e Costa Sul se tornou famoso por escaramuça após escaramuça entre as duas cidades, sem que nenhuma consiga derrotar a outra.",
			source = "https://warcraft.wiki.gg/wiki/Tarren_Mill",
		},
		["thoradins wall"] = {
			name = "Muralha de Thoradin",
			short = "O Rei Thoradin ergueu esta muralha para conter os trolls amani, nos tempos em que Strom ainda era jovem e Arathor mal havia conquistado a terra para a humanidade.",
			full = "O Rei Thoradin ergueu esta muralha para conter os trolls amani, nos tempos em que Strom ainda era jovem e Arathor mal havia conquistado a terra para a humanidade. Por gerações, ela foi uma sentinela firme, uma linha que nenhuma horda troll conseguia atravessar.\n\nSéculos depois, ela ainda está de pé, mas muito danificada, com suas pedras quebradas e sua longa vigília reduzida a ruínas.",
			source = "https://warcraft.wiki.gg/wiki/Thoradin's_Wall",
		},
		["western strand"] = {
			name = "Praia Ocidental",
			short = "A Praia Ocidental fica no litoral sudoeste do Contraforte de Eira dos Montes. Os murlocs Rancapina ergueram pequenos acampamentos ao longo de sua margem, e Andy Murgole patrulha estas águas, vigiando o litoral onde eles vivem.",
			full = "A Praia Ocidental fica no litoral sudoeste do Contraforte de Eira dos Montes. Os murlocs Rancapina ergueram pequenos acampamentos ao longo de sua margem, e Andy Murgole patrulha estas águas, vigiando o litoral onde eles vivem.",
			source = "https://warcraft.wiki.gg/wiki/Western_Strand",
		},
	},
	-- Terras Agrestes: 20 subzones
	[1425] = {
		["aerie peak"] = {
			name = "Ninho da Águia",
			short = "Os anões Martelo Feroz não escolheram as Terras Agrestes em primeiro lugar.",
			full = "Os anões Martelo Feroz não escolheram as Terras Agrestes em primeiro lugar. Seu lar era Grim Batol, nas profundezas da montanha, até que a Guerra dos Três Martelos terminou e os anões voltaram para encontrar sua fortaleza envenenada pela morte de Modgud. Grim Batol não podia mais ser habitada. Então os Martelo Feroz construíram de novo aqui, no alto da encosta em vez de dentro dela, sem vontade, depois dos horrores dos combates em túneis contra os anões Ferro Negro, de se enterrar na pedra outra vez. O Ninho se abre para o céu por causa daquela guerra.\n\nFoi daqui que Kurdran Martelo Feroz liderou seus cavaleiros de grifo contra as forças orcs enviadas para atacar as Terras Agrestes como distração, enquanto o verdadeiro exército da Horda avançava sobre Quel'Thalas. As forças de Anduin Lothar vieram em seu auxílio e ajudaram a expulsar os orcs e os trolls da floresta da terra dos Martelo Feroz, e por isso Kurdran jurou seu clã à Aliança.\n\nFalstad Martelo Feroz, que ficou como Grão-thane quando Kurdran não retornou, ainda governa o Ninho. Os trolls da floresta das Terras Agrestes, que chamam os Martelo Feroz de invasores de seu solo ancestral, ainda atacam os ninhais de grifos, enquanto os altos elfos de Quel'Danil continuam aliados dos anões contra esse mesmo inimigo.",
			source = "https://warcraft.wiki.gg/wiki/Aerie_Peak",
		},
		["agolwatha"] = {
			name = "Agol'watha",
			short = "As pedras de Agol'watha são mais antigas que os trolls que por último as consideraram sagradas, erguidas como um templo do Império Amani antes da queda desse império.",
			full = "As pedras de Agol'watha são mais antigas que os trolls que por último as consideraram sagradas, erguidas como um templo do Império Amani antes da queda desse império. Os trolls Vilebranch, que vieram depois, tomaram a ruína para si. Agora o templo foi invadido por lodos animados que enchem seus pátios despedaçados.",
			source = "https://warcraft.wiki.gg/wiki/Agol'watha",
		},
		["altar of zul"] = {
			name = "Altar de Zul",
			short = "O Altar de Zul se ergue nas Terras Agrestes, erguido pelos trolls da floresta Vilebranch para seus antigos ritos. Qiaga, a Guardiã, monta vigília no alto das pedras, protetora de qualquer poder que o altar ainda guarde.",
			full = "O Altar de Zul se ergue nas Terras Agrestes, erguido pelos trolls da floresta Vilebranch para seus antigos ritos. Qiaga, a Guardiã, monta vigília no alto das pedras, protetora de qualquer poder que o altar ainda guarde.",
			source = "https://warcraft.wiki.gg/wiki/Altar_of_Zul",
		},
		["bogens ledge"] = {
			name = "Covil do Bogen",
			short = "O Covil do Bogen é uma caverna no sudoeste das Terras Agrestes.",
			full = "O Covil do Bogen é uma caverna no sudoeste das Terras Agrestes.",
			source = "https://warcraft.wiki.gg/wiki/Bogen's_Ledge",
		},
		["creeping ruin"] = {
			name = "Ruína Assustadora",
			short = "A Ruína Assustadora jaz destroçada nas Terras Agrestes, pedra um dia moldada por mãos de trolls da floresta. Gosmas rastejam agora por seus salões caídos, escorrendo entre as velhas pedras trolls por onde os trolls um dia caminharam.",
			full = "A Ruína Assustadora jaz destroçada nas Terras Agrestes, pedra um dia moldada por mãos de trolls da floresta. Gosmas rastejam agora por seus salões caídos, escorrendo entre as velhas pedras trolls por onde os trolls um dia caminharam.",
			source = "https://warcraft.wiki.gg/wiki/Creeping_Ruin",
		},
		["featherbeards hovel"] = {
			name = "Casa de Barbapena",
			short = "Ao lado do Ninho da Águia fica uma pequena casa que um dia pertenceu a alguém chamado Barbapena. Não abriga guarnição nem tesouro.",
			full = "Ao lado do Ninho da Águia fica uma pequena casa que um dia pertenceu a alguém chamado Barbapena. Não abriga guarnição nem tesouro. Não serve a nenhum propósito agora além de continuar onde sempre esteve, vazia da vida que um dia a preencheu.",
			source = "https://warcraft.wiki.gg/wiki/Featherbeard's_Hovel",
		},
		["hiriwatha"] = {
			name = "Hiri'watha",
			short = "Os trolls Cascasseca ocupam Hiri'watha, uma aldeia ao sul do Pavilhão Quel'Danil, nas Terras Agrestes, no fundo da floresta que reivindicam como sua.",
			full = "Os trolls Cascasseca ocupam Hiri'watha, uma aldeia ao sul do Pavilhão Quel'Danil, nas Terras Agrestes, no fundo da floresta que reivindicam como sua.",
			source = "https://warcraft.wiki.gg/wiki/Hiri'watha",
		},
		["jinthaalor"] = {
			name = "Jintha'Alor",
			short = "Jintha'Alor se ergue em terraços acima das Terras Agrestes, a segunda maior das cidades dos trolls da floresta, atrás apenas de Zul'Aman.",
			full = "Jintha'Alor se ergue em terraços acima das Terras Agrestes, a segunda maior das cidades dos trolls da floresta, atrás apenas de Zul'Aman. Foi erguida nos tempos do Império Amani e leva o nome de Jintha, um dos antigos líderes dos amani.\n\nA cidade pertence à tribo Vilebranch, que transformou suas alturas numa fortaleza de sacrifício. A Sacerdotisa Vil Hexx governa ali a serviço de Hakkar, o Esfolalmas, e os Vilebranch atacam sem piedade a tribo Revatusco, mais fraca, para alimentar a fome de seu deus. O Ancião Presa-arrancada, dos Revatusco, foi levado num desses ataques e ainda é mantido cativo dentro da cidade; seu capitão da guarda, o Caçador Malkhor, foi capturado no mesmo ataque e executado, e seus restos foram jogados aos lobos e às gosmas mantidos dentro das muralhas.\n\nO clã Martelo Feroz e a tribo Revatusco, unidos por um rancor comum contra os Vilebranch, sitiaram juntos a cidade, buscando pôr fim a seus ataques e vingar seus mortos.",
			source = "https://warcraft.wiki.gg/wiki/Jintha'Alor",
		},
		["overlook cliffs"] = {
			name = "Penhascos Panorâmicos",
			short = "Os Penhascos Panorâmicos marcam o lugar onde as Terras Agrestes deixam de ser montanhas e se tornam céu.",
			full = "Os Penhascos Panorâmicos marcam o lugar onde as Terras Agrestes deixam de ser montanhas e se tornam céu. O grande rio que serpenteia pela região se reúne aqui e se despeja pela borda numa única cachoeira colossal, caindo até o litoral lá embaixo.\n\nOs penhascos são íngremes e enganosamente altos. Muitos dos que caminharam até sua borda calcularam mal a queda e despencaram para a morte.",
			source = "https://warcraft.wiki.gg/wiki/Overlook_Cliffs",
		},
		["plaguemist ravine"] = {
			name = "Trilha da Névoa Pestilenta",
			short = "Uma névoa paira onde a muralha da montanha se abre a oeste do Pavilhão Quel'Danil, marcando a ravina que corta para o norte rumo a Castro das Flechas. Nada vive na passagem.",
			full = "Uma névoa paira onde a muralha da montanha se abre a oeste do Pavilhão Quel'Danil, marcando a ravina que corta para o norte rumo a Castro das Flechas. Nada vive na passagem. Nenhum pássaro a atravessa, nenhuma fera faz toca em sua rocha.\n\nAs Terras Agrestes ao redor continuam verdes e limpas, mas a ravina exala outra coisa, uma névoa que não pertence à floresta. É por isso que o lugar leva o nome que tem agora: Névoa Pestilenta, dado por causa da neblina doentia que contamina este único caminho, enquanto o resto da terra permanece intocado.",
			source = "https://warcraft.wiki.gg/wiki/Plaguemist_Ravine",
		},
		["queldanil lodge"] = {
			name = "Pavilhão Quel'Danil",
			short = "O Pavilhão Quel'Danil é um dos últimos verdadeiros agrupamentos de altos elfos, o maior dos apenas dois povoados desse tipo que restam em Lordaeron.",
			full = "O Pavilhão Quel'Danil é um dos últimos verdadeiros agrupamentos de altos elfos, o maior dos apenas dois povoados desse tipo que restam em Lordaeron. Depois da Terceira Guerra, tornou-se um lugar de correspondência, com seus embaixadores buscando contato com os outros povos da Aliança. Esse esforço rendeu aos elfos de Highvale uma aliança com os anões Martelo Feroz e lhes valeu o ódio dos trolls Revatusco, que queriam ver os elfos massacrados e seus registros queimados. Os documentos sobreviveram: registros de mortes, nascimentos, estações e de todos os tratados que os elfos haviam feito.",
			source = "https://warcraft.wiki.gg/wiki/Quel'Danil_Lodge",
		},
		["revantusk village"] = {
			name = "Aldeia Revatusco",
			short = "A Aldeia Revatusco fica no litoral das Terras Agrestes, o último lar de uma tribo de trolls da floresta que escolheu a lealdade em vez da sobrevivência.",
			full = "A Aldeia Revatusco fica no litoral das Terras Agrestes, o último lar de uma tribo de trolls da floresta que escolheu a lealdade em vez da sobrevivência.\n\nQuando a Velha Horda se desfez na Segunda Guerra, os captores dos orcs se voltaram contra seus antigos aliados, e tribos de trolls da floresta de toda a terra abandonaram a Horda sem hesitar. Os Revatusco não. Não tinham números para libertar os orcs cativos, que, de todo modo, mostravam pouca vontade de ser libertados, mas sua lealdade persistente os marcou como alvo de outros trolls que não queriam mais nada com os orcs. Expulsos de suas terras, os Revatusco fugiram para o litoral das Terras Agrestes, esperando que o isolamento os mantivesse a salvo, e construíram ali sua aldeia.\n\nCom o tempo, chegou até eles a notícia de que Thrall havia refeito a Horda e levado seu povo de volta aos costumes xamânicos de seus ancestrais. Os Revatusco enviaram seus corredores mais velozes para encontrá-lo, e desse encontro nasceu um pacto de amizade entre a tribo e a nova Horda. Os outros trolls da floresta nunca perdoaram isso, chamando os Revatusco de fracos e traiçoeiros, enquanto os Revatusco chamam de verdadeiros traidores todos os que desertaram a Horda.",
			source = "https://warcraft.wiki.gg/wiki/Revantusk_Village",
		},
		["seradane"] = {
			name = "Seradane",
			short = "No nordeste das Terras Agrestes fica Seradane, onde um grande portal circular se abre para o Sonho Esmeralda. A floresta pertence à revoada verde, atraída para guardar o limiar que sua espécie considera sagrado.",
			full = "No nordeste das Terras Agrestes fica Seradane, onde um grande portal circular se abre para o Sonho Esmeralda. A floresta pertence à revoada verde, atraída para guardar o limiar que sua espécie considera sagrado. Os dracos Rothos e Dreamtracker fizeram seu lar entre estas árvores.\n\nA maioria dos que guardam a mata são dracônidas, nascidos do poder da revoada. Eles se movem em grupos de três, um Oráculo Verdantino flanqueado por Guarda-galhos e Protetores das Árvores, patrulhando as trilhas emaranhadas numa vigília permanente sobre o caminho para o Sonho.",
			source = "https://warcraft.wiki.gg/wiki/Seradane",
		},
		["shadraalor"] = {
			name = "Shadra'Alor",
			short = "Nas Terras Agrestes fica Shadra'Alor, um povoado erguido pelos trolls da floresta do Império Amani. Aqui a loa Shadra podia ser chamada e invocada, um lugar reservado apenas a esse propósito.",
			full = "Nas Terras Agrestes fica Shadra'Alor, um povoado erguido pelos trolls da floresta do Império Amani. Aqui a loa Shadra podia ser chamada e invocada, um lugar reservado apenas a esse propósito.",
			source = "https://warcraft.wiki.gg/wiki/Shadra'Alor",
		},
		["shaolwatha"] = {
			name = "Shaol'watha",
			short = "Shaol'watha é uma ruína dos trolls da floresta Vilebranch no nordeste das Terras Agrestes. Um dia foi um templo.",
			full = "Shaol'watha é uma ruína dos trolls da floresta Vilebranch no nordeste das Terras Agrestes. Um dia foi um templo.",
			source = "https://warcraft.wiki.gg/wiki/Shaol'watha",
		},
		["shindiggers camp"] = {
			name = "Alambique do Borracho",
			short = "Rapsódico Festanjeiro, um anão chegado a uma bebida, mantém seu pequeno acampamento nas Terras Agrestes ao lado do alto elfo Gilveradin Buscassol, uma dupla estranha que ocupa este trecho tranquilo de terra.",
			full = "Rapsódico Festanjeiro, um anão chegado a uma bebida, mantém seu pequeno acampamento nas Terras Agrestes ao lado do alto elfo Gilveradin Buscassol, uma dupla estranha que ocupa este trecho tranquilo de terra.",
			source = "https://warcraft.wiki.gg/wiki/Shindigger's_Camp",
		},
		["skulk rock"] = {
			name = "Rocha Oculta",
			short = "A Rocha Oculta é uma ruína dos trolls da floresta tomada por gosmas. Uma caverna sob ela é um dos poucos lugares onde ainda crescem Cogumelos-fantasma.",
			full = "A Rocha Oculta é uma ruína dos trolls da floresta tomada por gosmas. Uma caverna sob ela é um dos poucos lugares onde ainda crescem Cogumelos-fantasma.\n\nDurante a Segunda Guerra, a Velha Horda usou a rocha como base, até que a Aliança de Lordaeron a expulsou.",
			source = "https://warcraft.wiki.gg/wiki/Skulk_Rock",
		},
		["valorwind lake"] = {
			name = "Lago Valovento",
			short = "O Lago Valovento repousa tranquilo a nordeste de Shadra'Alor, com águas aparentemente comuns.",
			full = "O Lago Valovento repousa tranquilo a nordeste de Shadra'Alor, com águas aparentemente comuns. Ainda assim, ao longo de suas margens cresce algo que não se conhece em nenhum outro lugar do mundo: o Tragan Violeta, um cogumelo misterioso cujos segredos continuam só seus.",
			source = "https://warcraft.wiki.gg/wiki/Valorwind_Lake",
		},
		["wildhammer keep"] = {
			name = "Bastilha Martelo Feroz",
			short = "A Bastilha Martelo Feroz se ergue no coração do Ninho da Águia, sede dos anões Martelo Feroz que a ocupam. Seus salões estão abertos aos viajantes que chegam ao pico.",
			full = "A Bastilha Martelo Feroz se ergue no coração do Ninho da Águia, sede dos anões Martelo Feroz que a ocupam. Seus salões estão abertos aos viajantes que chegam ao pico.",
			source = "https://warcraft.wiki.gg/wiki/Wildhammer_Keep",
		},
		["zunwatha"] = {
			name = "Zun'watha",
			short = "As pedras de Zun'watha abrigaram, e ainda abrigam, os trolls Cascasseca das Terras Agrestes.",
			full = "As pedras de Zun'watha abrigaram, e ainda abrigam, os trolls Cascasseca das Terras Agrestes. Entre as ruínas que deixaram de pé, um malévolo zul'arek é visto de vez em quando, andando por onde os Cascasseca ainda vivem.",
			source = "https://warcraft.wiki.gg/wiki/Zun'watha",
		},
	},
	-- Dun Morogh: 25 subzones
	[1426] = {
		["amberstill ranch"] = {
			name = "Rancho Ambarmanso",
			short = "O Rancho Ambarmanso fica à beira da estrada para Loch Modan, ao norte da Pedreira Gol'Bolar, onde os anões da família Ambarmanso criam seus rebanhos enfrentando o frio de Dun Morogh.",
			full = "O Rancho Ambarmanso fica à beira da estrada para Loch Modan, ao norte da Pedreira Gol'Bolar, onde os anões da família Ambarmanso criam seus rebanhos enfrentando o frio de Dun Morogh. Rudra Ambarmanso cria carneiros premiados aqui, enquanto a jovem Yarlyn mantém seus coelhos-da-neve sempre por perto.\n\nOs rebanhos não vivem sem problemas. Um wendigo chamado Vagash passou a caçar os animais do rancho, e os Ambarmanso tiveram de defender o que criam contra sua fome.",
			source = "https://warcraft.wiki.gg/wiki/Amberstill_Ranch",
		},
		["anvilmar"] = {
			name = "Sidermar",
			short = "No Vale Cristálgida fica Sidermar, um salão construído ao redor de uma grande forja. Foi o primeiro povoado de verdade que os anões ergueram nestas terras do norte, um ponto de encontro antes que qualquer outro tomasse forma.",
			full = "No Vale Cristálgida fica Sidermar, um salão construído ao redor de uma grande forja. Foi o primeiro povoado de verdade que os anões ergueram nestas terras do norte, um ponto de encontro antes que qualquer outro tomasse forma. A forja em seu coração ainda arde, embora nenhum ferreiro ensine seu ofício ali agora.",
			source = "https://warcraft.wiki.gg/wiki/Anvilmar",
		},
		["brewnall village"] = {
			name = "Aldeia da Cevada",
			short = "A Aldeia da Cevada fica no Vale Brisa Álgida, perto de Gnomeregan, lar da família Cervevada. Os Cervevada se dedicaram a uma única busca: aperfeiçoar a arte anã da cervejaria.",
			full = "A Aldeia da Cevada fica no Vale Brisa Álgida, perto de Gnomeregan, lar da família Cervevada. Os Cervevada se dedicaram a uma única busca: aperfeiçoar a arte anã da cervejaria. Eles mandam seus jovens para fora da aldeia para protegê-la dos animais selvagens e buscar ingredientes raros para a cerveja definitiva.",
			source = "https://warcraft.wiki.gg/wiki/Brewnall_Village",
		},
		["chill breeze valley"] = {
			name = "Vale Brisa Álgida",
			short = "O Vale Brisa Álgida corre de leste a oeste entre Gnomeregan e Kharanos, com seu caminho bem conhecido pelos jovens anões e gnomos que passam por ali.",
			full = "O Vale Brisa Álgida corre de leste a oeste entre Gnomeregan e Kharanos, com seu caminho bem conhecido pelos jovens anões e gnomos que passam por ali. Mas o vale também se curva para o norte e para o sul, e ali a neve conta outra história: manchas de sangue se espalham pelo branco, e carcaças de animais despedaçadas jazem abandonadas. Poucos percorrem esse ramal por vontade própria. Os que o fazem vão caçar as feras responsáveis, na esperança de acabar com a ameaça às terras anãs, e muitos não voltam. No fundo de uma das cavernas fica o covil de um wendigo, a criatura mais responsável pelo sangue na neve.",
			source = "https://warcraft.wiki.gg/wiki/Chill_Breeze_Valley",
		},
		["coldridge pass"] = {
			name = "Caminho de Cristálgida",
			short = "O Caminho de Cristálgida é a saída estreita do Vale Cristálgida, o último trecho que um anão precisa atravessar antes de chegar a Kharanos e às estradas mais amplas de Dun Morogh.",
			full = "O Caminho de Cristálgida é a saída estreita do Vale Cristálgida, o último trecho que um anão precisa atravessar antes de chegar a Kharanos e às estradas mais amplas de Dun Morogh. Os troggs tomaram o caminho, e os viajantes ficam com apenas duas opções: atravessar correndo o mais rápido que as pernas permitirem ou abrir à força um caminho sangrento entre os invasores.\n\nFendrig Redbeard certa vez levou outros doze mineiros ao caminho para investigar a infestação. Lá no fundo, ele ficou preso sob um desabamento de pedras. Os outros voltaram para desenterrá-lo, mas o esforço fez o caminho desabar ao redor deles. Doze mineiros morreram. Apenas Fendrig, retirado dos escombros, sobreviveu.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Pass",
		},
		["coldridge valley"] = {
			name = "Vale Cristálgida",
			short = "A neve se acumula espessa sobre o Vale Cristálgida, cercado por todos os lados, com a única saída sendo o túnel estreito do Caminho de Cristálgida, a nordeste.",
			full = "A neve se acumula espessa sobre o Vale Cristálgida, cercado por todos os lados, com a única saída sendo o túnel estreito do Caminho de Cristálgida, a nordeste. Essa passagem está infestada de troggs saqueadores, criaturas brutais que há muito tornam perigosa a travessia até Kharanos e Altaforja para quem viaja sozinho.\n\nAlém do caminho, a estrada sobe para o leste e depois para o norte, passando por Kharanos, antes de serpentear pelas montanhas até os próprios portões de Altaforja.",
			source = "https://warcraft.wiki.gg/wiki/Coldridge_Valley",
		},
		["frostmane hold"] = {
			name = "Fortaleza Jubafria",
			short = "A Fortaleza Jubafria fica no limite oeste das montanhas geladas de Dun Morogh, ao sul de Gnomeregan, um punhado de construções ligadas a um sistema de cavernas escavado na encosta da montanha.",
			full = "A Fortaleza Jubafria fica no limite oeste das montanhas geladas de Dun Morogh, ao sul de Gnomeregan, um punhado de construções ligadas a um sistema de cavernas escavado na encosta da montanha. É o acampamento-base dos trolls do gelo Jubafria, que dominam o terreno com caçadores de cabeças e esfoladores guardando cada acesso.",
			source = "https://warcraft.wiki.gg/wiki/Frostmane_Hold",
		},
		["gates of ironforge"] = {
			name = "Portões de Altaforja",
			short = "Os Portões de Altaforja se erguem onde a grande rampa de Dun Morogh sobe para encontrar a montanha, visíveis a quilômetros de distância sobre a neve antes que o viajante chegue até eles.",
			full = "Os Portões de Altaforja se erguem onde a grande rampa de Dun Morogh sobe para encontrar a montanha, visíveis a quilômetros de distância sobre a neve antes que o viajante chegue até eles. São o limiar entre as terras abertas dos anões e a própria Altaforja.\n\nAo atravessá-los, fica-se sob o olhar de uma enorme estátua erguida ao Grão-rei Modimus Sidermar, posta para vigiar logo depois da entrada, de modo que ninguém entre na cidade sem antes passar sob seus olhos.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
		["gnomeregan"] = {
			name = "Gnomeregan",
			short = "Gnomeregan é a capital subterrânea do reino gnômico de mesmo nome, uma prova em ferro forjado do brilhantismo, da ambição e da engenhosidade dos gnomos.",
			full = "Gnomeregan é a capital subterrânea do reino gnômico de mesmo nome, uma prova em ferro forjado do brilhantismo, da ambição e da engenhosidade dos gnomos.\n\nDurante a Terceira Guerra, uma invasão de troggs provocou sua queda. Os troggs haviam sido arrancados de seu sono pela agitação dos sítios titânicos e invadiram a cidade vindos de baixo. Numa tentativa desesperada de matar os invasores, o Grão-faz-tudo Gelbin Mekkatorque, a conselho de seu assessor Sicco Thermaplugg, ordenou a seu povo que abrisse as válvulas de pressão de suas máquinas gigantescas e trituradoras e liberasse radiação tóxica por toda Gnomeregan. Embora o gás tenha matado alguns troggs, só fortaleceu outros, e quase oitenta por cento dos gnomos morreram em poucos dias. Os sobreviventes fugiram para a proteção de Altaforja. Outros foram transformados em gnomos leprosos horrendos, sem mente e malignos, que ainda assombram os túneis arruinados.\n\nEnlouquecido ele próprio pela radiação, Thermaplugg se declarou \"Rei de Gnomeregan\" e tomou o controle da cidade envenenada, liderando um exército de troggs e gnomos leprosos por seus salões e oficinas destroçados.",
			source = "https://warcraft.wiki.gg/wiki/Gnomeregan",
		},
		["golbolar quarry"] = {
			name = "Pedreira Gol'Bolar",
			short = "A Pedreira Gol'Bolar fica escavada no sudeste de Dun Morogh, um acampamento de mineração interrompido pelo que veio rastejando lá de baixo.",
			full = "A Pedreira Gol'Bolar fica escavada no sudeste de Dun Morogh, um acampamento de mineração interrompido pelo que veio rastejando lá de baixo. Os anões abriram a escavação em busca do que a montanha guardava, mas a escavação despertou os troggs, que subiram em massa das profundezas da mina e tomaram os poços e túneis que os mineiros haviam aberto.\n\nO acampamento que resta é um ponto de apoio, não uma vitória: os anões dominam a superfície, enquanto a mina lá embaixo continua perdida para os troggs.",
			source = "https://warcraft.wiki.gg/wiki/Gol'Bolar_Quarry",
		},
		["grizzled den"] = {
			name = "Covil Cinzento",
			short = "Um grande sistema de cavernas se abre a sudoeste de Kharanos, penetrando fundo no gelo de Dun Morogh. Os wendigos fizeram seu covil aqui, feras peludas de hálito gélido que se juntam contra qualquer um que invada.",
			full = "Um grande sistema de cavernas se abre a sudoeste de Kharanos, penetrando fundo no gelo de Dun Morogh. Os wendigos fizeram seu covil aqui, feras peludas de hálito gélido que se juntam contra qualquer um que invada. Suas jubas são valorizadas para forrar assentos, embora poucos dos que entram atrás delas saiam sem luta, pois os wendigos não se dispersam: cerram fileiras e expulsam os intrusos com garras e hálito congelante.",
			source = "https://warcraft.wiki.gg/wiki/Grizzled_Den",
		},
		["helms bed lake"] = {
			name = "Lago Helm",
			short = "O Lago Helm fica congelado a maior parte do ano, com a superfície presa sob um gelo espesso o bastante para se atravessar com segurança. Apenas um único buraco é mantido aberto, cortado para que ainda se possa tirar água doce de baixo da geada.",
			full = "O Lago Helm fica congelado a maior parte do ano, com a superfície presa sob um gelo espesso o bastante para se atravessar com segurança. Apenas um único buraco é mantido aberto, cortado para que ainda se possa tirar água doce de baixo da geada.\n\nA segurança termina na margem. Lobos e outras criaturas selvagens percorrem as margens, e troggs perdidos assombram as rochas ao redor. Ao sul do lago fica uma construção abandonada tomada por anões Ferro Negro, que atacam qualquer um que se aproxime demais.",
			source = "https://warcraft.wiki.gg/wiki/Helm's_Bed_Lake",
		},
		["iceflow lake"] = {
			name = "Lago Nevado",
			short = "O Lago Nevado congela por completo no frio de Dun Morogh, mas os anões da Aldeia da Cevada mantêm um buraco aberto no gelo, tirando água doce e peixes de baixo da superfície congelada.",
			full = "O Lago Nevado congela por completo no frio de Dun Morogh, mas os anões da Aldeia da Cevada mantêm um buraco aberto no gelo, tirando água doce e peixes de baixo da superfície congelada.\n\nMais para o centro do lago se erguem duas ilhas que é melhor deixar em paz. Uma matilha de lobos famintos as tomou, sob o comando de um lobo chamado Timber, e sua presença mantém as ilhas vazias de tudo, exceto das feras que as dominam.",
			source = "https://warcraft.wiki.gg/wiki/Iceflow_Lake",
		},
		["ironbands compound"] = {
			name = "Complexo de Bandaferro",
			short = "Ao sul do Lago Helm, o Complexo de Bandaferro serve de ponto de apoio para os anões Ferro Negro, que atacam qualquer um que se aproxime demais. O lugar um dia pertenceu a Sturgy Bandaferro, antes de cair nas mãos dos Ferro Negro.",
			full = "Ao sul do Lago Helm, o Complexo de Bandaferro serve de ponto de apoio para os anões Ferro Negro, que atacam qualquer um que se aproxime demais. O lugar um dia pertenceu a Sturgy Bandaferro, antes de cair nas mãos dos Ferro Negro.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Compound",
		},
		["kharanos"] = {
			name = "Kharanos",
			short = "Kharanos fica entre os picos de Dun Morogh, com as ruas cercadas por ermos invernais que nunca deixam seu povo amolecer.",
			full = "Kharanos fica entre os picos de Dun Morogh, com as ruas cercadas por ermos invernais que nunca deixam seu povo amolecer. Uma forja arde em seu coração, uma oficina gnômica faz barulho sem parar, e a Destilaria Cervaforte serve algumas das melhores cervejas que se podem encontrar em qualquer lugar, mas a cidade nunca conseguiu descansar tranquila em seu encanto. A oeste fica uma caverna repleta de wendigos, e a noroeste os trolls Jubafria ocupam a Cordilheira Cintilante, vigiando a cidade lá embaixo.\n\nEssa vigilância certa vez se transformou em guerra, quando um troll Jubafria gigante caiu sobre Kharanos e quase exterminou todos os anões que viviam ali. Onde os defensores da cidade vacilaram, um anão não vacilou. Lazlo Grindwidget enfrentou o troll e o derrubou sozinho, e por isso a cidade o chamou de herói, um título que o acompanha desde então pelas ruas que se lembram de quão perto chegaram do silêncio.",
			source = "https://warcraft.wiki.gg/wiki/Kharanos",
		},
		["misty pine refuge"] = {
			name = "Refúgio Pinhal das Brumas",
			short = "O Refúgio Pinhal das Brumas repousa tranquilo no centro de Dun Morogh, uma clareira abrigada entre os pinheiros carregados de neve.",
			full = "O Refúgio Pinhal das Brumas repousa tranquilo no centro de Dun Morogh, uma clareira abrigada entre os pinheiros carregados de neve.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Pine_Refuge",
		},
		["north gate outpost"] = {
			name = "Posto de Guarda do Portão Norte",
			short = "O Posto de Guarda do Portão Norte fica sobre o Desfiladeiro do Portão Norte, a passagem estreita pelas montanhas que liga Dun Morogh a Loch Modan, a mais a nordeste das posses anãs nestas terras altas.",
			full = "O Posto de Guarda do Portão Norte fica sobre o Desfiladeiro do Portão Norte, a passagem estreita pelas montanhas que liga Dun Morogh a Loch Modan, a mais a nordeste das posses anãs nestas terras altas.\n\nOs montanhistas aquartelados aqui passam os dias repelindo os animais selvagens que avançam dos picos ao redor. Alguns dos que saíram para caçar as feras mais perigosas não voltaram, e as montanhas foram vasculhadas em busca de notícias deles, com pouco resultado.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Outpost",
		},
		["north gate pass"] = {
			name = "Desfiladeiro do Portão Norte",
			short = "O desfiladeiro corta as altas montanhas, descendo de Dun Morogh em direção a Loch Modan.",
			full = "O desfiladeiro corta as altas montanhas, descendo de Dun Morogh em direção a Loch Modan. É o caminho mais curto entre as duas, e os viajantes com destino às terras além do Loch passam por aqui mais do que por qualquer outro caminho.\n\nO Posto de Guarda do Portão Norte monta guarda aqui, defendendo a passagem.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["shimmer ridge"] = {
			name = "Cordilheira Cintilante",
			short = "A Cordilheira Cintilante se ergue no norte de Dun Morogh, ocupada por trolls Jubafria que mantêm dois acampamentos ligados por uma ponte, cultivando erva-cintilante e domando javalis entre as rochas.",
			full = "A Cordilheira Cintilante se ergue no norte de Dun Morogh, ocupada por trolls Jubafria que mantêm dois acampamentos ligados por uma ponte, cultivando erva-cintilante e domando javalis entre as rochas.",
			source = "https://warcraft.wiki.gg/wiki/Shimmer_Ridge",
		},
		["south gate outpost"] = {
			name = "Posto de Guarda do Portão Sul",
			short = "O Posto de Guarda do Portão Sul fica onde o desfiladeiro se estreita entre Dun Morogh e Loch Modan, um gargalo de pedra ocupado por montanhistas anões.",
			full = "O Posto de Guarda do Portão Sul fica onde o desfiladeiro se estreita entre Dun Morogh e Loch Modan, um gargalo de pedra ocupado por montanhistas anões. O trabalho deles é mais tranquilo que o de seus parentes do Portão Norte: eles repeliram os animais selvagens que antes pressionavam o desfiladeiro, e a estrada que passa por ele continua aberta e segura para quem vai ou vem de Thelsamar.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Outpost",
		},
		["south gate pass"] = {
			name = "Desfiladeiro do Portão Sul",
			short = "O Desfiladeiro do Portão Sul corta as montanhas, ligando as neves altas de Dun Morogh aos vales mais baixos de Loch Modan. É o caminho mais curto até Thelsamar, gasto pelos viajantes entre as duas terras.",
			full = "O Desfiladeiro do Portão Sul corta as montanhas, ligando as neves altas de Dun Morogh aos vales mais baixos de Loch Modan. É o caminho mais curto até Thelsamar, gasto pelos viajantes entre as duas terras.\n\nAqui fica o Posto de Guarda do Portão Sul, um posto de guarda instalado para vigiar o desfiladeiro.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["steelgrills depot"] = {
			name = "Garagem do Gradaço",
			short = "A Garagem do Gradaço fica a leste de Kharanos, um pequeno acampamento de mineiros e engenheiros que trabalham o chão congelado de Dun Morogh.",
			full = "A Garagem do Gradaço fica a leste de Kharanos, um pequeno acampamento de mineiros e engenheiros que trabalham o chão congelado de Dun Morogh.",
			source = "https://warcraft.wiki.gg/wiki/Steelgrill's_Depot",
		},
		["thunderbrew distillery"] = {
			name = "Destilaria Cervaforte",
			short = "A Destilaria Cervaforte fica em Kharanos, com um nome conhecido muito além da cidade anã pela qualidade de sua cerveja. O Estalajadeiro Belm cuida do lugar, oferecendo descanso e bebida aos que passam por ali.",
			full = "A Destilaria Cervaforte fica em Kharanos, com um nome conhecido muito além da cidade anã pela qualidade de sua cerveja. O Estalajadeiro Belm cuida do lugar, oferecendo descanso e bebida aos que passam por ali.",
			source = "https://warcraft.wiki.gg/wiki/Thunderbrew_Distillery",
		},
		["tundrid hills"] = {
			name = "Montes Túndricos",
			short = "Os Montes Túndricos ficam ao sul da Pedreira Gol'Bolar, uma extensão de terreno varrido pelo vento onde poucos viajam sem uma lâmina na mão.",
			full = "Os Montes Túndricos ficam ao sul da Pedreira Gol'Bolar, uma extensão de terreno varrido pelo vento onde poucos viajam sem uma lâmina na mão. Lobos e outras criaturas selvagens rondam as encostas, e os que atravessam os montes como atalho entre o Vale Cristálgida e o leste de Dun Morogh o fazem sabendo que a estrada por Kharanos teria sido mais segura.\n\nOs trolls Jubafria ergueram um acampamento no vale daqui, ocupando este terreno à vista da pedreira dos anões.",
			source = "https://warcraft.wiki.gg/wiki/Tundrid_Hills",
		},
	},
	-- Garganta Abrasadora: 11 subzones
	[1427] = {
		["blackchar cave"] = {
			name = "Caverna Calcinar",
			short = "A Caverna Calcinar está selada perto da Montanha Rocha Negra, com sua pedra escura silenciosa e isolada do mundo lá fora.",
			full = "A Caverna Calcinar está selada perto da Montanha Rocha Negra, com sua pedra escura silenciosa e isolada do mundo lá fora.",
			source = "https://warcraft.wiki.gg/wiki/Blackchar_Cave",
		},
		["blackrock mountain"] = {
			name = "Montanha Rocha Negra",
			short = "A Montanha Rocha Negra não nasceu de um fogo comum.",
			full = "A Montanha Rocha Negra não nasceu de um fogo comum. Quando os exércitos Barbabronze e Martelo Feroz marcharam para expurgar o clã Ferro Negro durante a Guerra dos Três Martelos, o Feiticeiro-thane Thaurissan alcançou o coração derretido do mundo e arrancou seu poder como arma. O que lhe respondeu foi Ragnaros. O renascimento do Senhor do Fogo despedaçou as montanhas, afogou em fogo as terras ao redor e fez os dois reis recuarem seus exércitos em vez de enfrentá-lo. Onde antes ficava o reino dos Ferro Negro, agora fumegava um vulcão, com as Estepes Ardentes ao sul e a Garganta Abrasadora ao norte. Ragnaros se recolheu ao núcleo da montanha e escravizou os anões Ferro Negro sobreviventes para escavar a Cidade Forjasombra sob seu próprio lar arruinado.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["cauldron"] = {
			name = "O Caldeirão",
			short = "O Caldeirão é uma vasta escavação aberta no centro da Garganta Abrasadora, fortificada pelos anões Ferro Negro algum tempo depois de invocarem Ragnaros.",
			full = "O Caldeirão é uma vasta escavação aberta no centro da Garganta Abrasadora, fortificada pelos anões Ferro Negro algum tempo depois de invocarem Ragnaros. As grandes máquinas que eles usaram para abri-lo ainda cercam suas bordas. Lá embaixo, elementais de fogo e de magma se movem pelas fendas rachadas e incandescentes.\n\nTrabalhadores escravos capturados pelos Ferro Negro labutam sem fim lá embaixo, destroçados pelo trabalho e pelo calor opressivo. Já não distinguem amigo de captor e recebem qualquer um que entre com a mesma violência cega de qualquer capataz.",
			source = "https://warcraft.wiki.gg/wiki/Cauldron",
		},
		["dustfire valley"] = {
			name = "Vale Calcinado",
			short = "O Vale Calcinado corta a Garganta Abrasadora, um terreno varrido pelo vento que leva ao norte até os portões da Galeria Lapidada e, mais além, ao Vale dos Reis, em Loch Modan.",
			full = "O Vale Calcinado corta a Garganta Abrasadora, um terreno varrido pelo vento que leva ao norte até os portões da Galeria Lapidada e, mais além, ao Vale dos Reis, em Loch Modan.",
			source = "https://warcraft.wiki.gg/wiki/Dustfire_Valley",
		},
		["firewatch ridge"] = {
			name = "Cerro da Sentinela de Fogo",
			short = "O Cerro da Sentinela de Fogo é o principal acampamento dos anões Ferro Negro na Garganta Abrasadora, com vista para a grande escavação do Caldeirão.",
			full = "O Cerro da Sentinela de Fogo é o principal acampamento dos anões Ferro Negro na Garganta Abrasadora, com vista para a grande escavação do Caldeirão. Os anões Ferro Negro dominam as encostas com golens mecânicos e aranhas de fogo gigantes, tornando o cerro um lugar perigoso de se pisar.",
			source = "https://warcraft.wiki.gg/wiki/Firewatch_Ridge",
		},
		["grimesilt dig site"] = {
			name = "Escavação Pedrassuja",
			short = "Anões de Altaforja escavavam aqui, até que os anões Ferro Negro chegaram e tomaram o sítio para si. Ele continua nas mãos dos Ferro Negro.",
			full = "Anões de Altaforja escavavam aqui, até que os anões Ferro Negro chegaram e tomaram o sítio para si. Ele continua nas mãos dos Ferro Negro.",
			source = "https://warcraft.wiki.gg/wiki/Grimesilt_Dig_Site",
		},
		["sea of cinders"] = {
			name = "Mar de Cinzas",
			short = "O Mar de Cinzas se estende plano e aberto no extremo sul da Garganta Abrasadora, logo ao norte da Montanha Rocha Negra. Nada cresce ali.",
			full = "O Mar de Cinzas se estende plano e aberto no extremo sul da Garganta Abrasadora, logo ao norte da Montanha Rocha Negra. Nada cresce ali. O chão ainda fumega, e as cinzas sobem constantemente com o vento, espalhando-se pela planície estéril. O fogo e o vento não deixaram nada além de devastação, e a queima nunca parou.",
			source = "https://warcraft.wiki.gg/wiki/Sea_of_Cinders",
		},
		["slag pit"] = {
			name = "Fosso de Lava",
			short = "O Fosso de Lava afunda nas profundezas da escavação do Caldeirão, na Garganta Abrasadora, trabalhado por escravos sob a crueldade dos anões Ferro Negro.",
			full = "O Fosso de Lava afunda nas profundezas da escavação do Caldeirão, na Garganta Abrasadora, trabalhado por escravos sob a crueldade dos anões Ferro Negro. Escravagistas e capatazes mantêm o trabalho em andamento, e até os trabalhadores intimidados se voltam contra qualquer um que ataque seus feitores. Os Ferro Negro respondem a qualquer interferência em sua mineração com hostilidade aberta e, na escuridão mais profunda do fosso, incendossauros famintos se aninham entre as escavações.",
			source = "https://warcraft.wiki.gg/wiki/Slag_Pit",
		},
		["stonewrought pass"] = {
			name = "Galeria Lapidada",
			short = "O túnel conhecido como Galeria Lapidada atravessa as montanhas, ligando a Garganta Abrasadora ao Vale dos Reis, em Loch Modan, na extremidade norte do Vale Calcinado.",
			full = "O túnel conhecido como Galeria Lapidada atravessa as montanhas, ligando a Garganta Abrasadora ao Vale dos Reis, em Loch Modan, na extremidade norte do Vale Calcinado. É obra de Franclorn Forjífice, que também ergueu o Dique Lapidado e muitas outras obras de cantaria anã pelos Reinos do Leste.\n\nO portão de Loch Modan é mantido fechado pelo Montanhista Pedrabrita, que barra o caminho a todos, exceto aos que provaram seu valor contra Margol, o Furioso.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Pass",
		},
		["tanner camp"] = {
			name = "Acampamento Curtume",
			short = "Sara Correia, mestra em couraria elemental, mantém uma tenda solitária na Garganta Abrasadora. Atrás dela, uma longa passagem serpenteia montanha adentro, terminando onde o lagarto-trovão Margol, o Furioso, espera.",
			full = "Sara Correia, mestra em couraria elemental, mantém uma tenda solitária na Garganta Abrasadora. Atrás dela, uma longa passagem serpenteia montanha adentro, terminando onde o lagarto-trovão Margol, o Furioso, espera.",
			source = "https://warcraft.wiki.gg/wiki/Tanner_Camp",
		},
		["thorium point"] = {
			name = "Posto de Tório",
			short = "No norte calcinado da Garganta Abrasadora fica o Posto de Tório, uma pequena cidade neutra mantida pela Irmandade do Tório, habitada principalmente por anões Ferro Negro que se mantêm fiéis à Irmandade em vez dos poderes sombrios sob as montanhas.",
			full = "No norte calcinado da Garganta Abrasadora fica o Posto de Tório, uma pequena cidade neutra mantida pela Irmandade do Tório, habitada principalmente por anões Ferro Negro que se mantêm fiéis à Irmandade em vez dos poderes sombrios sob as montanhas. Uma forja e uma bigorna estão prontas aqui, mantidas acesas em meio às cinzas e ao calor, onde o metal ainda é moldado apesar do que a Garganta se tornou.",
			source = "https://warcraft.wiki.gg/wiki/Thorium_Point",
		},
	},
	-- Estepes Ardentes: 11 subzones
	[1428] = {
		["blackrock mountain"] = {
			name = "Montanha Rocha Negra",
			short = "A Montanha Rocha Negra não nasceu de um fogo comum.",
			full = "A Montanha Rocha Negra não nasceu de um fogo comum. Quando os exércitos Barbabronze e Martelo Feroz marcharam para expurgar o clã Ferro Negro durante a Guerra dos Três Martelos, o Feiticeiro-thane Thaurissan alcançou o coração derretido do mundo e arrancou seu poder como arma. O que lhe respondeu foi Ragnaros. O renascimento do Senhor do Fogo despedaçou as montanhas, afogou em fogo as terras ao redor e fez os dois reis recuarem seus exércitos em vez de enfrentá-lo. Onde antes ficava o reino dos Ferro Negro, agora fumegava um vulcão, com as Estepes Ardentes ao sul e a Garganta Abrasadora ao norte. Ragnaros se recolheu ao núcleo da montanha e escravizou os anões Ferro Negro sobreviventes para escavar a Cidade Forjasombra sob seu próprio lar arruinado.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Mountain",
		},
		["blackrock pass"] = {
			name = "Estreito Rocha Negra",
			short = "O Estreito Rocha Negra é o limiar entre dois mundos. De um lado fica Cristarrubra, verde e tranquila. Do outro, esperam as Estepes Ardentes, calcinadas e retorcidas a ponto de ficarem irreconhecíveis.",
			full = "O Estreito Rocha Negra é o limiar entre dois mundos. De um lado fica Cristarrubra, verde e tranquila. Do outro, esperam as Estepes Ardentes, calcinadas e retorcidas a ponto de ficarem irreconhecíveis. Um portão fica na fronteira, marcando a linha com clareza.\n\nAtravessá-lo é deixar a segurança para trás num único passo. Os que passam despreparados acham a mudança brutal: as criaturas do outro lado são muito mais cruéis do que qualquer coisa que se mova nas montanhas às suas costas.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Pass",
		},
		["blackrock stronghold"] = {
			name = "Fortaleza Rocha Negra",
			short = "A fortaleza se ergue na borda das Estepes Ardentes, colada à sombra do Pico da Rocha Negra, uma fortificação de pedra negra ocupada pelo clã Rocha Negra.",
			full = "A fortaleza se ergue na borda das Estepes Ardentes, colada à sombra do Pico da Rocha Negra, uma fortificação de pedra negra ocupada pelo clã Rocha Negra. Do lado de fora de suas muralhas, nos Campos de Honra, os guerreiros do clã e seus aliados se reúnem e treinam, mantidos na linha pelo chicote e pela voz dos Sargentos Rocha Negra.\n\nO comando da fortaleza cabe ao General Thorg'izog, que disciplina as tropas reunidas nos campos e garante que suas ordens sejam cumpridas sem questionamento.",
			source = "https://warcraft.wiki.gg/wiki/Blackrock_Stronghold",
		},
		["dracodar"] = {
			name = "Draco'dar",
			short = "As colinas de Draco'dar estão enegrecidas e calcinadas, entregues por completo à revoada negra. Seus membros circulam livremente por aqui, tão numerosos que ninguém deveria entrar ali sem cautela e sem companhia.",
			full = "As colinas de Draco'dar estão enegrecidas e calcinadas, entregues por completo à revoada negra. Seus membros circulam livremente por aqui, tão numerosos que ninguém deveria entrar ali sem cautela e sem companhia.",
			source = "https://warcraft.wiki.gg/wiki/Draco'dar",
		},
		["dreadmaul rock"] = {
			name = "Rochedo Malhorrendo",
			short = "O Rochedo Malhorrendo é uma fortaleza de caminhos de pedra e montes de ogros escavados, sede do clã Firegut.",
			full = "O Rochedo Malhorrendo é uma fortaleza de caminhos de pedra e montes de ogros escavados, sede do clã Firegut. De suas alturas e túneis, os Firegut lançam seus ataques para o sul, nas Montanhas Cristarrubra, usando o rochedo como base antes de recuar para suas profundezas.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmaul_Rock",
		},
		["flame crest"] = {
			name = "Monte Candente",
			short = "O Monte Candente fica num afloramento nu nas Estepes Ardentes, acessível apenas por uma ponte rústica. Na pequena caverna ao fundo vive Kibler, que tem um papagaio falante.",
			full = "O Monte Candente fica num afloramento nu nas Estepes Ardentes, acessível apenas por uma ponte rústica. Na pequena caverna ao fundo vive Kibler, que tem um papagaio falante.",
			source = "https://warcraft.wiki.gg/wiki/Flame_Crest",
		},
		["morgans vigil"] = {
			name = "Vigia de Morgan",
			short = "A Vigia de Morgan jaz em ruínas no sudeste das Estepes Ardentes, com as casas queimadas até o chão e a torre dos magos reduzida a escombros.",
			full = "A Vigia de Morgan jaz em ruínas no sudeste das Estepes Ardentes, com as casas queimadas até o chão e a torre dos magos reduzida a escombros. Tendas se erguem entre os destroços, abrigando os que ficaram.\n\nDessas tendas a Aliança mantém sua vigília sobre a Montanha Rocha Negra, atacando o perigo mais perto de sua origem.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Vigil",
		},
		["pillar of ash"] = {
			name = "Pilar de Cinzas",
			short = "Uma torre alta de pedra calcinada se ergue na extremidade leste da Choupana Dente Negro, com a superfície enegrecida como se o próprio fogo tivesse subido por ela e parado.",
			full = "Uma torre alta de pedra calcinada se ergue na extremidade leste da Choupana Dente Negro, com a superfície enegrecida como se o próprio fogo tivesse subido por ela e parado. Nada cresce perto dela, e nada mais aqui se ergue tão alto.",
			source = "https://warcraft.wiki.gg/wiki/Pillar_of_Ash",
		},
		["ruins of thaurissan"] = {
			name = "Ruínas de Thaurissan",
			short = "Um dia, estas planícies cobertas de cinzas nas Estepes Ardentes foram verdes, e a cidade daqui levava o nome de seu fundador: a Cidade de Thaurissan, capital do clã Ferro Negro, exilado de Altaforja e conduzido ao sul pelo Feiticeiro-thane Thaurissan durante a Guerra dos Três Martelos.",
			full = "Um dia, estas planícies cobertas de cinzas nas Estepes Ardentes foram verdes, e a cidade daqui levava o nome de seu fundador: a Cidade de Thaurissan, capital do clã Ferro Negro, exilado de Altaforja e conduzido ao sul pelo Feiticeiro-thane Thaurissan durante a Guerra dos Três Martelos.\n\nOs Ferro Negro estavam perdendo aquela guerra. Seu exército acabara de ser destroçado contra as fortalezas dos outros dois clãs quando Thaurissan, desesperado para virar o jogo, reuniu sete de seus anões de maior confiança e clamou aos poderes adormecidos sob a terra por um servo que vencesse a guerra por eles. O que respondeu não foi um servo, mas Ragnaros, o Senhor Elemental do Fogo, e sua chegada partiu as montanhas com um vulcão que reduziu o vale a cinzas. A cidade foi aniquilada, e os Ferro Negro sobreviventes foram escravizados pelo Senhor do Fogo. Abandonando as ruínas, construíram um novo lar sob a Montanha Rocha Negra, e das cinzas de Thaurissan surgiram o Pico da Rocha Negra e uma nova nação Ferro Negro.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Thaurissan",
		},
		["slither rock"] = {
			name = "Rocha Coleante",
			short = "A Rocha Coleante é uma pequena caverna escondida além do Vale Asa do Terror, no extremo nordeste das Estepes Ardentes.",
			full = "A Rocha Coleante é uma pequena caverna escondida além do Vale Asa do Terror, no extremo nordeste das Estepes Ardentes. Ela abriga o dracônida negro Cyrus Therepentous, que ajuda outros contra um inimigo comum, embora nunca sem comentários grosseiros e desdenhosos.",
			source = "https://warcraft.wiki.gg/wiki/Slither_Rock",
		},
		["terror wing path"] = {
			name = "Vale Asa do Terror",
			short = "O Vale Asa do Terror é um vale no leste das Estepes Ardentes, entregue por completo à revoada negra. Dragonetes e dracônicos se aninham entre suas rochas e cinzas.",
			full = "O Vale Asa do Terror é um vale no leste das Estepes Ardentes, entregue por completo à revoada negra. Dragonetes e dracônicos se aninham entre suas rochas e cinzas.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Wing_Path",
		},
	},
	-- Floresta de Elwynn: 23 subzones
	[1429] = {
		["brackwell pumpkin patch"] = {
			name = "Plantação de Abóboras dos Braga",
			short = "No sudeste da Floresta de Elwynn fica uma fazenda que um dia pertenceu à família Braga. O que foi feito deles, ninguém sabe dizer.",
			full = "No sudeste da Floresta de Elwynn fica uma fazenda que um dia pertenceu à família Braga. O que foi feito deles, ninguém sabe dizer. A Irmandade Defias tomou o lugar para si, e os Braga simplesmente desapareceram de seus campos e cercas.\n\nDeles, resta apenas uma lembrança: uma porca premiada chamada Princesa, que ficou enorme com os legumes que roubava ao se esgueirar noite após noite até a vizinha Fazenda Campedra, muito antes de os bandidos chegarem.",
			source = "https://warcraft.wiki.gg/wiki/Brackwell_Pumpkin_Patch",
		},
		["crystal lake"] = {
			name = "Lago de Cristal",
			short = "O Lago de Cristal fica a leste de Vila d'Ouro, com as águas repletas de murlocs que tornam a margem um lugar ruim para os desavisados. Uma propriedade humana vigia a água a partir da margem sul.",
			full = "O Lago de Cristal fica a leste de Vila d'Ouro, com as águas repletas de murlocs que tornam a margem um lugar ruim para os desavisados. Uma propriedade humana vigia a água a partir da margem sul.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Lake",
		},
		["eastvale logging camp"] = {
			name = "Madeireira Vale do Leste",
			short = "Os acampamentos da serraria do Vale do Leste se espalham pelo leste de Elwynn, com seus alojamentos enfileirados entre os fossos de serrar, e o trabalho nunca para de verdade.",
			full = "Os acampamentos da serraria do Vale do Leste se espalham pelo leste de Elwynn, com seus alojamentos enfileirados entre os fossos de serrar, e o trabalho nunca para de verdade. Os pedidos de madeira chegam mais depressa do que os prazos permitem, e os lenhadores trabalham sob a pressão constante de compradores à espera da madeira de Ventobravo.\n\nO Delegado Fadigas, que um dia liderou a Guarda de Ventobravo, aposentou-se desse comando há alguns anos e escolheu passar o resto de seus dias numa casa dentro do acampamento, e não na cidade que um dia defendeu. Ceya Northbrooke também foi criada aqui.\n\nA floresta aperta de todos os lados, e sua selvageria não é pouca coisa. Lobos e ursos têm acossado os lenhadores, dispersando as turmas de trabalho e ameaçando enterrar de vez os prazos do acampamento. O problema ficou tão grave que a Guarda de Ventobravo foi obrigada a pedir ajuda de fora para abater as feras.",
			source = "https://warcraft.wiki.gg/wiki/Eastvale_Logging_Camp",
		},
		["echo ridge mine"] = {
			name = "Mina da Serra do Eco",
			short = "Os túneis da Mina da Serra do Eco ficam no noroeste do Vale de Vila Norte.",
			full = "Os túneis da Mina da Serra do Eco ficam no noroeste do Vale de Vila Norte. Kobolds infestaram os poços e os tomaram para si, para grande frustração dos humanos que vivem nas proximidades, e o Major Belmonte não pôde fazer mais do que mandar homens reduzir seus números vez após vez.",
			source = "https://warcraft.wiki.gg/wiki/Echo_Ridge_Mine",
		},
		["fargodeep mine"] = {
			name = "Mina Vailafundo",
			short = "A Mina Vailafundo já foi explorada em busca do ouro de Ventobravo, com seus poços afundados nas profundezas da Floresta de Elwynn. Hoje está abandonada, com os túneis tomados por um clã de kobolds.",
			full = "A Mina Vailafundo já foi explorada em busca do ouro de Ventobravo, com seus poços afundados nas profundezas da Floresta de Elwynn. Hoje está abandonada, com os túneis tomados por um clã de kobolds. As Minas Inferiores, os níveis mais profundos sob as galerias principais, avançam ainda mais pela escuridão.\n\nO Delegado Durão, que zela pela segurança de Elwynn, mandou reforçar as patrulhas ao redor assim que a presença dos kobolds lá dentro foi confirmada. Entre os kobolds se esgueira Dentadouro, que guarda um colar roubado da Titia Berenice Campedra, uma lembrança que ela não perdeu a esperança de ver de novo.",
			source = "https://warcraft.wiki.gg/wiki/Fargodeep_Mine",
		},
		["forests edge"] = {
			name = "Boca da Mata",
			short = "A Boca da Mata fica a sudoeste de Ventobravo, uma faixa de bosque entre o Pomar do Lago Espelhado, o rio Nazferiti e um riacho menor que segue rumo ao Cerro Oeste.",
			full = "A Boca da Mata fica a sudoeste de Ventobravo, uma faixa de bosque entre o Pomar do Lago Espelhado, o rio Nazferiti e um riacho menor que segue rumo ao Cerro Oeste. Javalis fuçam sua vegetação rasteira, e veios de cobre correm ao longo das margens. A floresta pertence a um bando de gnolls, e entre eles há um que não é um mero animal de matilha. Hogger percorre a mata entre os gnolls menores, e não é um vira-lata qualquer entre eles.",
			source = "https://warcraft.wiki.gg/wiki/Forest's_Edge",
		},
		["goldshire"] = {
			name = "Vila d'Ouro",
			short = "Vila d'Ouro fica no coração da Floresta de Elwynn, com seus campos à vista de Vila Norte e suas estradas se estendendo rumo a Ventobravo, ao Cerro Oeste e a Cristarrubra.",
			full = "Vila d'Ouro fica no coração da Floresta de Elwynn, com seus campos à vista de Vila Norte e suas estradas se estendendo rumo a Ventobravo, ao Cerro Oeste e a Cristarrubra. Ela cresceu nos anos seguintes à fundação de Ventobravo, quando o povo do reino se espalhou da capital pelos campos ao redor.\n\nA pior hora da cidade veio durante a Primeira Guerra, quando o Chefe Guerreiro Mão Negra voltou a Horda contra a linha vital que ligava a Bastilha de Ventobravo a seu povo. Vila d'Ouro e Arroio da Lua eram as duas últimas cidades entre os orcs e a capital e, quando caíram, o caminho para a Bastilha ficou aberto. Vila d'Ouro só se reergueu depois da Segunda Guerra, quando a Aliança de Lordaeron a reconstruiu, com o próprio Comandante Supremo Turalyon cuidando do retorno dos cidadãos dispersos de Ventobravo.\n\nO que resta agora é mais tranquilo: a Estalagem Orgulho do Leão fica no centro da cidade, com sua lareira e sua cerveja atraindo viajantes de todas as estradas que se encontram aqui. O Delegado Durão, da Guarda de Ventobravo, ainda vigia a cidade, atento ao que um dia custou perdê-la.",
			source = "https://warcraft.wiki.gg/wiki/Goldshire",
		},
		["heroes vigil"] = {
			name = "Vigia dos Heróis",
			short = "Um círculo de pedras erguidas contorna a pequena ilha do Lago do Monumento, com a Pedra da Lembrança no centro.",
			full = "Um círculo de pedras erguidas contorna a pequena ilha do Lago do Monumento, com a Pedra da Lembrança no centro. Ela homenageia os mortos da Primeira Guerra, quando os orcs saquearam Vila d'Ouro e as terras ao redor e as entregaram ao fogo.\n\nMagos renegados ocupam a ilha agora. Entre as pedras jaz o corpo de Henze Faulk, deixado onde caiu.",
			source = "https://warcraft.wiki.gg/wiki/Heroes'_Vigil",
		},
		["jasperlode mine"] = {
			name = "Mina de Jaspe",
			short = "A Mina de Jaspe um dia abasteceu as forjas de Ventobravo, um dos lugares da Floresta de Elwynn que forneciam o minério bruto de que a cidade precisava para suas guerras.",
			full = "A Mina de Jaspe um dia abasteceu as forjas de Ventobravo, um dos lugares da Floresta de Elwynn que forneciam o minério bruto de que a cidade precisava para suas guerras. Esse trabalho acabou. Os kobolds tomaram os túneis, e o exército de Ventobravo, sobrecarregado por ameaças mais graves, não tem homens de sobra para expulsá-los.\n\nOs kobolds não são o único perigo lá embaixo. Nos recessos mais profundos da mina, uma colônia de aranhas de mina se instalou e, para elas, os kobolds não são invasores a temer, mas presas a caçar. Sua rainha, a Mãe Presa, remói na escuridão e não tolera nenhuma intrusão em seu ninho.",
			source = "https://warcraft.wiki.gg/wiki/Jasperlode_Mine",
		},
		["jerods landing"] = {
			name = "Ancoradouro de Jerod",
			short = "O Ancoradouro de Jerod é um cais para barcos na margem do rio Nazferiti do lado da Floresta de Elwynn.",
			full = "O Ancoradouro de Jerod é um cais para barcos na margem do rio Nazferiti do lado da Floresta de Elwynn. A Irmandade Defias o ocupa, e o Mestre de Doca e seus homens o usam para contrabandear mercadorias roubadas das Montanhas Cristarrubra até a Torre de Klaven, no Cerro Oeste.",
			source = "https://warcraft.wiki.gg/wiki/Jerod's_Landing",
		},
		["maclure vineyards"] = {
			name = "Vinhedos dos Madruga",
			short = "Os Vinhedos dos Madruga ficam no sul da Floresta de Elwynn, cuidados pela família Madruga ao longo de extensas fileiras de videiras e terra.",
			full = "Os Vinhedos dos Madruga ficam no sul da Floresta de Elwynn, cuidados pela família Madruga ao longo de extensas fileiras de videiras e terra. Os Madruga mantêm uma rivalidade amarga com a família vizinha, os Campedra, e trocam antipatia com a mesma liberdade com que não trocam mais nada. Ainda assim, um filho dos Madruga e uma filha dos Campedra se apaixonaram, desafiando tudo o que suas famílias defendem, e há quem espere que esse amor consiga consertar o que gerações de rancor não conseguiram.",
			source = "https://warcraft.wiki.gg/wiki/Maclure_Vineyards",
		},
		["mirror lake"] = {
			name = "Lago Espelhado",
			short = "O Lago Espelhado repousa pequeno e tranquilo no oeste da Floresta de Elwynn, com sua cachoeira caindo reluzente ao lado de um pomar próximo, o tipo de lugar que parece feito para nadar ou pescar.",
			full = "O Lago Espelhado repousa pequeno e tranquilo no oeste da Floresta de Elwynn, com sua cachoeira caindo reluzente ao lado de um pomar próximo, o tipo de lugar que parece feito para nadar ou pescar. Já não é tão simples. Bandidos Defias se instalaram na mata ao redor, e o que deveria ser um lugar de descanso se tornou um lugar a ser atravessado com cuidado.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake",
		},
		["mirror lake orchard"] = {
			name = "Pomar do Lago Espelhado",
			short = "O Pomar do Lago Espelhado fica na margem sul do Lago Espelhado, com suas fileiras de árvores e um chalé solitário entre os campos do oeste da Floresta de Elwynn.",
			full = "O Pomar do Lago Espelhado fica na margem sul do Lago Espelhado, com suas fileiras de árvores e um chalé solitário entre os campos do oeste da Floresta de Elwynn. Bandidos Defias chegaram a ocupar o pomar e o chalé ao lado, usando o lugar como se fosse deles, e se os verdadeiros donos do pomar foram expulsos por eles, ninguém sabe dizer com certeza.",
			source = "https://warcraft.wiki.gg/wiki/Mirror_Lake_Orchard",
		},
		["northshire abbey"] = {
			name = "Abadia de Vila Norte",
			short = "A Abadia de Vila Norte repousa no vale que leva seu nome, no sopé da Floresta de Elwynn, com seu salão principal, seu salão de armas e sua ala da biblioteca erguidos onde os clérigos da Igreja da Luz Sagrada se estabeleceram pela primeira vez depois de se aventurarem ao sul, vindos de Lordaeron.",
			full = "A Abadia de Vila Norte repousa no vale que leva seu nome, no sopé da Floresta de Elwynn, com seu salão principal, seu salão de armas e sua ala da biblioteca erguidos onde os clérigos da Igreja da Luz Sagrada se estabeleceram pela primeira vez depois de se aventurarem ao sul, vindos de Lordaeron. Daqui a Sagrada Ordem dos Clérigos de Vila Norte deu a Ventobravo seu conforto e sua sabedoria, e foi entre estas paredes que Medivh, o Guardião de Tirisfal, foi tratado durante os longos anos de seu coma.\n\nA abadia não saiu ilesa da Primeira Guerra. Seu Abade cedeu os Clérigos de Vila Norte para a defesa de Ventobravo e, pouco depois de a meio-orc Garona ser trazida para cá como prisioneira, os orcs invadiram Vila Norte e a incendiaram até as ruínas. Os refugiados fugiram rumo a Lordaeron, mas não sem antes resgatar dos destroços tomos sagrados, textos que mais tarde ensinariam aos magos de Dalaran a arte da invisibilidade.\n\nO terreno arruinado não ficou vazio. O clã Martelo do Crepúsculo, de Cho'gall, fez do local seu quartel-general durante a Segunda Guerra, até que a Aliança retomou a Floresta de Elwynn e o Arcebispo Alonsus Faol reconstruiu a abadia pedra por pedra, fundando em seus salões a Irmandade de Vila Norte.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Abbey",
		},
		["northshire valley"] = {
			name = "Vale de Vila Norte",
			short = "O Vale de Vila Norte é fechado por todos os lados, menos um, com montanhas intransponíveis e sua única passagem ao sul selada por grossas muralhas de pedra e um portão vigiado.",
			full = "O Vale de Vila Norte é fechado por todos os lados, menos um, com montanhas intransponíveis e sua única passagem ao sul selada por grossas muralhas de pedra e um portão vigiado. Um rio corta sua quietude, descendo serpenteante em direção ao Lago de Cristal, passando pela abadia e pelas fileiras de vinhedos que dão ao lugar seu ar de paz.\n\nEssa paz nem sempre foi tão certa. Durante a Segunda Guerra, a Abadia de Vila Norte serviu de quartel-general ao clã Martelo do Crepúsculo, de Cho'gall, jurado à causa de Gul'dan, e suas paredes abrigaram conselhos de guerra orcs em vez de noviços e fazendeiros.\n\nAgora o Major Belmonte comanda a guarnição da abadia e responde pela segurança de toda Vila Norte, embora o vale não esteja inteiramente pacificado nem mesmo sob sua vigilância. Lobos avançam da Floresta do Crepúsculo em números que ninguém consegue explicar, e kobolds cavam túneis na Mina da Serra do Eco.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Valley",
		},
		["northshire vineyards"] = {
			name = "Vinhedos de Vila Norte",
			short = "Os vinhedos se estendem a leste da abadia, cultivados para a colheita até que a Irmandade Defias tomou a terra.",
			full = "Os vinhedos se estendem a leste da abadia, cultivados para a colheita até que a Irmandade Defias tomou a terra. Garrick Padfoot liderava os agentes que a ocupavam, usando as fileiras como ponto de apoio para os lacaios da Irmandade, que levaram consigo os bens roubados de Madel Quintana.",
			source = "https://warcraft.wiki.gg/wiki/Northshire_Vineyards",
		},
		["ridgepoint tower"] = {
			name = "Torre Serrana",
			short = "A Torre Serrana vigia a fronteira da Floresta de Elwynn, uma das torres de observação da Guarda de Ventobravo.",
			full = "A Torre Serrana vigia a fronteira da Floresta de Elwynn, uma das torres de observação da Guarda de Ventobravo. Suas sentinelas voltam os olhos para Cristarrubra, onde gnolls e orcs se reúnem, para a Floresta do Crepúsculo, onde os mortos não ficam enterrados, e para os acampamentos Defias próximos. A guarnição se mantém bem defendida contra os três.",
			source = "https://warcraft.wiki.gg/wiki/Ridgepoint_Tower",
		},
		["stone cairn lake"] = {
			name = "Lago do Monumento",
			short = "O Lago do Monumento leva o nome da Vigia dos Heróis, o monumento de pedras erguido na ilha em seu centro para lembrar os mortos da Primeira Guerra contra os orcs, quando tantos caíram que nenhum túmulo sozinho poderia guardar sua memória.",
			full = "O Lago do Monumento leva o nome da Vigia dos Heróis, o monumento de pedras erguido na ilha em seu centro para lembrar os mortos da Primeira Guerra contra os orcs, quando tantos caíram que nenhum túmulo sozinho poderia guardar sua memória. Já foi um lugar de peregrinação silenciosa.\n\nEssa paz acabou. Magos renegados tomaram a ilha, e o monumento destinado ao luto agora fica atrás deles. Ao longo da margem sul, uma tribo de murlocs ergueu suas próprias moradias rústicas, indiferente ao monumento do outro lado da água.",
			source = "https://warcraft.wiki.gg/wiki/Stone_Cairn_Lake",
		},
		["stonefield farm"] = {
			name = "Fazenda dos Campedra",
			short = "A Fazenda Campedra fica no sul da Floresta de Elwynn, trabalhada pela família Campedra, que mantém uma rivalidade amarga com os vizinhos Madruga.",
			full = "A Fazenda Campedra fica no sul da Floresta de Elwynn, trabalhada pela família Campedra, que mantém uma rivalidade amarga com os vizinhos Madruga. Ainda assim, um filho de cada casa se apaixonou, desafiando o velho rancor entre suas famílias. Há quem espere que esse romance consiga o que anos de brigas nunca conseguiram e conserte o que a rixa quebrou.",
			source = "https://warcraft.wiki.gg/wiki/Stonefield_Farm",
		},
		["thunder falls"] = {
			name = "Cachoeira do Trovão",
			short = "O caminho que sobe da cachoeira do Lago Espelhado escala íngreme e estreito pelas montanhas antes de se abrir para a Cachoeira do Trovão, uma ravina diferente das outras da Floresta de Elwynn por ter quedas d'água nas duas extremidades.",
			full = "O caminho que sobe da cachoeira do Lago Espelhado escala íngreme e estreito pelas montanhas antes de se abrir para a Cachoeira do Trovão, uma ravina diferente das outras da Floresta de Elwynn por ter quedas d'água nas duas extremidades. Uma terceira cachoeira despenca dos penhascos do norte, alimentando a ravina lá de cima. Abaixo da elevação fica um pequeno chalé rural, com a bigorna e o fogo mantidos acesos, um pequeno píer e um barco repousando no rio ao lado da casa. Bandidos rondam o chalé. O rio segue adiante por uma segunda cachoeira perto da fronteira com o Cerro Oeste. Dizem que as percas-violeta que nadam nestas águas não são encontradas com tanta facilidade em nenhum outro lugar.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Falls",
		},
		["tower of azora"] = {
			name = "Torre de Azora",
			short = "A Torre de Azora se ergue entre os campos do centro da Floresta de Elwynn, lar de um grupo de criados gnomos que respondem ao Arquimago Teócrito.",
			full = "A Torre de Azora se ergue entre os campos do centro da Floresta de Elwynn, lar de um grupo de criados gnomos que respondem ao Arquimago Teócrito.\n\nLá longe, nas Montanhas Cristarrubra, fica sua rival, a Torre de Ilgalar, governada pelo feiticeiro Morganth. As duas torres nunca entraram em guerra aberta, mas se vigiam constantemente por meios mágicos, cada uma esperando flagrar a outra em algum passo em falso.\n\nA própria magia da torre transborda para os campos ao redor, e tudo o que se demora perto demais corre o risco de ser tocado por ela e transformado em algo mais estranho do que era. Os criados cuidam da torre contra esse pequeno e constante incômodo, sempre com um olho voltado para Cristarrubra.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Azora",
		},
		["westbrook garrison"] = {
			name = "Guarnição da Ribeira d'Oeste",
			short = "A Guarnição da Ribeira d'Oeste fica no limite oeste da Floresta de Elwynn, onde as árvores dão lugar às terras mais pobres do Cerro Oeste, e sempre foi um posto solitário para a Guarda de Ventobravo.",
			full = "A Guarnição da Ribeira d'Oeste fica no limite oeste da Floresta de Elwynn, onde as árvores dão lugar às terras mais pobres do Cerro Oeste, e sempre foi um posto solitário para a Guarda de Ventobravo.\n\nSeus anos mais difíceis vieram enquanto a corrupção de Lady Katrana Prestor pesava sobre o reino e a maior parte do Exército de Ventobravo estava empenhada em outros lugares. Com poucos soldados de sobra, gnolls e ladrões vindos do Cerro Oeste pressionavam a mata com mais força a cada estação, e a guarnição mal conseguia manter as estradas seguras.\n\nEntre os gnolls, o chefe Riverpaw Hogger se tornou um nome temido. Ele sobrepujou todas as tentativas de capturá-lo, e cartazes de procurado com seu nome ainda estão pendurados no portão da guarnição, sem que ninguém tenha cumprido a tarefa.",
			source = "https://warcraft.wiki.gg/wiki/Westbrook_Garrison",
		},
	},
	-- Trilha do Vento Morto: 9 subzones
	[1430] = {
		["aridens camp"] = {
			name = "Acampamento de Ariden",
			short = "O acampamento está abandonado ao norte da estrada que atravessa a Trilha do Vento Morto, um punhado de fogueiras frias e colchonetes vazios sob as árvores eternamente escuras.",
			full = "O acampamento está abandonado ao norte da estrada que atravessa a Trilha do Vento Morto, um punhado de fogueiras frias e colchonetes vazios sob as árvores eternamente escuras. Ariden um dia liderou os Cavaleiros Sombrios a partir deste terreno, montando acampamento aqui antes de ser amaldiçoado, e daqui tentou vender artefatos falsos que alegava terem pertencido a Medivh. Nada resta agora além do próprio acampamento.",
			source = "https://warcraft.wiki.gg/wiki/Ariden's_Camp",
		},
		["deadmans crossing"] = {
			name = "Encruzilhada do Defunto",
			short = "Uma árvore de enforcados fica na encruzilhada, com um par de cadáveres ainda balançando em seus galhos. Ao lado dela, uma placa traz dois avisos: \"Volte!\" e \"Deixai toda esperança, vós que entrais\".",
			full = "Uma árvore de enforcados fica na encruzilhada, com um par de cadáveres ainda balançando em seus galhos. Ao lado dela, uma placa traz dois avisos: \"Volte!\" e \"Deixai toda esperança, vós que entrais\".\n\nAqui, a estrada a oeste leva à Floresta do Crepúsculo, a estrada a leste ao Pântano das Mágoas, e a estrada ao sul entra na Trilha do Vento Morto, onde fica Karazhan. A forca e o aviso foram erguidos para quem se sentisse tentado a deixar a encruzilhada e entrar no passo mais além.",
			source = "https://warcraft.wiki.gg/wiki/Deadman's_Crossing",
		},
		["deadwind ravine"] = {
			name = "Garganta do Vento Morto",
			short = "A ravina abre uma fenda escarpada pelas montanhas, com sua estrada oeste correndo pelo nível superior rumo a Karazhan, cuja silhueta espera, ameaçadora, lá no fim.",
			full = "A ravina abre uma fenda escarpada pelas montanhas, com sua estrada oeste correndo pelo nível superior rumo a Karazhan, cuja silhueta espera, ameaçadora, lá no fim. No fim da ravina fica a ponte sul, a última travessia antes da própria torre.",
			source = "https://warcraft.wiki.gg/wiki/Deadwind_Ravine",
		},
		["groshgok compound"] = {
			name = "Complexo Grosh'gok",
			short = "Os ogros do Vento Morto reivindicam o Complexo Grosh'gok como seu, um monte de terra e pedra erguido na Garra.",
			full = "Os ogros do Vento Morto reivindicam o Complexo Grosh'gok como seu, um monte de terra e pedra erguido na Garra. Das cavernas que perfuram aquele trecho de terra, esta é a mais ao sul, e nenhuma das outras se compara a ela em tamanho.",
			source = "https://warcraft.wiki.gg/wiki/Grosh'gok_Compound",
		},
		["karazhan"] = {
			name = "Karazhan",
			short = "Karazhan está abandonada no sul da Trilha do Vento Morto, construída sobre um nexo de linhas de energia. A torre é mais conhecida por seu último ocupante, Medivh, o último Guardião de Tirisfal.",
			full = "Karazhan está abandonada no sul da Trilha do Vento Morto, construída sobre um nexo de linhas de energia. A torre é mais conhecida por seu último ocupante, Medivh, o último Guardião de Tirisfal. Depois que Medivh foi morto por Khadgar, Anduin Lothar e Garona, a torre se isolou do mundo. Mas, recentemente, Karazhan voltou a se agitar: uma presença maligna a tomou para si, seus salões fervilham de espíritos e demônios, e a Sombra de Medivh ainda se demora ali, com um poder tão grande que sua magia ainda ecoa pela torre.\n\nÉ impossível pôr os olhos em Karazhan sem refletir sobre a saga sombria de seu senhor. Como convinha a seu título, o Último Guardião de Tirisfal havia reunido uma vasta coleção de escritos e artefatos, que superava até a do Kirin Tor. A torre é vasta e perigosa, com salões repletos de fantasmas.",
			source = "https://warcraft.wiki.gg/wiki/Karazhan",
		},
		["masters cellar"] = {
			name = "Porão do Senhorio",
			short = "Sob a aldeia arruinada ao sul de Karazhan, onde os criados da torre um dia tinham suas casas, o chão se abre em porões que já não pertencem aos vivos.",
			full = "Sob a aldeia arruinada ao sul de Karazhan, onde os criados da torre um dia tinham suas casas, o chão se abre em porões que já não pertencem aos vivos. Duas entradas levam para baixo. Uma se abre para uma vasta adega, com suas prateleiras e barris há muito abandonados aos mortos. A outra desce para um segundo porão cujo piso cedeu por completo, desabando num sistema de cavernas que corre fundo sob a terra.\n\nOs dois estão repletos de inquietos: zeladores mortos-vivos que ainda parecem cuidar de uma casa sem senhor, almas condenadas, sombras que não se aquietam, espectros cujos lamentos sobem pelas pedras quebradas. Qualquer que tenha sido o serviço que os ligou a Karazhan em vida, ele azedou em algo que não os deixa partir na morte.\n\nSomente a adega guarda algo que se destaque entre os mortos. O sistema de cavernas inferior, silencioso e afogado em escuridão, não guarda nada além de mais mortos inquietos, nada com nome, nada que alguém tenha julgado digno de ser lembrado.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Cellar",
		},
		["morgans plot"] = {
			name = "Terreno de Morgan",
			short = "Uma pequena igreja decrépita fica atrás de Karazhan, com seu cemitério e sua cripta afundados na penumbra da Trilha do Vento Morto.",
			full = "Uma pequena igreja decrépita fica atrás de Karazhan, com seu cemitério e sua cripta afundados na penumbra da Trilha do Vento Morto. A capela há muito abriga coisas que não descansam em paz, e algo mais ainda patrulha a colina logo abaixo.\n\nQue um lugar destinado aos mortos falhe tantas vezes em mantê-los diz algo sobre o que há atrás dele.",
			source = "https://warcraft.wiki.gg/wiki/Morgan's_Plot",
		},
		["sleeping gorge"] = {
			name = "Garganta Adormecida",
			short = "A Garganta Adormecida corta o leste da Trilha do Vento Morto, um pequeno abismo que os viajantes do acesso sul a Karazhan precisam atravessar antes que o caminho vire para o leste, rumo à Garra.",
			full = "A Garganta Adormecida corta o leste da Trilha do Vento Morto, um pequeno abismo que os viajantes do acesso sul a Karazhan precisam atravessar antes que o caminho vire para o leste, rumo à Garra.",
			source = "https://warcraft.wiki.gg/wiki/Sleeping_Gorge",
		},
		["vice"] = {
			name = "A Garra",
			short = "A Garra se estende pelo trecho sul da estrada para Karazhan, onde os ogros do Vento Morto ergueram seus montes e acampamentos entre os penhascos.",
			full = "A Garra se estende pelo trecho sul da estrada para Karazhan, onde os ogros do Vento Morto ergueram seus montes e acampamentos entre os penhascos. É um trecho desolado de terra, lar de pouco mais que espíritos inquietos e dos abutres que circulam sobre eles. Por que os ogros escolheram se enraizar aqui, num lugar tão vazio e malfadado, ninguém que tenha olhado para ele sabe dizer.",
			source = "https://warcraft.wiki.gg/wiki/Vice",
		},
	},
	-- Floresta do Crepúsculo: 17 subzones
	[1431] = {
		["addles stead"] = {
			name = "Quinta dos Aguiar",
			short = "A Quinta dos Aguiar está abandonada entre os campos do sudoeste da Floresta do Crepúsculo, uma das muitas fazendas deixadas para apodrecer quando a escuridão se espalhou pela terra.",
			full = "A Quinta dos Aguiar está abandonada entre os campos do sudoeste da Floresta do Crepúsculo, uma das muitas fazendas deixadas para apodrecer quando a escuridão se espalhou pela terra. O celeiro está vazio, a casa em silêncio, e apenas Espíritos Esquecidos ainda se demoram ali, que dizem ser as sombras de membros mortos da Irmandade Defias que um dia tomaram o lugar.\n\nOs Defias tomaram a Quinta dos Aguiar por completo, esgueirando-se pelo campo tomado pelo mato, escondendo-se no celeiro, rondando os cômodos da casa.",
			source = "https://warcraft.wiki.gg/wiki/Addle's_Stead",
		},
		["beggars haunt"] = {
			name = "Refúgio dos Mendigos",
			short = "A torre chamada Refúgio dos Mendigos está abandonada acima da estrada que entra na Trilha do Vento Morto, a nordeste do Casarão dos Brumanto.",
			full = "A torre chamada Refúgio dos Mendigos está abandonada acima da estrada que entra na Trilha do Vento Morto, a nordeste do Casarão dos Brumanto. Erguida como posto de observação da Guarda de Ventobravo, hoje serve aos Renegados, cujos Sicário Zaqueu e Boticário Faustino realizam experimentos entre suas paredes.\n\nUma trilha desce até um pequeno lago alimentado por uma cachoeira, onde um túmulo sem nome repousa sob duas grandes estátuas esculpidas como as do Portal Negro. Perto da torre fica outro pequeno cemitério, que guarda o túmulo de um Soldado Desconhecido.",
			source = "https://warcraft.wiki.gg/wiki/Beggar's_Haunt",
		},
		["brightwood grove"] = {
			name = "Bosque Brilhante",
			short = "O Bosque Brilhante fica logo a oeste de Vila Sombria, com suas poucas construções há muito em ruínas.",
			full = "O Bosque Brilhante fica logo a oeste de Vila Sombria, com suas poucas construções há muito em ruínas. O que resta do lugar pertence agora aos worgens Nightbane, que rondam os campos escuros em matilhas, erguendo acampamentos rústicos entre os destroços e caindo sobre qualquer um que se aproxime demais.",
			source = "https://warcraft.wiki.gg/wiki/Brightwood_Grove",
		},
		["darkened bank"] = {
			name = "Margem Escurecida",
			short = "A Margem Escurecida se estende pela margem norte da Floresta do Crepúsculo, do limite oeste da região até a ponte que a liga a Cristarrubra, a leste.",
			full = "A Margem Escurecida se estende pela margem norte da Floresta do Crepúsculo, do limite oeste da região até a ponte que a liga a Cristarrubra, a leste. Em sua extremidade oeste fica um pequeno acampamento onde os refugiados Noel Figueira e Lars se abrigaram, empurrados para a beira da água por aquilo que tornou o resto da Floresta do Crepúsculo perigoso demais para ser ocupado.",
			source = "https://warcraft.wiki.gg/wiki/Darkened_Bank",
		},
		["darkshire"] = {
			name = "Vila Sombria",
			short = "Vila Sombria nem sempre teve esse nome. Ela surgiu há muito tempo como Grã-vila, uma pequena cidade florestal que cresceu à medida que o povo de Ventobravo se espalhava pelas terras próximas.",
			full = "Vila Sombria nem sempre teve esse nome. Ela surgiu há muito tempo como Grã-vila, uma pequena cidade florestal que cresceu à medida que o povo de Ventobravo se espalhava pelas terras próximas. Mas a própria terra nunca se recuperou do que aconteceu em Karazhan. Quando o Guardião Medivh foi morto em sua torre ali, a energia vil liberada por sua morte se infiltrou na floresta ao redor, retorcendo-a no lugar espinhoso e sem luz que continua sendo. O Bosque Brilhante se tornou a Floresta do Crepúsculo, e Grã-vila assumiu o nome mais verdadeiro de Vila Sombria.\n\nA milícia da cidade, a Vigília Noturna, existe porque Ventobravo a abandonou. Quando as tramas de Lady Katrana Prestor em Ventobravo esvaziaram as guarnições do reino na floresta, os moradores se armaram em vez de esperar por soldados que nunca viriam. Formados e treinados inteiramente pelo povo da floresta, eles desde então defendem as estradas contra lobos, cadáveres ambulantes e coisas piores, sem nenhum exército a que recorrer além de si mesmos.",
			source = "https://warcraft.wiki.gg/wiki/Darkshire",
		},
		["dawning wood catacombs"] = {
			name = "Catacumbas do Bosque da Aurora",
			short = "Sob o Cemitério de Monte Corvo, a terra se abre nas Catacumbas do Bosque da Aurora, um labirinto de túneis que serpenteiam tão fundo que poucos dos que entram sozinhos voltam a sair.",
			full = "Sob o Cemitério de Monte Corvo, a terra se abre nas Catacumbas do Bosque da Aurora, um labirinto de túneis que serpenteiam tão fundo que poucos dos que entram sozinhos voltam a sair. Dois caminhos levam para baixo. A passagem leste se abre para um covil de carniçais, doentes e ferozes. A passagem oeste se abre para um salão de esqueletos, montando sentinela sobre os túmulos dos mortos que um dia foram.",
			source = "https://warcraft.wiki.gg/wiki/Dawning_Wood_Catacombs",
		},
		["forlorn rowe"] = {
			name = "Morro dos Esquecidos",
			short = "Uma colina na borda norte do Cemitério de Monte Corvo, o Morro dos Esquecidos está envolto numa escuridão que se agarra mais perto que a sombra das árvores ao redor.",
			full = "Uma colina na borda norte do Cemitério de Monte Corvo, o Morro dos Esquecidos está envolto numa escuridão que se agarra mais perto que a sombra das árvores ao redor. Aqui fica a casa de Morbent Fel, um necromante que submete os mortos-vivos da floresta à sua vontade por meio de uma maligna magia arcana. Somente uma única arma de grande poder poderia ter a esperança de detê-lo.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Rowe",
		},
		["hushed bank"] = {
			name = "Margem Silenciada",
			short = "A Margem Silenciada se estende pelo rio a oeste da Floresta do Crepúsculo, desde o ponto onde o Cerro Oeste, a Floresta de Elwynn e a Floresta do Crepúsculo se encontram, rumo ao sul até a Selva do Espinhaço.",
			full = "A Margem Silenciada se estende pelo rio a oeste da Floresta do Crepúsculo, desde o ponto onde o Cerro Oeste, a Floresta de Elwynn e a Floresta do Crepúsculo se encontram, rumo ao sul até a Selva do Espinhaço. Uma ponte coberta atravessa o rio aqui, ligando a Floresta do Crepúsculo ao Cerro Oeste.\n\nNo canto norte da margem, os irmãos Lars e Noel Figueira mantêm um acampamento.\n\nLobos e aranhas percorrem a margem entre as árvores.",
			source = "https://warcraft.wiki.gg/wiki/Hushed_Bank",
		},
		["manor mistmantle"] = {
			name = "Casarão dos Brumanto",
			short = "O Casarão dos Brumanto fica no nordeste da Floresta do Crepúsculo, com o terreno apodrecido e os jardins em ruínas.",
			full = "O Casarão dos Brumanto fica no nordeste da Floresta do Crepúsculo, com o terreno apodrecido e os jardins em ruínas. Um dia foi o lar de Stalvan Brumanto, um professor e preceptor que se tornou agente dos mortos-vivos, deixando carniçais cambaleando pela propriedade em seu lugar. Em meio à corrupção, uma coisa ainda cresce: uma única flor chamada Lágrima de Tilloa, o único sinal de vida que resta num jardim que de resto foi entregue à podridão.",
			source = "https://warcraft.wiki.gg/wiki/Manor_Mistmantle",
		},
		["raven hill"] = {
			name = "Monte Corvo",
			short = "As casas de Monte Corvo estão vazias no oeste da Floresta do Crepúsculo, entregues à podridão e à escuridão. Algumas almas resistiram mesmo assim: Medrisco e Bliztik, um goblin que se mantinha escondido num andar de cima.",
			full = "As casas de Monte Corvo estão vazias no oeste da Floresta do Crepúsculo, entregues à podridão e à escuridão. Algumas almas resistiram mesmo assim: Medrisco e Bliztik, um goblin que se mantinha escondido num andar de cima.\n\nA cidade é assombrada pelos Invisíveis, invisíveis não só no nome, que se movem por seus cômodos vazios.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill",
		},
		["raven hill cemetery"] = {
			name = "Cemitério de Monte Corvo",
			short = "O Cemitério de Monte Corvo se estende ao norte da cidade que lhe dá nome e cresceu muito além de seus antigos limites desde que a corrupção da Floresta do Crepúsculo se instalou.",
			full = "O Cemitério de Monte Corvo se estende ao norte da cidade que lhe dá nome e cresceu muito além de seus antigos limites desde que a corrupção da Floresta do Crepúsculo se instalou. Mortos-vivos agora caminham entre as lápides, e aranhas enormes e bandos de ladrões de túmulos trabalham sobre as covas sem ser perturbados, expulsando qualquer um que tropece em seus negócios.\n\nNo canto noroeste do cemitério fica o Morro dos Esquecidos, lar do necromante Morbent Fel, cujo trabalho sombrio agita os mortos do cemitério.\n\nEsse nome, Ladimore, marca a dor mais antiga do cemitério. Morgan Ladimore voltou da Terceira Guerra e encontrou a esposa e os filhos já enterrados aqui. A dor o destroçou; ele assassinou três dos zeladores do cemitério sobre os túmulos deles. Agora o morto-vivo Mor'Ladim patrulha o terreno, e a morte chega rápida e invisível a qualquer um que ele encontre desprevenido entre as lápides.",
			source = "https://warcraft.wiki.gg/wiki/Raven_Hill_Cemetery",
		},
		["rolands doom"] = {
			name = "O Descanso de Rolando",
			short = "O Descanso de Rolando é uma mina no sudeste da Floresta do Crepúsculo, a leste do Horto Pútrido.",
			full = "O Descanso de Rolando é uma mina no sudeste da Floresta do Crepúsculo, a leste do Horto Pútrido. A sacerdotisa elfa noturna Velinde Starsong levou a Foice de Eluna para estas colinas antes de desaparecer, e a relíquia se perdeu na mina. O homem chamado Medrisco a encontrou ali, e essa descoberta atraiu mais worgens sobre a Floresta do Crepúsculo e Vila Sombria.\n\nA mina agora pertence a Gutspill e Nefaru, da matilha Nightbane, cujos worgens se espalham até o Horto Pútrido.",
			source = "https://warcraft.wiki.gg/wiki/Roland's_Doom",
		},
		["rotting orchard"] = {
			name = "O Horto Pútrido",
			short = "O horto fica no sul da Floresta do Crepúsculo, com as árvores enegrecidas pela podridão e as construções em ruínas entre a Fazenda dos Figueira e o Cemitério Jardins da Paz.",
			full = "O horto fica no sul da Floresta do Crepúsculo, com as árvores enegrecidas pela podridão e as construções em ruínas entre a Fazenda dos Figueira e o Cemitério Jardins da Paz.\n\nOs worgens da matilha Nightbane o tomaram para si. Tecelões das Sombras fazem sua magia entre as construções arruinadas, enquanto Espreitadores esperam invisíveis na escuridão entre as árvores.\n\nEstar aqui agora é estar num lugar que deixou de ser uma fazenda e se tornou um território de caça.",
			source = "https://warcraft.wiki.gg/wiki/Rotting_Orchard",
		},
		["tranquil gardens cemetery"] = {
			name = "Cemitério Jardins da Paz",
			short = "O Cemitério Jardins da Paz fica a sudeste de Vila Sombria, e seu nome agora é uma piada amarga.",
			full = "O Cemitério Jardins da Paz fica a sudeste de Vila Sombria, e seu nome agora é uma piada amarga. Os mortos daqui não descansam, embora sejam mais fracos que os mortos-vivos encontrados em outros lugares da Floresta do Crepúsculo, vagando entre as lápides e a igreja arruinada no coração do cemitério. O Carniçal Insano assombra este terreno, às vezes dentro da igreja destroçada, às vezes entre as covas. Logo ao norte fica a casa da Maria Cega.",
			source = "https://warcraft.wiki.gg/wiki/Tranquil_Gardens_Cemetery",
		},
		["twilight grove"] = {
			name = "Bosque do Crepúsculo",
			short = "Uma grande árvore sem nome se ergue no coração do Bosque do Crepúsculo, no fundo da Floresta do Crepúsculo, ao lado de um poço lunar e de um antigo gazebo dos elfos noturnos.",
			full = "Uma grande árvore sem nome se ergue no coração do Bosque do Crepúsculo, no fundo da Floresta do Crepúsculo, ao lado de um poço lunar e de um antigo gazebo dos elfos noturnos. Sob seus galhos fica um dos quatro únicos portais para o Sonho Esmeralda, irmão dos que estão escondidos em Feralas, nas Terras Agrestes e no Vale Gris.\n\nO portal do bosque não ficou sem guarda. Quatro grandes dragões, outrora orgulhosos tenentes de Ysera, a Aspecto dos Sonhos, montavam vigília aqui como os protetores do Sonho escolhidos por ela. Mas o Pesadelo Esmeralda os corrompeu por sua vez, transformando guardiões em destruidores que não queriam nada além da morte, e coube à Aliança e à Horda pegar em armas contra os mesmos dragões que um dia montaram sentinela sobre este lugar.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Grove",
		},
		["vulgol ogre mound"] = {
			name = "Gruta de Vul'Gol",
			short = "O sul da Floresta do Crepúsculo desce para uma pequena bacia onde a estrada se divide rumo à Selva do Espinhaço, e onde havia casas de fazenda antes da chegada dos ogros.",
			full = "O sul da Floresta do Crepúsculo desce para uma pequena bacia onde a estrada se divide rumo à Selva do Espinhaço, e onde havia casas de fazenda antes da chegada dos ogros. Os ogros Splinter Fist a ocupam agora, e o lugar leva o nome de seu líder, Zzarc'Vul, que governa a gruta de dentro dela.\n\nAs casas de fazenda arruinadas são o único sinal de que havia gente vivendo aqui antes que os ogros tomassem a bacia para si. Seja lá o que tenha acontecido com aquelas famílias, os ogros não deixaram nada além de paredes quebradas.\n\nA Vigília Noturna não destaca seus homens para este lugar, julgando a ameaça daqui menos urgente que outras que pressionam a Floresta do Crepúsculo, e por isso coube a forasteiros reduzir o número de ogros quando necessário. Entre o saque dos ogros estava um caixote de ferramentas e ervas roubado do necromante Abercrombie, levado para a gruta depois que o atacaram. E o próprio Zzarc'Vul usa um monóculo que um pesquisador um dia cobiçou para seus próprios estudos, uma pequena vaidade numa criatura brutal.",
			source = "https://warcraft.wiki.gg/wiki/Vul'Gol_Ogre_Mound",
		},
		["yorgen farmstead"] = {
			name = "Fazenda dos Figueira",
			short = "A Fazenda dos Figueira está abandonada no sul da Floresta do Crepúsculo, com os campos apodrecidos. Noel Figueira um dia trabalhou esta terra, mas agora vive num pequeno acampamento na Margem Escurecida.",
			full = "A Fazenda dos Figueira está abandonada no sul da Floresta do Crepúsculo, com os campos apodrecidos. Noel Figueira um dia trabalhou esta terra, mas agora vive num pequeno acampamento na Margem Escurecida. A própria fazenda caiu desde então nas mãos da Irmandade Defias, cujos assassinos se movem invisíveis pelos campos, atacando apenas quando já é tarde demais.",
			source = "https://warcraft.wiki.gg/wiki/Yorgen_Farmstead",
		},
	},
	-- Loch Modan: 16 subzones
	[1432] = {
		["algaz station"] = {
			name = "Estação Algaz",
			short = "A Estação Algaz fica a leste do Desfiladeiro do Portão Norte e leva o nome de Dun Algaz, ao norte.",
			full = "A Estação Algaz fica a leste do Desfiladeiro do Portão Norte e leva o nome de Dun Algaz, ao norte. Aqui os montanhistas anões mantêm sua vigília, entre eles o Montanhista Lançatroz, e o armeiro Gothor Brumn cuida de seu equipamento.",
			source = "https://warcraft.wiki.gg/wiki/Algaz_Station",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "O túnel de Dun Algaz é mais antigo que a disputa que dividiu os anões. Quando a Guerra dos Três Martelos expulsou os Martelo Feroz de Altaforja, foi por esta passagem que eles bateram em retirada.",
			full = "O túnel de Dun Algaz é mais antigo que a disputa que dividiu os anões. Quando a Guerra dos Três Martelos expulsou os Martelo Feroz de Altaforja, foi por esta passagem que eles bateram em retirada.\n\nEle também serviu à retirada da Horda. Rechaçados de Dun Modr, os orcs recuaram para o sul pelo Vale Thandol e se entrincheiraram no posto avançado daqui, e Anduin Lothar, querendo expulsá-los de vez de Khaz Modan, enviou suas forças para derrubar a fortaleza. O ataque fracassou. Os orcs resistiram, e Dun Algaz se tornou o último território que a Horda manteve na região, um ponto de apoio que não se deixava arrancar.\n\nOs montanhistas anões que vigiavam esta passagem ficavam principalmente nas colinas acima dela, mas o clã Presa do Dragão tomou seu posto e os empurrou de volta para o túnel superior, onde ainda resistem. Com a passagem inferior perdida, a estrada entre as terras natais dos anões e o Porto de Menethil ficou muito mais perigosa.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["farstrider lodge"] = {
			name = "Pavilhão dos Andarilhos",
			short = "O Pavilhão dos Andarilhos fica no sudeste de Loch Modan, com uma arquitetura inconfundivelmente de altos elfos, embora apenas um membro dessa raça ainda permaneça em seus salões.",
			full = "O Pavilhão dos Andarilhos fica no sudeste de Loch Modan, com uma arquitetura inconfundivelmente de altos elfos, embora apenas um membro dessa raça ainda permaneça em seus salões. Humanos e anões passaram a morar ali, caçadores entre eles, vivendo entre paredes erguidas por mãos que há muito partiram deste lugar.",
			source = "https://warcraft.wiki.gg/wiki/Farstrider_Lodge",
		},
		["grizzlepaw ridge"] = {
			name = "Serra Garracinza",
			short = "A Serra Garracinza se ergue ao sul de Thelsamar, repleta de ursos que tomaram as alturas para si.",
			full = "A Serra Garracinza se ergue ao sul de Thelsamar, repleta de ursos que tomaram as alturas para si. O principal deles é o Velho Fuligem, um urso de tamanho e temperamento temíveis, que desce de seu covil até o fundo do vale, pronto para atacar qualquer um que tenha o azar de irritá-lo.\n\nGorick Guzzledraught também vive na serra.",
			source = "https://warcraft.wiki.gg/wiki/Grizzlepaw_Ridge",
		},
		["ironbands excavation site"] = {
			name = "Sítio de Escavação de Bandaferro",
			short = "O Sítio de Escavação de Bandaferro, no sudeste de Loch Modan, é uma escavação anã aberta pelo Prospector Bandaferro em busca do que os antigos haviam enterrado.",
			full = "O Sítio de Escavação de Bandaferro, no sudeste de Loch Modan, é uma escavação anã aberta pelo Prospector Bandaferro em busca do que os antigos haviam enterrado. Mas a terra entregou mais que relíquias: troggs, maiores e mais instáveis que os encontrados nas outras escavações anãs, subiram lá de baixo e tomaram o sítio, expulsando os prospectores e mineiros que o haviam aberto.",
			source = "https://warcraft.wiki.gg/wiki/Ironband's_Excavation_Site",
		},
		["loch"] = {
			name = "Loch",
			short = "O Loch ocupa o coração de Loch Modan, a maior massa de água de toda Khaz Modan e a terceira maior do mundo conhecido, atrás apenas do Espelho de Lordaeron e do Lago das Flechas.",
			full = "O Loch ocupa o coração de Loch Modan, a maior massa de água de toda Khaz Modan e a terceira maior do mundo conhecido, atrás apenas do Espelho de Lordaeron e do Lago das Flechas.",
			source = "https://warcraft.wiki.gg/wiki/The_Loch",
		},
		["mogrosh stronghold"] = {
			name = "Fortaleza Mo'grosh",
			short = "As cavernas da Fortaleza Mo'grosh ficam no nordeste de Loch Modan, lar de uma tribo de ogros cujos malhadores sombrios e dobradores de terra não respondem a ninguém além dos seus.",
			full = "As cavernas da Fortaleza Mo'grosh ficam no nordeste de Loch Modan, lar de uma tribo de ogros cujos malhadores sombrios e dobradores de terra não respondem a ninguém além dos seus.",
			source = "https://warcraft.wiki.gg/wiki/Mo'grosh_Stronghold",
		},
		["north gate pass"] = {
			name = "Desfiladeiro do Portão Norte",
			short = "O desfiladeiro corta as altas montanhas, descendo de Dun Morogh em direção a Loch Modan.",
			full = "O desfiladeiro corta as altas montanhas, descendo de Dun Morogh em direção a Loch Modan. É o caminho mais curto entre as duas, e os viajantes com destino às terras além do Loch passam por aqui mais do que por qualquer outro caminho.\n\nO Posto de Guarda do Portão Norte monta guarda aqui, defendendo a passagem.",
			source = "https://warcraft.wiki.gg/wiki/North_Gate_Pass",
		},
		["silver stream mine"] = {
			name = "Mina da Prata",
			short = "A Mina da Prata um dia foi rica em prata, e por gerações os anões de Altaforja tiraram riqueza de seus veios.",
			full = "A Mina da Prata um dia foi rica em prata, e por gerações os anões de Altaforja tiraram riqueza de seus veios. Quando o minério se esgotou, a Liga dos Mineiros transformou os túneis num depósito em vez de abandoná-los.\n\nA mina ainda guarda uma coisa que vale a pena levar: Gemas da Fenda Carregadas, que não se encontram em nenhum outro lugar, valorizadas para a confecção de togas de mago.\n\nMas os anões já não controlam estes túneis. Kobolds Rato de Túnel tomaram a mina, buscando para si os recursos que restam.",
			source = "https://warcraft.wiki.gg/wiki/Silver_Stream_Mine",
		},
		["south gate pass"] = {
			name = "Desfiladeiro do Portão Sul",
			short = "O Desfiladeiro do Portão Sul corta as montanhas, ligando as neves altas de Dun Morogh aos vales mais baixos de Loch Modan. É o caminho mais curto até Thelsamar, gasto pelos viajantes entre as duas terras.",
			full = "O Desfiladeiro do Portão Sul corta as montanhas, ligando as neves altas de Dun Morogh aos vales mais baixos de Loch Modan. É o caminho mais curto até Thelsamar, gasto pelos viajantes entre as duas terras.\n\nAqui fica o Posto de Guarda do Portão Sul, um posto de guarda instalado para vigiar o desfiladeiro.",
			source = "https://warcraft.wiki.gg/wiki/South_Gate_Pass",
		},
		["stonesplinter valley"] = {
			name = "Vale Lascapedra",
			short = "O Vale Lascapedra corta as montanhas do sudoeste de Loch Modan. Antes intocado, agora pertence aos troggs Lascapedra, que tomaram seu fundo e suas encostas.",
			full = "O Vale Lascapedra corta as montanhas do sudoeste de Loch Modan. Antes intocado, agora pertence aos troggs Lascapedra, que tomaram seu fundo e suas encostas. Os anões de Loch Modan os consideram pragas a serem exterminadas. No ponto mais profundo do vale vive Grawmug, o líder em torno de quem os troggs se reúnem.",
			source = "https://warcraft.wiki.gg/wiki/Stonesplinter_Valley",
		},
		["stonewrought dam"] = {
			name = "Dique Lapidado",
			short = "O Dique Lapidado se ergue a leste do desfiladeiro de Dun Algaz, ao longo do limite norte de Loch Modan.",
			full = "O Dique Lapidado se ergue a leste do desfiladeiro de Dun Algaz, ao longo do limite norte de Loch Modan.\n\nSeu construtor foi um anão Ferro Negro. Franclorn Forjífice, arquiteto daquele clã, criou o método de cantaria lapidada com que o dique foi erguido, embora poucos dos que o atravessam saibam que foi uma mão Ferro Negro que o construiu.\n\nO dique represa o Loch, fazendo-o crescer a mais do dobro de seu tamanho anterior, e a inundação que provocou formou os pântanos mais além, terreno que antes ficava quase todo submerso.\n\nO clã Ferro Negro atacou o dique, e Altaforja respondeu reforçando a vigilância. O Engenheiro-chefe Vedaçude VII é hoje o responsável por essa tarefa.",
			source = "https://warcraft.wiki.gg/wiki/Stonewrought_Dam",
		},
		["stoutlager inn"] = {
			name = "Estalagem Pilsen",
			short = "A Estalagem Pilsen fica em Thelsamar, com uma lareira raramente fria. Anões e viajantes se reúnem aqui para beber e trocar notícias do Loch, e poucos lugares da região atraem um público tão constante porta adentro.",
			full = "A Estalagem Pilsen fica em Thelsamar, com uma lareira raramente fria. Anões e viajantes se reúnem aqui para beber e trocar notícias do Loch, e poucos lugares da região atraem um público tão constante porta adentro.",
			source = "https://warcraft.wiki.gg/wiki/Stoutlager_Inn",
		},
		["thelsamar"] = {
			name = "Thelsamar",
			short = "Thelsamar fica na margem oeste de Loch Modan, ao norte da Serra Garracinza e a nordeste do Vale Lascapedra. Uma estrada passa logo a oeste da cidade, subindo pelos desfiladeiros rumo a Dun Morogh e ao Pantanal.",
			full = "Thelsamar fica na margem oeste de Loch Modan, ao norte da Serra Garracinza e a nordeste do Vale Lascapedra. Uma estrada passa logo a oeste da cidade, subindo pelos desfiladeiros rumo a Dun Morogh e ao Pantanal. Grifos se aninham em seu poleiro, e sua estalagem abriga os viajantes que atravessam as terras altas.",
			source = "https://warcraft.wiki.gg/wiki/Thelsamar",
		},
		["valley of kings"] = {
			name = "Vale dos Reis",
			short = "O Vale dos Reis fica no extremo sudoeste de Loch Modan, onde a terra verde se estreita em direção ao portão que desce para a enegrecida Garganta Abrasadora.",
			full = "O Vale dos Reis fica no extremo sudoeste de Loch Modan, onde a terra verde se estreita em direção ao portão que desce para a enegrecida Garganta Abrasadora. Esse portão fica trancado e vigiado, sob os olhos do Montanhista Pedrabrita, que só dá passagem aos que provam ser dignos dela.\n\nO que chama a atenção aqui são as duas grandes estátuas que se erguem sobre o desfiladeiro: Madoran Barbabronze e Khardros Martelo Feroz, esculpidos em pedra para vigiar a estrada ao sul. Quando os dois reis morreram, foram seus filhos que ergueram juntos as estátuas, unindo Barbabronze e Martelo Feroz em pedra como seus pais haviam estado unidos em vida. As terras do sul mais além haviam sido transformadas em fogo e cinzas por Ragnaros, e as estátuas encaram essa ruína de frente: um aviso a qualquer um que se atrevesse a agir contra os reinos anões e uma lembrança do preço que os Ferro Negro pagaram pelo que haviam feito.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Kings",
		},
	},
	-- Montanhas Cristarrubra: 16 subzones
	[1433] = {
		["althers mill"] = {
			name = "Serraria Alther",
			short = "A serraria a nordeste de Vila Plácida está vazia, com sua roda há muito parada. Não passava de uma parada na estrada para a Bastilha Mirante de Pedra, e suas ruínas abrigam aranhas, urubus e um ou outro orc desgarrado.",
			full = "A serraria a nordeste de Vila Plácida está vazia, com sua roda há muito parada. Não passava de uma parada na estrada para a Bastilha Mirante de Pedra, e suas ruínas abrigam aranhas, urubus e um ou outro orc desgarrado.",
			source = "https://warcraft.wiki.gg/wiki/Alther's_Mill",
		},
		["galardell valley"] = {
			name = "Vale Galardell",
			short = "O Vale Galardell, no nordeste das Montanhas Cristarrubra, fervilha de gnolls sob o comando do Tenente Fangore, cujo uivo faz as matilhas caírem sobre qualquer um que o enfrente despreparado.",
			full = "O Vale Galardell, no nordeste das Montanhas Cristarrubra, fervilha de gnolls sob o comando do Tenente Fangore, cujo uivo faz as matilhas caírem sobre qualquer um que o enfrente despreparado.\n\nAcima do vale fica a Torre de Ilgalar, morada do maligno Morganth, cujo nome por si só marca o lugar como algo a ser temido.",
			source = "https://warcraft.wiki.gg/wiki/Galardell_Valley",
		},
		["lake everstill"] = {
			name = "Lago Plácido",
			short = "O Lago Plácido fica no coração das Montanhas Cristarrubra, com águas amplas e azuis o bastante para dar à sonolenta cidade de Vila Plácida toda a sua razão de existir.",
			full = "O Lago Plácido fica no coração das Montanhas Cristarrubra, com águas amplas e azuis o bastante para dar à sonolenta cidade de Vila Plácida toda a sua razão de existir. O lago escoa para o leste, com seu rio correndo rumo às pedras escuras da Bastilha Mirante de Pedra.\n\nJá foi um lago de pescadores, calmo e confiável, mas isso mudou. Tribos de murlocs tomaram tanto os baixios quanto as profundezas, e em algum ponto das águas fundas um debulhador ainda patrulha, velho e enorme o bastante para que até os caçadores experientes das tribos murlocs se mantenham bem longe. A Ponte Plácida ainda leva os viajantes sobre a água, acima dos acampamentos murlocs e da coisa que observa lá de baixo.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Everstill",
		},
		["lakeridge highway"] = {
			name = "Estrada Beira-lago",
			short = "A Estrada Beira-lago um dia teve tráfego constante ao longo da margem sul do Lago Plácido, antes que os orcs tomassem a Bastilha Mirante de Pedra e a estrada caísse em desuso.",
			full = "A Estrada Beira-lago um dia teve tráfego constante ao longo da margem sul do Lago Plácido, antes que os orcs tomassem a Bastilha Mirante de Pedra e a estrada caísse em desuso. Gnolls agora percorrem quase toda a sua extensão, e caçadores Rocha Negra camuflados esperam de tocaia mais adiante. Viajar por ela não é algo que alguém recomendaria.",
			source = "https://warcraft.wiki.gg/wiki/Lakeridge_Highway",
		},
		["lakeshire"] = {
			name = "Vila Plácida",
			short = "O Lago Plácido repousa imóvel e frio sob os picos de Cristarrubra, e a cidade em sua margem já sangrou por esse chão mais de uma vez.",
			full = "O Lago Plácido repousa imóvel e frio sob os picos de Cristarrubra, e a cidade em sua margem já sangrou por esse chão mais de uma vez. Quando o Chefe Guerreiro Mão Negra levou os orcs a estas montanhas pela primeira vez, Sir Anduin Lothar e os Cavaleiros de Ventobravo os emboscaram nas encostas e quase os destroçaram, até que dois bruxos do Conselho das Sombras viraram a batalha e forçaram Lothar a recuar. Mão Negra voltou semanas depois com uma hoste maior e tomou Vila Plácida de vez. Só depois da Segunda Guerra a Aliança de Lordaeron a recuperou, com o Comandante Supremo Turalyon supervisionando o retorno de seu povo disperso.",
			source = "https://warcraft.wiki.gg/wiki/Lakeshire",
		},
		["redridge canyons"] = {
			name = "Garganta Cristarrubra",
			short = "Os desfiladeiros cortam o noroeste de Cristarrubra, com paredes que escondem o covil de Berrante, que lidera os gnolls que dominam este terreno.",
			full = "Os desfiladeiros cortam o noroeste de Cristarrubra, com paredes que escondem o covil de Berrante, que lidera os gnolls que dominam este terreno.",
			source = "https://warcraft.wiki.gg/wiki/Redridge_Canyons",
		},
		["renders camp"] = {
			name = "Acampamento dos Laceradores",
			short = "Os orcs Rocha Negra mantêm um acampamento no noroeste das Montanhas Cristarrubra, perto da passagem para as Estepes Ardentes.",
			full = "Os orcs Rocha Negra mantêm um acampamento no noroeste das Montanhas Cristarrubra, perto da passagem para as Estepes Ardentes. Daqui eles vigiam o desfiladeiro, um ponto de apoio do clã Rocha Negra encostado nas montanhas que levam aos domínios de seu senhor.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Camp",
		},
		["renders rock"] = {
			name = "Rocha dos Laceradores",
			short = "A Rocha dos Laceradores é uma caverna ampla no noroeste das Montanhas Cristarrubra, perto das Estepes Ardentes. Os orcs Rocha Negra a ocupam em grande número.",
			full = "A Rocha dos Laceradores é uma caverna ampla no noroeste das Montanhas Cristarrubra, perto das Estepes Ardentes. Os orcs Rocha Negra a ocupam em grande número.\n\nAqui o Cabo Keeshan jaz ferido, isolado, precisando chegar vivo a Vila Plácida.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Rock",
		},
		["renders valley"] = {
			name = "Vale dos Laceradores",
			short = "O Vale dos Laceradores fica no sudeste das Montanhas Cristarrubra, um posto avançado dos orcs Rocha Negra que se tornou uma fortaleza, cercada de torres e defendida por guerreiros de elite.",
			full = "O Vale dos Laceradores fica no sudeste das Montanhas Cristarrubra, um posto avançado dos orcs Rocha Negra que se tornou uma fortaleza, cercada de torres e defendida por guerreiros de elite.",
			source = "https://warcraft.wiki.gg/wiki/Render's_Valley",
		},
		["rethban caverns"] = {
			name = "Cavernas Retibanas",
			short = "As Cavernas Retibanas penetram fundo no noroeste das Montanhas Cristarrubra. Gnolls ocupam os túneis, liderados pelo astuto Ardo Dirtpaw, acumulando minério retibano arrancado da pedra.",
			full = "As Cavernas Retibanas penetram fundo no noroeste das Montanhas Cristarrubra. Gnolls ocupam os túneis, liderados pelo astuto Ardo Dirtpaw, acumulando minério retibano arrancado da pedra. As cavernas talvez levem o nome de um homem chamado Bart Rethban, embora pouco mais se lembre dele.",
			source = "https://warcraft.wiki.gg/wiki/Rethban_Caverns",
		},
		["stonewatch"] = {
			name = "Mirante de Pedra",
			short = "O Mirante de Pedra um dia pertenceu aos humanos de Vila Plácida, uma fortaleza encostada nos penhascos onde a cachoeira despenca abaixo da bastilha, vigiando Cristarrubra contra a ameaça orc das Estepes Ardentes.",
			full = "O Mirante de Pedra um dia pertenceu aos humanos de Vila Plácida, uma fortaleza encostada nos penhascos onde a cachoeira despenca abaixo da bastilha, vigiando Cristarrubra contra a ameaça orc das Estepes Ardentes.\n\nEssa vigília foi rompida pela traição. O bruxo Morganth firmou uma aliança com Gath'Ilzogg e seus orcs Rocha Negra, e juntos suas forças caíram sobre a Bastilha Mirante de Pedra com uma selvageria que destroçou a guarnição. Os orcs tomaram a bastilha, mas seu triunfo durou pouco em matéria de confiança, pois Morganth se voltou contra os aliados que a haviam conquistado para ele. Ergueu para si a Torre de Ilgalar e submeteu a seus próprios propósitos um bando de gnolls Shadowhide, sob o comando do Tenente Fangore. Desde essa reviravolta, tanto orcs quanto homens que cruzam o caminho dos gnolls pagam caro por isso.\n\nAbandonados pelo bruxo que os usara, os orcs Rocha Negra mantiveram a bastilha por conta própria, com Gath'Ilzogg governando-a e seu tenente Tharil'zun ao lado.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch",
		},
		["stonewatch falls"] = {
			name = "Cachoeira do Mirante de Pedra",
			short = "Abaixo do Mirante de Pedra, o rio leste do Lago Plácido despenca numa longa queda encosta abaixo, formando um lago profundo num recanto das Montanhas Cristarrubra.",
			full = "Abaixo do Mirante de Pedra, o rio leste do Lago Plácido despenca numa longa queda encosta abaixo, formando um lago profundo num recanto das Montanhas Cristarrubra. Uma pequena tribo de murlocs se instalou em suas margens, pescando na água e erguendo abrigos rústicos sob a cachoeira.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Falls",
		},
		["stonewatch keep"] = {
			name = "Bastilha Mirante de Pedra",
			short = "A Bastilha Mirante de Pedra um dia pertenceu aos humanos de Vila Plácida, erguida para vigiar Cristarrubra.",
			full = "A Bastilha Mirante de Pedra um dia pertenceu aos humanos de Vila Plácida, erguida para vigiar Cristarrubra. Ela caiu quando o bruxo Morganth firmou uma aliança com o senhor da guerra orc Rocha Negra Gath'Ilzogg, e juntas suas forças se lançaram contra a bastilha com uma selvageria alimentada pela magia sombria de Morganth. Os defensores foram destroçados, e a bastilha foi tomada.\n\nA aliança não durou. Mal o Mirante de Pedra havia caído, Morganth se voltou contra os orcs que haviam sangrado por ele a seu lado. Ergueu a Torre de Ilgalar ali perto e a encheu de gnolls Shadowhide sob o comando do Tenente Fangore, criaturas submetidas apenas à sua vontade. Orcs e homens caíram desde então diante dos brutos que ele soltou.\n\nAbandonados pelo aliado bruxo, os orcs Rocha Negra mantiveram a bastilha por conta própria, com Gath'Ilzogg e seu tenente Tharil'zun governando o que restava dela. Durante a batalha, haviam feito prisioneiro o Cabo Keeshan, do Exército de Ventobravo, e o arrastado para o norte, até seus acampamentos. O Magistrado Salomão pôs a cabeça de Gath'Ilzogg a prêmio por isso, e o Oficial Marris, de Vila Plácida, jurou que Tharil'zun também responderia por seus crimes.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Keep",
		},
		["stonewatch tower"] = {
			name = "Torre Mirante de Pedra",
			short = "A Torre Mirante de Pedra ficava ao lado da Bastilha Mirante de Pedra, ambas pertencentes aos humanos de Vila Plácida, até que o clã Rocha Negra tomou a fortaleza.",
			full = "A Torre Mirante de Pedra ficava ao lado da Bastilha Mirante de Pedra, ambas pertencentes aos humanos de Vila Plácida, até que o clã Rocha Negra tomou a fortaleza. A torre serve de posto de observação para os subordinados de Gath'Ilzogg, orcs do clã Rocha Negra que vigiam a fortaleza que seus parentes tomaram dos homens de Vila Plácida.",
			source = "https://warcraft.wiki.gg/wiki/Stonewatch_Tower",
		},
		["three corners"] = {
			name = "Três Caminhos",
			short = "Em Três Caminhos, a estrada se divide em três: a oeste, até Vila d'Ouro, na Floresta de Elwynn; a leste, até Vila Plácida; ao sul, até Vila Sombria, na Floresta do Crepúsculo.",
			full = "Em Três Caminhos, a estrada se divide em três: a oeste, até Vila d'Ouro, na Floresta de Elwynn; a leste, até Vila Plácida; ao sul, até Vila Sombria, na Floresta do Crepúsculo. Parado aqui, o viajante está na costura de três terras, com apenas a encruzilhada para marcar a passagem entre elas. Gnolls avançam das colinas próximas.",
			source = "https://warcraft.wiki.gg/wiki/Three_Corners",
		},
		["tower of ilgalar"] = {
			name = "Torre de Ilgalar",
			short = "A Torre de Ilgalar se ergue no leste das Montanhas Cristarrubra.",
			full = "A Torre de Ilgalar se ergue no leste das Montanhas Cristarrubra. Morganth a governa, um feiticeiro exilado do Distrito dos Magos de Ventobravo por seus estudos sombrios, que tomou a torre como refúgio e submeteu à sua vontade o clã de gnolls Shadowhide.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Ilgalar",
		},
	},
	-- Selva do Espinhaço: 38 subzones
	[1434] = {
		["baliamah ruins"] = {
			name = "Ruínas de Balia'mah",
			short = "As pedras de Balia'mah são uma antiga obra troll, erguidas a leste do rio abaixo de Mosh'Ogg. Os trolls Rachacrânio as ocupam agora, tendo feito um lar do que seus ancestrais ergueram.",
			full = "As pedras de Balia'mah são uma antiga obra troll, erguidas a leste do rio abaixo de Mosh'Ogg. Os trolls Rachacrânio as ocupam agora, tendo feito um lar do que seus ancestrais ergueram.",
			source = "https://warcraft.wiki.gg/wiki/Balia'mah_Ruins",
		},
		["ballal ruins"] = {
			name = "Ruínas de Bal'lal",
			short = "Colunas quebradas se erguem perto do Arrecife Torpe, ao norte do Acampamento Grom'gol, tudo o que resta de um povoado erguido há muito tempo por trolls. Pouco do que ele foi ainda está de pé.",
			full = "Colunas quebradas se erguem perto do Arrecife Torpe, ao norte do Acampamento Grom'gol, tudo o que resta de um povoado erguido há muito tempo por trolls. Pouco do que ele foi ainda está de pé. Agora os trolls Bloodscalp ocupam a ruína, vivendo entre as pedras que seus ancestrais deixaram.",
			source = "https://warcraft.wiki.gg/wiki/Bal'lal_Ruins",
		},
		["bloodsail compound"] = {
			name = "Complexo da Vela Sangrenta",
			short = "Os Bucaneiros da Vela Sangrenta mantêm um acampamento desordenado ao longo do litoral oeste da Selva do Espinhaço, escondido mais para o meio da costa.",
			full = "Os Bucaneiros da Vela Sangrenta mantêm um acampamento desordenado ao longo do litoral oeste da Selva do Espinhaço, escondido mais para o meio da costa. Nenhuma bandeira de ordem tremula aqui, nenhuma disciplina de um porto de verdade: apenas o ajuntamento disperso de piratas que chamam o lugar de seu.",
			source = "https://warcraft.wiki.gg/wiki/Bloodsail_Compound",
		},
		["booty bay"] = {
			name = "Angra do Butim",
			short = "A Angra do Butim fica numa lagoa azul no extremo sul da Selva do Espinhaço, com entrada a pé pelas mandíbulas descoradas de um tubarão gigante.",
			full = "A Angra do Butim fica numa lagoa azul no extremo sul da Selva do Espinhaço, com entrada a pé pelas mandíbulas descoradas de um tubarão gigante. A vida vale pouco aqui, e não se pode confiar em ninguém; é um paraíso para ladinos, repleto de informantes e comerciantes de todo tipo.\n\nAntes de ter esse nome, a enseada se chamava Angra Aguanegra, um pequeno porto humano até ser tomado por trolls da selva. Os goblins do Cartel Bondebico rechaçaram os trolls da praia e tomaram a enseada para si, antes mesmo de a Primeira Guerra ser travada, e ali construíram seu centro de operações nos Reinos do Leste.\n\nOs Saqueadores de Aguanegra administram o porto agora, em estreita parceria com o Cartel, e suas portas estão abertas a qualquer viajante, seja qual for a bandeira. O Barão Rezingada governa do alto da estalagem, ao lado do Mestre de Frota Chifre do Mar, dos Saqueadores, e gastou sem economia para contratar espadas contra os Bucaneiros da Vela Sangrenta, piratas que tramaram, sem sucesso, tomar a própria angra.",
			source = "https://warcraft.wiki.gg/wiki/Booty_Bay",
		},
		["cape of stranglethorn"] = {
			name = "Cabo do Espinhaço",
			short = "O sul da Selva do Espinhaço está repleto de ruínas trolls, meio engolidas pela selva, e de longos trechos de praia arenosa onde as árvores dão lugar ao mar.",
			full = "O sul da Selva do Espinhaço está repleto de ruínas trolls, meio engolidas pela selva, e de longos trechos de praia arenosa onde as árvores dão lugar ao mar.\n\nAo longo da costa fica a Angra do Butim, uma cidade portuária administrada por piratas goblins, com seu cais e seu mercado abertos a qualquer um com moedas, seja qual for a bandeira.\n\nEssa neutralidade não é paz. Os goblins da Angra do Butim mantêm seu porto pelo comércio e pela força, e seus rivais são os Bucaneiros da Vela Sangrenta, piratas que se voltaram contra eles e passaram a saquear as águas e a praia que os goblins chamam de suas. O conflito entre os dois só piorou, navio contra navio e acampamento contra acampamento, com os goblins guardando o que construíram enquanto os Vela Sangrenta pressionam para tomá-lo deles.\n\nAlém do porto e das ruínas, a terra é tranquila: areia, pedra antiga e o mar mais além.",
			source = "https://warcraft.wiki.gg/wiki/Cape_of_Stranglethorn",
		},
		["crystal shore"] = {
			name = "Praia Cristalina",
			short = "A Praia Cristalina é um litoral arenoso no sudeste do Espinhaço, onde os Mares do Sul quebram contra o continente e contra as praias do leste da Ilha Jaguara.",
			full = "A Praia Cristalina é um litoral arenoso no sudeste do Espinhaço, onde os Mares do Sul quebram contra o continente e contra as praias do leste da Ilha Jaguara. Ela vai da Praia Selvagem até os penhascos onde a terra sobe para o norte, isolada do interior por uma serra íngreme atravessada por apenas duas trilhas, uma delas subindo rumo ao Vale da Névoa.\n\nAs Ruínas de Aboraz ficam na extremidade norte da praia.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Shore",
		},
		["crystalvein mine"] = {
			name = "Mina Veia de Cristal",
			short = "Cranque Mirrabolha os chamava de Cristais Cantantes, exclusivos do Espinhaço e valendo uma fortuna.",
			full = "Cranque Mirrabolha os chamava de Cristais Cantantes, exclusivos do Espinhaço e valendo uma fortuna. Eles formam veios na rocha da Mina Veia de Cristal, perto de Zul'Mamwe, e os basiliscos que se aninham ali os comem crus, endurecendo o couro até virar pedra. A Empreendimentos S.A. entrou na esperança de despojar a mina, mas os basiliscos repeliram todas as tentativas. Do lado de fora da entrada, trolls e humanos estão cristalizados onde caíram.",
			source = "https://warcraft.wiki.gg/wiki/Crystalvein_Mine",
		},
		["gromgol base camp"] = {
			name = "Acampamento Grom'gol",
			short = "O Acampamento Grom'gol fica fortificado no litoral sudoeste do Espinhaço, com paliçadas erguidas contra os trolls da selva da costa, contra os nagas que surgem da arrebentação e contra a Aliança, que chega da Angra do Butim e da Floresta do Crepúsculo.",
			full = "O Acampamento Grom'gol fica fortificado no litoral sudoeste do Espinhaço, com paliçadas erguidas contra os trolls da selva da costa, contra os nagas que surgem da arrebentação e contra a Aliança, que chega da Angra do Butim e da Floresta do Crepúsculo. O Comandante Aggro'gosh defende o acampamento, mantendo-o como o elo seguro da cadeia de suprimentos que vai até Pedregal, no Pântano das Mágoas.",
			source = "https://warcraft.wiki.gg/wiki/Grom'gol_Base_Camp",
		},
		["gurubashi arena"] = {
			name = "Arena de Gurubashi",
			short = "A Arena de Gurubashi fica no noroeste do Espinhaço, uma relíquia erguida nos tempos em que o Império Gurubashi governava vastas extensões do sul dos Reinos do Leste.",
			full = "A Arena de Gurubashi fica no noroeste do Espinhaço, uma relíquia erguida nos tempos em que o Império Gurubashi governava vastas extensões do sul dos Reinos do Leste.\n\nEm tempos antigos, as lutas travadas aqui não eram esporte, mas matança. A areia virava lama com o sangue troll enquanto os combatentes lutavam até a morte. Agora João Tampinha Mithril supervisiona combates de um tipo mais brando, oferecendo fama e saque em vez de morte. Velhas histórias ainda advertem que quem encontrar um amuleto vermelho-sangue à meia-noite será devorado por um demônio antes do amanhecer.",
			source = "https://warcraft.wiki.gg/wiki/Gurubashi_Arena",
		},
		["jaguero isle"] = {
			name = "Ilha Jaguara",
			short = "Ao largo da costa da Praia Selvagem fica a Ilha Jaguara, uma selva dominada por panteras e gorilas que não respondem a ninguém.",
			full = "Ao largo da costa da Praia Selvagem fica a Ilha Jaguara, uma selva dominada por panteras e gorilas que não respondem a ninguém. O principal deles é o Rei Mukla, um macaco enorme, que governa a ilha e mantém cativa a Princesa Manda-chuva, uma tauren presa contra a vontade.\n\nMeio enterradas ao longo da praia há garrafas trazidas pelo mar, uma delas com um bilhete dobrado.",
			source = "https://warcraft.wiki.gg/wiki/Jaguero_Isle",
		},
		["janeiros point"] = {
			name = "Pontal de Janeiro",
			short = "O Pontal de Janeiro é uma pequena ilha diante da Angra do Butim, marcada por um grande goblin de pedra de braços abertos, erguido como farol para dar boas-vindas aos navios que entram no porto.",
			full = "O Pontal de Janeiro é uma pequena ilha diante da Angra do Butim, marcada por um grande goblin de pedra de braços abertos, erguido como farol para dar boas-vindas aos navios que entram no porto. Ninguém mais se lembra de quem ele retrata. O gigante do mar Mok'rash, o Cutelo, fez da ilha sua morada.",
			source = "https://warcraft.wiki.gg/wiki/Janeiro's_Point",
		},
		["kalai ruins"] = {
			name = "Ruínas de Kal'ai",
			short = "As Ruínas de Kal'ai estão meio engolidas pelo mar na Selva do Espinhaço, antiga cantaria troll desgastada pela maré e pelo tempo.",
			full = "As Ruínas de Kal'ai estão meio engolidas pelo mar na Selva do Espinhaço, antiga cantaria troll desgastada pela maré e pelo tempo. A tribo de murlocs Murkgill agora se aninha entre as colunas caídas, tendo tomado os salões submersos para si.",
			source = "https://warcraft.wiki.gg/wiki/Kal'ai_Ruins",
		},
		["kurzens compound"] = {
			name = "Complexo do Kurzen",
			short = "O Complexo do Kurzen fica a leste do Acampamento dos Rebeldes, sede da Expedição de Kurzen. O Coronel Kurzen a lidera, embora a loucura tenha tomado conta dele.",
			full = "O Complexo do Kurzen fica a leste do Acampamento dos Rebeldes, sede da Expedição de Kurzen. O Coronel Kurzen a lidera, embora a loucura tenha tomado conta dele. No que ele se transformou não se comenta, apenas no resultado: os homens sob seu comando se dividiram. Os que se recusaram a continuar a segui-lo romperam com ele e se tornaram os combatentes da selva do Acampamento dos Rebeldes, e o complexo está em guerra com eles desde então, homens que um dia serviram sob um mesmo comando agora se matando entre as árvores.\n\nO próprio Kurzen já não é visto com frequência entre seus homens; dizem que ele fica no Arsenal, nos fundos do complexo, onde os combatentes guardam suas armas. Perto dos estábulos, panteras e tigres do Espinhaço são mantidos em jaulas, domados e treinados como feras de guerra para uso da expedição.",
			source = "https://warcraft.wiki.gg/wiki/Kurzen's_Compound",
		},
		["lake nazferiti"] = {
			name = "Lago Nazferiti",
			short = "As águas do Lago Nazferiti fervilham de piranhas e crocoliscos, e uma grande base da Empreendimentos S.A. se amontoa em sua margem.",
			full = "As águas do Lago Nazferiti fervilham de piranhas e crocoliscos, e uma grande base da Empreendimentos S.A. se amontoa em sua margem.\n\nO lago é alimentado pelo rio Nazferiti, que alguns consideram o mais longo do sul dos Reinos do Leste, nascendo numa cachoeira nas Montanhas Cristarrubra, talvez ainda mais longe, na Trilha do Vento Morto.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Nazferiti",
		},
		["mistvale valley"] = {
			name = "Vale da Névoa",
			short = "A neblina se assenta baixa sobre o Vale da Névoa, espessa o bastante para borrar a linha das árvores no sul da Selva do Espinhaço.",
			full = "A neblina se assenta baixa sobre o Vale da Névoa, espessa o bastante para borrar a linha das árvores no sul da Selva do Espinhaço. Os grandes gorilas do Vale da Névoa fazem seu lar aqui, movendo-se pela névoa entre as árvores, senhores imperturbáveis deste vale tranquilo e úmido.",
			source = "https://warcraft.wiki.gg/wiki/Mistvale_Valley",
		},
		["mizjah ruins"] = {
			name = "Ruínas de Nizjah",
			short = "As Ruínas de Nizjah ficam a sudeste do Acampamento Grom'gol, dominadas por Brutamontes Mosh'Ogg e seus mandingueiros.",
			full = "As Ruínas de Nizjah ficam a sudeste do Acampamento Grom'gol, dominadas por Brutamontes Mosh'Ogg e seus mandingueiros. Destas pedras quebradas os ogros atacam as caravanas com destino a Pedregal, emboscando as linhas de suprimento e sumindo de volta nas ruínas antes que qualquer resposta possa ser dada.",
			source = "https://warcraft.wiki.gg/wiki/Mizjah_Ruins",
		},
		["moshogg ogre mound"] = {
			name = "Gruta de Mosh'Ogg",
			short = "A Gruta de Mosh'Ogg fica ao sul de Zul'Gurub, com suas cavidades escuras abrigando a tribo de ogros Mosh'Ogg.",
			full = "A Gruta de Mosh'Ogg fica ao sul de Zul'Gurub, com suas cavidades escuras abrigando a tribo de ogros Mosh'Ogg. Lá no fundo, seu líder, o ogro-magi Mai'Zoth, guarda uma poderosa relíquia conhecida como Olho da Mente, e é dessas profundezas que ele governa a gruta hoje.",
			source = "https://warcraft.wiki.gg/wiki/Mosh'Ogg_Ogre_Mound",
		},
		["nekmani wellspring"] = {
			name = "Olho-d'água Nek'mani",
			short = "O Olho-d'água Nek'mani brota nos penhascos acima da Costa Selvagem Sul, no limite oeste do Espinhaço.",
			full = "O Olho-d'água Nek'mani brota nos penhascos acima da Costa Selvagem Sul, no limite oeste do Espinhaço.\n\nEstudiosos de todas as raças afirmam que as águas foram consagradas apenas para seu próprio povo, e ninguém jamais resolveu a questão.",
			source = "https://warcraft.wiki.gg/wiki/Nek'mani_Wellspring",
		},
		["nesingwarys expedition"] = {
			name = "Expedição do Rosarães",
			short = "Hemet Rosarães, um mestre caçador anão, liderou uma expedição ao Espinhaço, atraído pela caça selvagem da selva.",
			full = "Hemet Rosarães, um mestre caçador anão, liderou uma expedição ao Espinhaço, atraído pela caça selvagem da selva. Ele montou seu acampamento logo abaixo do rio ao norte do Lago Nazferiti, e o acampamento ainda está de pé, um ponto de apoio de caçador aberto na vastidão verde do Espinhaço.",
			source = "https://warcraft.wiki.gg/wiki/Nesingwary's_Expedition",
		},
		["rebel camp"] = {
			name = "Acampamento dos Rebeldes",
			short = "O Acampamento dos Rebeldes fica no norte da Selva do Espinhaço, a oeste da estrada que desce da Floresta do Crepúsculo, a noroeste do Complexo do Kurzen.",
			full = "O Acampamento dos Rebeldes fica no norte da Selva do Espinhaço, a oeste da estrada que desce da Floresta do Crepúsculo, a noroeste do Complexo do Kurzen.\n\nSeus fundadores serviram na expedição do Coronel Kurzen até que a loucura tomou conta dele e de seus homens, distorcendo suas mentes a ponto de ficarem irreconhecíveis. Um pequeno bando sob o comando do Tenente Doren se libertou antes que a loucura os dominasse, fugindo do Complexo do Kurzen para o oeste, pela selva.\n\nAli construíram o Acampamento dos Rebeldes, um ponto de apoio a partir do qual desfazer aquilo em que Kurzen havia se transformado. Krazek, da Angra do Butim, os mantém abastecidos com minas terrestres e outros meios de defesa, o suficiente para que os rebeldes resistam à guarnição amaldiçoada ao lado da qual um dia serviram.",
			source = "https://warcraft.wiki.gg/wiki/Rebel_Camp",
		},
		["ruins of aboraz"] = {
			name = "Ruínas de Aboraz",
			short = "Aboraz foi erguida por trolls antigos, mas hoje não pertence a nenhum deles.",
			full = "Aboraz foi erguida por trolls antigos, mas hoje não pertence a nenhum deles. Zanzil, o Proscrito, exilado de sua própria gente, tomou as ruínas como seu domínio, enchendo-as de carniçais, nagas e lacaios trolls que obedecem à sua arte de mandingueiro.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Aboraz",
		},
		["ruins of jubuwal"] = {
			name = "Ruínas de Jubuwal",
			short = "As Ruínas de Jubuwal ficam a leste da Arena de Gurubashi, um antigo povoado troll agora ocupado por carniçais, nagas e trolls a serviço de Zanzil, o Proscrito.",
			full = "As Ruínas de Jubuwal ficam a leste da Arena de Gurubashi, um antigo povoado troll agora ocupado por carniçais, nagas e trolls a serviço de Zanzil, o Proscrito. Entre eles se escondem Jon-Jon, o Corvo, e Maury \"Pé Torto\" Wilkins, homens que fugiram para essa companhia sinistra para escapar de dívidas com o implacável MacKinley \"Lobo do Mar\".",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Jubuwal",
		},
		["ruins of zulkunda"] = {
			name = "Ruínas de Zul'Kanda",
			short = "Os terraços de pedra de Zul'Kanda pertencem agora aos trolls Bloodscalp, governados por Nezzliok, o Atroz, e Gan'zulah.",
			full = "Os terraços de pedra de Zul'Kanda pertencem agora aos trolls Bloodscalp, governados por Nezzliok, o Atroz, e Gan'zulah. O caminho a leste das Ruínas Zuuldaia leva direto ao território deles, onde a antiga cantaria troll está tomada pelos vivos.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Kunda",
		},
		["ruins of zulmamwe"] = {
			name = "Ruínas de Zul'Mamwe",
			short = "As Ruínas de Zul'Mamwe estão cercadas de montanhas por todos os lados, menos ao norte, ao sul da Gruta de Mosh'Ogg.",
			full = "As Ruínas de Zul'Mamwe estão cercadas de montanhas por todos os lados, menos ao norte, ao sul da Gruta de Mosh'Ogg. São a sede dos Rachacrânio, a segunda das tribos trolls da Selva do Espinhaço, governados por seu chefe Ana'thek, o Cruel.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Zul'Mamwe",
		},
		["savage coast"] = {
			name = "Costa Selvagem",
			short = "A Costa Selvagem se estende pela margem norte da Selva do Espinhaço, da fronteira com o Cerro Oeste, passando pelo Arrecife Torpe, até Grom'gol.",
			full = "A Costa Selvagem se estende pela margem norte da Selva do Espinhaço, da fronteira com o Cerro Oeste, passando pelo Arrecife Torpe, até Grom'gol.\n\nCrocoliscos assombram seus baixios, e basiliscos espreitam em suas rochas, com um olhar que transforma os desavisados em pedra. Vários povoados trolls vigiam estas águas.",
			source = "https://warcraft.wiki.gg/wiki/Savage_Coast",
		},
		["south seas"] = {
			name = "Mares do Sul",
			short = "Os Mares do Sul enchem as águas entre os continentes conhecidos, uma parte do Grande Mar. Zandalar se ergue destas águas, antigo lar do império troll.",
			full = "Os Mares do Sul enchem as águas entre os continentes conhecidos, uma parte do Grande Mar. Zandalar se ergue destas águas, antigo lar do império troll. Kezan também fica entre elas, uma ilha vulcânica que mantém seu próprio povo afastado das potências do continente. Mais perto da Selva do Espinhaço, o mar fica traiçoeiro, cheio de recifes e pequenas ilhas, algumas nada mais que um banco de areia, outras guardando ruínas cujos construtores já se foram. Os Mares do Sul banham as fronteiras do Espinhaço, de Tanaris e de Uldum.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southern savage coast"] = {
			name = "Costa Selvagem Sul",
			short = "A Costa Selvagem Sul fica onde os Mares do Sul quebram contra praias abertas e águas rasas, estendendo-se até as águas perto da Angra do Butim e do Pontal de Janeiro, onde o litoral dá lugar à Praia Selvagem mais além.",
			full = "A Costa Selvagem Sul fica onde os Mares do Sul quebram contra praias abertas e águas rasas, estendendo-se até as águas perto da Angra do Butim e do Pontal de Janeiro, onde o litoral dá lugar à Praia Selvagem mais além.\n\nO Arrecife Torpe marca a linha entre esta costa e sua contraparte ao norte, onde o Grande Mar dá lugar aos Mares do Sul. Baías e enseadas põem a costa em contato com a Arena de Gurubashi e o Olho-d'água Nek'mani.",
			source = "https://warcraft.wiki.gg/wiki/Southern_Savage_Coast",
		},
		["spirit den"] = {
			name = "Covil dos Espíritos",
			short = "O Covil dos Espíritos fica escondido numa caverna na extremidade norte do Vale da Névoa. Ali o mandingueiro Unbagwa se mantém nas sombras do covil, cuidando dos espíritos que se demoram naquela cavidade tranquila e oculta.",
			full = "O Covil dos Espíritos fica escondido numa caverna na extremidade norte do Vale da Névoa. Ali o mandingueiro Unbagwa se mantém nas sombras do covil, cuidando dos espíritos que se demoram naquela cavidade tranquila e oculta.",
			source = "https://warcraft.wiki.gg/wiki/Spirit_Den",
		},
		["stockpile"] = {
			name = "O Arsenal",
			short = "Numa caverna nos fundos do Complexo do Kurzen, o Coronel Kurzen guarda o equipamento de sua guerra.",
			full = "Numa caverna nos fundos do Complexo do Kurzen, o Coronel Kurzen guarda o equipamento de sua guerra.",
			source = "https://warcraft.wiki.gg/wiki/Stockpile",
		},
		["tkashi ruins"] = {
			name = "Ruínas de Tkashi",
			short = "As Ruínas de Tkashi ficam na Selva do Espinhaço, antiga cantaria troll retomada pela selva.",
			full = "As Ruínas de Tkashi ficam na Selva do Espinhaço, antiga cantaria troll retomada pela selva. A tribo Bloodscalp as ocupa agora, com seus xamãs realizando ritos antigos entre as muralhas quebradas e artefatos ainda espalhados pelos destroços.",
			source = "https://warcraft.wiki.gg/wiki/Tkashi_Ruins",
		},
		["venture co base camp"] = {
			name = "Base da Empreendimentos S.A.",
			short = "A Empreendimentos S.A. mantém uma base aqui, dedicada à busca de Cristais Rolados. Perto dali fica seu Centro de Operações, e os dois trabalham juntos em busca do mesmo achado.",
			full = "A Empreendimentos S.A. mantém uma base aqui, dedicada à busca de Cristais Rolados. Perto dali fica seu Centro de Operações, e os dois trabalham juntos em busca do mesmo achado.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Base_Camp",
		},
		["venture co operations center"] = {
			name = "Centro de Operações da Empreendimentos S.A.",
			short = "A plataforma de petróleo da Empreendimentos S.A. se ergue de um lago na selva, o centro de operações de seu avanço pelos ermos.",
			full = "A plataforma de petróleo da Empreendimentos S.A. se ergue de um lago na selva, o centro de operações de seu avanço pelos ermos. Mecânicos, geólogos e outras equipes goblins lotam a plataforma, operando as máquinas de uma empresa decidida a despojar a terra em busca de lucro.",
			source = "https://warcraft.wiki.gg/wiki/Venture_Co._Operations_Center",
		},
		["vile reef"] = {
			name = "O Arrecife Torpe",
			short = "Ao largo do litoral oeste da Selva do Espinhaço, perto de Grom'gol, o mar quebra reluzente sobre os corais.",
			full = "Ao largo do litoral oeste da Selva do Espinhaço, perto de Grom'gol, o mar quebra reluzente sobre os corais. Sob ele jazem ruínas trolls submersas, e entre essa pedra afogada os murlocs agora fazem seu lar, cardumes densos movendo-se por salões que um dia pertenceram a outros. O Altar das Marés ainda está de pé ali. Mariscos gigantes se espalham pelo fundo do arrecife, e dizem que guardam Pérolas Azuis, e destroços de navios que nunca passaram pelo arrecife chegam rolando à praia.",
			source = "https://warcraft.wiki.gg/wiki/Vile_Reef",
		},
		["wild shore"] = {
			name = "Praia Selvagem",
			short = "A Praia Selvagem é onde os Reinos do Leste dão lugar aos Mares do Sul, com praias dominadas pelos Bucaneiros da Vela Sangrenta, cuja frota fica ancorada ao largo e cujas tripulações reivindicam as areias como suas.",
			full = "A Praia Selvagem é onde os Reinos do Leste dão lugar aos Mares do Sul, com praias dominadas pelos Bucaneiros da Vela Sangrenta, cuja frota fica ancorada ao largo e cujas tripulações reivindicam as areias como suas. Em algum lugar ao longo da praia vaga Gorlash, um gigante solitário, e, entre piratas e gigante, a costa não responde a coroa alguma.\n\nA terra se estreita para o oeste até uma ponta rochosa antes de virar em direção à Angra do Butim. A leste, do outro lado de um estreito raso, fica a Ilha Jaguara. Ao norte, as areias se confundem com a Praia Cristalina.",
			source = "https://warcraft.wiki.gg/wiki/Wild_Shore",
		},
		["yojamba isle"] = {
			name = "Ilha Yojamba",
			short = "Nestas pequenas ilhas ao largo do litoral noroeste do Espinhaço, perto da fronteira com o Cerro Oeste, a Tribo Zandalar resistiu contra um deus enlouquecido.",
			full = "Nestas pequenas ilhas ao largo do litoral noroeste do Espinhaço, perto da fronteira com o Cerro Oeste, a Tribo Zandalar resistiu contra um deus enlouquecido.\n\nHakkar, o Esfolalmas, havia transformado Zul'Gurub num lugar de sangue e loucura, e os zandalari sabiam que não poderiam enfrentá-lo sozinhos. Então vieram à Ilha Yojamba e chamaram tanto a Aliança quanto a Horda a deixar de lado sua guerra pelo tempo necessário para ajudar a destruí-lo. Era uma tribo antiga e orgulhosa confiando a forasteiros o destino de sua cidade tocada pelos deuses.",
			source = "https://warcraft.wiki.gg/wiki/Yojamba_Isle",
		},
		["ziatajai ruins"] = {
			name = "Ruínas Ziata'jai",
			short = "As Ruínas Ziata'jai são pedras antigas erguidas há muito tempo por trolls, agora tomadas pela tribo Rachacrânio, que ocupa as velhas muralhas como suas.",
			full = "As Ruínas Ziata'jai são pedras antigas erguidas há muito tempo por trolls, agora tomadas pela tribo Rachacrânio, que ocupa as velhas muralhas como suas.",
			source = "https://warcraft.wiki.gg/wiki/Ziata'jai_Ruins",
		},
		["zulgurub"] = {
			name = "Zul'Gurub",
			short = "Zul'Gurub emerge da selva no nordeste da Selva do Espinhaço, com seus terraços e ídolos cobertos de vegetação, mas ainda de pé, uma cidade-templo que um dia foi o coração pulsante de um império.",
			full = "Zul'Gurub emerge da selva no nordeste da Selva do Espinhaço, com seus terraços e ídolos cobertos de vegetação, mas ainda de pé, uma cidade-templo que um dia foi o coração pulsante de um império. Há milhares de anos, ela foi a capital do Império Gurubashi, sede de todas as tribos de trolls da selva ligadas a ele. Agora pertence apenas à tribo Gurubashi que resta, e a selva ao seu redor não parece vazia.\n\nO império se despedaçou quando um círculo de sacerdotes chamado Atal'ai invocou o avatar de um antigo deus do sangue, Hakkar, o Esfolalmas, e foi exilado por isso. Eles descobriram que Hakkar só podia assumir forma física num único lugar: a própria antiga capital Gurubashi. É aqui que Jin'do, o Bagateiro, escravizou vários sumos sacerdotes Gurubashi, submetendo-os à tarefa de trazer Hakkar ao mundo. Campeões enviados para detê-lo, cada um ligado a um Deus Primordial, caíram em vez disso sob o domínio de Hakkar, e seu poder agora alimenta justamente aquilo que vieram destruir.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Gurub",
		},
		["zuuldaia ruins"] = {
			name = "Ruínas Zuuldaia",
			short = "Pedras desgastadas pelo tempo se erguem acima do litoral oeste da Selva do Espinhaço, ruínas de um povoado caído há muito tempo.",
			full = "Pedras desgastadas pelo tempo se erguem acima do litoral oeste da Selva do Espinhaço, ruínas de um povoado caído há muito tempo. Os trolls Bloodscalp agora ocupam as muralhas quebradas, numerosos entre as velhas fundações, reivindicando um terreno que seus ancestrais nunca ergueram.",
			source = "https://warcraft.wiki.gg/wiki/Zuuldaia_Ruins",
		},
	},
	-- Pântano das Mágoas: 14 subzones
	[1435] = {
		["fallow sanctuary"] = {
			name = "Retiro Alqueivado",
			short = "No Pântano das Mágoas fica o Retiro Alqueivado, lar de uma tribo de Perdidos conhecida simplesmente como os Perdidos.",
			full = "No Pântano das Mágoas fica o Retiro Alqueivado, lar de uma tribo de Perdidos conhecida simplesmente como os Perdidos. A saudade de casa tomou cada um deles, tornando-os completamente selvagens, de modo que nada do que um dia foram resta para receber quem se aproxima de sua aldeia.",
			source = "https://warcraft.wiki.gg/wiki/Fallow_Sanctuary",
		},
		["harborage"] = {
			name = "O Refúgio",
			short = "No norte do Pântano das Mágoas fica um refúgio daqueles que atravessaram de Draenor para Azeroth e, ao contrário de tantos de seus semelhantes, mantiveram a mente intacta.",
			full = "No norte do Pântano das Mágoas fica um refúgio daqueles que atravessaram de Draenor para Azeroth e, ao contrário de tantos de seus semelhantes, mantiveram a mente intacta. Magtoor os lidera aqui.",
			source = "https://warcraft.wiki.gg/wiki/Harborage",
		},
		["ithariuss cave"] = {
			name = "Caverna de Itharius",
			short = "No sudoeste do Pântano das Mágoas, uma caverna abriga o alto elfo Itharius. Do lado de fora, dragonetes verdes rebeldes brigam e tropeçam, jovens demais para dominar as asas ou o fogo.",
			full = "No sudoeste do Pântano das Mágoas, uma caverna abriga o alto elfo Itharius. Do lado de fora, dragonetes verdes rebeldes brigam e tropeçam, jovens demais para dominar as asas ou o fogo. Itharius tomou para si a tarefa de cuidar deles enquanto crescem.",
			source = "https://warcraft.wiki.gg/wiki/Itharius's_Cave",
		},
		["misty reed post"] = {
			name = "Posto Brumalga",
			short = "O Posto Brumalga é um pequeno posto avançado de Pedregal, entre o Pantanal dos Cervos e o sul da Praia Brumalga. Tok'Kar o comanda, com Katar, um punhado de caçadores de Pedregal e um xamã de Pedregal.",
			full = "O Posto Brumalga é um pequeno posto avançado de Pedregal, entre o Pantanal dos Cervos e o sul da Praia Brumalga. Tok'Kar o comanda, com Katar, um punhado de caçadores de Pedregal e um xamã de Pedregal. É apenas um acampamento, sem toca nem torre, embora Tok'Kar sonhe em um dia erguer uma.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Post",
		},
		["misty reed strand"] = {
			name = "Praia Brumalga",
			short = "A Praia Brumalga se estende ao longo do Pântano das Mágoas, um trecho sombrio de praia onde pouco cresce além de madeira à deriva e podridão. Crocoliscos tomam sol em seus baixios, e caranguejos e murlocs ficam na praia mais além.",
			full = "A Praia Brumalga se estende ao longo do Pântano das Mágoas, um trecho sombrio de praia onde pouco cresce além de madeira à deriva e podridão. Crocoliscos tomam sol em seus baixios, e caranguejos e murlocs ficam na praia mais além.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Reed_Strand",
		},
		["misty valley"] = {
			name = "Vale Nebuloso",
			short = "A névoa paira baixa sobre este canto do Pântano das Mágoas, espessa o bastante para engolir o som. No fundo de uma caverna nos fundos do vale habitava o Senhor do Lodo, uma força elemental.",
			full = "A névoa paira baixa sobre este canto do Pântano das Mágoas, espessa o bastante para engolir o som. No fundo de uma caverna nos fundos do vale habitava o Senhor do Lodo, uma força elemental.",
			source = "https://warcraft.wiki.gg/wiki/Misty_Valley",
		},
		["pool of tears"] = {
			name = "Poço de Lágrimas",
			short = "O Poço de Lágrimas repousa amplo e imóvel no limite leste do Pântano das Mágoas. Sob sua superfície calma fica o Templo de Atal'Hakkar, afundado ali por Ysera depois que os trolls o ergueram, escondido do mundo.",
			full = "O Poço de Lágrimas repousa amplo e imóvel no limite leste do Pântano das Mágoas. Sob sua superfície calma fica o Templo de Atal'Hakkar, afundado ali por Ysera depois que os trolls o ergueram, escondido do mundo. A revoada verde vigiou por muito tempo o lugar submerso, guardando-o contra qualquer coisa que pudesse despertar o que dormia lá embaixo.\n\nPiranhas sedentas de sangue se movem pela água agora, e cantaria Atal'ai destroçada se espalha pela margem.",
			source = "https://warcraft.wiki.gg/wiki/Pool_of_Tears",
		},
		["shifting mire"] = {
			name = "Lodaçal Mutante",
			short = "O lodo do Lodaçal Mutante nunca fica parado. Ele se acumula pelo chão em montes finos e rasteja pelo pântano como se algo invisível o arrastasse, enrolando-se e se empoçando como uma coisa viva.",
			full = "O lodo do Lodaçal Mutante nunca fica parado. Ele se acumula pelo chão em montes finos e rasteja pelo pântano como se algo invisível o arrastasse, enrolando-se e se empoçando como uma coisa viva.\n\nHá quem diga que a força por trás desse movimento não é maligna, mas alguma energia positiva que agita o lodo sem nenhuma vontade de causar mal.",
			source = "https://warcraft.wiki.gg/wiki/Shifting_Mire",
		},
		["sorrowmurk"] = {
			name = "Penumbra das Mágoas",
			short = "A Penumbra das Mágoas fica a leste do Poço de Lágrimas, perto do Templo Submerso.",
			full = "A Penumbra das Mágoas fica a leste do Poço de Lágrimas, perto do Templo Submerso. Ela pertence aos dracônicos, dracônidas verdes que rastejam por seu lodaçal sob a vigilância de um grande draco verde, que mantém afastados todos, exceto os viajantes mais imprudentes.",
			source = "https://warcraft.wiki.gg/wiki/Sorrowmurk",
		},
		["splinterspear junction"] = {
			name = "Entroncamento da Lança Lascada",
			short = "Onde a estrada que entra no Pântano das Mágoas se bifurca, uma velha torre de vigia orc ainda está de pé, e patrulhas da Horda mantêm o cruzamento sob seus olhos.",
			full = "Onde a estrada que entra no Pântano das Mágoas se bifurca, uma velha torre de vigia orc ainda está de pé, e patrulhas da Horda mantêm o cruzamento sob seus olhos.\n\nA torre é o que resta de Kyross, um posto avançado orc erguido aqui durante a Primeira Guerra. Kyross ficava mais perto da vila humana de Grã-vila do que qualquer outra posição da Horda no pântano, e Ventobravo não podia deixá-la em paz. Grupos de guerra foram enviados para derrubá-la.\n\nA torre ainda vigia a bifurcação da estrada.",
			source = "https://warcraft.wiki.gg/wiki/Splinterspear_Junction",
		},
		["stagalbog"] = {
			name = "Pantanal dos Cervos",
			short = "Ao sul do Poço de Lágrimas, onde o Pântano das Mágoas se eleva em montanhas, o brejo se adensa no Pantanal dos Cervos. A oeste da vastidão úmida, na borda da montanha, uma caverna se abre na rocha.",
			full = "Ao sul do Poço de Lágrimas, onde o Pântano das Mágoas se eleva em montanhas, o brejo se adensa no Pantanal dos Cervos. A oeste da vastidão úmida, na borda da montanha, uma caverna se abre na rocha.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog",
		},
		["stagalbog cave"] = {
			name = "Caverna Pantanal dos Cervos",
			short = "No leste do Pantanal dos Cervos, no Pântano das Mágoas, uma caverna se abre no lodaçal.",
			full = "No leste do Pantanal dos Cervos, no Pântano das Mágoas, uma caverna se abre no lodaçal.",
			source = "https://warcraft.wiki.gg/wiki/Stagalbog_Cave",
		},
		["stonard"] = {
			name = "Pedregal",
			short = "Pedregal se ergue do lodaçal do Pântano das Mágoas, com seu grande salão ainda de pé onde tantos outros salões orcs já caíram há muito tempo.",
			full = "Pedregal se ergue do lodaçal do Pântano das Mágoas, com seu grande salão ainda de pé onde tantos outros salões orcs já caíram há muito tempo. Duas tocas guardam o acesso, e patrulhas orcs saem para defender os pequenos acampamentos próximos, cada um mais uma reivindicação cravada contra o pântano.\n\nO posto avançado é antigo, mais antigo que quase qualquer outro ponto de apoio orc deste lado do mundo, irmão da fortaleza um dia conhecida como Rockard. Foi erguido pela Velha Horda no Lamaçal Negro nos dias que se seguiram à primeira abertura do Portal Negro. Quando veio a Segunda Guerra e a Horda se desfez, Pedregal silenciou, provavelmente abandonado ou destruído junto com tanto do que os orcs haviam construído.\n\nNão ficou vazio. Com a ascensão da nova Horda e uma vontade renovada de manter este território, Pedregal foi reconstruído, com seu salão restaurado e suas tocas escavadas de novo. Rockard não teve a mesma sorte: os ogros Malhorrendo tomaram a antiga fortaleza para si e a rebatizaram de Domínio de Malhorrendo, deixando Pedregal como o único posto avançado da Horda no pântano, o último salão de seu tipo ainda aceso nestas terras baixas.",
			source = "https://warcraft.wiki.gg/wiki/Stonard",
		},
		["temple of atalhakkar"] = {
			name = "Templo de Atal'Hakkar",
			short = "Há mais de mil anos, o Império Gurubashi se despedaçou numa guerra civil. Em seu centro estavam os Atal'ai, sacerdotes trolls que buscavam trazer de volta ao mundo o deus do sangue Hakkar, o Esfolalmas.",
			full = "Há mais de mil anos, o Império Gurubashi se despedaçou numa guerra civil. Em seu centro estavam os Atal'ai, sacerdotes trolls que buscavam trazer de volta ao mundo o deus do sangue Hakkar, o Esfolalmas. Derrotados e exilados, fugiram para o norte, até o Pântano das Mágoas, e ergueram ali um templo para preparar seu retorno.\n\nO Aspecto dragônico Ysera soube do plano deles e afundou o templo sob o pântano, com a intenção de enterrar sua obra para sempre. Não foi o que aconteceu. Sem ser perturbados na escuridão submersa, protegidos de qualquer olhar que pudesse detê-los, os Atal'ai continuaram seus rituais em paz. Os dragões verdes que Ysera pôs para guardar as ruínas montam vigília desde então, mantendo fechada uma porta que nunca foi realmente selada.\n\nO templo ainda está afundado e meio inundado, com seus altares a Hakkar intactos, e os que entram arriscam algo pior que a morte. Ao Loa do Sangue se devem almas, além de carne, e cada uma que lhe é entregue alimenta o dia em que ele não fracassará.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Atal'Hakkar",
		},
	},
	-- Cerro Oeste: 17 subzones
	[1436] = {
		["alexston farmstead"] = {
			name = "Fazenda dos Aleixo",
			short = "Os campos da Fazenda dos Aleixo alimentavam famílias antes que a Irmandade Defias tomasse a terra para si.",
			full = "Os campos da Fazenda dos Aleixo alimentavam famílias antes que a Irmandade Defias tomasse a terra para si. Agora só os Vigias da Colheita mecânicos se movem entre os sulcos, incansáveis e sem ninguém que cuide deles, guardando fileiras que ninguém mais planta.\n\nBaros Aleixo, que passou a servir a Ventobravo como arquiteto, nasceu neste solo. Ele trabalhou aqui quando menino, entre os mesmos campos que os Vigias da Colheita agora patrulham, antes que a terra que o formou passasse para outras mãos.",
			source = "https://warcraft.wiki.gg/wiki/Alexston_Farmstead",
		},
		["dagger hills"] = {
			name = "Os Obeliscos",
			short = "Os Obeliscos se erguem como uma serra nos fundos de Arroio da Lua, no sul do Cerro Oeste. Pouca coisa se mexe ali agora.",
			full = "Os Obeliscos se erguem como uma serra nos fundos de Arroio da Lua, no sul do Cerro Oeste. Pouca coisa se mexe ali agora. Canabraba Cervaforte vive entre as colinas, uma das únicas almas vivas que se encontram naquele trecho tranquilo de terra, e sabe-se que o carniçal Leprithus também se ergue da terra ali.",
			source = "https://warcraft.wiki.gg/wiki/Dagger_Hills",
		},
		["dead acre"] = {
			name = "O Alqueire Morto",
			short = "O Alqueire Morto já foi uma fazenda entre as outras do sudeste do Cerro Oeste, perto da ponte para a Floresta do Crepúsculo. Quando a Irmandade Defias tomou a região, ficou com a fazenda que havia ali, junto com seus campos.",
			full = "O Alqueire Morto já foi uma fazenda entre as outras do sudeste do Cerro Oeste, perto da ponte para a Floresta do Crepúsculo. Quando a Irmandade Defias tomou a região, ficou com a fazenda que havia ali, junto com seus campos.\n\nNenhum fazendeiro anda por ali agora. Em vez disso, Vigias da Colheita mecânicos rondam o terreno, vagando onde antes crescia uma colheita.",
			source = "https://warcraft.wiki.gg/wiki/Dead_Acre",
		},
		["deadmines"] = {
			name = "Minas Mortas",
			short = "Sob Arroio da Lua os túneis correm fundo, e um dia correram cheios de ouro. Antes que os orcs atravessassem para as terras humanas, as Minas Mortas abasteciam o tesouro de Ventobravo; segundo alguns relatos, um terço dele saía desta rocha.",
			full = "Sob Arroio da Lua os túneis correm fundo, e um dia correram cheios de ouro. Antes que os orcs atravessassem para as terras humanas, as Minas Mortas abasteciam o tesouro de Ventobravo; segundo alguns relatos, um terço dele saía desta rocha. A Primeira Guerra esvaziou as minas de mineiros, e depois elas foram deixadas como mortas, consideradas assombradas, e ficaram intocadas por muito tempo.\n\nNesse silêncio chegou Edwin VanCleef, que reuniu a Irmandade Defias, antigos trabalhadores transformados em salteadores, e os pôs para construir um colosso nas profundezas com a ajuda dos goblins.\n\nNessas profundezas VanCleef continua, guardado por sua Irmandade, enquanto Gryan Stoutmantle reúne homens no Morro da Sentinela, jurados a trazer de volta sua cabeça.",
			source = "https://warcraft.wiki.gg/wiki/Deadmines",
		},
		["demonts place"] = {
			name = "Recanto de Demont",
			short = "Pouco resta do Recanto de Demont além de madeira quebrada e campos tomados pelo mato, a oeste de Arroio da Lua. Antes uma fazenda produtiva, agora está ocupado por agentes Defias, que o tratam como seu.",
			full = "Pouco resta do Recanto de Demont além de madeira quebrada e campos tomados pelo mato, a oeste de Arroio da Lua. Antes uma fazenda produtiva, agora está ocupado por agentes Defias, que o tratam como seu.",
			source = "https://warcraft.wiki.gg/wiki/Demont's_Place",
		},
		["dust plains"] = {
			name = "Planícies do Pó",
			short = "As Planícies do Pó se estendem pelo sul do Cerro Oeste, terra seca entregue aos gnolls, que mantêm ali acampamentos espalhados e ameaçam qualquer um que atravesse seu território.",
			full = "As Planícies do Pó se estendem pelo sul do Cerro Oeste, terra seca entregue aos gnolls, que mantêm ali acampamentos espalhados e ameaçam qualquer um que atravesse seu território.\n\nNa borda leste fica a Torre de Mortwake, uma antiga torre de mago cujo propósito original há muito deu lugar a novos senhores.",
			source = "https://warcraft.wiki.gg/wiki/Dust_Plains",
		},
		["furlbrows pumpkin farm"] = {
			name = "Plantação de Abóboras do Taturana",
			short = "A Plantação de Abóboras do Taturana era cuidada pelo Fazendeiro Taturana e sua esposa, Verna, mas quando a Irmandade Defias varreu o Cerro Oeste com seus golens mecânicos de colheita, a fazenda caiu como tantas outras naquela região.",
			full = "A Plantação de Abóboras do Taturana era cuidada pelo Fazendeiro Taturana e sua esposa, Verna, mas quando a Irmandade Defias varreu o Cerro Oeste com seus golens mecânicos de colheita, a fazenda caiu como tantas outras naquela região. Taturana e Verna fugiram, refugiando-se na estrada perto do Sítio dos Jansen, ao norte, deixando para trás suas abóboras e seu nome.",
			source = "https://warcraft.wiki.gg/wiki/Furlbrow's_Pumpkin_Farm",
		},
		["gold coast quarry"] = {
			name = "Pedreira Costa Dourada",
			short = "A Pedreira Costa Dourada um dia rendeu ouro e minério para Ventobravo, antes que o Cerro Oeste caísse em ruínas. A Irmandade Defias a ocupa agora, explorando as cavas sob sua própria bandeira.",
			full = "A Pedreira Costa Dourada um dia rendeu ouro e minério para Ventobravo, antes que o Cerro Oeste caísse em ruínas. A Irmandade Defias a ocupa agora, explorando as cavas sob sua própria bandeira. A Milícia do Povo e seus membros já se enfrentaram com a Irmandade aqui, emboscados pelos Defias entre as pedras que ainda patrulham.",
			source = "https://warcraft.wiki.gg/wiki/Gold_Coast_Quarry",
		},
		["jangolode mine"] = {
			name = "Mina Veiojango",
			short = "A Mina Veiojango um dia enviou minério a Ventobravo, uma das fontes mais estáveis de riqueza mineral do Cerro Oeste.",
			full = "A Mina Veiojango um dia enviou minério a Ventobravo, uma das fontes mais estáveis de riqueza mineral do Cerro Oeste.\n\nEssa estabilidade acabou quando a Irmandade Defias tomou a mina. Desde então, kobolds se infiltraram em seus poços e os tomaram para si.",
			source = "https://warcraft.wiki.gg/wiki/Jangolode_Mine",
		},
		["jansen stead"] = {
			name = "Sítio dos Jansen",
			short = "O Sítio dos Jansen fica no limite norte do Cerro Oeste, perto da ponte para a Floresta de Elwynn. Como as outras fazendas da região, foi esvaziado de seus legítimos donos quando a Irmandade Defias os expulsou.",
			full = "O Sítio dos Jansen fica no limite norte do Cerro Oeste, perto da ponte para a Floresta de Elwynn. Como as outras fazendas da região, foi esvaziado de seus legítimos donos quando a Irmandade Defias os expulsou.\n\nPerto dali estão o Fazendeiro Taturana e sua esposa, que fugiram de seu próprio lar na Plantação de Abóboras do Taturana e agora se abrigam no sítio.",
			source = "https://warcraft.wiki.gg/wiki/Jansen_Stead",
		},
		["longshore"] = {
			name = "Praia Grande",
			short = "O litoral do Cerro Oeste se estende longo e vazio, uma das praias mais largas de Azeroth.",
			full = "O litoral do Cerro Oeste se estende longo e vazio, uma das praias mais largas de Azeroth. Murlocs se movem por ela em números grandes demais para serem contidos, e entre eles nada o Velho Olho Turvo, uma criatura que os pescadores da costa aprenderam a temer e a chamar pelo nome. Além da arrebentação jazem os ossos de navios que nunca chegaram, entre eles destróieres élficos, entregues à maré.\n\nNo extremo sudoeste da praia fica a fazenda de Dafne Calmafonte. A Irmandade Defias veio atrás dela mais de uma vez, com a intenção de expulsá-la a fogo, como incendiou tanta coisa no Cerro Oeste. A notícia de seus problemas chegou a Benedito Brião, que enviou aspirantes a Cavaleiros do Punho de Prata até a costa para vigiar suas terras, e eles as defenderam.",
			source = "https://warcraft.wiki.gg/wiki/Longshore",
		},
		["molsen farm"] = {
			name = "Fazenda dos Peçanha",
			short = "A Fazenda dos Peçanha está entre as muitas fazendas do Cerro Oeste ocupadas pela Irmandade Defias.",
			full = "A Fazenda dos Peçanha está entre as muitas fazendas do Cerro Oeste ocupadas pela Irmandade Defias. Suas fileiras estão entregues à ferrugem e às máquinas, e Vigias da Colheita mecânicos percorrem os campos, abatendo qualquer um que se aproxime demais.",
			source = "https://warcraft.wiki.gg/wiki/Molsen_Farm",
		},
		["moonbrook"] = {
			name = "Arroio da Lua",
			short = "Sob os campos de Arroio da Lua um dia correu um terço do tesouro de Ventobravo, ouro tirado dos túneis mais tarde chamados de Minas Mortas.",
			full = "Sob os campos de Arroio da Lua um dia correu um terço do tesouro de Ventobravo, ouro tirado dos túneis mais tarde chamados de Minas Mortas. A cidade era o celeiro do reino, até que a dissolução da Guilda dos Pedreiros desencadeou revoltas que mataram a Rainha Tiffin Wrynn. A vingança do Rei Varian por sua morte caiu com mais força sobre a guilda, e os Pedreiros fugiram para as terras de cultivo do Cerro Oeste para escapar dele. Atiçada das sombras, sua raiva se tornou a Irmandade Defias. Sob Edwin VanCleef, eles se voltaram para o banditismo, expulsaram os fazendeiros de Arroio da Lua e fizeram dos túneis de mina abandonados sob a cidade seu quartel-general, trabalhando ali em segredo para construir uma arma destinada a destruir Ventobravo pelo mar.\n\nHá anos nenhum exército vem responder a eles. A Irmandade ainda domina Arroio da Lua, e apenas a Milícia do Povo, de Gryan Stoutmantle, se opõe a ela, reunindo forças no Morro da Sentinela para um acerto de contas que ainda está por vir.",
			source = "https://warcraft.wiki.gg/wiki/Moonbrook",
		},
		["saldeans farm"] = {
			name = "Fazenda dos Saldanha",
			short = "A Fazenda dos Saldanha foi a única do Cerro Oeste que a Irmandade Defias nunca tomou. Golens de colheita Defias percorrem seus campos, mas o Fazendeiro Saldanha e sua esposa, Salma, se recusaram a partir.",
			full = "A Fazenda dos Saldanha foi a única do Cerro Oeste que a Irmandade Defias nunca tomou. Golens de colheita Defias percorrem seus campos, mas o Fazendeiro Saldanha e sua esposa, Salma, se recusaram a partir. A casa da fazenda serve há anos de pousada no meio do caminho, com o casal fazendo o que pode para manter seus hóspedes vivos.",
			source = "https://warcraft.wiki.gg/wiki/Saldean's_Farm",
		},
		["sentinel hill"] = {
			name = "Morro da Sentinela",
			short = "O Morro da Sentinela fica num terreno elevado acima das terras de cultivo do Cerro Oeste, com sua torre vigiando os chalés, a forja e o moinho construídos na encosta abaixo.",
			full = "O Morro da Sentinela fica num terreno elevado acima das terras de cultivo do Cerro Oeste, com sua torre vigiando os chalés, a forja e o moinho construídos na encosta abaixo.\n\nTanto os gnolls Riverpaw quanto a Irmandade Defias já atacaram o morro e as terras que ele protege.",
			source = "https://warcraft.wiki.gg/wiki/Sentinel_Hill",
		},
		["stendels pond"] = {
			name = "Lago Stendel",
			short = "Um pequeno lago fica a sudoeste do Morro da Sentinela, com a água parada sob um círculo de gnolls.",
			full = "Um pequeno lago fica a sudoeste do Morro da Sentinela, com a água parada sob um círculo de gnolls. Dois túmulos repousam em sua margem, junto com velhos ossos espalhados, e algo na água parece errado, como se ela nunca mais devesse ser bebida.\n\nOs pescadores que tentam a sorte ali quase sempre fisgam peixes-sálvia comuns. Mas dizem que outra coisa nada sob a superfície, um peixe chamado Ruína de Stendel, raramente visto e mais raramente ainda pescado.",
			source = "https://warcraft.wiki.gg/wiki/Stendel's_Pond",
		},
		["westfall lighthouse"] = {
			name = "Farol de Cerro Oeste",
			short = "O farol fica no extremo sul do Cerro Oeste, com seu facho ainda girando sobre a água à noite, embora a mão que o mantém agora pertença a um homem morto.",
			full = "O farol fica no extremo sul do Cerro Oeste, com seu facho ainda girando sobre a água à noite, embora a mão que o mantém agora pertença a um homem morto.\n\nUma família cuidava da chama, até que o murloc Velho Olho Turvo saiu da arrebentação e os expulsou aterrorizados. Eles voltaram e reacenderam a luz, mas o Velho Olho Turvo retornou e, desta vez, trouxe consigo os murlocs da costa num ataque ao farol. A família não sobreviveu. Grayson os viu morrer diante dele, sem poder impedir, e é o seu fantasma que mantém a luz agora, montando sentinela do lado de fora da torre, sem ninguém que venha rendê-lo.",
			source = "https://warcraft.wiki.gg/wiki/Westfall_Lighthouse",
		},
	},
	-- Pantanal: 23 subzones
	[1437] = {
		["angerfang encampment"] = {
			name = "Acampamento Presirada",
			short = "O Acampamento Presirada se espalha pelo centro do Pantanal, o maior acampamento que o clã Presa do Dragão mantém na região, lar dos orcs Presirada.",
			full = "O Acampamento Presirada se espalha pelo centro do Pantanal, o maior acampamento que o clã Presa do Dragão mantém na região, lar dos orcs Presirada.\n\nSob o comando de Nek'rosh Esmagacrânio, filho de Nekros Esmagacrânio, o acampamento se tornou uma base de preparação, reunindo catapultas destinadas a um ataque ao Porto de Menethil. A ameaça é real o bastante para que o Capitão Punhoforte tenha jurado ver Nek'rosh morto e os estandartes de guerra do clã derrubados antes que as catapultas avancem.",
			source = "https://warcraft.wiki.gg/wiki/Angerfang_Encampment",
		},
		["baradin bay"] = {
			name = "Baía de Baradin",
			short = "As águas da Baía de Baradin banham a costa onde Khaz Modan encontra Lordaeron, tocando as margens do Porto de Menethil e da Bastilha de Stromgarde.",
			full = "As águas da Baía de Baradin banham a costa onde Khaz Modan encontra Lordaeron, tocando as margens do Porto de Menethil e da Bastilha de Stromgarde. Murlocs e crocoliscos flutuam em seus baixios, enquanto tubarões e caranguejos dominam as águas mais fundas.\n\nA verdadeira história da baía jaz destroçada em seu fundo. Durante a Segunda Guerra, a armada de Kul Tiraz patrulhava estas águas, defendendo a costa contra a guerra que se espalhava pelos Reinos do Leste. Mas Kul Tiraz pagou caro por essa vigilância: a Terceira Frota da nação foi destruída nos combates. Alguns de seus destroços ainda jazem despedaçados ao longo da costa do Pantanal, visíveis nos baixios onde se partiram, enquanto outros afundaram por completo, assentando-se na escuridão lá embaixo, de onde ninguém os ergueu desde então.",
			source = "https://warcraft.wiki.gg/wiki/Baradin_Bay",
		},
		["black channel marsh"] = {
			name = "Pântano do Canal Negro",
			short = "A estrada para o Porto de Menethil contorna o Pântano do Canal Negro, no sudoeste do Pantanal.",
			full = "A estrada para o Porto de Menethil contorna o Pântano do Canal Negro, no sudoeste do Pantanal. Raptores se aninham por todo o brejo, e os mais famintos vagam perto da beira da estrada, por isso os viajantes que passam por este trecho fazem bem em ficar atentos.",
			source = "https://warcraft.wiki.gg/wiki/Black_Channel_Marsh",
		},
		["bluegill marsh"] = {
			name = "Pântano Peixeazul",
			short = "As águas do Pântano Peixeazul, no oeste do Pantanal, abrigam acampamentos de murlocs Peixeazul, que nunca andam sozinhos, mas em duplas e trios entre os juncos.",
			full = "As águas do Pântano Peixeazul, no oeste do Pantanal, abrigam acampamentos de murlocs Peixeazul, que nunca andam sozinhos, mas em duplas e trios entre os juncos. À frente deles está Gobbler, um murloc mais feroz que os demais, cuja presença faz do pântano um lugar onde é melhor entrar com cautela.",
			source = "https://warcraft.wiki.gg/wiki/Bluegill_Marsh",
		},
		["deepwater tavern"] = {
			name = "Taberna Aguafunda",
			short = "A Taberna Aguafunda fica no Porto de Menethil, com o salão cheio da conversa dos marinheiros de passagem.",
			full = "A Taberna Aguafunda fica no Porto de Menethil, com o salão cheio da conversa dos marinheiros de passagem. É um lugar bruto: cadeiras voam com a mesma frequência com que se serve cerveja, e as brigas muitas vezes começam por instigação de Tapoke Jahn, o Fino.",
			source = "https://warcraft.wiki.gg/wiki/Deepwater_Tavern",
		},
		["direforge hill"] = {
			name = "Monte Umbraforja",
			short = "O Monte Umbraforja um dia serviu de grande acampamento aos anões Ferro Negro, liderados pelo bruxo Balgaras, o Imundo.",
			full = "O Monte Umbraforja um dia serviu de grande acampamento aos anões Ferro Negro, liderados pelo bruxo Balgaras, o Imundo.",
			source = "https://warcraft.wiki.gg/wiki/Direforge_Hill",
		},
		["dragonmaw gates"] = {
			name = "Portões Presa do Dragão",
			short = "Os Portões Presa do Dragão são guardados pela revoada vermelha sob o comando do draco Axtroz, que defende o caminho contra os que buscam chegar a Grim Batol.",
			full = "Os Portões Presa do Dragão são guardados pela revoada vermelha sob o comando do draco Axtroz, que defende o caminho contra os que buscam chegar a Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmaw_Gates",
		},
		["dun algaz"] = {
			name = "Dun Algaz",
			short = "O túnel de Dun Algaz é mais antigo que a disputa que dividiu os anões. Quando a Guerra dos Três Martelos expulsou os Martelo Feroz de Altaforja, foi por esta passagem que eles bateram em retirada.",
			full = "O túnel de Dun Algaz é mais antigo que a disputa que dividiu os anões. Quando a Guerra dos Três Martelos expulsou os Martelo Feroz de Altaforja, foi por esta passagem que eles bateram em retirada.\n\nEle também serviu à retirada da Horda. Rechaçados de Dun Modr, os orcs recuaram para o sul pelo Vale Thandol e se entrincheiraram no posto avançado daqui, e Anduin Lothar, querendo expulsá-los de vez de Khaz Modan, enviou suas forças para derrubar a fortaleza. O ataque fracassou. Os orcs resistiram, e Dun Algaz se tornou o último território que a Horda manteve na região, um ponto de apoio que não se deixava arrancar.\n\nOs montanhistas anões que vigiavam esta passagem ficavam principalmente nas colinas acima dela, mas o clã Presa do Dragão tomou seu posto e os empurrou de volta para o túnel superior, onde ainda resistem. Com a passagem inferior perdida, a estrada entre as terras natais dos anões e o Porto de Menethil ficou muito mais perigosa.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Algaz",
		},
		["dun modr"] = {
			name = "Dun Modr",
			short = "Dun Modr fica ao sul da Ponte Thandol, uma antiga cidade anã há muito em ruínas, com sua ferraria e sua estalagem-cervejaria ainda de pé em meio aos destroços que os anões Ferro Negro agora reivindicam como seus.",
			full = "Dun Modr fica ao sul da Ponte Thandol, uma antiga cidade anã há muito em ruínas, com sua ferraria e sua estalagem-cervejaria ainda de pé em meio aos destroços que os anões Ferro Negro agora reivindicam como seus.\n\nDurante a Segunda Guerra, a Horda orc tomou as ruínas e construiu ali um posto avançado, usando-o para repelir as tropas da Aliança e saquear as terras de cultivo ao redor, uma base de preparação vital para seus exércitos. Guerreiros de Stromgarde partiram da cidadela insular de Tol Barad para derrubar esse posto, sitiando-o e empurrando os orcs para o sul, até seu reduto secundário em Dun Algaz. A Horda contra-atacou, retomou Dun Modr e voltou sua força até mesmo contra a própria Tol Barad. Só quando a Horda foi derrotada na Capital foi que Anduin Lothar a rechaçou pela Ponte Thandol até Khaz Modan, e Dun Modr passou para a Aliança.\n\nEssa paz não durou. Com os soldados de Altaforja esgotados em guerras travadas longe de casa, os anões Ferro Negro irromperam pela Ponte Thandol, e Dun Modr caiu pouco depois diante do bruxo Balgaras, o Imundo, que agora domina a cidade que seu povo reivindicou.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Modr",
		},
		["green belt"] = {
			name = "Zona Verde",
			short = "A Zona Verde está repleta de crocoliscos, monstros do brejo e gosmas, e Rethiel, o Guardião Verde, monta vigília aqui, irritado com uma terra que ficou estranha e inquieta.",
			full = "A Zona Verde está repleta de crocoliscos, monstros do brejo e gosmas, e Rethiel, o Guardião Verde, monta vigília aqui, irritado com uma terra que ficou estranha e inquieta.\n\nA oeste, as feras do lodo se tornaram malignas. A nordeste, elementais do fogo surgem inesperadamente do Monte Umbraforja. As duas são feridas na terra que Rethiel guarda, e nenhuma delas diminuiu.\n\nDentro da Zona fica uma caravana destroçada do clã Presa do Dragão, com dragonetes vermelhos agora entocados entre seus restos, tudo o que resta de uma tentativa de roubar filhotes da revoada negra que terminou aqui, engolida pelo pântano.",
			source = "https://warcraft.wiki.gg/wiki/Green_Belt",
		},
		["grim batol"] = {
			name = "Grim Batol",
			short = "Grim Batol é uma fortaleza nas montanhas do leste do Pantanal. Tem grandes muralhas e torres que se erguem para um céu cinza-chumbo, mas a maior parte da fortaleza fica debaixo da terra.",
			full = "Grim Batol é uma fortaleza nas montanhas do leste do Pantanal. Tem grandes muralhas e torres que se erguem para um céu cinza-chumbo, mas a maior parte da fortaleza fica debaixo da terra. Foi fundada pelos anões Martelo Feroz até ser amaldiçoada durante a Guerra dos Três Martelos. Mais tarde, foi tomada pelos orcs para servir de prisão ao Aspecto dragônico Alexstrasza, até que ela foi libertada durante a Batalha de Grim Batol.",
			source = "https://warcraft.wiki.gg/wiki/Grim_Batol",
		},
		["ironbeards tomb"] = {
			name = "Tumba dos Barbaférreos",
			short = "A Tumba dos Barbaférreos fica a oeste da estrada para Dun Modr, no centro-norte do Pantanal. Uma estátua anã se ergue sobre o cemitério daqui, presumivelmente esculpida à semelhança do próprio Barbaférrea.",
			full = "A Tumba dos Barbaférreos fica a oeste da estrada para Dun Modr, no centro-norte do Pantanal. Uma estátua anã se ergue sobre o cemitério daqui, presumivelmente esculpida à semelhança do próprio Barbaférrea.\n\nOs mortos já não descansam em paz ali. Gosmas negras, carmesins e de tons monstruosos se infiltraram na cripta e a profanaram, espalhando-se pelo cemitério até que ninguém que queira enterrar seus parentes se aproxima mais do lugar.",
			source = "https://warcraft.wiki.gg/wiki/Ironbeard's_Tomb",
		},
		["lost fleet"] = {
			name = "Frota Perdida",
			short = "Os destroços do Senhora das Ondas e do Intrépido jazem no leito da Baía de Baradin, ao largo da costa do norte do Pântano Peixeazul.",
			full = "Os destroços do Senhora das Ondas e do Intrépido jazem no leito da Baía de Baradin, ao largo da costa do norte do Pântano Peixeazul.\n\nEles faziam parte da Terceira Frota de Kul Tiraz, comandada por Derek Proudmore, filho mais velho do Lorde Almirante Daelin Proudmore, durante a Segunda Guerra. Na Batalha de Crestfall, dragões vermelhos escravizados pelo clã Presa do Dragão caíram do céu e incendiaram a frota. Derek subiu ao cesto da gávea para avisar o pai do perigo. Um dragão o matou ali antes que o aviso pudesse servir de algo, e seu navio afundou com o resto da frota pouco depois. Apenas um homem sobreviveu, o Primeiro Oficial Simonez, do Senhora das Ondas.\n\nOs mortos não ficaram quietos. No fundo do porão do Intrépido, seu comandante, o Capitão Halyndor, havia escondido por ganância um orbe enegrecido: o Olho Amaldiçoado de Paleth. Sua maldição alcançou a tripulação afundada anos depois, prendendo-a à morte-vida. Apenas o Primeiro Oficial Snellig manteve a mente durante tudo isso, e seu fantasma ainda caminha pela praia próxima.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Fleet",
		},
		["menethil bay"] = {
			name = "Baía de Menethil",
			short = "A Baía de Menethil fica entre o porto e os penhascos de Dun Morogh, encaixada na enseada da Baía de Baradin.",
			full = "A Baía de Menethil fica entre o porto e os penhascos de Dun Morogh, encaixada na enseada da Baía de Baradin.\n\nPerto da entrada da baía repousam os destroços do Águia-pescadora Voadora, com o casco partido assentado na água.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Bay",
		},
		["menethil harbor"] = {
			name = "Porto de Menethil",
			short = "A muralha é a primeira coisa que todos notam, pedra grossa erguida em torno de uma cidade portuária que fica metade sobre a rocha, metade sobre o mar.",
			full = "A muralha é a primeira coisa que todos notam, pedra grossa erguida em torno de uma cidade portuária que fica metade sobre a rocha, metade sobre o mar. Quatro torres se erguem acima dela, vigiando tanto a água quanto a estrada, e não há como entrar a não ser pela ponte, pela maré ou por uma passagem oculta que corre por baixo da terra até o continente.\n\nOs orcs ergueram aqui o primeiro estaleiro. Depois da Primeira Guerra, o Chefe Guerreiro Orgrim Martelo da Perdição escolheu esta costa para construir a frota que levaria a Horda além das defesas terrestres de Lordaeron, arrancando ferro e madeira das minas anãs de Khaz Modan para isso. Quando a Segunda Guerra terminou, a Aliança tomou o lugar e o reconstruiu como seu, e o Grão-almirante Daelin Proudmore deu-lhe o nome de Porto de Menethil em homenagem a Terenas Menethil II, Rei de Lordaeron.\n\nPor anos depois disso, raptores desciam das colinas para atacar a cidade, nunca em grande número, mas com bastante frequência.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Harbor",
		},
		["menethil keep"] = {
			name = "Bastilha Menethil",
			short = "Quatro torres se erguem acima do Porto de Menethil, vigiando a cidade lá embaixo como guardiões severos. Esta é a Bastilha Menethil.",
			full = "Quatro torres se erguem acima do Porto de Menethil, vigiando a cidade lá embaixo como guardiões severos. Esta é a Bastilha Menethil.",
			source = "https://warcraft.wiki.gg/wiki/Menethil_Keep",
		},
		["mosshide fen"] = {
			name = "Charco Pelemusgo",
			short = "O Charco Pelemusgo é um trecho encharcado do leste do Pantanal, com o chão pontilhado pelos acampamentos dos gnolls Pelemusgo. A tribo domina o charco, capturando e devorando qualquer um que se aventure longe demais no pântano.",
			full = "O Charco Pelemusgo é um trecho encharcado do leste do Pantanal, com o chão pontilhado pelos acampamentos dos gnolls Pelemusgo. A tribo domina o charco, capturando e devorando qualquer um que se aventure longe demais no pântano.",
			source = "https://warcraft.wiki.gg/wiki/Mosshide_Fen",
		},
		["raptor ridge"] = {
			name = "Serra dos Raptores",
			short = "A Serra dos Raptores se ergue no leste do Pantanal, a noroeste dos Portões Presa do Dragão, com encostas e caverna repletas de raptores. Lá no fundo, a Matriarca Rasgaqueixo choca sua ninhada.",
			full = "A Serra dos Raptores se ergue no leste do Pantanal, a noroeste dos Portões Presa do Dragão, com encostas e caverna repletas de raptores. Lá no fundo, a Matriarca Rasgaqueixo choca sua ninhada.",
			source = "https://warcraft.wiki.gg/wiki/Raptor_Ridge",
		},
		["saltspray glen"] = {
			name = "Vale Espuma de Sal",
			short = "O Vale Espuma de Sal fica onde o Pantanal encontra a Baía de Baradin, entre o Pântano Peixeazul e a Tumba dos Barbaférreos.",
			full = "O Vale Espuma de Sal fica onde o Pantanal encontra a Baía de Baradin, entre o Pântano Peixeazul e a Tumba dos Barbaférreos. Seu nome vem do vento: quando sopra forte da baía, o oceano lança sua espuma terra adentro aqui, mais longe do que em qualquer outro ponto desta costa, até deixar o próprio chão escorregadio de sal. Raptores se aninham em grande número por todo o vale, como fazem em todo o pântano e na serra próxima.",
			source = "https://warcraft.wiki.gg/wiki/Saltspray_Glen",
		},
		["sundown marsh"] = {
			name = "Pântano do Ocaso",
			short = "No fundo do noroeste do Pantanal fica o Pântano do Ocaso, repleto de crocoliscos, gnolls, raptores, monstros do brejo e gosmas que mantêm a maioria dos viajantes afastada.",
			full = "No fundo do noroeste do Pantanal fica o Pântano do Ocaso, repleto de crocoliscos, gnolls, raptores, monstros do brejo e gosmas que mantêm a maioria dos viajantes afastada. Em seu coração fica a Estação Ligeira, uma pequena casa de pedra com um moinho de vento, onde Fradd Swiftgear e Wenna Silkbeard fizeram seu lar. A dupla negocia o que o pântano rende, itens estranhos tirados da lama e receitas raramente encontradas em outros lugares.",
			source = "https://warcraft.wiki.gg/wiki/Sundown_Marsh",
		},
		["thandol span"] = {
			name = "Ponte Thandol",
			short = "Dois grandes arcos de pedra atravessam o vão entre o Pantanal e o Planalto Arathi, erguidos por mãos anãs e guardados por três gerações pela linhagem Sidermar.",
			full = "Dois grandes arcos de pedra atravessam o vão entre o Pantanal e o Planalto Arathi, erguidos por mãos anãs e guardados por três gerações pela linhagem Sidermar. Foram construídos depois da Guerra dos Três Martelos, quando Altaforja buscou manter a boa-fé com seus parentes Martelo Feroz do Ninho da Águia, e as pontes se tornaram ao mesmo tempo estrada e símbolo entre os dois reinos anões, levando um comércio que enriquecia a ambos.\n\nAs pontes agora estão marcadas por cicatrizes. Kam Deepfury e Balgaras, o Imundo, lideraram os anões Ferro Negro contra a Ponte, derrubando por completo um dos dois arcos e quase tomando o segundo. As forças anãs lutaram ferozmente para defender o que restava e retomar a cidade vizinha de Dun Modr, e muitos morreram nesses combates, entre eles Sully Balloo, Ebenezer Rustlocke e o irmão de Trançalonga, o Austero. Os Ferro Negro ainda ocupam os destroços, e Balgaras, o Imundo, ainda vive entre eles.",
			source = "https://warcraft.wiki.gg/wiki/Thandol_Span",
		},
		["thelgen rock"] = {
			name = "Rocha de Thelgen",
			short = "A Rocha de Thelgen se ergue no sul do Pantanal, com cavernas que penetram fundo na montanha, repletas de aranhas venenosas tecendo seda em cada fenda.",
			full = "A Rocha de Thelgen se ergue no sul do Pantanal, com cavernas que penetram fundo na montanha, repletas de aranhas venenosas tecendo seda em cada fenda. Em algum ponto dos túneis mais profundos há veios de minério de incendicita, guardados pelo grande número de aranhas.",
			source = "https://warcraft.wiki.gg/wiki/Thelgen_Rock",
		},
		["whelgars excavation site"] = {
			name = "Sítio de Escavação de Whelgar",
			short = "O sítio de escavação a leste do Porto de Menethil já foi um trabalho tranquilo para anões que cavavam uma terra mais antiga que a memória. Então raptores malhados o invadiram, encurralando os escavadores numa crista acima de sua própria escavação.",
			full = "O sítio de escavação a leste do Porto de Menethil já foi um trabalho tranquilo para anões que cavavam uma terra mais antiga que a memória. Então raptores malhados o invadiram, encurralando os escavadores numa crista acima de sua própria escavação. Eles não resistiram e abandonaram o sítio por um acampamento feito por eles mesmos, fora da estrada principal, o Refúgio de Whelgar.\n\nO que deixaram para trás ainda jaz meio desenterrado. Fósseis vivos e antigos elementais percorrem as cavas agora, sem se incomodar com as picaretas deixadas enferrujando ali.",
			source = "https://warcraft.wiki.gg/wiki/Whelgar's_Excavation_Site",
		},
	},
	-- Teldrassil: 17 subzones
	[1438] = {
		["aldrassil"] = {
			name = "Aldrassil",
			short = "Aldrassil se ergue no coração de Umbravale, uma árvore que cresceu tanto que abriga uma aldeia entre seus galhos.",
			full = "Aldrassil se ergue no coração de Umbravale, uma árvore que cresceu tanto que abriga uma aldeia entre seus galhos. Bem no topo, acima do alcance do povoado lá embaixo, Tenaron Fortagarras fez seu lar, vigiando o vale da copa da grande árvore.",
			source = "https://warcraft.wiki.gg/wiki/Aldrassil",
		},
		["banethil barrow den"] = {
			name = "Gruta de Ban'ethil",
			short = "A Gruta de Ban'ethil foi erguida pelos elfos noturnos como um túmulo sagrado para abrigar em repouso tranquilo seus Druidas da Garra adormecidos.",
			full = "A Gruta de Ban'ethil foi erguida pelos elfos noturnos como um túmulo sagrado para abrigar em repouso tranquilo seus Druidas da Garra adormecidos.\n\nEssa paz agora está rompida. Os furbolgs Masca-pinho corrompidos tomaram suas galerias Inferior e Superior, e o que antes era solo consagrado não é lugar para um elfo noturno vagar sozinho.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Barrow_Den",
		},
		["banethil hollow"] = {
			name = "Ravina de Ban'ethil",
			short = "Uma ravina corta a terra ao sul da estrada entre Dolanaar e Darnassus, com encostas dominadas por furbolgs hostis que emboscam os viajantes que se aproximam demais.",
			full = "Uma ravina corta a terra ao sul da estrada entre Dolanaar e Darnassus, com encostas dominadas por furbolgs hostis que emboscam os viajantes que se aproximam demais. No fundo da ravina fica a Gruta de Ban'ethil, afundada na terra. É preciso cautela na estrada lá em cima.",
			source = "https://warcraft.wiki.gg/wiki/Ban'ethil_Hollow",
		},
		["cleft"] = {
			name = "A Fenda",
			short = "A Fenda fica a noroeste de Dolanaar, um covil de furbolgs Masca-pinho corrompidos liderados por Ursal, o Espancador. Eles emboscam os viajantes na estrada para Darnassus e mantêm um grupo de druidas adormecidos cativos lá dentro.",
			full = "A Fenda fica a noroeste de Dolanaar, um covil de furbolgs Masca-pinho corrompidos liderados por Ursal, o Espancador. Eles emboscam os viajantes na estrada para Darnassus e mantêm um grupo de druidas adormecidos cativos lá dentro. A Sacerdotisa da Lua Amara e seus guarda-costas vigiam a estrada perto da entrada.",
			source = "https://warcraft.wiki.gg/wiki/Cleft",
		},
		["dolanaar"] = {
			name = "Dolanaar",
			short = "Dolanaar fica no centro-leste de Teldrassil, a sudoeste de Umbravale, com suas raízes e pontes de corda entrelaçadas na própria grande árvore.",
			full = "Dolanaar fica no centro-leste de Teldrassil, a sudoeste de Umbravale, com suas raízes e pontes de corda entrelaçadas na própria grande árvore. Sua posição central nos caminhos da ilha fez dela há muito tempo um ponto de passagem, uma aldeia que sentia o pulso de tudo o que acontecia ao seu redor.",
			source = "https://warcraft.wiki.gg/wiki/Dolanaar",
		},
		["fel rock"] = {
			name = "Pedra Vil",
			short = "Ao norte de Dolanaar fica uma caverna antes bela, agora corrompida. Grells infestam suas cavidades escuras, e lá dentro habita o sátiro Lorde Melenas, cuja presença envenenou o lugar.",
			full = "Ao norte de Dolanaar fica uma caverna antes bela, agora corrompida. Grells infestam suas cavidades escuras, e lá dentro habita o sátiro Lorde Melenas, cuja presença envenenou o lugar. O druida elfo noturno Tallonkai Radicélere observa essa corrupção com pavor, pois o que antes era um belo lugar agora é sinistro.",
			source = "https://warcraft.wiki.gg/wiki/Fel_Rock",
		},
		["gnarlpine hold"] = {
			name = "Acampamento Masca-pinho",
			short = "No extremo sudoeste de Teldrassil fica o Acampamento Masca-pinho, lar dos furbolgs Masca-pinho.",
			full = "No extremo sudoeste de Teldrassil fica o Acampamento Masca-pinho, lar dos furbolgs Masca-pinho.",
			source = "https://warcraft.wiki.gg/wiki/Gnarlpine_Hold",
		},
		["lake alameth"] = {
			name = "Lago Al'Ameth",
			short = "O Lago Al'Ameth se estende amplo ao sul de Dolanaar, uma das grandes águas de Teldrassil. Pouco marca suas margens além de um pequeno píer.",
			full = "O Lago Al'Ameth se estende amplo ao sul de Dolanaar, uma das grandes águas de Teldrassil. Pouco marca suas margens além de um pequeno píer.\n\nUltimamente, sua calma azedou: muscoides enfurecidos assombram a margem, e já não é seguro caminhar sozinho pelo lago.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Al'Ameth",
		},
		["oracle glade"] = {
			name = "Clareira do Oráculo",
			short = "A Clareira do Oráculo fica no noroeste de Teldrassil e abriga o primeiro e mais poderoso dos poços lunares da grande árvore.",
			full = "A Clareira do Oráculo fica no noroeste de Teldrassil e abriga o primeiro e mais poderoso dos poços lunares da grande árvore. Aqui fica a Árvore do Oráculo, com o tronco largo se erguendo em galhos que têm a forma de uma águia empoleirada sobre um urso. Muitos sussurram que nenhum crescimento comum poderia assumir tal forma e que só a magia da natureza a moldou.\n\nA árvore tem acompanhado o crescimento de Teldrassil ao lado dos druidas.\n\nHarpias Plumassangue fizeram ninhos nas proximidades, ameaçando a árvore, e uma pequena companhia de Sentinelas foi enviada para contê-las.",
			source = "https://warcraft.wiki.gg/wiki/Oracle_Glade",
		},
		["pools of arlithrien"] = {
			name = "Águas de Arlithrien",
			short = "Ao sul de Darnassus, no oeste de Teldrassil, as Águas de Arlithrien já foram pacíficas. Um poço lunar ali foi abandonado pelos elfos noturnos quando os furbolgs Masca-pinho tomaram a área.",
			full = "Ao sul de Darnassus, no oeste de Teldrassil, as Águas de Arlithrien já foram pacíficas. Um poço lunar ali foi abandonado pelos elfos noturnos quando os furbolgs Masca-pinho tomaram a área. O poço ainda está de pé, sem cuidados, entre as águas, agora lar de animais hostis.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Arlithrien",
		},
		["ruttheran village"] = {
			name = "Vila de Rut'theran",
			short = "A Vila de Rut'theran fica nas raízes de Teldrassil, onde a Árvore do Mundo encontra a água, sob Darnassus, lá no alto.",
			full = "A Vila de Rut'theran fica nas raízes de Teldrassil, onde a Árvore do Mundo encontra a água, sob Darnassus, lá no alto. Suas construções são modestas perto das da capital, mas extremamente bem cuidadas, como se o orgulho estivesse na simplicidade e não no tamanho.\n\nAqui os kaldorei cuidam do poleiro de hipogrifos, recolhendo e cuidando dos ovos e criando os filhotes até que possam voar. É um trabalho silencioso, feito por gente que, fora isso, trabalha para manter a vila funcionando a serviço da cidade lá em cima, sem pedir muito reconhecimento por isso.\n\nMas a vila não é só trabalho. Quando chega o Festival do Fogo do Solstício, seus braseiros são acesos, e as mesmas mãos que cuidam dos ovos de hipogrifo e carregam os barcos se voltam para a celebração.",
			source = "https://warcraft.wiki.gg/wiki/Rut'theran_Village",
		},
		["shadowglen"] = {
			name = "Umbravale",
			short = "Sob os galhos de Teldrassil, escondida no nordeste da ilha, fica uma clareira que nunca vê de todo a luz do dia. Umbravale mantém um crepúsculo perpétuo ao seu redor, cercada de montanhas por todos os lados, menos um.",
			full = "Sob os galhos de Teldrassil, escondida no nordeste da ilha, fica uma clareira que nunca vê de todo a luz do dia. Umbravale mantém um crepúsculo perpétuo ao seu redor, cercada de montanhas por todos os lados, menos um. Só ao sul a pedra se abre, deixando uma trilha escapar rumo a Dolanaar.\n\nNo coração da clareira fica Aldrassil, uma grande árvore cuja presença domina a clareira por completo, como se todo o vale estivesse disposto ao seu redor. A noroeste, o chão se abre na Caverna Fionumbra, uma fenda escura aberta nas colinas que cercam a clareira.",
			source = "https://warcraft.wiki.gg/wiki/Shadowglen",
		},
		["shadowthread cave"] = {
			name = "Caverna Fionumbra",
			short = "A Caverna Fionumbra fica no canto noroeste de Umbravale, nas raízes de Teldrassil. Sempre pertenceu às grandes aranhas da ilha, mas ultimamente elas ficaram inquietas e a caverna, mais perigosa.",
			full = "A Caverna Fionumbra fica no canto noroeste de Umbravale, nas raízes de Teldrassil. Sempre pertenceu às grandes aranhas da ilha, mas ultimamente elas ficaram inquietas e a caverna, mais perigosa.\n\nNo ponto mais profundo vive Githyiss, a Vil, a maior da ninhada, a ruína de mais de um jovem kaldorei que se aventurou longe demais lá dentro.",
			source = "https://warcraft.wiki.gg/wiki/Shadowthread_Cave",
		},
		["starbreeze village"] = {
			name = "Vilarejo Brisastral",
			short = "O Vilarejo Brisastral um dia pertenceu aos elfos noturnos, um aglomerado de casinhas a sudeste de Umbravale. Agora está vazio deles, com as casas tomadas pelos furbolgs Masca-pinho corrompidos.",
			full = "O Vilarejo Brisastral um dia pertenceu aos elfos noturnos, um aglomerado de casinhas a sudeste de Umbravale. Agora está vazio deles, com as casas tomadas pelos furbolgs Masca-pinho corrompidos. Uruson anda por suas trilhas e, em suas bordas, espreita Ferócitas, o Comedor de Sonhos, uma fera cuja presença por si só mostra o quanto o vilarejo decaiu do que um dia foi.",
			source = "https://warcraft.wiki.gg/wiki/Starbreeze_Village",
		},
		["wellspring lake"] = {
			name = "Lago Olho-d'Água",
			short = "O Lago Olho-d'Água tira sua água de uma nascente no fundo da própria Teldrassil, e seu excesso escoa como Rio Olho-d'Água. Os pescadores elfos noturnos um dia preferiam estas águas tranquilas.",
			full = "O Lago Olho-d'Água tira sua água de uma nascente no fundo da própria Teldrassil, e seu excesso escoa como Rio Olho-d'Água. Os pescadores elfos noturnos um dia preferiam estas águas tranquilas. Agora os muscoides que vivem aqui foram corrompidos, e sabres-noturnos e aranhas se infiltraram nas terras ao redor, fazendo do que antes era um tranquilo local de pesca um lugar de perigo.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_Lake",
		},
		["wellspring river"] = {
			name = "Rio Olho-d'Água",
			short = "O Rio Olho-d'Água nasce de uma fonte no fundo de Teldrassil e corre do Lago Olho-d'Água para o norte até a borda da árvore, onde despenca numa grande cachoeira até o mar lá embaixo.",
			full = "O Rio Olho-d'Água nasce de uma fonte no fundo de Teldrassil e corre do Lago Olho-d'Água para o norte até a borda da árvore, onde despenca numa grande cachoeira até o mar lá embaixo.\n\nMuscoides enlouquecidos agora rondam suas margens, atacando qualquer um que se aproxime.",
			source = "https://warcraft.wiki.gg/wiki/Wellspring_River",
		},
	},
	-- Costa Negra: 15 subzones
	[1439] = {
		["ametharan"] = {
			name = "Ameth'Aran",
			short = "As ruínas de Ameth'Aran ficam a sudeste de Auberdine, na Costa Negra, e algo da cidade ainda caminha por ali.",
			full = "As ruínas de Ameth'Aran ficam a sudeste de Auberdine, na Costa Negra, e algo da cidade ainda caminha por ali.\n\nA Rainha Azshara um dia ergueu Ameth'Aran como gêmea de Bashal'Aran, instalando seus Bem-nascidos favoritos em seus bazares e em seus templos a Eluna. Acima dela pôs Athrikus Narassin, um mago de grande poder que vivia recluso em sua Torre de Althalaxx.\n\nQuando a Cisão veio e a cidade já desmoronava, seu povo se agarrou ao chão como se só isso pudesse salvá-lo. Athrikus Narassin apareceu entre eles e prometeu um feitiço que os pouparia da destruição que se aproximava, concedendo-lhes a vida eterna dentro das gemas de alma que carregava. Enquanto ele o pronunciava, os elfos ao seu redor morreram. A eternidade que lhes deu foi uma prisão, não um resgate, e são seus espíritos, não suas vidas, que permanecem em Ameth'Aran desde então.\n\nDuas grandes tábuas de pedra ainda estão de pé entre as ruínas, gravadas com a história da queda da cidade. Uma sentinela que veio lê-las foi atacada pelos Bem-nascidos inquietos antes de terminar e fugiu.",
			source = "https://warcraft.wiki.gg/wiki/Ameth'Aran",
		},
		["auberdine"] = {
			name = "Auberdine",
			short = "Auberdine fica onde a Cisão partiu a terra, num litoral que engoliu as grandes cidades do antigo Império Kaldorei. Todas as tentativas de povoamento na Costa Negra desde então fracassaram, exceto esta única cidade às margens do Mar Velado.",
			full = "Auberdine fica onde a Cisão partiu a terra, num litoral que engoliu as grandes cidades do antigo Império Kaldorei. Todas as tentativas de povoamento na Costa Negra desde então fracassaram, exceto esta única cidade às margens do Mar Velado.\n\nEla cresceu diferente do resto da sociedade dos elfos noturnos. Seu porto atrai navios e comerciantes dos Reinos do Leste, e suas ruas estão cheias de anões, gnomos, humanos e até altos elfos, de modo que Auberdine é mais iluminada do que uma cidade dos elfos noturnos teria motivo para ser, com placas escritas em duas línguas para os forasteiros. Darnassus a olha com desdém por isso. Broll Bearmantle, que visitou a cidade certa vez, considera seu povo pouco melhor que proscritos e desajustados, e as Sentinelas aquarteladas aqui se mantêm afastadas das pessoas que protegem. Ainda assim, Shandris Plumaluna, que já esteve destacada aqui, lembra-se dela como um lugar onde ecoavam risadas.\n\nPerto do farol, os destroços de um navio um dia comandado pela elfa Elura ainda marcam as rochas, com sua carga de minério de elunita perdida quando afundou.",
			source = "https://warcraft.wiki.gg/wiki/Auberdine",
		},
		["bashalaran"] = {
			name = "Bashal'Aran",
			short = "Antes que o mar subisse sobre o mundo e o partisse, a Rainha Azshara ergueu cidades gêmeas no norte da Costa Negra para seus Bem-nascidos favoritos: Ameth'Aran e Bashal'Aran.",
			full = "Antes que o mar subisse sobre o mundo e o partisse, a Rainha Azshara ergueu cidades gêmeas no norte da Costa Negra para seus Bem-nascidos favoritos: Ameth'Aran e Bashal'Aran. Ela pôs Athrikus Narassin, um elfo de grande poder mágico, para governá-las e, abaixo dele, servia Astérion, um mago tão hábil nas artes arcanas quanto nas armas, que vivia entre o povo de Bashal'Aran e viajava com frequência a Ameth'Aran para cuidar de sua gente. Naqueles dias, as cidades gêmeas tinham bazares e templos a Eluna, agraciados com o favor da própria rainha.\n\nQuando o primeiro Poço da Eternidade foi destruído, as duas cidades caíram em ruínas. Mas, em algum momento, Athrikus Narassin voltou sua arte contra seu próprio braço direito, prendendo Astérion num selo de pedra da lua e aprisionando-o entre as pedras de Bashal'Aran. Por que o mestre se voltou contra seu servo, ninguém vivo hoje sabe dizer. Astérion suportou a prisão durante uma vida longa e dolorosa e, quando enfim morreu, descobriu que a morte não o havia libertado. Seu espírito continuou preso tão firmemente quanto sua carne estivera.",
			source = "https://warcraft.wiki.gg/wiki/Bashal'Aran",
		},
		["blackwood den"] = {
			name = "Antro dos Bosqueneros",
			short = "No extremo sul da Costa Negra, perto da fronteira com o Vale Gris, um punhado de acampamentos de furbolgs e uma pequena caverna formam o lugar chamado Antro dos Bosqueneros, às vezes chamado de Forte dos Bosqueneros.",
			full = "No extremo sul da Costa Negra, perto da fronteira com o Vale Gris, um punhado de acampamentos de furbolgs e uma pequena caverna formam o lugar chamado Antro dos Bosqueneros, às vezes chamado de Forte dos Bosqueneros. Os furbolgs que o ocupam estão corrompidos, distorcidos em relação ao que um dia foram.\n\nDentro da caverna fica um elfo noturno solitário chamado Volcor, mantido cativo entre os furbolgs.",
			source = "https://warcraft.wiki.gg/wiki/Blackwood_Den",
		},
		["cliffspring falls"] = {
			name = "Quedas de Fontescarpa",
			short = "As Quedas de Fontescarpa são a nascente do Rio Fontescarpa, que um dia foi sua água mais pura e a fonte de água potável de toda a Costa Negra. Essa água já não é limpa.",
			full = "As Quedas de Fontescarpa são a nascente do Rio Fontescarpa, que um dia foi sua água mais pura e a fonte de água potável de toda a Costa Negra. Essa água já não é limpa. A caverna de onde brotam as quedas se tornou imunda, e a corrupção se espalha com a correnteza pela região que antes ela sustentava.\n\nNinguém concorda sobre o motivo. Alguns culpam a Selva Maleva, dizendo que a mácula simplesmente vaza daquela floresta arruinada. Outros apontam para o que foi encontrado no fundo da própria caverna, onde nagas agora rastejam pela escuridão junto à nascente.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_Falls",
		},
		["cliffspring river"] = {
			name = "Rio Fontescarpa",
			short = "O Rio Fontescarpa corre das Quedas de Fontescarpa até o mar, no norte da Costa Negra. Suas águas estão contaminadas pelos nagas Escamatroz, e os animais que bebem dele muitas vezes adoecem.",
			full = "O Rio Fontescarpa corre das Quedas de Fontescarpa até o mar, no norte da Costa Negra. Suas águas estão contaminadas pelos nagas Escamatroz, e os animais que bebem dele muitas vezes adoecem.",
			source = "https://warcraft.wiki.gg/wiki/Cliffspring_River",
		},
		["grove of the ancients"] = {
			name = "Bosque dos Ancientes",
			short = "O Bosque dos Ancientes é um antigo templo dos elfos noturnos, com as pedras assentadas ao redor do caudaloso Rio Crenado, nas montanhas da Costa Negra.",
			full = "O Bosque dos Ancientes é um antigo templo dos elfos noturnos, com as pedras assentadas ao redor do caudaloso Rio Crenado, nas montanhas da Costa Negra. Aqui vive Onu, um Ancião do Saber, com um druida adormecido e um par de mercadores, e aqui o Círculo dos Anciãos ainda se reúne.",
			source = "https://warcraft.wiki.gg/wiki/Grove_of_the_Ancients",
		},
		["long wash"] = {
			name = "Praia da Ressaca",
			short = "A Praia da Ressaca se estende ao sul de Auberdine até as águas a oeste de Ameth'Aran, o trecho de costa mais curto da Costa Negra, apesar do nome.",
			full = "A Praia da Ressaca se estende ao sul de Auberdine até as águas a oeste de Ameth'Aran, o trecho de costa mais curto da Costa Negra, apesar do nome. Areia cinzenta se estende sob um céu permanentemente encoberto. A maré deixa pouco além de madeira à deriva e carcaças de criaturas marinhas mortas. Murlocs são vistos ao longo da praia.",
			source = "https://warcraft.wiki.gg/wiki/Long_Wash",
		},
		["masters glaive"] = {
			name = "Glaive do Mestre",
			short = "No sudoeste da Costa Negra jaz um crânio colossal, meio engolido pela terra, com uma glaive de adamantita ainda cravada no osso.",
			full = "No sudoeste da Costa Negra jaz um crânio colossal, meio engolido pela terra, com uma glaive de adamantita ainda cravada no osso. Este era Soggoth, o Rastejante, um arauto dos Deuses Antigos, e a lâmina se chama Glaive do Mestre.\n\nTábuas desenterradas na Escavação de Trilheiro contaram o que aconteceu aqui. Os titãs haviam enviado vinte gigantes de pedra contra Soggoth, e a batalha que se seguiu foi tão terrível que apenas um deles viveu para ver seu fim: Kronn, o maior dos vinte. Quando os tentáculos de Soggoth se fecharam ao seu redor, Kronn não lutou para se soltar. Deixou-se arrastar para dentro, cada vez mais perto do crânio da criatura, até ficar perto o bastante para golpear. O golpe que matou Soggoth foi desferido de dentro de suas próprias garras, e a espada deixada cravada em seu crânio recebeu o nome daquela vitória.\n\nO Martelo do Crepúsculo tomou o local desde então, escavando os restos de Soggoth, trabalhando para desfazer o que a espada de Kronn realizou e trazer de volta ao mundo o arauto do Deus Antigo.",
			source = "https://warcraft.wiki.gg/wiki/Master's_Glaive",
		},
		["mists edge"] = {
			name = "Beira das Névoas",
			short = "O litoral chamado Beira das Névoas percorre toda a extensão da Costa Negra, a faixa de costa mais longa da região.",
			full = "O litoral chamado Beira das Névoas percorre toda a extensão da Costa Negra, a faixa de costa mais longa da região.\n\nÉ um trecho sombrio: praias cinzentas e baías lúgubres, cheias das enormes carcaças de animais marinhos mortos e dos destroços de navios afundados.\n\nCaranguejos correm por toda a sua extensão, e murlocs espreitam nas baías rasas, uma ameaça sempre presente para quem caminha pela praia.",
			source = "https://warcraft.wiki.gg/wiki/Mist's_Edge",
		},
		["remtravels excavation"] = {
			name = "Escavação de Trilheiro",
			short = "O Prospector Trilheiro deu seu nome a este sítio de escavação na Costa Negra.",
			full = "O Prospector Trilheiro deu seu nome a este sítio de escavação na Costa Negra. Em suas escavações, ele encontrou um fóssil diferente de qualquer outro, vibrando com propriedades místicas, mas o distraído prospector perdeu a noção de onde o guardou.\n\nA própria escavação se tornou perigosa: troggs Cascalho tomaram seus túneis, e golens enormes, desenterrados pela escavação, agora se agitam lá dentro.",
			source = "https://warcraft.wiki.gg/wiki/Remtravel's_Excavation",
		},
		["ruins of mathystra"] = {
			name = "Ruínas de Mathistra",
			short = "Depois da Torre de Althalaxx, no norte da Costa Negra, ficam as ruínas de Mathistra. Antes da Grande Cisão, ela era uma cidade dos elfos noturnos, erguida na era dos Bem-nascidos.",
			full = "Depois da Torre de Althalaxx, no norte da Costa Negra, ficam as ruínas de Mathistra. Antes da Grande Cisão, ela era uma cidade dos elfos noturnos, erguida na era dos Bem-nascidos. Quando o Poço da Eternidade se despedaçou e o mundo se partiu sob ele, Mathistra foi arruinada junto com tanta coisa, e os elfos noturnos que sobreviveram não voltaram para reconstruí-la. Em vez disso, retiraram-se para aldeias menores ao longo da costa, mais ao sul, deixando as ruínas para trás.\n\nRelíquias espalhadas dos antigos Bem-nascidos ainda jazem entre as pedras caídas, e jovens elfos noturnos às vezes vêm procurá-las em Mathistra, cautelosos com os sabres-fantasma que rondam ali, entre as ruínas do que seu povo um dia construiu.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Mathystra",
		},
		["tower of althalaxx"] = {
			name = "Torre de Althalaxx",
			short = "Na era da Grande Cisão, quando a Rainha Azshara elevou os Bem-nascidos acima de todos os outros, ela pôs um elfo chamado Athrikus Narassin para governar as cidades gêmeas de Ameth'Aran e Bashal'Aran.",
			full = "Na era da Grande Cisão, quando a Rainha Azshara elevou os Bem-nascidos acima de todos os outros, ela pôs um elfo chamado Athrikus Narassin para governar as cidades gêmeas de Ameth'Aran e Bashal'Aran. Athrikus a serviu bem o bastante no início, mas o trabalho o entediava, e ele passou a gastar seus dias longe das cidades, numa torre própria chamada Althalaxx.\n\nDez mil anos depois, o que há muito se sussurrava sobre aquela torre se provou verdadeiro. Um culto que se chamava Culto da Trama Sombria havia se reunido ali, com bruxos e um sátiro entre eles, e à sua frente estava o próprio Athrikus Narassin. Seu propósito não era claro até se descobrir que o culto respondia ao Conselho das Sombras e que Althalaxx havia se tornado mais um fio na teia daquela antiga conspiração.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Althalaxx",
		},
		["twilight vale"] = {
			name = "Vale do Crepúsculo",
			short = "As florestas ao sul de Ameth'Aran, que se estendem até a fronteira com o Vale Gris, são chamadas de Vale do Crepúsculo.",
			full = "As florestas ao sul de Ameth'Aran, que se estendem até a fronteira com o Vale Gris, são chamadas de Vale do Crepúsculo. Furbolgs corrompidos, sabres-noturnos selvagens e ursos raivosos assombram estas matas, e aconselha-se aos viajantes que fiquem nas estradas em vez de vagar sob as árvores.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Vale",
		},
		["wildbend river"] = {
			name = "Rio Crenado",
			short = "O Rio Crenado traz sua doença das montanhas, uma continuação do Rio Peçonha que sai da Selva Maleva e entra no sul da Costa Negra, perto do Bosque dos Ancientes.",
			full = "O Rio Crenado traz sua doença das montanhas, uma continuação do Rio Peçonha que sai da Selva Maleva e entra no sul da Costa Negra, perto do Bosque dos Ancientes. Suas águas correm contaminadas, com a corrupção da Selva Maleva seguindo a correnteza até estas terras mais baixas.",
			source = "https://warcraft.wiki.gg/wiki/Wildbend_River",
		},
	},
	-- Vale Gris: 41 subzones
	[1440] = {
		["astranaar"] = {
			name = "Astranaar",
			short = "Astranaar se ergue de uma ilha no coração do Vale Gris, o maior dos povoados dos elfos noturnos da região, acessível apenas por um par de pontes que levam a estrada sobre a água.",
			full = "Astranaar se ergue de uma ilha no coração do Vale Gris, o maior dos povoados dos elfos noturnos da região, acessível apenas por um par de pontes que levam a estrada sobre a água. O lago a separa da floresta ao redor, um lugar tranquilo e defensável no centro de uma terra disputada.\n\nSeu cemitério fica junto à margem, guardando os mortos da cidade entre as fileiras silenciosas de pedra.\n\nAlém da cidade, os furbolgs Pelocardo ganharam força no norte, e há o medo em Astranaar de que um dia eles encontrem coragem para voltar sua força contra a própria cidade.",
			source = "https://warcraft.wiki.gg/wiki/Astranaar",
		},
		["bathrans haunt"] = {
			name = "Refúgio de Bathran",
			short = "Os pilares do Refúgio de Bathran um dia fizeram parte de uma ruína kaldorei, erguida numa era em que os elfos noturnos ainda percorriam esta parte do Vale Gris.",
			full = "Os pilares do Refúgio de Bathran um dia fizeram parte de uma ruína kaldorei, erguida numa era em que os elfos noturnos ainda percorriam esta parte do Vale Gris. Essa era passou, os elfos se retiraram, e o mármore foi deixado para rachar e cair.\n\nAgora não está vazio. Agentes Renegados se instalaram entre as colunas quebradas, herboristas e os capangas que os protegem, e onde quer que se instalem a terra responde à altura: o capim ficou marrom, as flores murcharam. Entre as pedras caídas eles ergueram um laboratório improvisado, trabalhando as ervas locais para fins próprios.\n\nO que mais os atrai para cá é uma planta que não se encontra em nenhum outro lugar próximo: o Cabelo de Bathran, uma erva medicinal rara o bastante para justificar, sozinha, a ocupação do local.",
			source = "https://warcraft.wiki.gg/wiki/Bathran's_Haunt",
		},
		["blackfathom deeps"] = {
			name = "Profundezas Negras",
			short = "Sob a Praia de Zoram, onde a antiga cidade de Zoram afundou no mar, ficam os salões submersos de Lathar'Lazal, um dia um templo a Eluna.",
			full = "Sob a Praia de Zoram, onde a antiga cidade de Zoram afundou no mar, ficam os salões submersos de Lathar'Lazal, um dia um templo a Eluna. Pensava-se que a Cisão o havia destruído por completo, e por milênios o oceano o guardou.\n\nEntão veio o Martelo do Crepúsculo, atraído por sussurros e sonhos imundos para as cavernas aquáticas em que o templo se transformara. O culto sacrificou incontáveis inocentes naquelas profundezas e foi recompensado com uma missão: nutrir e proteger uma criatura estimada dos Deuses Antigos, a monstruosa hidra Aku'mai, a Devoradora, até o dia em que ela for libertada sobre o mundo. O lugar agora se chama Profundezas Negras, e o nome lhe cai bem.",
			source = "https://warcraft.wiki.gg/wiki/Blackfathom_Deeps",
		},
		["bloodtooth camp"] = {
			name = "Aldeia Dente Sangrento",
			short = "A Aldeia Dente Sangrento fica a oeste do Rio Felfarren, a sudoeste do poço lunar do sul do Vale Gris. Leva o nome de Ran Dente Sangrento, chefe da tribo de furbolgs que a ocupa.",
			full = "A Aldeia Dente Sangrento fica a oeste do Rio Felfarren, a sudoeste do poço lunar do sul do Vale Gris. Leva o nome de Ran Dente Sangrento, chefe da tribo de furbolgs que a ocupa.\n\nEsses furbolgs um dia foram como quaisquer outros de sua espécie, mas a corrupção tomou cada um deles, e agora a aldeia responde com hostilidade a qualquer forasteiro que se aproxime.",
			source = "https://warcraft.wiki.gg/wiki/Bloodtooth_Camp",
		},
		["bough shadow"] = {
			name = "Sombrarrama",
			short = "Além de Cantilenda, onde as árvores do Vale Gris crescem densas e antigas, Sombrarrama guarda um dos portais para o Sonho Esmeralda.",
			full = "Além de Cantilenda, onde as árvores do Vale Gris crescem densas e antigas, Sombrarrama guarda um dos portais para o Sonho Esmeralda.\n\nA revoada verde o protege. Os dracos Phantim e Dreamstalker vigiam a passagem, e dracônidas percorrem as matas ao redor em patrulhas de três, um Oráculo Esmeraldino flanqueado por Guarda-galhos e Protetores das Árvores, pisando o mesmo chão vez após vez em sua longa vigília.",
			source = "https://warcraft.wiki.gg/wiki/Bough_Shadow",
		},
		["demon fall canyon"] = {
			name = "Cânion do Demônio Caído",
			short = "O Cânion do Demônio Caído carrega a cicatriz do momento em que os orcs se libertaram de sua antiga servidão.",
			full = "O Cânion do Demônio Caído carrega a cicatriz do momento em que os orcs se libertaram de sua antiga servidão.\n\nAqui Mannoroth, o senhor do abismo, enfrentou Grommash Grito Infernal e Thrall em combate. O demônio derrubou Thrall, mas não conseguiu desviar a tempo do machado de Grom, que se cravou em seu peito. A morte de Mannoroth explodiu em fogo e luz, e esse mesmo fogo arrancou a vida de Grom enquanto consumia o demônio. Os orcs tomaram o local de seu sacrifício e lhe deram seu nome, pois foi ali que a maldição que a Legião Ardente lançara sobre seu povo foi quebrada.\n\nMuitos orcs ainda viajam até aqui para honrar o guerreiro que pagou por essa liberdade, e um monumento se ergue em sua memória. Mas o chão continua tocado pela energia vil, e demônios menores agora assombram o cânion.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Canyon",
		},
		["demon fall ridge"] = {
			name = "Serra do Demônio Caído",
			short = "Acima do Cânion do Demônio Caído, a serra se ergue partida, com suas encostas e a gruta aberta em sua lateral tomadas por demônios menores.",
			full = "Acima do Cânion do Demônio Caído, a serra se ergue partida, com suas encostas e a gruta aberta em sua lateral tomadas por demônios menores. Mais fundo, além do alcance da luz do dia, espera Diathorus, o Buscador, um senhor do medo que governa o conclave demoníaco reunido no Vale Gris, mantendo sua corte na escuridão enquanto demônios menores guardam a serra acima.",
			source = "https://warcraft.wiki.gg/wiki/Demon_Fall_Ridge",
		},
		["dordanil barrow den"] = {
			name = "Retiro de Dor'Danil",
			short = "O Retiro de Dor'Danil há muito é um local de descanso para druidas elfos noturnos, que dormem ali em corpo enquanto seus espíritos vagam livres.",
			full = "O Retiro de Dor'Danil há muito é um local de descanso para druidas elfos noturnos, que dormem ali em corpo enquanto seus espíritos vagam livres. Foram os Renegados que voltaram sua atenção para os adormecidos, separando os druidas de seus espíritos errantes. O experimento não os matou. Enlouqueceu-os.\n\nAgora a gruta não abriga adormecidos em paz. Assassinos Renegados se movem por ela sem ser vistos, enquanto as almas enfurecidas dos druidas separados se agitam pelo túmulo sem ter para onde voltar. Entre elas permanecem três espíritos mais fortes que os demais: Uthil Mooncall, Mavoris Cloudsbreak e Taneel Darkwood.",
			source = "https://warcraft.wiki.gg/wiki/Dor'Danil_Barrow_Den",
		},
		["falfarren river"] = {
			name = "Rio Felfarren",
			short = "O Felfarren corta o Vale Gris quase ao meio. A oeste ficam os elfos noturnos, sob Astranaar; a leste, os orcs ocupam o Posto Machadada.",
			full = "O Felfarren corta o Vale Gris quase ao meio. A oeste ficam os elfos noturnos, sob Astranaar; a leste, os orcs ocupam o Posto Machadada. O rio é raso o bastante para ser atravessado a vau e estreito o bastante para ser cruzado sem muito esforço, exceto quando as chuvas o fazem transbordar, mas ainda assim marca uma fronteira, que os dois povos entendem sem precisar falar dela.\n\nSuas águas nascem nas encostas do Monte Hyjal, caindo em cascatas até o lago de Xavian antes de seguir entre o Posto Machadada e a Trilha da Noite, sob a grande ponte que a maioria dos viajantes usa para atravessar o Vale Gris, e passando pelo Posto Avançado Asa de Prata e pelo Poço Lunar da Purificação, antes de sumir debaixo da terra sob as montanhas do norte, rumo aos Sertões.\n\nPerto do Monte Fogovil, o rio esconde outro perigo. Monstros do brejo espreitam sob sua superfície ali, atacando qualquer coisa que se demore demais na água.",
			source = "https://warcraft.wiki.gg/wiki/Falfarren_River",
		},
		["fallen sky lake"] = {
			name = "Lago Céu Caído",
			short = "Um pequeno lago fica ao sul do Posto Avançado Asa de Prata, no Vale Gris, com as águas reunidas em torno de uma ilha solitária.",
			full = "Um pequeno lago fica ao sul do Posto Avançado Asa de Prata, no Vale Gris, com as águas reunidas em torno de uma ilha solitária. Nessa ilha vive um Oráculo Sombrouça, um ancião entre o povo sombrouça que cerca a margem em números menores, vigiando a água a partir dos juncos e das moitas ao redor.",
			source = "https://warcraft.wiki.gg/wiki/Fallen_Sky_Lake",
		},
		["felfire hill"] = {
			name = "Monte Fogovil",
			short = "O Monte Fogovil ainda carrega as cicatrizes da Terceira Guerra, quando infernais caíram em chamas do céu e atingiram a terra aqui. Demônios permanecem desde então, criaturas imundas entocadas entre as pedras.",
			full = "O Monte Fogovil ainda carrega as cicatrizes da Terceira Guerra, quando infernais caíram em chamas do céu e atingiram a terra aqui. Demônios permanecem desde então, criaturas imundas entocadas entre as pedras.\n\nA Horda fortificou as duas pontes que levam ao monte, defendendo-as para impedir que os demônios se espalhem em direção aos povoados próximos.",
			source = "https://warcraft.wiki.gg/wiki/Felfire_Hill",
		},
		["fire scar shrine"] = {
			name = "Santuário Cicatriz de Fogo",
			short = "O Santuário Cicatriz de Fogo fica no sudoeste do Vale Gris, corrompido pela influência demoníaca do Conselho das Sombras até se tornar um lugar de grande maldade.",
			full = "O Santuário Cicatriz de Fogo fica no sudoeste do Vale Gris, corrompido pela influência demoníaca do Conselho das Sombras até se tornar um lugar de grande maldade. O bruxo orc Ilkrud Magthrull viveu aqui, a serviço de Athrikus Narassin, líder do Culto da Trama Sombria.\n\nAgora demônios infestam o santuário, atraídos pela mácula deixada na pedra. Entre eles, sabe-se que um guarda vil chamado Akkrilus aparece na área de tempos em tempos, um sinal raro e perigoso de quão fundo a corrupção vai.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Scar_Shrine",
		},
		["forest song"] = {
			name = "Cantilenda",
			short = "Cantilenda é uma antiga ruína dos elfos noturnos nas florestas do Vale Gris, há muito entregue ao musgo e à memória. Por um tempo, não abrigou quase ninguém.",
			full = "Cantilenda é uma antiga ruína dos elfos noturnos nas florestas do Vale Gris, há muito entregue ao musgo e à memória. Por um tempo, não abrigou quase ninguém.\n\nEntão o druida Kainet Brisacalma a tomou para si, o único habitante da ruína, dirigindo de suas pedras a luta contra os Renegados na região. Um lugar esquecido se tornou um posto de sentinela, defendido não por números, mas pela recusa de um único druida em abandoná-lo.",
			source = "https://warcraft.wiki.gg/wiki/Forest_Song",
		},
		["greenpaw village"] = {
			name = "Aldeia Pataverde",
			short = "A Aldeia Pataverde é o lar da tribo Torpeflora, furbolgs liderados pelo Chefe Murgut e pelo xamã Oakpaw. Os homens-urso daqui estão corrompidos.",
			full = "A Aldeia Pataverde é o lar da tribo Torpeflora, furbolgs liderados pelo Chefe Murgut e pelo xamã Oakpaw. Os homens-urso daqui estão corrompidos.",
			source = "https://warcraft.wiki.gg/wiki/Greenpaw_Village",
		},
		["howling vale"] = {
			name = "Vale Uivante",
			short = "Uma caverna se abre no vale onde fica o Santuário de Mel'Thandris, com a pedra gravada com uma antiga inscrição em louvor a Eluna e, acima dela, em darnassiano: a verdade é uma luz que guia.",
			full = "Uma caverna se abre no vale onde fica o Santuário de Mel'Thandris, com a pedra gravada com uma antiga inscrição em louvor a Eluna e, acima dela, em darnassiano: a verdade é uma luz que guia.\n\nO santuário foi erguido pela mãe de Velinde Starsong em honra a Mel'Thandris, a quem fora confiada a Foice de Eluna. Quando Mel'Thandris morreu, a foice foi depositada aqui, escondida dentro do santuário. Ficou esquecida até que Velinde, tendo encontrado em Darnassus um livro que contava a história, veio ao vale e a desenterrou ela mesma.\n\nCom o tempo, o santuário caiu em ruínas, e uma tribo de worgens chamada Terrowulf o tomou, fazendo da caverna seu covil. Seus uivos, ecoando pela pedra, deram ao vale o nome que ele carrega hoje.",
			source = "https://warcraft.wiki.gg/wiki/Howling_Vale",
		},
		["iris lake"] = {
			name = "Lago Íris",
			short = "O Lago Íris fica no centro-norte do Vale Gris, a leste de Astranaar e a oeste do poço lunar de Shael'dryn.",
			full = "O Lago Íris fica no centro-norte do Vale Gris, a leste de Astranaar e a oeste do poço lunar de Shael'dryn. Antes parte da floresta intacta dos elfos noturnos, ele caiu diante da corrupção que se espalha da Selva Maleva, com a água tingida de um verde-amarelado doentio. Monstros do brejo retorcidos agora assombram suas margens, atacando qualquer um que venha em busca das Lágrimas de Eluna.",
			source = "https://warcraft.wiki.gg/wiki/Iris_Lake",
		},
		["kargathia keep"] = {
			name = "Bastilha Karrathia",
			short = "A Bastilha Karrathia se ergue entre barricadas de estacas no Acampamento de Lenhadores Brado Guerreiro, no leste do Vale Gris, perto do Rio Furiaustral.",
			full = "A Bastilha Karrathia se ergue entre barricadas de estacas no Acampamento de Lenhadores Brado Guerreiro, no leste do Vale Gris, perto do Rio Furiaustral. Serve de sede aos oficiais do clã Brado Guerreiro, e sua posição foi escolhida para que reforços possam ser chamados de Orgrimmar caso a Aliança avance em força contra o acampamento.\n\nA bastilha leva o nome de Kargath Carpunhal, o herói orc também homenageado em Karrath, nos Ermos, e na Baía Carpunhal, em Durotar. O Capataz Gorthak comanda o acampamento de dentro de suas muralhas, dirigindo a derrubada da madeira do Vale Gris.",
			source = "https://warcraft.wiki.gg/wiki/Kargathia_Keep",
		},
		["lake falathim"] = {
			name = "Lago Falathim",
			short = "O Lago Falathim fica no oeste do Vale Gris, onde o luar da deusa sempre toca a água, de dia ou de noite. Os elfos noturnos um dia vinham aqui livremente para nadar e pescar, até que murlocs tomaram o lago e o tornaram selvagem.",
			full = "O Lago Falathim fica no oeste do Vale Gris, onde o luar da deusa sempre toca a água, de dia ou de noite. Os elfos noturnos um dia vinham aqui livremente para nadar e pescar, até que murlocs tomaram o lago e o tornaram selvagem. O estudioso Teronis foi visto pela última vez perto de suas margens e nunca voltou.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Falathim",
		},
		["maestras post"] = {
			name = "Entreposto de Maestra",
			short = "Uma torre e um único salão dos elfos noturnos se erguem em silêncio aqui, abrigando um punhado de defensores e, o mais estranho para o Vale Gris, dois humanos entre os elfos: Firo Maniferro e Delgren, o Purificador, os únicos de sua espécie neste posto.",
			full = "Uma torre e um único salão dos elfos noturnos se erguem em silêncio aqui, abrigando um punhado de defensores e, o mais estranho para o Vale Gris, dois humanos entre os elfos: Firo Maniferro e Delgren, o Purificador, os únicos de sua espécie neste posto.\n\nSão poucos, pois a corrupção que se espalha entre os furbolgs próximos desvia mãos que, de outra forma, poderiam montar guarda aqui, deixando os defensores do posto sobrecarregados.",
			source = "https://warcraft.wiki.gg/wiki/Maestra's_Post",
		},
		["mystral lake"] = {
			name = "Lago Mistral",
			short = "A água do Lago Mistral era guardada por espíritos leais aos elfos noturnos, presos ao lago como seus guardiões.",
			full = "A água do Lago Mistral era guardada por espíritos leais aos elfos noturnos, presos ao lago como seus guardiões. Sarilus Foulborne os converteu, corrompendo os elementais até que passassem a responder a ele e não aos elfos a quem um dia serviram. O que espera no lago agora não é o que era.",
			source = "https://warcraft.wiki.gg/wiki/Mystral_Lake",
		},
		["night run"] = {
			name = "Trilha da Noite",
			short = "A Trilha da Noite fica num promontório que avança terra adentro, com penhascos íngremes demais para escalar, de modo que o viajante precisa seguir o Felfarren quase até as águas de Xavian antes de virar para o oeste, ou então encontrar a borda estreita ao norte de Bosque Real.",
			full = "A Trilha da Noite fica num promontório que avança terra adentro, com penhascos íngremes demais para escalar, de modo que o viajante precisa seguir o Felfarren quase até as águas de Xavian antes de virar para o oeste, ou então encontrar a borda estreita ao norte de Bosque Real. Há pouco a encontrar lá dentro: apenas pilares quebrados espalhados e cantaria em ruínas, o menor e mais pobre dos três redutos de sátiros do Vale Gris, ofuscado tanto por Xavian quanto por Satyrnaar. Os sátiros Felmusk que se abrigam entre estas ruínas pouco precisam de muralhas quando a própria terra os protege. Entre os escombros jaz uma das gemas de alma do Culto da Trama Sombria, com quem os Felmusk são aliados.",
			source = "https://warcraft.wiki.gg/wiki/Night_Run",
		},
		["nightsong woods"] = {
			name = "Floresta Noturcanto",
			short = "O Rio Felfarren corta as matas do leste em duas, e a linha que ele traça é a linha de uma guerra que nunca termina.",
			full = "O Rio Felfarren corta as matas do leste em duas, e a linha que ele traça é a linha de uma guerra que nunca termina. A oeste de suas margens, as Sentinelas Asa de Prata defendem o terreno para a Aliança; a leste, o clã Brado Guerreiro cravou suas estacas na terra, e aqui a luta entre os dois povos é mais intensa e constante.\n\nMais a leste, um segundo rio sem nome marca outra fronteira. De um lado fica o Posto Machadada, o coração da força da Horda nestas matas; do outro, o Bosque Asa de Prata responde pela Aliança. Além desse rio fica um terreno que não pertence a ninguém por muito tempo, reivindicado aos pedaços pelos elfos noturnos de Cantilenda, pelos sátiros de Satyrnaar e Xavian, pelos orcs Brado Guerreiro e pela própria Legião Ardente. Nenhuma bandeira jamais tremulou ali sem ser contestada.\n\nAo sul da luta, a floresta pagou o preço da guerra. O clã Brado Guerreiro desnudou estas terras, derrubando as árvores antigas para obter madeira e erguer seus povoados, deixando um terreno aberto e ferido onde antes havia uma floresta ancestral intacta.",
			source = "https://warcraft.wiki.gg/wiki/Nightsong_Woods",
		},
		["raynewood retreat"] = {
			name = "Refúgio Bosque Real",
			short = "No alto dos galhos da Grande Árvore que dá nome a este lugar se esconde Ordanus, um guardião do bosque e um dos filhos mais velhos de Cenarius.",
			full = "No alto dos galhos da Grande Árvore que dá nome a este lugar se esconde Ordanus, um guardião do bosque e um dos filhos mais velhos de Cenarius. Ele veio para cá para se ocultar do Conselho das Sombras, cujos agentes o haviam marcado para morrer. A principal deles era Braelyn Firehand, que fez de sua morte seu único propósito e enviou assassinos contra ele. Ordanus sobreviveu ao atentado e continua escondido nos galhos altos da árvore.\n\nAbaixo dele, Protetores Cenarianos, Dragões Cintilantes e as Irmãs Risonhas vigiam a partir do posto, guardando o caminho norte que leva às terras arrasadas da Selva Maleva.",
			source = "https://warcraft.wiki.gg/wiki/Raynewood_Retreat",
		},
		["ruins of ordilaran"] = {
			name = "Ruínas de Ordil'Aran",
			short = "Pouco resta de Ordil'Aran agora além de pedras quebradas. O Culto da Trama Sombria um dia tomou as ruínas para si, pronto para cair sobre qualquer um que se aproximasse demais.",
			full = "Pouco resta de Ordil'Aran agora além de pedras quebradas. O Culto da Trama Sombria um dia tomou as ruínas para si, pronto para cair sobre qualquer um que se aproximasse demais. Isso terminou em sangue: os furbolgs Pelocardo os expulsaram e tomaram as ruínas para si, e os corpos dos cultistas ainda jazem espalhados onde caíram.\n\nEm meio aos destroços fica o Cerne da Mata, enraizado no que um dia foi uma cidade de algum nome e importância. Nada mais dela sobrevive para dizer o que foi.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ordil'Aran",
		},
		["ruins of stardust"] = {
			name = "Ruínas de Poeira Estelar",
			short = "As Ruínas de Poeira Estelar ficam numa ilha do lago, um dia mergulhadas em santidade, agora mergulhadas em podridão. A mácula demoníaca que escorre da Selva Maleva se infiltrou tanto na água quanto na pedra, tingindo a ilha de um verde-amarelado doentio.",
			full = "As Ruínas de Poeira Estelar ficam numa ilha do lago, um dia mergulhadas em santidade, agora mergulhadas em podridão. A mácula demoníaca que escorre da Selva Maleva se infiltrou tanto na água quanto na pedra, tingindo a ilha de um verde-amarelado doentio. Monstros do brejo, retorcidos pelo lago envenenado, se arrastam agora pelos destroços.\n\nAinda assim, os arbustos de poeira estelar continuam crescendo ali, intocados pela corrupção ao redor. Dizem que suas folhas têm uma virtude curativa, a única parte das ruínas que ainda se parece com o que o lugar deve ter sido antes que a podridão chegasse.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Stardust",
		},
		["satyrnaar"] = {
			name = "Satyrnaar",
			short = "Satyrnaar está em ruínas entre as árvores do nordeste do Vale Gris, com suas construções há muito caídas, embora agora tendas se amontoem entre os destroços onde os sátiros Cordúmbria fizeram seu lar.",
			full = "Satyrnaar está em ruínas entre as árvores do nordeste do Vale Gris, com suas construções há muito caídas, embora agora tendas se amontoem entre os destroços onde os sátiros Cordúmbria fizeram seu lar. Dos três redutos de sátiros da floresta, apenas Satyrnaar continua em grande parte intacto, e sua posição ao lado da estrada que vai do Posto Machadada até Azshara fez dele o mais fácil de alcançar e o mais disputado dos três.\n\nOs Cordúmbria guardam mais que abrigo aqui. Dentro de Satyrnaar repousa uma das gemas de alma do Culto da Trama Sombria, um símbolo do pacto que liga os sátiros aos propósitos sombrios desse culto.",
			source = "https://warcraft.wiki.gg/wiki/Satyrnaar",
		},
		["shady nook"] = {
			name = "Gruta Escura",
			short = "A Gruta Escura fica ao sul do Refúgio Bosque Real e a leste da Aldeia Pataverde, um pequeno vale discretamente dobrado no Vale Gris.",
			full = "A Gruta Escura fica ao sul do Refúgio Bosque Real e a leste da Aldeia Pataverde, um pequeno vale discretamente dobrado no Vale Gris. Uma caverna se abre em sua encosta, lar de uma pequena família de ursos que vive reservada entre as árvores e a sombra.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Nook",
		},
		["shrine of aessina"] = {
			name = "Altar de Aessina",
			short = "O Altar de Aessina fica no sudoeste do Vale Gris, escondido entre o Entreposto de Maestra e Astranaar.",
			full = "O Altar de Aessina fica no sudoeste do Vale Gris, escondido entre o Entreposto de Maestra e Astranaar.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Aessina",
		},
		["silverwind refuge"] = {
			name = "Refúgio Brisaprata",
			short = "O Refúgio Brisaprata pertence aos elfos noturnos, mantido sob a vigilância das Sentinelas e dos elementais da água que servem ao lado delas.",
			full = "O Refúgio Brisaprata pertence aos elfos noturnos, mantido sob a vigilância das Sentinelas e dos elementais da água que servem ao lado delas. Junto com Astranaar, é um dos principais postos avançados do Vale Gris, e seu nome é bem merecido: um lugar acolhedor, com uma estalagem considerada entre as mais confortáveis da região.",
			source = "https://warcraft.wiki.gg/wiki/Silverwind_Refuge",
		},
		["silverwing grove"] = {
			name = "Bosque Asa de Prata",
			short = "O Bosque Asa de Prata fica no centro-sul do Vale Gris, um arvoredo defendido pelas Sentinelas Asa de Prata, a sudoeste de seu posto avançado e a oeste do Lago Céu Caído.",
			full = "O Bosque Asa de Prata fica no centro-sul do Vale Gris, um arvoredo defendido pelas Sentinelas Asa de Prata, a sudoeste de seu posto avançado e a oeste do Lago Céu Caído. A Sentinela Cantálgures monta guarda aqui entre os que juraram defender o bosque.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Grove",
		},
		["silverwing outpost"] = {
			name = "Posto Avançado Asa de Prata",
			short = "O Posto Avançado Asa de Prata fica do lado errado do Rio Felfarren, no fundo de um território que os orcs do Posto Machadada pretendem limpar.",
			full = "O Posto Avançado Asa de Prata fica do lado errado do Rio Felfarren, no fundo de um território que os orcs do Posto Machadada pretendem limpar. Duriel Moonfire o comanda, e comandar aqui significa guerra constante: os orcs não atacam em busca de saque, mas para apagar o posto e expulsar de vez todas as sentinelas destas matas.",
			source = "https://warcraft.wiki.gg/wiki/Silverwing_Outpost",
		},
		["southfury river"] = {
			name = "Rio Furiaustral",
			short = "O Furiaustral nasce no alto do Monte Hyjal, despejando-se de um lago de montanha numa queda que despenca trovejante nas terras baixas.",
			full = "O Furiaustral nasce no alto do Monte Hyjal, despejando-se de um lago de montanha numa queda que despenca trovejante nas terras baixas. Dali ele corre largo e veloz, cortando a terra em duas: marca onde o Vale Gris dá lugar a Azshara e, mais ao sul, onde terminam os Sertões e começa Durotar. Na foz, o rio se lança numa última cascata no Grande Mar, logo a nordeste do porto goblin de Vila Catraca.\n\nPontes cruzam seu curso, uma ligando Azshara ao Vale Gris, outra unindo Durotar aos Sertões. Logo ao norte da mais ocidental delas, um único trecho de água toca as quatro terras ao mesmo tempo, o único lugar onde o Vale Gris, Azshara, Durotar e os Sertões se encontram.\n\nO rio ainda alimenta os campos ao longo de suas margens e ainda deixa verde o solo por onde passa. Mas já não se pode bebê-lo.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["splintertree post"] = {
			name = "Posto Machadada",
			short = "As madeiras do Posto Machadada ainda carregam as marcas dos machados que o ergueram, pois foram Grommash Grito Infernal e seu clã Brado Guerreiro que construíram este posto avançado quando os orcs avançaram pela primeira vez sobre o Vale Gris durante a Terceira Guerra, derrubando as árvores antigas para abrir sua estrada e seus acampamentos.",
			full = "As madeiras do Posto Machadada ainda carregam as marcas dos machados que o ergueram, pois foram Grommash Grito Infernal e seu clã Brado Guerreiro que construíram este posto avançado quando os orcs avançaram pela primeira vez sobre o Vale Gris durante a Terceira Guerra, derrubando as árvores antigas para abrir sua estrada e seus acampamentos.\n\nOs elfos noturnos nunca fizeram as pazes com o que o Brado Guerreiro fez com suas florestas, e as velhas feridas pesam sob a trégua tensa entre a Horda e a Aliança. Por isso o Posto Machadada atrai mais retaliação que a maioria dos postos destas matas, com ataques frequentes dos dois lados envolvendo a vizinha Astranaar.\n\nO que resta agora é uma guarnição, não um povoado: orcs e taurens fazendo reconhecimento e montando guarda, vigiando a linha das árvores à espera dos atacantes que aprenderam a esperar.",
			source = "https://warcraft.wiki.gg/wiki/Splintertree_Post",
		},
		["talondeep path"] = {
			name = "Túnel Garracava",
			short = "O Túnel Garracava é uma passagem sinuosa que liga o Vale Gris à Cordilheira das Torres de Pedra, com um trajeto irregular cheio de pequenos becos sem saída e estranhas cavidades gastas na rocha.",
			full = "O Túnel Garracava é uma passagem sinuosa que liga o Vale Gris à Cordilheira das Torres de Pedra, com um trajeto irregular cheio de pequenos becos sem saída e estranhas cavidades gastas na rocha. Numa ponta, abre-se a oeste do Lago Mistral; na outra, no noroeste do Rochedo Cortavento. Nada vive ali; é simplesmente um caminho através das montanhas.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["thistlefur village"] = {
			name = "Aldeia dos Pelocardo",
			short = "A Aldeia dos Pelocardo fica no centro-oeste do Vale Gris, ao norte de Astranaar. É o lar da tribo Pelocardo, furbolgs que se tornaram corrompidos e hostis e atacam qualquer um que se aproxime.",
			full = "A Aldeia dos Pelocardo fica no centro-oeste do Vale Gris, ao norte de Astranaar. É o lar da tribo Pelocardo, furbolgs que se tornaram corrompidos e hostis e atacam qualquer um que se aproxime. Dois guerreiros ferozes, Dal Sangarra e Rorgish Jowl, lideram a tribo e defendem a aldeia contra todos que chegam.",
			source = "https://warcraft.wiki.gg/wiki/Thistlefur_Village",
		},
		["warsong labor camp"] = {
			name = "Campo de Trabalho Brado Guerreiro",
			short = "No sudeste do Vale Gris, a leste do Lago Céu Caído, o clã Brado Guerreiro mantém um campo de trabalho onde lenhadores e coletores trabalham sob guarda orc, cortando madeira para as posses do clã.",
			full = "No sudeste do Vale Gris, a leste do Lago Céu Caído, o clã Brado Guerreiro mantém um campo de trabalho onde lenhadores e coletores trabalham sob guarda orc, cortando madeira para as posses do clã.\n\nO campo fica afastado do grosso das forças do Brado Guerreiro, com seus guardas isolados e sem esperança de reforços.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Labor_Camp",
		},
		["warsong lumber camp"] = {
			name = "Acampamento de Lenhadores Brado Guerreiro",
			short = "As florestas do Vale Gris ecoam com machados no Acampamento de Lenhadores Brado Guerreiro, onde o clã Brado Guerreiro despoja as árvores antigas em busca de madeira.",
			full = "As florestas do Vale Gris ecoam com machados no Acampamento de Lenhadores Brado Guerreiro, onde o clã Brado Guerreiro despoja as árvores antigas em busca de madeira. O acampamento é sustentado por um canil de feras de guerra e pela Bastilha Karrathia, uma fortaleza erguida para proteger o corte.\n\nA fome de madeira do clã não ficou sem resposta. Iliana e suas irmãs passaram a agir na mata daqui, voltando a magia da natureza contra os retalhadores que roem os troncos, e o terreno entre as toras empilhadas se tornou um campo de batalha entre a Aliança e a Horda.\n\nMesmo assim, o acampamento ainda cumpre seu papel: um fluxo constante de madeira segue daqui para o Posto Machadada, cujas muralhas e cujo povo dependem do que o Acampamento de Lenhadores Brado Guerreiro lhes envia.",
			source = "https://warcraft.wiki.gg/wiki/Warsong_Lumber_Camp",
		},
		["xavian"] = {
			name = "Xavian",
			short = "Xavian se ergue onde antes ficava um templo dos elfos noturnos, com suas pedras agora entregues aos sátiros.",
			full = "Xavian se ergue onde antes ficava um templo dos elfos noturnos, com suas pedras agora entregues aos sátiros. Entre os três redutos de sátiros do Vale Gris, é aqui que o poder se concentra: o Príncipe Raze e Geltharis têm ambos sua sede nestas ruínas, e é aqui que os sátiros passaram a usar o Óleo do Brado Guerreiro roubado em seus rituais.\n\nO lugar leva o nome de Xavius, que há muito tempo ajudou a abrir caminho para a Legião Ardente por meio de um portal extraído do Poço da Eternidade em Zin-Azshari. Sargeras, descontente com a lentidão daquele trabalho, transformou Xavius no primeiríssimo sátiro. Xavian fica perto o bastante de Azshara para que o nome não pareça coincidência.\n\nDríades já avançaram contra Xavian; uma delas, Anilia, foi encontrada aqui mortalmente ferida depois de procurar um galho de Cenarius que os sátiros haviam tomado para si, caída no chão em meio às ruínas que não conseguiu limpar.",
			source = "https://warcraft.wiki.gg/wiki/Xavian",
		},
		["zoram strand"] = {
			name = "Praia de Zoram",
			short = "As ondas ao longo da Praia de Zoram quebram sobre o que um dia foi uma cidade.",
			full = "As ondas ao longo da Praia de Zoram quebram sobre o que um dia foi uma cidade. Antes que o mundo fosse despedaçado na Grande Cisão, Zoram ficava aqui como uma cidade dos elfos noturnos e, quando o mar subiu para reivindicar sua parte do mundo partido, Zoram afundou com ele. Nada resta acima da água agora além do nome.\n\nO que caminha pela praia hoje não são elfos, mas nagas. Eles tomaram a costa para si, e os destroços espalhados pela areia, navios quebrados e corpos de criaturas marinhas encalhadas, mostram o quanto o litoral passou por completo para suas mãos. Entre as rochas e cavidades submersas próximas ficam as Profundezas Negras, afundadas na terra como Zoram um dia afundou no mar.\n\nA Horda mantém um pequeno ponto de apoio aqui, no Assentamento Zoram'gar, levada a ele mais por necessidade que por escolha, e se desgastou lutando contra os nagas Wrathtail, que disputam cada palmo da praia. Esses mesmos nagas caíram sobre Talen, deixando o posto com inimigos pressionando por mais de uma direção. É um trecho de costa duro, úmido e disputado, reivindicado por um império que se afogou e ocupado agora por criaturas nascidas do mar que o engoliu.",
			source = "https://warcraft.wiki.gg/wiki/Zoram_Strand",
		},
		["zoramgar outpost"] = {
			name = "Assentamento Zoram'gar",
			short = "O Assentamento Zoram'gar é um porto da Horda ao longo da Praia de Zoram, no Vale Gris, com seu cais avançando pelas águas lá embaixo.",
			full = "O Assentamento Zoram'gar é um porto da Horda ao longo da Praia de Zoram, no Vale Gris, com seu cais avançando pelas águas lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Zoram'gar_Outpost",
		},
	},
	-- Mil Agulhas: 20 subzones
	[1441] = {
		["camp ethok"] = {
			name = "Aldeia E'thok",
			short = "A Aldeia E'thok é um acampamento de centauros Galath no noroeste de Mil Agulhas.",
			full = "A Aldeia E'thok é um acampamento de centauros Galath no noroeste de Mil Agulhas. Seus centauros atacaram uma caravana que levava o goblin Wizlo Bearingshiner, mas não conseguiram roubar a engenhoca que ele mais prezava, guardada em segurança no pescoço de sua feroz pantera de estimação.",
			source = "https://warcraft.wiki.gg/wiki/Camp_E'thok",
		},
		["darkcloud pinnacle"] = {
			name = "Pináculo da Nuvem Negra",
			short = "O Pináculo da Nuvem Negra se ergue sobre três pequenas mesas a leste do Grande Elevador, com seus topos unidos por pontes de corda estendidas sobre o vazio.",
			full = "O Pináculo da Nuvem Negra se ergue sobre três pequenas mesas a leste do Grande Elevador, com seus topos unidos por pontes de corda estendidas sobre o vazio. Apenas dois caminhos levam para cima, ambos bem guardados: uma encosta natural que atravessa uma quarta mesa ou uma ponte que vem do Urzal dos Mortos.\n\nOs taurens Temível Totem ocupam estas alturas, liderados por Arnak Temível Totem e Harb Foulmountain. Por trás das pontes guardadas, os dois líderes mantêm uma correspondência secreta com algum poder sombrio cuja identidade não se conhece. O que se passa entre eles não é dito abertamente, mas o cuidado com que as mesas são isoladas mostra o quanto esse segredo é bem guardado.",
			source = "https://warcraft.wiki.gg/wiki/Darkcloud_Pinnacle",
		},
		["freewind post"] = {
			name = "Aldeia Vento Livre",
			short = "A Aldeia Vento Livre fica no alto de uma mesa em Mil Agulhas, erguida fora do alcance dos centauros que vagam lá embaixo.",
			full = "A Aldeia Vento Livre fica no alto de uma mesa em Mil Agulhas, erguida fora do alcance dos centauros que vagam lá embaixo. Elevadores de madeira levam seu povo do fundo do desfiladeiro até lá em cima, e pontes de corda se estendem entre os pináculos vizinhos, subindo pináculo por pináculo até chegar à aldeia. Lá embaixo, os centauros Galath avançam com seus bandos de guerra, e harpias circulam e guincham sobre as planícies, mas a própria altura é a verdadeira defesa do posto.\n\nO problema mais grave veio do noroeste, do Pináculo da Nuvem Negra, onde a tribo Temível Totem ocupava suas próprias alturas. A Aldeia Vento Livre passou a desconfiar deles muito antes da guerra aberta: taurens desapareciam, agentes de origem desconhecida e sombria eram vistos visitando o pináculo, e assassinatos eram atribuídos aos Temível Totem. O Chefe Arnak Temível Totem carregava a maior parte da culpa. Quando Lakota Windsong, da Aldeia Vento Livre, recusou suas investidas, ele mandou levá-la à força e, quando o irmão dela veio defendê-la, os Temível Totem o mataram.",
			source = "https://warcraft.wiki.gg/wiki/Freewind_Post",
		},
		["great lift"] = {
			name = "O Grande Elevador",
			short = "O Grande Elevador é um elevador construído pelos taurens que leva os viajantes entre os Sertões e Mil Agulhas, lá embaixo. Grish Pisa Léguas e o Valente Chifre da Lua o vigiam para a Horda.",
			full = "O Grande Elevador é um elevador construído pelos taurens que leva os viajantes entre os Sertões e Mil Agulhas, lá embaixo. Grish Pisa Léguas e o Valente Chifre da Lua o vigiam para a Horda.",
			source = "https://warcraft.wiki.gg/wiki/Great_Lift",
		},
		["highperch"] = {
			name = "Alcândora",
			short = "A Alcândora se ergue acima de Mil Agulhas, lar das mantícoras e de seus ninhos. Entre os penhascos, o tauren Pao'ka Swiftmountain está encurralado, na esperança de passar pelas mantícoras e voltar para casa.",
			full = "A Alcândora se ergue acima de Mil Agulhas, lar das mantícoras e de seus ninhos. Entre os penhascos, o tauren Pao'ka Swiftmountain está encurralado, na esperança de passar pelas mantícoras e voltar para casa.",
			source = "https://warcraft.wiki.gg/wiki/Highperch",
		},
		["ironstone camp"] = {
			name = "Acampamento Petraferro",
			short = "O Acampamento Petraferro fica na borda da Chapada Cintilante.",
			full = "O Acampamento Petraferro fica na borda da Chapada Cintilante.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Camp",
		},
		["mirage raceway"] = {
			name = "Circuito da Ilusão",
			short = "Um goblin chamado Pozzik e um gnomo chamado Fizzle Brassbolts acreditavam, cada um, que seu povo tinha os engenheiros mais inteligentes, e nenhum dos dois cedia.",
			full = "Um goblin chamado Pozzik e um gnomo chamado Fizzle Brassbolts acreditavam, cada um, que seu povo tinha os engenheiros mais inteligentes, e nenhum dos dois cedia. Então resolveram a questão como fazem os engenhoqueiros: construíram uma pista e construíram carros-foguete para correr nela.\n\nA rivalidade atrai multidões muito além dos dois. Horda e Aliança vêm torcer por seus favoritos enquanto dragsters gnomos e goblins correm todos os dias, e depois cada equipe corre para reconstruir seus motores com alguma nova vantagem. A verdadeira disputa é sempre a mesma: qual raça constrói a melhor máquina, e ela nunca é resolvida.",
			source = "https://warcraft.wiki.gg/wiki/Mirage_Raceway",
		},
		["razorfen downs"] = {
			name = "Urzal dos Mortos",
			short = "No fundo dos espinheiros de Mil Agulhas fica um labirinto de espinhos e ossos, cuja entrada dizem ter sido moldada a partir da própria bocarra de Agamaggan, uma abertura em arco na cúpula externa tão escondida que só quem já conhece sua forma consegue encontrá-la.",
			full = "No fundo dos espinheiros de Mil Agulhas fica um labirinto de espinhos e ossos, cuja entrada dizem ter sido moldada a partir da própria bocarra de Agamaggan, uma abertura em arco na cúpula externa tão escondida que só quem já conhece sua forma consegue encontrá-la. Este é o Urzal dos Mortos, o cemitério ancestral e capital tradicional dos javaturnos, feito das mesmas vinhas poderosas que o Urzal dos Tuscos. Charlga Razorflank moldou a maior parte da grande cúpula de espinhos que o cobre.\n\nPor gerações, o Urzal dos Mortos foi um lugar dos mortos javaturnos, cuidado pelos sumos sacerdotes da tribo Caveira da Morte. Mas depois da Terceira Guerra, o lich Amnennar, o Gélido, voltou seus agentes contra os javaturnos e tomou sua cidade sagrada, transformando-a num bastião do Flagelo. Os javaturnos lutaram amargamente para reconquistar o que era seu antes que a praga de Amnennar se espalhasse ainda mais pelos Sertões e, nessa luta, os vivos foram arrastados e enjaulados entre os espinhos ao lado dos mortos.\n\nAmnennar ainda está dentro do labirinto, governando os javaturnos que submeteu à sua vontade, com seu domínio sobre o Urzal intacto.",
			source = "https://warcraft.wiki.gg/wiki/Razorfen_Downs",
		},
		["roguefeather den"] = {
			name = "Covil Plumerrante",
			short = "Numa pequena caverna no centro-sul de Mil Agulhas, as harpias do Covil Plumerrante fizeram seu ninho.",
			full = "Numa pequena caverna no centro-sul de Mil Agulhas, as harpias do Covil Plumerrante fizeram seu ninho. Elas guincham para qualquer um que se aproxime e, no fundo do covil, acumulam os alimentos que juntaram, guardando as provisões com a mesma ferocidade com que guardam seus filhotes.",
			source = "https://warcraft.wiki.gg/wiki/Roguefeather_Den",
		},
		["rustmaul dig site"] = {
			name = "Sítio de Escavação Velhomalho",
			short = "O Sítio de Escavação Velhomalho fica na Chapada Cintilante, com as trincheiras abandonadas no meio do trabalho. A Liga dos Exploradores viera até aqui para desenterrar ruínas antigas, trabalhando o terreno à sombra de uma caverna que abrigava um ninho de silitídeos.",
			full = "O Sítio de Escavação Velhomalho fica na Chapada Cintilante, com as trincheiras abandonadas no meio do trabalho. A Liga dos Exploradores viera até aqui para desenterrar ruínas antigas, trabalhando o terreno à sombra de uma caverna que abrigava um ninho de silitídeos.\n\nA escavação parou antes de terminar. As trincheiras estão abertas e vazias, as ferramentas dos anões abandonadas onde foram deixadas, e a caverna sob o sítio continua sendo o lar dos silitídeos que ainda vivem ali.",
			source = "https://warcraft.wiki.gg/wiki/Rustmaul_Dig_Site",
		},
		["screeching canyon"] = {
			name = "Garganta Uivante",
			short = "A Garganta Uivante corta o sul de Mil Agulhas, com paredes que ecoam os gritos das harpias Uivantes que a infestam.",
			full = "A Garganta Uivante corta o sul de Mil Agulhas, com paredes que ecoam os gritos das harpias Uivantes que a infestam. No fundo da garganta fica o Covil Plumerrante, a fortaleza das harpias.",
			source = "https://warcraft.wiki.gg/wiki/Screeching_Canyon",
		},
		["shimmering flats"] = {
			name = "Chapada Cintilante",
			short = "A Chapada Cintilante fica no limite sudeste de Mil Agulhas, onde a terra se estende plana e nua até a fronteira com Tanaris.",
			full = "A Chapada Cintilante fica no limite sudeste de Mil Agulhas, onde a terra se estende plana e nua até a fronteira com Tanaris. Nada cresce aqui. O chão é sal endurecido pelo sol, lar apenas de basiliscos, escorpídeos, tartarugas e abutres. Um dia, este foi o fundo de um lago: o casco destroçado de um veleiro ainda está meio enterrado no norte da chapada, um navio encalhado longe de qualquer água, prova do que este lugar era antes de secar em sal e terra rachada.\n\nEssa planura atraiu goblins e gnomos de lados opostos de sua longa rivalidade. Eles ergueram aqui o Circuito da Ilusão e disputaram quem construía máquinas mais rápidas. As geringonças raramente se mantinham inteiras. Crateras marcam a chapada onde os motores falharam, e os destroços de corredores fracassados se espalham pelo sal, deixados para torrar onde caíram.",
			source = "https://warcraft.wiki.gg/wiki/Shimmering_Flats",
		},
		["splithoof crag"] = {
			name = "Rochedo do Casco Fendido",
			short = "O Rochedo do Casco Fendido fica encostado na parede norte de Mil Agulhas, a leste do Pináculo da Nuvem Negra, lar dos centauros Galath.",
			full = "O Rochedo do Casco Fendido fica encostado na parede norte de Mil Agulhas, a leste do Pináculo da Nuvem Negra, lar dos centauros Galath. Em seu centro fica o Castelo do Casco Fendido, uma caverna na encosta da montanha onde os Galath guardam o Casco Fendido, um antigo artefato protegido pelo Braseiro Ancestral e sua Chama Sagrada.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Crag",
		},
		["splithoof hold"] = {
			name = "Castelo do Casco Fendido",
			short = "Os centauros Galath fizeram do Castelo do Casco Fendido sua fortaleza nas cavernas do Rochedo do Casco Fendido. Dentro dele arde a Chama Sagrada sobre o Braseiro Ancestral, um fogo que dizem resistir até debaixo d'água.",
			full = "Os centauros Galath fizeram do Castelo do Casco Fendido sua fortaleza nas cavernas do Rochedo do Casco Fendido. Dentro dele arde a Chama Sagrada sobre o Braseiro Ancestral, um fogo que dizem resistir até debaixo d'água.",
			source = "https://warcraft.wiki.gg/wiki/Splithoof_Hold",
		},
		["tahonda ruins"] = {
			name = "Ruínas de Tahonda",
			short = "Uma aldeia tauren um dia ficava onde hoje está a Chapada Cintilante, há muito em ruínas e engolida pela areia. Basiliscos de pedra-de-sal agora se aninham entre as pedras, e há quem diga que foram eles que expulsaram os taurens.",
			full = "Uma aldeia tauren um dia ficava onde hoje está a Chapada Cintilante, há muito em ruínas e engolida pela areia. Basiliscos de pedra-de-sal agora se aninham entre as pedras, e há quem diga que foram eles que expulsaram os taurens.\n\nResta uma pista: na parede de couro de uma construção, dois conjuntos de três rasgos paralelos, a marca de garras, não do vento nem do tempo. Algo veio atrás daquela aldeia com um propósito.\n\nNenhum nome sobreviveu. Só restam as ruínas, perto da trilha da montanha que leva a Tanaris.",
			source = "https://warcraft.wiki.gg/wiki/Tahonda_Ruins",
		},
		["weathered nook"] = {
			name = "Gruta Velha",
			short = "A parede norte de Mil Agulhas esconde uma pequena caverna conhecida como Gruta Velha, fácil de passar despercebida a menos que se saiba onde procurar.",
			full = "A parede norte de Mil Agulhas esconde uma pequena caverna conhecida como Gruta Velha, fácil de passar despercebida a menos que se saiba onde procurar. Aqui Dorn Plainstalker e Pradosa Fita Nuvens fizeram seu lar, abrigados dos ventos e da poeira do desfiladeiro lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Weathered_Nook",
		},
		["weazels crater"] = {
			name = "Cratera do Furão",
			short = "Uma grande cicatriz se abre no norte da Chapada Cintilante, funda o bastante para engolir a luz ao meio-dia. Ninguém sabe como ela surgiu, embora seu nome sugira alguma figura chamada Furão, seja quem a encontrou, seja quem a fez.",
			full = "Uma grande cicatriz se abre no norte da Chapada Cintilante, funda o bastante para engolir a luz ao meio-dia. Ninguém sabe como ela surgiu, embora seu nome sugira alguma figura chamada Furão, seja quem a encontrou, seja quem a fez. Escombros espalhados e crateras menores próximas sugerem alguma engenhoca goblin ou gnômica que deu errado, alguma invenção levada longe demais.\n\nBasiliscos de pedra-de-sal tomaram a cratera para si desde então.",
			source = "https://warcraft.wiki.gg/wiki/Weazel's_Crater",
		},
		["whitereach post"] = {
			name = "Posto Confinalvo",
			short = "O Posto Confinalvo é um pequeno acampamento da Horda ao longo da estrada perto da Aldeia E'thok, em Mil Agulhas.",
			full = "O Posto Confinalvo é um pequeno acampamento da Horda ao longo da estrada perto da Aldeia E'thok, em Mil Agulhas.",
			source = "https://warcraft.wiki.gg/wiki/Whitereach_Post",
		},
		["windbreak canyon"] = {
			name = "Garganta do Quebravento",
			short = "A Garganta do Quebravento fica entre a Aldeia Vento Livre e a Chapada Cintilante, com paredes crivadas de ninhos. Serpentes aladas reivindicam o lugar como seu, subindo nas correntes que dão nome à garganta.",
			full = "A Garganta do Quebravento fica entre a Aldeia Vento Livre e a Chapada Cintilante, com paredes crivadas de ninhos. Serpentes aladas reivindicam o lugar como seu, subindo nas correntes que dão nome à garganta. Uma trilha daqui leva à Gruta Velha.",
			source = "https://warcraft.wiki.gg/wiki/Windbreak_Canyon",
		},
	},
	-- Cordilheira das Torres de Pedra: 18 subzones
	[1442] = {
		["blackwolf river"] = {
			name = "Rio Lobonegro",
			short = "O Rio Lobonegro corre do Lago do Rochedo através do Rochedo Cortavento, na Cordilheira das Torres de Pedra. Suas águas correm imundas, envenenadas pelo desmatamento do vale pela Empreendimentos S.A.",
			full = "O Rio Lobonegro corre do Lago do Rochedo através do Rochedo Cortavento, na Cordilheira das Torres de Pedra. Suas águas correm imundas, envenenadas pelo desmatamento do vale pela Empreendimentos S.A.",
			source = "https://warcraft.wiki.gg/wiki/Blackwolf_River",
		},
		["boulderslide cavern"] = {
			name = "Caverna da Avalanche",
			short = "No fim da Ravina da Avalanche, a Caverna da Avalanche abriga o ninho dos kobolds da Avalanche. Eles mineram um raro cristal roxo chamado ressonita, tocado por magia terrena, e guardam cada veio dele com a própria vida.",
			full = "No fim da Ravina da Avalanche, a Caverna da Avalanche abriga o ninho dos kobolds da Avalanche. Eles mineram um raro cristal roxo chamado ressonita, tocado por magia terrena, e guardam cada veio dele com a própria vida.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Cavern",
		},
		["boulderslide ravine"] = {
			name = "Ravina da Avalanche",
			short = "A Ravina da Avalanche repousa tranquila ao longo da Passagem Tramateia, intocada pelas guerras que perturbam as terras ao redor. Carneiros escolhem seu caminho pelas encostas, e tempestuosos dos penhascos circulam lá no alto.",
			full = "A Ravina da Avalanche repousa tranquila ao longo da Passagem Tramateia, intocada pelas guerras que perturbam as terras ao redor. Carneiros escolhem seu caminho pelas encostas, e tempestuosos dos penhascos circulam lá no alto.\n\nEm frente à caverna da ravina fica uma caverna abandonada, com seus barris ainda empilhados e suas tochas rústicas ainda de pé, embora não reste ninguém para acendê-las. Em suas paredes resiste uma arte tribal, feita num estilo que parece obra tauren.",
			source = "https://warcraft.wiki.gg/wiki/Boulderslide_Ravine",
		},
		["camp aparaje"] = {
			name = "Aldeia Apareje",
			short = "A Aldeia Apareje era uma aldeia tauren no leste da Cordilheira das Torres de Pedra, atacada por forças Temível Totem vindas da Aldeia do Temível Totem sob o comando de Grundig Nuvem Negra.",
			full = "A Aldeia Apareje era uma aldeia tauren no leste da Cordilheira das Torres de Pedra, atacada por forças Temível Totem vindas da Aldeia do Temível Totem sob o comando de Grundig Nuvem Negra. Makaba Casco Chato vivia ali com sua filha Kaya antes do ataque.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Aparaje",
		},
		["charred vale"] = {
			name = "Vale Carbonizado",
			short = "O Vale Carbonizado já foi verde, um vale no sudoeste da Cordilheira das Torres de Pedra onde as harpias Furissangue faziam seus ninhos e os treants caminhavam pela floresta como seus guardiões.",
			full = "O Vale Carbonizado já foi verde, um vale no sudoeste da Cordilheira das Torres de Pedra onde as harpias Furissangue faziam seus ninhos e os treants caminhavam pela floresta como seus guardiões.\n\nEntão os goblins da Empreendimentos S.A. vieram despojar o vale de sua madeira e seu minério. Os treants se ergueram contra eles e repeliram as máquinas, mas os espíritos do vale não se acalmaram. A escavação havia despertado algo sob a terra, e fogo e elementais jorraram pelo chão partido onde antes ficava a floresta. Os treants que expulsaram os goblins não voltaram inteiros; o que quer que as armas dos goblins tenham lhes feito ficou, e agora eles contam entre os perigos do vale, e não entre seus guardiões.\n\nO que resta é um vale de chamas e lava, com árvores negras de pé nas cinzas onde antes havia árvores verdes. Os druidas do Retiro Rocha do Sol assumiram o trabalho que os treants faziam, estimulando novos brotos no chão queimado na esperança de que o vale volte a ser uma floresta em vez de uma ferida nas montanhas.",
			source = "https://warcraft.wiki.gg/wiki/Charred_Vale",
		},
		["cragpool lake"] = {
			name = "Lago do Rochedo",
			short = "O Lago do Rochedo fica sob a grande estrutura de madeira que a Empreendimentos S.A. ergueu sobre o Rochedo Cortavento. Hanfritz Schaventorck vigia a operação deste ponto.",
			full = "O Lago do Rochedo fica sob a grande estrutura de madeira que a Empreendimentos S.A. ergueu sobre o Rochedo Cortavento. Hanfritz Schaventorck vigia a operação deste ponto.\n\nO próprio lago é proibido, reivindicado por Cragjaw, um peixe que cresceu monstruoso em sua água parada.",
			source = "https://warcraft.wiki.gg/wiki/Cragpool_Lake",
		},
		["greatwood vale"] = {
			name = "Vale Matagrande",
			short = "O Vale Matagrande fica arborizado no sopé da Cordilheira das Torres de Pedra, acessível pela Passagem Tramateia, com Malaka'jin ao sul.",
			full = "O Vale Matagrande fica arborizado no sopé da Cordilheira das Torres de Pedra, acessível pela Passagem Tramateia, com Malaka'jin ao sul.\n\nA quietude do vale se rompeu quando a tribo Temível Totem, sob o comando de Grundig Nuvem Negra, caiu sobre a Aldeia Apareje e massacrou quase todos ali. Makaba Casco Chato sobreviveu e pediu, em resposta, que os Temível Totem do vale fossem caçados.",
			source = "https://warcraft.wiki.gg/wiki/Greatwood_Vale",
		},
		["grimtotem post"] = {
			name = "Aldeia do Temível Totem",
			short = "A Aldeia do Temível Totem é o ponto de apoio da tribo na Cordilheira das Torres de Pedra, com seus brutamontes, rufiões, feiticeiros e mercenários patrulhando as encostas ao redor.",
			full = "A Aldeia do Temível Totem é o ponto de apoio da tribo na Cordilheira das Torres de Pedra, com seus brutamontes, rufiões, feiticeiros e mercenários patrulhando as encostas ao redor. Grundig Nuvem Negra os comanda aqui, mantendo o posto para os próprios propósitos dos Temível Totem.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Post",
		},
		["malakajin"] = {
			name = "Malaka'jin",
			short = "Malaka'jin fica na Cordilheira das Torres de Pedra, ao sul da Aldeia do Temível Totem.",
			full = "Malaka'jin fica na Cordilheira das Torres de Pedra, ao sul da Aldeia do Temível Totem. É uma aldeia modesta, lar de caçadores trolls que ganham a vida vendendo o que caçam aos membros da Horda que passam por ali, um ponto de apoio à vista do território Temível Totem.",
			source = "https://warcraft.wiki.gg/wiki/Malaka'jin",
		},
		["mirkfallon lake"] = {
			name = "Lago Mirkfallon",
			short = "O Lago Mirkfallon fica no coração da Cordilheira das Torres de Pedra, uma bacia selvagem repleta de mantícoras, gosmas e lagartos-trovão que se movem por suas águas e margens.",
			full = "O Lago Mirkfallon fica no coração da Cordilheira das Torres de Pedra, uma bacia selvagem repleta de mantícoras, gosmas e lagartos-trovão que se movem por suas águas e margens. Uma colina se ergue no centro do lago e, acima dela, nas Alturas Cortavento, as mantícoras que restam na área ainda se aninham.",
			source = "https://warcraft.wiki.gg/wiki/Mirkfallon_Lake",
		},
		["sishir canyon"] = {
			name = "Desfiladeiro Sishir",
			short = "O desfiladeiro leva da estrada principal da Cordilheira das Torres de Pedra em direção às Ruínas de Eldre'thar, mas ninguém passa por ele com facilidade.",
			full = "O desfiladeiro leva da estrada principal da Cordilheira das Torres de Pedra em direção às Ruínas de Eldre'thar, mas ninguém passa por ele com facilidade. O Desfiladeiro Sishir está entregue por completo às aranhas Musgofundo, uma ninhada monstruosa cujos ovos e teias sufocam cada saliência e cavidade da pedra. Lá no fundo, a maior delas, Besseleth, espera entre seus semelhantes.",
			source = "https://warcraft.wiki.gg/wiki/Sishir_Canyon",
		},
		["stonetalon peak"] = {
			name = "Morro das Torres de Pedra",
			short = "O Morro das Torres de Pedra fica num vale verde no extremo noroeste das montanhas que levam seu nome, cuidado pelos druidas do vizinho Retiro do Gadanho.",
			full = "O Morro das Torres de Pedra fica num vale verde no extremo noroeste das montanhas que levam seu nome, cuidado pelos druidas do vizinho Retiro do Gadanho. A montanha é considerada sagrada, e a magia corre densa por sua pedra.\n\nDurante a Terceira Guerra, Jaina Proudmore e sua expedição vieram até aqui e montaram uma base perto da entrada das cavernas sob o morro. Thrall e sua Horda vieram depois, em busca do Oráculo.\n\nDesde então, tornou-se um ponto central para os elfos noturnos e a Aliança, com seus druidas vigiando o vale.",
			source = "https://warcraft.wiki.gg/wiki/Stonetalon_Peak",
		},
		["sun rock retreat"] = {
			name = "Retiro Rocha do Sol",
			short = "O Retiro Rocha do Sol fica escondido entre os picos ao sul do Lago Mirkfallon, na Cordilheira das Torres de Pedra, um lugar onde o mundo espiritual se aproxima muito do mundo dos vivos.",
			full = "O Retiro Rocha do Sol fica escondido entre os picos ao sul do Lago Mirkfallon, na Cordilheira das Torres de Pedra, um lugar onde o mundo espiritual se aproxima muito do mundo dos vivos. Muito antes de a Horda erguer suas bandeiras aqui, os taurens peregrinavam até esta pedra para realizar seus ritos de travessia para o reino espiritual. Dizem que An'she, o sol, um dia beijou a montanha onde hoje fica o retiro.\n\nAgora orcs e taurens ocupam juntos o Retiro Rocha do Sol, a reunião mais movimentada das forças da Horda nestas montanhas, um centro de comércio e trabalho, reparando o que a Empreendimentos S.A. e outras forças malignas arrancaram da terra.",
			source = "https://warcraft.wiki.gg/wiki/Sun_Rock_Retreat",
		},
		["talon den"] = {
			name = "Retiro do Gadanho",
			short = "No alto do Morro das Torres de Pedra, a terra se abre no Retiro do Gadanho, uma gruta que é lar das dríades Mirkfallon e dos guardiões que compartilham seu nome, vigiada por Zeladores Cenarianos elfos noturnos.",
			full = "No alto do Morro das Torres de Pedra, a terra se abre no Retiro do Gadanho, uma gruta que é lar das dríades Mirkfallon e dos guardiões que compartilham seu nome, vigiada por Zeladores Cenarianos elfos noturnos.",
			source = "https://warcraft.wiki.gg/wiki/Talon_Den",
		},
		["talondeep path"] = {
			name = "Túnel Garracava",
			short = "O Túnel Garracava é uma passagem sinuosa que liga o Vale Gris à Cordilheira das Torres de Pedra, com um trajeto irregular cheio de pequenos becos sem saída e estranhas cavidades gastas na rocha.",
			full = "O Túnel Garracava é uma passagem sinuosa que liga o Vale Gris à Cordilheira das Torres de Pedra, com um trajeto irregular cheio de pequenos becos sem saída e estranhas cavidades gastas na rocha. Numa ponta, abre-se a oeste do Lago Mistral; na outra, no noroeste do Rochedo Cortavento. Nada vive ali; é simplesmente um caminho através das montanhas.",
			source = "https://warcraft.wiki.gg/wiki/Talondeep_Path",
		},
		["webwinder path"] = {
			name = "Passagem Tramateia",
			short = "A Passagem Tramateia corre entre Malaka'jin e o Lago Mirkfallon, por uma terra que afundou dos dois lados.",
			full = "A Passagem Tramateia corre entre Malaka'jin e o Lago Mirkfallon, por uma terra que afundou dos dois lados. A oeste de Malaka'jin, a Horda construiu uma barricada atravessando a estrada para impedir que a Aliança avance mais para o leste.",
			source = "https://warcraft.wiki.gg/wiki/Webwinder_Path",
		},
		["windshear crag"] = {
			name = "Rochedo Cortavento",
			short = "O Rochedo Cortavento já foi uma floresta ancestral, densa e verde em seu vale na Cordilheira das Torres de Pedra. Já não é. O que existe aqui são tocos, água imunda e máquinas que nunca param totalmente de ranger.",
			full = "O Rochedo Cortavento já foi uma floresta ancestral, densa e verde em seu vale na Cordilheira das Torres de Pedra. Já não é. O que existe aqui são tocos, água imunda e máquinas que nunca param totalmente de ranger.\n\nA ruína tem um nome por trás: Hanfritz Schaventorck, um gnomo leproso encarregado de toda a expedição madeireira sob a bandeira da Empreendimentos S.A. Ele construiu o Super Ceifador 6000, uma máquina capaz de reduzir as árvores mais antigas do rochedo a serragem, e observa seu trabalho de uma plataforma erguida acima do Lago do Rochedo, senhor de tudo o que a máquina limpou. Seu domínio sobre o lugar o tornou descartável para os que estão acima dele: o Diretor Riddlevox, do Sindicato dos Engenhoqueiros de Undermine, o quer morto, e o goblin Zé Fízzica espreita no rochedo, esperando para ver a ordem cumprida.\n\nNo canto sudeste do rochedo, os kobolds Cortavento tomaram a Mina Cortavento para si, cavando túneis atrás de minério de ferro fumacento.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Crag",
		},
		["windshear mine"] = {
			name = "Mina Cortavento",
			short = "A Mina Cortavento fica no fim do Rio Lobonegro, dentro do Rochedo Cortavento. A Empreendimentos S.A. chegou a explorar seus veios de estanho aqui, pondo kobolds para cavar.",
			full = "A Mina Cortavento fica no fim do Rio Lobonegro, dentro do Rochedo Cortavento. A Empreendimentos S.A. chegou a explorar seus veios de estanho aqui, pondo kobolds para cavar.",
			source = "https://warcraft.wiki.gg/wiki/Windshear_Mine",
		},
	},
	-- Desolação: 20 subzones
	[1443] = {
		["bolgans hole"] = {
			name = "Covil do Bolgan",
			short = "Na Aldeia Gelkis, a caverna chamada Covil do Bolgan abriga os membros mais proeminentes do clã, entre eles seu khan, Shaka.",
			full = "Na Aldeia Gelkis, a caverna chamada Covil do Bolgan abriga os membros mais proeminentes do clã, entre eles seu khan, Shaka.\n\nLá no fundo crescem cristais azuis, as lágrimas de Theradras, acumulados pelos xamãs Gelkis, que acreditam que as pedras carregam a proteção da princesa.",
			source = "https://warcraft.wiki.gg/wiki/Bolgan's_Hole",
		},
		["ethel rethor"] = {
			name = "Ethel Rethor",
			short = "Ao largo do litoral noroeste da Desolação, o mar engoliu a maior parte de Ethel Rethor. Apenas uma torre solitária rompe a superfície, ligada à costa por uma ponte estreita que leva a uma porta que continua fechada.",
			full = "Ao largo do litoral noroeste da Desolação, o mar engoliu a maior parte de Ethel Rethor. Apenas uma torre solitária rompe a superfície, ligada à costa por uma ponte estreita que leva a uma porta que continua fechada. Nagas tomaram a ruína submersa para si.",
			source = "https://warcraft.wiki.gg/wiki/Ethel_Rethor",
		},
		["gelkis village"] = {
			name = "Aldeia Gelkis",
			short = "A Aldeia Gelkis se estende em anel ao redor de uma ampla ravina no sudoeste da Desolação, sede do clã Gelkis.",
			full = "A Aldeia Gelkis se estende em anel ao redor de uma ampla ravina no sudoeste da Desolação, sede do clã Gelkis. Pontes estendidas entre os penhascos e escarpas da ravina descem até o Covil do Bolgan, uma caverna aberta na face sul da montanha, onde o Khan Gelkis tem sua residência.\n\nA aldeia fica colada à principal estrada norte-sul da Desolação, tão perto que a própria estrada se tornou um perigo para quem a percorre. Os Gelkis estenderam novas cabanas para o lado leste da estrada que leva a Feralas, ao longo do lago, espalhando-se além da ravina que primeiro os abrigou.",
			source = "https://warcraft.wiki.gg/wiki/Gelkis_Village",
		},
		["ghost walker post"] = {
			name = "Entreposto do Espírito que Anda",
			short = "O Entreposto do Espírito que Anda fica ao lado do Cemitério dos Kodos, no centro da Desolação, e os mortos dali moldam tudo no lugar.",
			full = "O Entreposto do Espírito que Anda fica ao lado do Cemitério dos Kodos, no centro da Desolação, e os mortos dali moldam tudo no lugar. Xamãs taurens vigiam os ossos, ajudando os espíritos dos kodos caídos a seguir para suas próximas vidas e, quando necessário, falando com os que já partiram. Gurda Juba Agreste os lidera, mantendo este posto exposto com pouco mais que o essencial para sustentá-lo.\n\nAo contrário da Aldeia Pescassombra, segura em outra parte da região, o Entreposto do Espírito que Anda não tem essa segurança. É um acampamento avançado construído para a guerra, não para o conforto, sem estalagem e sem lugar para descansar. Existe com um único propósito: levar adiante a luta da Horda contra os cultistas da Lâmina Ardente e as tribos de centauros que percorrem a Desolação.",
			source = "https://warcraft.wiki.gg/wiki/Ghost_Walker_Post",
		},
		["kodo graveyard"] = {
			name = "Cemitério dos Kodos",
			short = "Os kodos da Desolação vêm até aqui para morrer, com seus ossos empilhados e branqueados sobre a terra rachada. Perturbe-os, e os mortos não ficam quietos: aparições de kodos se erguem do chão para guardar o que resta de sua espécie.",
			full = "Os kodos da Desolação vêm até aqui para morrer, com seus ossos empilhados e branqueados sobre a terra rachada. Perturbe-os, e os mortos não ficam quietos: aparições de kodos se erguem do chão para guardar o que resta de sua espécie.",
			source = "https://warcraft.wiki.gg/wiki/Kodo_Graveyard",
		},
		["kolkar village"] = {
			name = "Aldeia Kolkar",
			short = "A aldeia na margem leste da Desolação é a sede do clã Kolkar, o mais numeroso dos clãs de centauros de Kalimdor, com postos avançados em lugares tão distantes quanto os Sertões e Durotar.",
			full = "A aldeia na margem leste da Desolação é a sede do clã Kolkar, o mais numeroso dos clãs de centauros de Kalimdor, com postos avançados em lugares tão distantes quanto os Sertões e Durotar. Os Magram, seus rivais, os pressionam constantemente, pois a rixa entre os clãs nunca descansa.",
			source = "https://warcraft.wiki.gg/wiki/Kolkar_Village",
		},
		["kormeks hut"] = {
			name = "Barraco do Kormek",
			short = "A cabana está castigada pelo tempo no centro-norte da Desolação. Lá dentro vive Faia, uma integrante do Martelo do Crepúsculo, que cuida do lugar com um carinho improvável para alguém daquele culto.",
			full = "A cabana está castigada pelo tempo no centro-norte da Desolação. Lá dentro vive Faia, uma integrante do Martelo do Crepúsculo, que cuida do lugar com um carinho improvável para alguém daquele culto. Do lado de fora, num cercado cheio de ossos de kodo, Bibbly Ferrafivela dança entre os restos, encantado com o lucro que esses ossos podem render.",
			source = "https://warcraft.wiki.gg/wiki/Kormek's_Hut",
		},
		["magram village"] = {
			name = "Aldeia Magram",
			short = "A Aldeia Magram se ergue de um punhado de ilhas em meio a lagoas amarelas poluídas no sudeste da Desolação, com suas cabanas ligadas por pontes rústicas lançadas sobre a água.",
			full = "A Aldeia Magram se ergue de um punhado de ilhas em meio a lagoas amarelas poluídas no sudeste da Desolação, com suas cabanas ligadas por pontes rústicas lançadas sobre a água. Aqui o clã Magram faz seu lar, um dos povos centauros em guerra com o clã Gelkis pelo domínio destas terras estéreis.",
			source = "https://warcraft.wiki.gg/wiki/Magram_Village",
		},
		["mannoroc coven"] = {
			name = "Ruínas de Mannoroc",
			short = "Entre as ruínas dos elfos noturnos espalhadas e partidas pela Desolação, um lugar leva um nome que nenhum viajante pronuncia de forma leviana.",
			full = "Entre as ruínas dos elfos noturnos espalhadas e partidas pela Desolação, um lugar leva um nome que nenhum viajante pronuncia de forma leviana. As Ruínas de Mannoroc levam o nome de Mannoroth, o temido Senhor do Abismo, e o chão daqui se lembra dele. A terra já estava morta muito antes de os demônios chegarem, mas a magia vil a devastou ainda mais, até que o próprio ar ficou carregado de corrupção e uma mortalha mortal cai sobre qualquer um que entre ali.\n\nOs cultistas da Lâmina Ardente abriram o caminho, rasgando vários portais no mundo para invocar por eles os servos da Legião Ardente: infernais, súcubos, canisvis e guardas vis que agora rondam as ruínas. O Lorde Azrethoc comanda esses demônios, enquanto o bruxo orc Jugkar Grim'rod está entre eles como a própria voz da Lâmina Ardente no covil. Juntos, formaram a maior concentração de demônios de todo o centro de Kalimdor, prova de que o plano dos cultistas foi bem-sucedido muito além de um mero aviso.",
			source = "https://warcraft.wiki.gg/wiki/Mannoroc_Coven",
		},
		["nijels point"] = {
			name = "Posto do Nijel",
			short = "O Posto do Nijel monta guarda nas montanhas do norte da Desolação, um posto avançado mantido pela Aliança e pelo Círculo Cenariano.",
			full = "O Posto do Nijel monta guarda nas montanhas do norte da Desolação, um posto avançado mantido pela Aliança e pelo Círculo Cenariano.\n\nO Guardião Marandis veio para cá com suas irmãs dríades, usando o posto como base enquanto perseguiam a Princesa Theradras. Seu propósito era recuperar o corpo de Zaetar das profundezas de Maraudon e levá-lo de volta para casa, na Cordilheira das Torres de Pedra.\n\nAo mesmo tempo, o Exército de Ventobravo destacou para cá a Guarda do Posto do Nijel sob o comando do Capitão Pentigast, contra a ameaça dos clãs de centauros que dominavam a região. Pentigast observava a rivalidade entre os Gelkis e os Magram com a desconfiança de um soldado, certo de que o clã que vencesse ficaria ousado o bastante para se voltar contra as posses da Aliança próximas, e por isso buscava descobrir como os centauros poderiam ser derrotados jogando um clã contra o outro.",
			source = "https://warcraft.wiki.gg/wiki/Nijel's_Point",
		},
		["ranazjar isle"] = {
			name = "Ilha Ranazjar",
			short = "A Ilha Ranazjar é uma pequena ilha rochosa ao largo do litoral noroeste da Desolação, lar dos serpentinos nagas.",
			full = "A Ilha Ranazjar é uma pequena ilha rochosa ao largo do litoral noroeste da Desolação, lar dos serpentinos nagas. Entre as pedras se erguem ruínas dos elfos noturnos, parte da mesma cidade antiga que Ethel Rethor, agora silenciosas acima dos nagas que vivem ali.",
			source = "https://warcraft.wiki.gg/wiki/Ranazjar_Isle",
		},
		["sargeron"] = {
			name = "Sargeron",
			short = "A cidade que ficava aqui um dia teve um nome élfico noturno, perdido desde que a Guerra dos Antigos despedaçou o mundo.",
			full = "A cidade que ficava aqui um dia teve um nome élfico noturno, perdido desde que a Guerra dos Antigos despedaçou o mundo. O que resta são ruínas, agora chamadas de Sargeron pelos sátiros Hatefury que vivem ali, em honra a seu senhor demoníaco, Sargeras.\n\nAs ruínas abrigavam três lugares sagrados de Eluna: sua catedral, seu templo e seu santuário. Relíquias dessa fé mais antiga ainda jazem entre as pedras: o Braseiro de Eluna, sua Serva, sua Taça e a Antiga Pedra Rúnica do Vórtice.",
			source = "https://warcraft.wiki.gg/wiki/Sargeron",
		},
		["sartheris strand"] = {
			name = "Praia de Sar'theris",
			short = "A costa onde a Desolação encontra o mar é diferente da terra atrás dela. Enquanto o interior se estende cinzento e desolado, a Praia de Sar'theris é ensolarada, com capim verde.",
			full = "A costa onde a Desolação encontra o mar é diferente da terra atrás dela. Enquanto o interior se estende cinzento e desolado, a Praia de Sar'theris é ensolarada, com capim verde. Gigantes do mar caminham por seus baixios, nagas serpenteiam por suas águas e makruras correm por suas areias.\n\nAbaixo de Ethel Rethor, um pequeno barco jaz despedaçado na praia, com a madeira estilhaçada e a tripulação que levava desaparecida.",
			source = "https://warcraft.wiki.gg/wiki/Sar'theris_Strand",
		},
		["scrabblescrews camp"] = {
			name = "Acampamento do Rabiscafuso",
			short = "Perto do Cemitério dos Kodos, na Desolação, fica um pequeno acampamento goblin.",
			full = "Perto do Cemitério dos Kodos, na Desolação, fica um pequeno acampamento goblin. Ele pertence a Smid Rabiscafuso, um goblin empreendedor que mantém uma caravana de kodos, conduzindo as grandes feras pelos ermos em busca do lucro que a terra permitir.",
			source = "https://warcraft.wiki.gg/wiki/Scrabblescrew's_Camp",
		},
		["shadowbreak ravine"] = {
			name = "Ravina da Sombra Partida",
			short = "A Ravina da Sombra Partida fica escondida nas montanhas a sudeste de Shok'Thokar, uma dobra da Desolação que poucos encontrariam por acaso.",
			full = "A Ravina da Sombra Partida fica escondida nas montanhas a sudeste de Shok'Thokar, uma dobra da Desolação que poucos encontrariam por acaso. Cogumelos gigantes se erguem entre suas rochas e, em seu coração, fica um círculo de invocação preso por correntes enormes, construído pelos cultistas da Lâmina Ardente que fizeram da ravina seu refúgio.",
			source = "https://warcraft.wiki.gg/wiki/Shadowbreak_Ravine",
		},
		["shadowprey village"] = {
			name = "Aldeia Pescassombra",
			short = "A Aldeia Pescassombra fica onde a Praia de Sar'theris encontra o litoral sul da Desolação, um povoado de pescadores trolls.",
			full = "A Aldeia Pescassombra fica onde a Praia de Sar'theris encontra o litoral sul da Desolação, um povoado de pescadores trolls. Seu povo tira o sustento do mar, e o que pescam é o que mantém alimentado o Entreposto do Espírito que Anda, mais para o interior.",
			source = "https://warcraft.wiki.gg/wiki/Shadowprey_Village",
		},
		["tethris aran"] = {
			name = "Tethris Aran",
			short = "Ruínas dos elfos noturnos se espalham pelo norte da Desolação, ao norte da Fortaleza Machado do Trovão, os restos de um povoado que se pensava destruído na Grande Cisão.",
			full = "Ruínas dos elfos noturnos se espalham pelo norte da Desolação, ao norte da Fortaleza Machado do Trovão, os restos de um povoado que se pensava destruído na Grande Cisão. Nada foi reconstruído. Apenas as criaturas selvagens da Desolação se movem agora entre as pedras quebradas.",
			source = "https://warcraft.wiki.gg/wiki/Tethris_Aran",
		},
		["thunder axe fortress"] = {
			name = "Fortaleza Machado do Trovão",
			short = "A Fortaleza Machado do Trovão fica no noroeste da Desolação, entregue ao culto da Lâmina Ardente.",
			full = "A Fortaleza Machado do Trovão fica no noroeste da Desolação, entregue ao culto da Lâmina Ardente. Por trás de suas muralhas, com fortaleza, quartel, caverna e torres de vigia, os cultistas sob o comando de Kohor trabalham para invocar o demônio Nazargen em toda a sua força, cautelosos para não chamá-lo cedo demais, quando estaria fraco o bastante para ser destruído.\n\nA fortaleza chegou a guardar o Cetro de Luz, um artefato de terrível potência roubado dos nagas pela Lâmina Ardente. Azore Albamorte, a serviço da Aurora Argêntea, dedicou-se a recuperá-lo e, com ajuda, conseguiu arrancá-lo das mãos do culto.\n\nEntre estas muralhas também viveu Tyranis Malem, um nome pronunciado com desprezo entre seu próprio povo, pois ele o traiu e se entregou ao estudo da magia demoníaca, fazendo da Fortaleza Machado do Trovão seu refúgio para essas buscas sombrias.",
			source = "https://warcraft.wiki.gg/wiki/Thunder_Axe_Fortress",
		},
		["valley of bones"] = {
			name = "Vale dos Ossos",
			short = "O Vale dos Ossos é um rochedo no limite sul da Desolação, assombrado por esqueletos, necromantes centauros e os fantasmas do clã Magram massacrado.",
			full = "O Vale dos Ossos é um rochedo no limite sul da Desolação, assombrado por esqueletos, necromantes centauros e os fantasmas do clã Magram massacrado. Contra as paredes do penhasco repousam dois esqueletos enormes, os Golias Mortos, de origem desconhecida.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Bones",
		},
		["valley of spears"] = {
			name = "Vale das Lanças",
			short = "O Vale das Lanças, no oeste da Desolação, é o lar do clã de centauros Maraudine, acessível a pé apenas por estreitas passagens nas montanhas ao sul e a leste.",
			full = "O Vale das Lanças, no oeste da Desolação, é o lar do clã de centauros Maraudine, acessível a pé apenas por estreitas passagens nas montanhas ao sul e a leste. Em sua extremidade sudoeste fica a entrada de Maraudon. Entre os centauros, mantida cativa, está Melizza Zumbidorla.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Spears",
		},
	},
	-- Feralas: 28 subzones
	[1444] = {
		["camp mojache"] = {
			name = "Aldeia Mojache",
			short = "A Aldeia Mojache fica onde um riacho veloz deságua no Lago Vento Selvagem.",
			full = "A Aldeia Mojache fica onde um riacho veloz deságua no Lago Vento Selvagem. Os taurens que ocupam este terreno são conhecidos pela espessura de seu couro e pela coragem de seus bravos, que protegem os viajantes dos perigos de Feralas.",
			source = "https://warcraft.wiki.gg/wiki/Camp_Mojache",
		},
		["dire maul"] = {
			name = "Gládio Cruel",
			short = "Há doze mil anos, uma seita secreta de feiticeiros elfos noturnos ergueu Eldre'Thalas para guardar os segredos arcanos mais preciosos da Rainha Azshara.",
			full = "Há doze mil anos, uma seita secreta de feiticeiros elfos noturnos ergueu Eldre'Thalas para guardar os segredos arcanos mais preciosos da Rainha Azshara. Entre seus Bem-nascidos, os arcanistas conhecidos como Shen'dralar viviam num esplendor discreto, e uma deles, Millicent Serene, criou o Fruto da Fertilidade, uma vinha cuja aura de crescimento e proteção permitia que toda a cidade florescesse.\n\nIsolados do Poço da Eternidade depois da Grande Cisão, os Bem-nascidos aprisionaram um demônio, Immol'thar, e tiraram seu poder desse cativeiro. Isso os sustentou por milhares de anos, até que o custo de mantê-lo preso ficou maior do que o que ele fornecia. Seu líder, o Príncipe Tortheldrin, respondeu voltando-se contra seu próprio povo, massacrando muitos deles para liberar poder suficiente para manter o resto vivo. Os sobreviventes se recolheram mais fundo nas ruínas que um dia governaram, abandonando o resto da cidade a quem quer que viesse habitá-la.\n\nAs pedras de Eldre'Thalas ainda estão de pé, com energia arcana presa nelas por uma arte de que ninguém mais se lembra, mantendo a forma de uma cidade que se alimentou do próprio povo para sobreviver.",
			source = "https://warcraft.wiki.gg/wiki/Dire_Maul",
		},
		["dream bough"] = {
			name = "Ramo de Morfeu",
			short = "Uma grande árvore se ergue de uma pequena ilha no meio do Lago Jademir, com raízes e galhos que abrigam um dos portais para o Sonho Esmeralda.",
			full = "Uma grande árvore se ergue de uma pequena ilha no meio do Lago Jademir, com raízes e galhos que abrigam um dos portais para o Sonho Esmeralda. A revoada verde a vigia, guardando o limiar contra qualquer um que queira mexer com o sonho lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Dream_Bough",
		},
		["feathermoon stronghold"] = {
			name = "Domínio de Plumaluna",
			short = "Ao largo do litoral oeste de Feralas, na Ilha de Sardor, fica uma fortaleza erguida no mar pela General Shandris Plumaluna, que há dez mil anos está ao lado de Tyrande Murmuréolo como seu braço direito entre as Sentinelas.",
			full = "Ao largo do litoral oeste de Feralas, na Ilha de Sardor, fica uma fortaleza erguida no mar pela General Shandris Plumaluna, que há dez mil anos está ao lado de Tyrande Murmuréolo como seu braço direito entre as Sentinelas. Ela deu seu nome à fortaleza, que ainda defende este trecho da costa de Kalimdor para os elfos noturnos.\n\nSó o mar a liga ao continente, com um barco fazendo a travessia da Costa Esquecida até o cais da ilha.",
			source = "https://warcraft.wiki.gg/wiki/Feathermoon_Stronghold_(Classic)",
		},
		["feral scar vale"] = {
			name = "Vale dos Abomináveis",
			short = "Na Selva Alta, no oeste de Feralas, fica o Vale dos Abomináveis, tomado pelos yetis abomináveis que lhe dão o nome.",
			full = "Na Selva Alta, no oeste de Feralas, fica o Vale dos Abomináveis, tomado pelos yetis abomináveis que lhe dão o nome.",
			source = "https://warcraft.wiki.gg/wiki/Feral_Scar_Vale",
		},
		["forgotten coast"] = {
			name = "Costa Esquecida",
			short = "A Costa Esquecida percorre todo o limite oeste de Feralas, onde a terra encontra o Mar Velado. Elementais da água surgem da arrebentação aqui, e gigantes do mar rondam o litoral.",
			full = "A Costa Esquecida percorre todo o limite oeste de Feralas, onde a terra encontra o Mar Velado. Elementais da água surgem da arrebentação aqui, e gigantes do mar rondam o litoral.\n\nUma aldeia de pescadores murlocs se agarra a esta costa. Sabe-se que pássaros mergulham e levam girinos, e a aldeia já sofreu ataques de humanos e de gnolls. Pior de todos são os ogros Gordunni, que a atacam há anos, arrastando murlocs para o cativeiro nas ruínas de Gládio Cruel. Uma dúzia ou mais foram levados assim, entre eles dois chamados Murrl e Murrgly.",
			source = "https://warcraft.wiki.gg/wiki/Forgotten_Coast",
		},
		["frayfeather highlands"] = {
			name = "Planalto Esfiapluma",
			short = "O Planalto Esfiapluma pertence aos hipogrifos Esfiapluma, que fazem ninhos nos lugares altos dali e dão nome à terra.",
			full = "O Planalto Esfiapluma pertence aos hipogrifos Esfiapluma, que fazem ninhos nos lugares altos dali e dão nome à terra. Entre os penhascos, seus ovos ficam escondidos em ninhos espalhados, guardados pelos bandos que circulam e chamam o planalto de lar.",
			source = "https://warcraft.wiki.gg/wiki/Frayfeather_Highlands",
		},
		["gordunni outpost"] = {
			name = "Assentamento Gordunni",
			short = "Nas montanhas ao norte do Pavilhão Lariss, o chão carrega a marca dos Gordunni. Onde o resto de Feralas é verde, o assentamento está murcho e marrom sob a presença dos ogros.",
			full = "Nas montanhas ao norte do Pavilhão Lariss, o chão carrega a marca dos Gordunni. Onde o resto de Feralas é verde, o assentamento está murcho e marrom sob a presença dos ogros.\n\nDuas cavernas marcam as colinas, uma pequena perto da entrada e um grande monte nos fundos, ambas ocupadas pelos Gordunni que reivindicam este chão arrasado.",
			source = "https://warcraft.wiki.gg/wiki/Gordunni_Outpost",
		},
		["grimtotem compound"] = {
			name = "Complexo do Temível Totem",
			short = "O Complexo do Temível Totem, a leste de Gládio Cruel, é um lar que os taurens Temível Totem construíram para si. Em sua parte sul fica uma grande jaula que mantém cativos dardejantes feéricos.",
			full = "O Complexo do Temível Totem, a leste de Gládio Cruel, é um lar que os taurens Temível Totem construíram para si. Em sua parte sul fica uma grande jaula que mantém cativos dardejantes feéricos. A leste da parte norte, gnolls montaram seus próprios acampamentos.",
			source = "https://warcraft.wiki.gg/wiki/Grimtotem_Compound",
		},
		["high wilderness"] = {
			name = "Selva Alta",
			short = "A Selva Alta se estende pelo oeste de Feralas, da Costa Esquecida até o Rio Verdantis.",
			full = "A Selva Alta se estende pelo oeste de Feralas, da Costa Esquecida até o Rio Verdantis. Ursos, lobos e hipogrifos percorrem suas árvores antigas, treants se erguem entre os bosques mais fundos, e yetis e ogros reivindicam os confins mais selvagens mais além.",
			source = "https://warcraft.wiki.gg/wiki/High_Wilderness",
		},
		["isle of dread"] = {
			name = "Ilha do Medo",
			short = "A Ilha do Medo fica ao largo da costa de Feralas, ao sul da Ilha de Sardor, com seu vale central cercado por todos os lados por penhascos intransponíveis, exceto por um único acesso no sudeste.",
			full = "A Ilha do Medo fica ao largo da costa de Feralas, ao sul da Ilha de Sardor, com seu vale central cercado por todos os lados por penhascos intransponíveis, exceto por um único acesso no sudeste. Dentro dessa bacia escondida vivem os quimerok, feras tocadas pelo arcano e devoradores, governados pelo Lorde Lakmaeran. Sua carne foi procurada para fins mais estranhos que a sobrevivência: derretida e remodelada, tornou-se uma ave monstruosa de mais de duzentos quilos devorada inteira pelo mago gnomo Narain Suavestilo.\n\nNa extremidade norte da ilha, uma caverna afunda na rocha diferente de tudo o que se conhece ali, profunda e estranha em sua feitura. Uma passagem secreta sob a água leva até uma câmara interna que não serve a nenhum propósito conhecido além de abrigar Lady Szallah em suas profundezas. A caverna e seus nagas são comandados pelo Lorde Shalzaru, cuja presença atraiu a atenção do Domínio de Plumaluna, desconfiado dos nagas tão perto de sua própria costa.",
			source = "https://warcraft.wiki.gg/wiki/Isle_of_Dread",
		},
		["jademir lake"] = {
			name = "Lago Jademir",
			short = "O Lago Jademir, no norte de Feralas, abriga em seu centro uma pequena ilha, o Ramo de Morfeu. Um portal para o Sonho Esmeralda fica ali, guardado por Lethlas e vários dracônidas verdes.",
			full = "O Lago Jademir, no norte de Feralas, abriga em seu centro uma pequena ilha, o Ramo de Morfeu. Um portal para o Sonho Esmeralda fica ali, guardado por Lethlas e vários dracônidas verdes. Dragonetes verdes infectados rondam a margem noroeste do lago.",
			source = "https://warcraft.wiki.gg/wiki/Jademir_Lake",
		},
		["lariss pavilion"] = {
			name = "Pavilhão Lariss",
			short = "O Pavilhão Lariss, de cantaria dos elfos noturnos, fica ao norte da Aldeia Mojache, em Feralas. Suas dríades eram pacíficas, mas o Pesadelo Esmeralda as corrompeu, e agora elas atacam qualquer um que se aproxime.",
			full = "O Pavilhão Lariss, de cantaria dos elfos noturnos, fica ao norte da Aldeia Mojache, em Feralas. Suas dríades eram pacíficas, mas o Pesadelo Esmeralda as corrompeu, e agora elas atacam qualquer um que se aproxime.\n\nSob o Pavilhão fica uma passagem oculta para baixo, conhecida por Azj'Tordin, um Bem-nascido que rompeu com o Príncipe Tortheldrin e fugiu de Gládio Cruel por ela. Ele escapou com pouca coisa, pois um diabrete chamado Pusillin roubou seu livro de encantamentos antes que ele pudesse sumir lá embaixo, e ele permanece naquela passagem desde então.",
			source = "https://warcraft.wiki.gg/wiki/Lariss_Pavilion",
		},
		["lower wilds"] = {
			name = "Baixio Selvagem",
			short = "O Baixio Selvagem ocupa o leste de Feralas, onde treants se movem entre as árvores e dríades corrompidas caminham, com seus dons tornados estranhos.",
			full = "O Baixio Selvagem ocupa o leste de Feralas, onde treants se movem entre as árvores e dríades corrompidas caminham, com seus dons tornados estranhos.",
			source = "https://warcraft.wiki.gg/wiki/Lower_Wilds",
		},
		["oneiros"] = {
			name = "Oneiros",
			short = "Ao sul do Lago Jademir, no norte de Feralas, ficam as ruínas de Oneiros.",
			full = "Ao sul do Lago Jademir, no norte de Feralas, ficam as ruínas de Oneiros.",
			source = "https://warcraft.wiki.gg/wiki/Oneiros",
		},
		["rage scar hold"] = {
			name = "Bastilha Cortifúria",
			short = "A Bastilha Cortifúria é uma caverna escavada em Feralas, que abriga os yetis mais ferozes da área.",
			full = "A Bastilha Cortifúria é uma caverna escavada em Feralas, que abriga os yetis mais ferozes da área. Espalhados lá dentro há livros e símbolos estranhos, indícios de estudo arcano, ou talvez os restos de algum mago infeliz que encontrou seu fim ali.",
			source = "https://warcraft.wiki.gg/wiki/Rage_Scar_Hold",
		},
		["ruins of isildien"] = {
			name = "Ruínas de Isildien",
			short = "As Ruínas de Isildien são o que resta de uma grande cidade dos elfos noturnos, destruída há dez mil anos. Os ogros Gordunni agora se aninham entre suas colunatas caídas, reinando sobre pedras erguidas por mãos muito mais antigas que as suas.",
			full = "As Ruínas de Isildien são o que resta de uma grande cidade dos elfos noturnos, destruída há dez mil anos. Os ogros Gordunni agora se aninham entre suas colunatas caídas, reinando sobre pedras erguidas por mãos muito mais antigas que as suas.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Isildien",
		},
		["ruins of ravenwind"] = {
			name = "Ruínas dos Ventos Corvejantes",
			short = "O norte de Feralas guarda as pedras partidas dos Ventos Corvejantes, erguidas há muito tempo pelos Bem-nascidos dos kaldorei, assim como Gládio Cruel foi erguido em outro lugar.",
			full = "O norte de Feralas guarda as pedras partidas dos Ventos Corvejantes, erguidas há muito tempo pelos Bem-nascidos dos kaldorei, assim como Gládio Cruel foi erguido em outro lugar. Pouco dessa glória ainda está de pé. As harpias Northspring tomaram as ruínas para si, fazendo ninhos entre as colunas caídas e os salões vazios.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Ravenwind",
		},
		["ruins of solarsal"] = {
			name = "Ruínas de Solarsal",
			short = "A sudoeste do Domínio de Plumaluna, na Ilha de Sardor, as velhas pedras de Solarsal ainda estão de pé entre as árvores, obra dos elfos noturnos há muito abandonada à natureza selvagem.",
			full = "A sudoeste do Domínio de Plumaluna, na Ilha de Sardor, as velhas pedras de Solarsal ainda estão de pé entre as árvores, obra dos elfos noturnos há muito abandonada à natureza selvagem. Os nagas Hatecrest ocupam as ruínas agora, serpenteando entre as colunas quebradas por onde os elfos um dia caminharam.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Solarsal",
		},
		["sardor isle"] = {
			name = "Ilha de Sardor",
			short = "A Ilha de Sardor se ergue ao largo da costa de Feralas, um pequeno refúgio mantido pelos elfos noturnos sob o comando de Shandris Plumaluna.",
			full = "A Ilha de Sardor se ergue ao largo da costa de Feralas, um pequeno refúgio mantido pelos elfos noturnos sob o comando de Shandris Plumaluna. Nagas se infiltraram em suas praias, e lobos percorrem os lugares selvagens que restam, por isso a vigília da fortaleza nunca fica ociosa.",
			source = "https://warcraft.wiki.gg/wiki/Sardor_Isle",
		},
		["shalzarus lair"] = {
			name = "Covil de Shalzaru",
			short = "Ao sul da ilha do Domínio de Plumaluna, na extremidade norte da Ilha do Medo, uma caverna sinuosa abriga duas câmaras ligadas por um curso d'água.",
			full = "Ao sul da ilha do Domínio de Plumaluna, na extremidade norte da Ilha do Medo, uma caverna sinuosa abriga duas câmaras ligadas por um curso d'água. Feiticeiras e guardas serpentinos Hatecrest preenchem toda a sua extensão. Lá no fundo vive Shalzaru, senhor dos Hatecrest.",
			source = "https://warcraft.wiki.gg/wiki/Shalzaru's_Lair",
		},
		["thalanaar"] = {
			name = "Thalanaar",
			short = "Thalanaar repousa tranquila, um pequeno posto avançado com pouco que atraia viajantes além de seu propósito.",
			full = "Thalanaar repousa tranquila, um pequeno posto avançado com pouco que atraia viajantes além de seu propósito. Caryssia Caçaluna exerce seu ofício aqui, trabalhando peles e couro à antiga maneira tribal, um dos poucos motivos que alguém tem para se demorar ali.",
			source = "https://warcraft.wiki.gg/wiki/Thalanaar",
		},
		["twin colossals"] = {
			name = "Colossos Gêmeos",
			short = "Os Colossos Gêmeos se erguem no limite oeste de Feralas, duas montanhas verticais tão altas que são o ponto mais alto da região, com a estrada para a Desolação passando pelo vão entre elas.",
			full = "Os Colossos Gêmeos se erguem no limite oeste de Feralas, duas montanhas verticais tão altas que são o ponto mais alto da região, com a estrada para a Desolação passando pelo vão entre elas.\n\nNo topo do pico leste fica um pequeno lago profundo, com água calma o bastante para pescar, onde se pode encontrar Gregan Cospechope. Do cume, toda a região se abre lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Twin_Colossals",
		},
		["verdantis river"] = {
			name = "Rio Verdantis",
			short = "O Rio Verdantis serpenteia pelo centro de Feralas, a sudeste das ruínas de Gládio Cruel, traçando um fio verde e tranquilo pela floresta emaranhada.",
			full = "O Rio Verdantis serpenteia pelo centro de Feralas, a sudeste das ruínas de Gládio Cruel, traçando um fio verde e tranquilo pela floresta emaranhada. Suas águas abrigam o atum ahi de Feralas, que não se encontra em nenhum outro lugar do mundo.",
			source = "https://warcraft.wiki.gg/wiki/Verdantis_River",
		},
		["wildwind lake"] = {
			name = "Lago Vento Selvagem",
			short = "O Lago Vento Selvagem fica perto da Aldeia Mojache, em Feralas, com águas tranquilas sob os ermos ao redor, sem abrigar nada mais notável que o que nada sob sua superfície e a quietude que paira sobre o acampamento próximo.",
			full = "O Lago Vento Selvagem fica perto da Aldeia Mojache, em Feralas, com águas tranquilas sob os ermos ao redor, sem abrigar nada mais notável que o que nada sob sua superfície e a quietude que paira sobre o acampamento próximo.",
			source = "https://warcraft.wiki.gg/wiki/Wildwind_Lake",
		},
		["woodpaw den"] = {
			name = "Covil dos Patábua",
			short = "No coração de Feralas fica o Covil dos Patábua, toca dos gnolls Patábua. Aqui os Alfas Patábua dominam seus semelhantes, numerosos no terreno em quantidade que poucos forasteiros se arriscam a testar.",
			full = "No coração de Feralas fica o Covil dos Patábua, toca dos gnolls Patábua. Aqui os Alfas Patábua dominam seus semelhantes, numerosos no terreno em quantidade que poucos forasteiros se arriscam a testar. Ao sul do covil ficam as Ruínas Névoa Negra, vizinhas silenciosas do alarido dos gnolls.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Den",
		},
		["woodpaw hills"] = {
			name = "Serra dos Patábua",
			short = "A Serra dos Patábua é coberta de floresta densa, lar dos gnolls do clã Patábua.",
			full = "A Serra dos Patábua é coberta de floresta densa, lar dos gnolls do clã Patábua. Seu domínio sobre a terra está escapando, pois nos confins mais a sudeste o chão se abriu no que hoje se chama Profundeza Atormentada, e as coisas que irromperam em enxame de baixo da terra vêm expulsando os gnolls de seu próprio território. Onde antes os Alfas Patábua lideravam a tribo a partir dos acampamentos, agora só resistem no Covil dos Patábua.",
			source = "https://warcraft.wiki.gg/wiki/Woodpaw_Hills",
		},
		["writhing deep"] = {
			name = "Profundeza Atormentada",
			short = "A Profundeza Atormentada, no sudeste de Feralas, está entregue à Colmeia Zukk'ash. Os silitídeos dali envenenaram o chão ao redor, levando os gnolls próximos ao frenesi e para o norte, contra a Aldeia Mojache.",
			full = "A Profundeza Atormentada, no sudeste de Feralas, está entregue à Colmeia Zukk'ash. Os silitídeos dali envenenaram o chão ao redor, levando os gnolls próximos ao frenesi e para o norte, contra a Aldeia Mojache.\n\nGuerreiros da aldeia abateram os silitídeos da superfície, mas o coração da colmeia sob a terra, repleto de ovos, nunca foi tocado. Rexxar adverte que é só uma questão de tempo até a próxima geração eclodir.",
			source = "https://warcraft.wiki.gg/wiki/Writhing_Deep",
		},
	},
	-- Pântano Vadeoso: 24 subzones
	[1445] = {
		["alcaz island"] = {
			name = "Ilha Alcaz",
			short = "A Ilha Alcaz se ergue do mar ao largo do Pântano Vadeoso, coberta por um verde tropical que não tinha nada que crescer tão perto da lama cinzenta do pântano, como se algum poder mais antigo e mais quente um dia tivesse tomado este chão e nunca o tivesse soltado.",
			full = "A Ilha Alcaz se ergue do mar ao largo do Pântano Vadeoso, coberta por um verde tropical que não tinha nada que crescer tão perto da lama cinzenta do pântano, como se algum poder mais antigo e mais quente um dia tivesse tomado este chão e nunca o tivesse soltado. Os nagas Strashaz a ocupam, com mirmidões e sereias apinhados ao longo de suas margens.\n\nAinda assim, durante a guerra contra Ahn'Qiraj, o Doutor Weavil chegou à ilha numa máquina voadora e instalou seus lacaios no alto da colina, transformando um trecho da costa numa oficina de invenções tecnológicas.",
			source = "https://warcraft.wiki.gg/wiki/Alcaz_Island",
		},
		["beezils wreck"] = {
			name = "Destroços de Beezil",
			short = "Um zepelim goblin que seguia para o sul com suprimentos caiu nos confins mais profundos do Pântano Vadeoso, a leste da Fazenda da Tabetha.",
			full = "Um zepelim goblin que seguia para o sul com suprimentos caiu nos confins mais profundos do Pântano Vadeoso, a leste da Fazenda da Tabetha. Seu casco jaz partido na lama, com a carga espalhada entre os destroços e Propulsores de Seafório ainda caídos onde tombaram.",
			source = "https://warcraft.wiki.gg/wiki/Beezil's_Wreck",
		},
		["bloodfen burrow"] = {
			name = "Antro do Dinossangue",
			short = "Uma caverna no sudoeste do Pântano Vadeoso abriga um número incomum de raptores Dinossangue. Diante da entrada estão os restos de algum povoado, despedaçado pelas criaturas, com seu povo agora perdido na lama do pântano.",
			full = "Uma caverna no sudoeste do Pântano Vadeoso abriga um número incomum de raptores Dinossangue. Diante da entrada estão os restos de algum povoado, despedaçado pelas criaturas, com seu povo agora perdido na lama do pântano. Em algum lugar lá dentro, uma parte do Enigma de Cortello espera entre os destroços.",
			source = "https://warcraft.wiki.gg/wiki/Bloodfen_Burrow",
		},
		["bluefen"] = {
			name = "Charneca Azul",
			short = "A Charneca Azul fica no norte do Pântano Vadeoso, com seu terreno baixo coberto de juncos e água parada.",
			full = "A Charneca Azul fica no norte do Pântano Vadeoso, com seu terreno baixo coberto de juncos e água parada. Aranhas, crocoliscos, raptores e aves do pântano se movem pela charneca sem controle, e infiltradores de Theramore passam por ela sem ser vistos entre os juncos.",
			source = "https://warcraft.wiki.gg/wiki/Bluefen",
		},
		["brackenwall village"] = {
			name = "Aldeia Muralha Verde",
			short = "A Aldeia Muralha Verde se ergue entre cabanas e montes de ogros no noroeste do Pântano Vadeoso, lar dos ogros Pedramalho e jurada à Horda.",
			full = "A Aldeia Muralha Verde se ergue entre cabanas e montes de ogros no noroeste do Pântano Vadeoso, lar dos ogros Pedramalho e jurada à Horda. Nem sempre foi o lar deles. Os Pedramalho tinham uma aldeia ao sul, até que a revoada negra caiu sobre ela e a reduziu a ruínas em chamas. O Suserano Mok'Morokk, que assumira a liderança depois de Rexxar, levou os sobreviventes para o norte e ergueu a Muralha Verde em seu lugar.\n\nMok'Morokk construiu seu governo sobre ficar parado. Quando o ogro Draz'Zilb descobriu que os atacantes eram a ninhada de Onyxia e lhe levou a verdade, Mok'Morokk não quis agir. A Muralha Verde estava segura, nenhum dragão negro vivia ali, e isso lhe bastava. Draz'Zilb não deixa o assunto morrer e pondera em silêncio o que seria preciso para ver o Suserano cair e os Pedramalho serem levados de volta ao que perderam.",
			source = "https://warcraft.wiki.gg/wiki/Brackenwall_Village",
		},
		["darkmist cavern"] = {
			name = "Caverna Névoa Negra",
			short = "Uma pequena mina fica no noroeste do Pântano Vadeoso, há muito entregue a aranhas que cresceram assustadoramente na escuridão.",
			full = "Uma pequena mina fica no noroeste do Pântano Vadeoso, há muito entregue a aranhas que cresceram assustadoramente na escuridão. O povo do pântano as chama de Aranhas da Névoa Negra, e a caverna, por sua vez, de Névoa Negra, embora ninguém saiba dizer qual nome veio primeiro, o do lugar ou o das criaturas que o tomaram.\n\nDiante da boca da mina ficam as ruínas de pequenas casas, meio afundadas no chão úmido, tudo o que resta de algum povoado há muito esquecido.",
			source = "https://warcraft.wiki.gg/wiki/Darkmist_Cavern",
		},
		["den of flame"] = {
			name = "Antro das Chamas",
			short = "O Antro das Chamas foi erguido pelos ogros Pedramalho como seu monte, e sua cantaria ainda carrega o ofício deles. Fica a oeste das Ruínas Pedramalho, em terras do pântano reivindicadas por Onyxia.",
			full = "O Antro das Chamas foi erguido pelos ogros Pedramalho como seu monte, e sua cantaria ainda carrega o ofício deles. Fica a oeste das Ruínas Pedramalho, em terras do pântano reivindicadas por Onyxia.\n\nOs ogros já se foram dali. Dracônicos negros tomaram o antro, mantendo-o como ninho da revoada negra. Só a velha cantaria e o estandarte Pedramalho, deixado de pé lá dentro, lembram seus primeiros construtores.",
			source = "https://warcraft.wiki.gg/wiki/Den_of_Flame",
		},
		["dragonmurk"] = {
			name = "Draconumbra",
			short = "No sul do Pântano Vadeoso fica um trecho de chão fétido chamado Draconumbra, repleto de dragonetes e crias da revoada negra.",
			full = "No sul do Pântano Vadeoso fica um trecho de chão fétido chamado Draconumbra, repleto de dragonetes e crias da revoada negra. Perto dali ficam o Antro das Chamas e as Ruínas Pedramalho, ambos igualmente tomados por dracônidas negros.",
			source = "https://warcraft.wiki.gg/wiki/Dragonmurk",
		},
		["dreadmurk shore"] = {
			name = "Costa Tenebrosa",
			short = "A costa entre a Ilha Theramore e a Fortaleza da Guardanorte está repleta de murlocs da tribo Lamapina, que reivindicam o litoral e suas ilhas espalhadas como seus.",
			full = "A costa entre a Ilha Theramore e a Fortaleza da Guardanorte está repleta de murlocs da tribo Lamapina, que reivindicam o litoral e suas ilhas espalhadas como seus. Tartarugas marinhas e outras criaturas dividem com eles as águas ao redor.",
			source = "https://warcraft.wiki.gg/wiki/Dreadmurk_Shore",
		},
		["dustwallow bay"] = {
			name = "Baía de Vadeoso",
			short = "A Baía de Vadeoso faz parte do Grande Mar e avança sobre a costa leste do Pântano Vadeoso, a oeste da Ilha Theramore.",
			full = "A Baía de Vadeoso faz parte do Grande Mar e avança sobre a costa leste do Pântano Vadeoso, a oeste da Ilha Theramore. Numa pequena ilha ao largo da baía, na Enseada da Fúria das Marés, o pescador Nat Pagle mantém sua vigília solitária sobre a água.",
			source = "https://warcraft.wiki.gg/wiki/Dustwallow_Bay",
		},
		["emberstrifes den"] = {
			name = "Covil de Ardeluta",
			short = "Uma caverna ampla se abre para o fétido Pântano da Serpe, lar do draco negro Ardeluta.",
			full = "Uma caverna ampla se abre para o fétido Pântano da Serpe, lar do draco negro Ardeluta. Aqui ele testa jovens dragonetes negros com provas de resistência e crueldade, pois só os que se provam dignos podem seguir adiante e entrar no Covil da Onyxia.",
			source = "https://warcraft.wiki.gg/wiki/Emberstrife's_Den",
		},
		["foothold citadel"] = {
			name = "Cidadela do Esteio",
			short = "A Cidadela do Esteio fica no coração da Ilha Theramore, quartel-general da Guarda de Theramore.",
			full = "A Cidadela do Esteio fica no coração da Ilha Theramore, quartel-general da Guarda de Theramore.\n\nFoi aqui que Daelin Proudmore encontrou seu fim, quando as forças de Thrall invadiram Theramore, conduzidas ao interior da fortaleza por Rexxar e seus companheiros. O almirante que desafiou a paz de sua filha Jaina com os orcs caiu entre estas muralhas.",
			source = "https://warcraft.wiki.gg/wiki/Foothold_Citadel",
		},
		["lost point"] = {
			name = "Posto Perdido",
			short = "O Posto Perdido, uma torre de observação decrépita erguida um dia por Theramore no oeste do Pântano Vadeoso, já não serve a seus construtores.",
			full = "O Posto Perdido, uma torre de observação decrépita erguida um dia por Theramore no oeste do Pântano Vadeoso, já não serve a seus construtores. Desertores de Theramore o ocupam agora, liderados por Balos Xavier, que sabe do envolvimento do Recruta Remos no sequestro de uma pessoa de grande importância.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Point",
		},
		["north point tower"] = {
			name = "Torre Norte",
			short = "A Torre Norte vigia o norte do Pântano Vadeoso ao lado de uma estrada muito movimentada, ocupada por um contingente considerável de guardas de Theramore.",
			full = "A Torre Norte vigia o norte do Pântano Vadeoso ao lado de uma estrada muito movimentada, ocupada por um contingente considerável de guardas de Theramore. Desde que desertores tomaram o Posto Perdido, esta torre é o posto avançado mais distante de Theramore.",
			source = "https://warcraft.wiki.gg/wiki/North_Point_Tower",
		},
		["onyxias lair"] = {
			name = "Covil da Onyxia",
			short = "A passagem para o covil de Onyxia tem a forma da própria mandíbula escancarada da mãe da ninhada. Além dela, o caminho é margeado por magma, com o chão rachado e brilhando com o fogo que vem de baixo.",
			full = "A passagem para o covil de Onyxia tem a forma da própria mandíbula escancarada da mãe da ninhada. Além dela, o caminho é margeado por magma, com o chão rachado e brilhando com o fogo que vem de baixo. O teto de pedra acima geme e se move, soltando constantes quedas de rochas, e as próprias paredes vertem lava onde o calor não pode ser contido. A própria Onyxia escavou este lugar, no fundo da Draconumbra, o lúgubre pântano dentro do Pântano Vadeoso.\n\nEla não é como seus parentes. Onde seu pai governa pela força bruta e seu irmão molda abominações retorcidas para cumprir suas ordens, Onyxia age por sussurros e encanto, deleitando-se com a política emaranhada dos mortais e dobrando-os discretamente a seus próprios propósitos. Por um tempo usou um nome roubado, chamando a si mesma de Katrana Prestor, e sob esse disfarce se enroscou no coração da corte de Ventobravo, trabalhando para desfazê-la por dentro. Foi o Marechal Vilasboas quem viu através da máscara e a chamou pelo que ela era. Desmascarada, ela fugiu da cidade e voltou a seu salão ardente sob o pântano, onde permanece, ainda guardada por seus próprios parentes, a revoada negra.",
			source = "https://warcraft.wiki.gg/wiki/Onyxia's_Lair",
		},
		["quagmire"] = {
			name = "O Atoleiro",
			short = "O Atoleiro é o coração encharcado do Pântano Vadeoso, estendendo-se entre o Posto Perdido e a Baía de Vadeoso, cercado pela Aldeia Muralha Verde ao norte e pela Draconumbra ao sul.",
			full = "O Atoleiro é o coração encharcado do Pântano Vadeoso, estendendo-se entre o Posto Perdido e a Baía de Vadeoso, cercado pela Aldeia Muralha Verde ao norte e pela Draconumbra ao sul.\n\nCrocoliscos espreitam em sua água negra, gosmas e aranhas rastejam por seus juncos, e taurens Temível Totem ocupam terreno aqui, longe de qualquer parente que os reivindique. É melhor atravessá-lo do que se demorar nele.",
			source = "https://warcraft.wiki.gg/wiki/Quagmire",
		},
		["sentry point"] = {
			name = "Pontal de Vigília",
			short = "O Pontal de Vigília se ergue logo depois da ponte que sai de Theramore, uma torre de observação construída pela cidadela para vigiar a estrada lá embaixo. Continua intacta, mantendo sua vigília silenciosa sobre todos os que passam rumo à cidade.",
			full = "O Pontal de Vigília se ergue logo depois da ponte que sai de Theramore, uma torre de observação construída pela cidadela para vigiar a estrada lá embaixo. Continua intacta, mantendo sua vigília silenciosa sobre todos os que passam rumo à cidade.",
			source = "https://warcraft.wiki.gg/wiki/Sentry_Point",
		},
		["shady rest inn"] = {
			name = "Estalagem Pouso do Umbral",
			short = "A Estalagem Pouso do Umbral ficava perto da fronteira entre o Pântano Vadeoso e os Sertões Meridionais, uma parada de estrada construída por humanos.",
			full = "A Estalagem Pouso do Umbral ficava perto da fronteira entre o Pântano Vadeoso e os Sertões Meridionais, uma parada de estrada construída por humanos.\n\nEla foi queimada até o chão sem aviso. Dois homens poderiam ter apontado os culpados, Paval Reethe e o Tenente Caldwell, mas ambos foram mortos antes que qualquer um deles pudesse contar a verdade, e o incêndio ficou sem solução.",
			source = "https://warcraft.wiki.gg/wiki/Shady_Rest_Inn",
		},
		["stonemaul ruins"] = {
			name = "Ruínas Pedramalho",
			short = "A Aldeia Pedramalho ficava no Pântano Vadeoso, lar dos ogros do clã Pedramalho, até que o senhor da guerra Kor'gall, tendo se apoderado do antigo machado orc Serathil, tomou o clã e o governou com brutalidade.",
			full = "A Aldeia Pedramalho ficava no Pântano Vadeoso, lar dos ogros do clã Pedramalho, até que o senhor da guerra Kor'gall, tendo se apoderado do antigo machado orc Serathil, tomou o clã e o governou com brutalidade. Foi aqui que Rexxar chegou e teve a entrada recusada, abrindo caminho à força. Kor'gall lhe ofereceu um lugar no clã se ele sobrevivesse ao Corredor, um vale repleto de feras mortais. Rexxar resistiu e voltou, e foi feito Pedramalho. Quando Kor'gall se recusou a ceder o clã para a guerra da Horda contra Kul Tiraz, Rexxar o desafiou pela liderança e o matou, depois levou ele próprio os Pedramalho à guerra. Em seguida, nomeou Mok'Morokk para governar em seu lugar e partiu.\n\nMok'Morokk não governou como Rexxar. Tirava de seu povo em vez de servi-lo e, quando a ninhada de Onyxia desceu sobre a aldeia e a tomou, ele levou os sobreviventes para um lugar seguro e se contentou em ficar por lá, longe dos dragões, em vez de lutar para retomar o antigo lar.\n\nAs ruínas agora ficam dentro da Draconumbra, infestadas de dracônidas Jubafogo.",
			source = "https://warcraft.wiki.gg/wiki/Stonemaul_Ruins",
		},
		["swamplight manor"] = {
			name = "Casarão do Pantanal Iluminado",
			short = "O Casarão do Pantanal Iluminado é uma casa modesta no Morro das Bruxas, no Pântano Vadeoso, lar do cozinheiro Zé \"Olho de Lama\".",
			full = "O Casarão do Pantanal Iluminado é uma casa modesta no Morro das Bruxas, no Pântano Vadeoso, lar do cozinheiro Zé \"Olho de Lama\".\n\nNo jardim do lado de fora, um monte de terra revolvida esconde algo que a culinária de Zé nunca explica: um relatório enterrado por um espião orc, deixado sob o solo para guardar seu segredo de olhos curiosos.",
			source = "https://warcraft.wiki.gg/wiki/Swamplight_Manor",
		},
		["theramore isle"] = {
			name = "Ilha Theramore",
			short = "Depois da Terceira Guerra, Jaina Proudmore levou os sobreviventes de Lordaeron pelo mar até Kalimdor.",
			full = "Depois da Terceira Guerra, Jaina Proudmore levou os sobreviventes de Lordaeron pelo mar até Kalimdor. Numa ilha rochosa ao largo do Pântano Vadeoso, eles ergueram Theramore, uma cidade murada destinada a abrigar o que restava da Aliança numa terra estranha.\n\nA cidade é cercada por uma muralha retangular pontilhada de torres de canhão, interrompida apenas no porto, que é guardado por duas torres de observação. Em seu coração se ergue a Torre de Jaina, a Cidadela, o edifício mais alto de Theramore, com seus muitos andares de piso de madeira ligados por escadas em caracol e protegidos contra ataques, abrigando os aposentos particulares de Jaina, sua biblioteca e a pequena sala do trono da cidade. Perto dela fica a Cidadela do Esteio, o quartel da guarda, onde soldados treinam contra bonecos de treino e recrutas lutam sob os olhos de sacerdotes prontos para invocar a Luz no momento em que alguém se machuca.\n\nO pântano oferece solo pobre e madeira ruim, e os marinheiros de Theramore resmungam que os carvalhos que os orcs cortam acima de Orgrimmar são muito melhores que qualquer coisa que Vadeoso oferece. Mesmo assim, humanos e orcs trocam peixe pelo excedente das colheitas de Durotar e, por enquanto, a criminalidade da cidade é baixa e seu povo vive, em sua maior parte, em paz.",
			source = "https://warcraft.wiki.gg/wiki/Theramore_Isle",
		},
		["tidefury cove"] = {
			name = "Enseada da Fúria das Marés",
			short = "A Enseada da Fúria das Marés fica no fim da Baía de Vadeoso, ao sul da Ilha Theramore, com as águas pontilhadas de pequenas ilhas e recifes escondidos. É uma água traiçoeira para navegar.",
			full = "A Enseada da Fúria das Marés fica no fim da Baía de Vadeoso, ao sul da Ilha Theramore, com as águas pontilhadas de pequenas ilhas e recifes escondidos. É uma água traiçoeira para navegar. Dois navios jazem destroçados em seus baixios, entregues agora a makruras errantes.\n\nEntre suas ilhotas fica o Desembarque do Nat, lar do pescador Nat Pagle.",
			source = "https://warcraft.wiki.gg/wiki/Tidefury_Cove",
		},
		["witch hill"] = {
			name = "Morro das Bruxas",
			short = "O Casarão do Pantanal Iluminado fica no centro do Morro das Bruxas, lar de Zé \"Olho de Lama\". Os murlocs Lamapina mantêm seus acampamentos perto dali, no lodaçal.",
			full = "O Casarão do Pantanal Iluminado fica no centro do Morro das Bruxas, lar de Zé \"Olho de Lama\". Os murlocs Lamapina mantêm seus acampamentos perto dali, no lodaçal.",
			source = "https://warcraft.wiki.gg/wiki/Witch_Hill",
		},
		["wyrmbog"] = {
			name = "Pântano da Serpe",
			short = "Ao sul da Draconumbra, no Pântano Vadeoso, o lodaçal se adensa no Pântano da Serpe.",
			full = "Ao sul da Draconumbra, no Pântano Vadeoso, o lodaçal se adensa no Pântano da Serpe. Dragões negros fazem seu lar aqui, e a terra se abre em dois lugares ocultos: a entrada do Covil de Ardeluta e o covil da própria Onyxia.",
			source = "https://warcraft.wiki.gg/wiki/Wyrmbog",
		},
	},
	-- Tanaris: 23 subzones
	[1446] = {
		["abyssal sands"] = {
			name = "Areias Abissais",
			short = "As areias daqui ficam em Tanaris, um deserto que se estende em todas as direções.",
			full = "As areias daqui ficam em Tanaris, um deserto que se estende em todas as direções.",
			source = "https://warcraft.wiki.gg/wiki/Abyssal_Sands",
		},
		["broken pillar"] = {
			name = "Pilar Partido",
			short = "Ao sul de Geringontzan, perto das Areias Abissais, fica um pequeno aglomerado de ruínas trolls conhecido como Pilar Partido.",
			full = "Ao sul de Geringontzan, perto das Areias Abissais, fica um pequeno aglomerado de ruínas trolls conhecido como Pilar Partido. Ali o cientista goblin Marlon Catarrebite montou seu acampamento, procurando entre as pedras caídas respostas próprias.",
			source = "https://warcraft.wiki.gg/wiki/Broken_Pillar",
		},
		["caverns of time"] = {
			name = "Cavernas do Tempo",
			short = "As Cavernas do Tempo ficam sob as areias do leste de Tanaris, um labirinto sinuoso selado contra o mundo lá em cima. Aqui a revoada bronze vigia os caminhos ramificados do próprio tempo.",
			full = "As Cavernas do Tempo ficam sob as areias do leste de Tanaris, um labirinto sinuoso selado contra o mundo lá em cima. Aqui a revoada bronze vigia os caminhos ramificados do próprio tempo. Desde que o mundo era jovem, esse tem sido seu encargo sagrado, imposto pelos titãs: guardar as cavernas contra a intrusão dos mortais, pois a interferência de mãos menores poderia desfazer o fluxo da história. No coração das cavernas fica uma grande ampulheta.\n\nNozdormu, o Aspecto do Tempo, vive aqui entre sua revoada, dedicando-se a um passatempo particular: colecionar artefatos raros. Depois da Segunda Guerra, o mago Krasus chegou ao covil de Nozdormu por meio de uma Rosa dos Éons, um dispositivo que lhe permitia atravessar a distância num instante. Nozdormu ficou descontente com a intrusão, pois ela o perturbou no meio de sua coleção, e fez seu descontentamento ser notado.",
			source = "https://warcraft.wiki.gg/wiki/Caverns_of_Time",
		},
		["dunemaul compound"] = {
			name = "Complexo Dunamalho",
			short = "O Complexo Dunamalho é o monte dos ogros Dunamalho, espalhado pelas areias de Tanaris, onde o clã se reúne em seus abrigos de terra sob o sol.",
			full = "O Complexo Dunamalho é o monte dos ogros Dunamalho, espalhado pelas areias de Tanaris, onde o clã se reúne em seus abrigos de terra sob o sol.",
			source = "https://warcraft.wiki.gg/wiki/Dunemaul_Compound",
		},
		["eastmoon ruins"] = {
			name = "Ruínas de Lunaleste",
			short = "Terraços de pedra e pilares rachados marcam as Ruínas de Lunaleste, a oeste da Fenda Hazzali, em Tanaris, tudo o que resta de um povoado troll abandonado há muito tempo.",
			full = "Terraços de pedra e pilares rachados marcam as Ruínas de Lunaleste, a oeste da Fenda Hazzali, em Tanaris, tudo o que resta de um povoado troll abandonado há muito tempo. Os ogros Dunamalho tomaram a cantaria em ruínas depois dos trolls e ainda a ocupam.",
			source = "https://warcraft.wiki.gg/wiki/Eastmoon_Ruins",
		},
		["gadgetzan"] = {
			name = "Geringontzan",
			short = "Geringontzan se ergue do deserto do norte de Tanaris sob um manto permanente de fumaça negra, a capital do Cartel Bondebico, o maior dos cartéis goblins.",
			full = "Geringontzan se ergue do deserto do norte de Tanaris sob um manto permanente de fumaça negra, a capital do Cartel Bondebico, o maior dos cartéis goblins. Aqui o credo dos goblins governa tudo: o lucro acima da lealdade. Tanto a Horda quanto a Aliança reconhecem oficialmente a cidade como território neutro, e leões de chácara goblins patrulham suas ruas, prontos para transformar em polpa qualquer tolo que traga a guerra para um lugar construído sobre o comércio. São as carteiras, e não as bandeiras, que decidem quem é bem-vindo.\n\nEssa neutralidade nunca agradou a todos. Os bandidos Wastewander tomaram as Ruínas da Sombrassolar e o Campo das Minas d'Água, a nordeste. Os goblins não davam a mínima para as ruínas antigas, mas o Campo das Minas d'Água era outra história: as torres d'água erguidas e mantidas ali pela Companhia de Águas de Geringontzan, sob o sol escaldante do deserto, eram o ouro líquido que mantinha a cidade viva. Os goblins não iam entregar torres pelas quais haviam suado, e assim mercenários dos cantos mais distantes do mundo foram atraídos para defender a água de Geringontzan contra os bandidos que queriam vê-la cair.",
			source = "https://warcraft.wiki.gg/wiki/Gadgetzan",
		},
		["gaping chasm"] = {
			name = "Fenda Hazzali",
			short = "A Fenda Hazzali fervilha de silitídeos Hazzali, com seus complexos de colmeias crivando a rocha no sudeste de Tanaris.",
			full = "A Fenda Hazzali fervilha de silitídeos Hazzali, com seus complexos de colmeias crivando a rocha no sudeste de Tanaris.\n\nO Topógrafo Sênior Secamolha certa vez enviou seu subordinado, Scrimshank, fenda abaixo para fazer o levantamento dela. Scrimshank nunca mais saiu. Morreu entre as colmeias, e apenas seu equipamento foi recuperado depois e levado de volta a Secamolha, que o mandara para a morte sem jamais saber disso.",
			source = "https://warcraft.wiki.gg/wiki/Gaping_Chasm",
		},
		["lands end beach"] = {
			name = "Praia do Fim do Mundo",
			short = "A Praia do Fim do Mundo fica no ponto mais ao sul de Tanaris, onde o canto sudeste de Kalimdor encontra o mar. A praia é tranquila, marcada principalmente pelas criaturas que a percorrem.",
			full = "A Praia do Fim do Mundo fica no ponto mais ao sul de Tanaris, onde o canto sudeste de Kalimdor encontra o mar. A praia é tranquila, marcada principalmente pelas criaturas que a percorrem. Planadores das ondas e caranguejos das dunas escolhem seu caminho pelo trecho leste da areia, sem ser perturbados.",
			source = "https://warcraft.wiki.gg/wiki/Land's_End_Beach",
		},
		["lost rigger cove"] = {
			name = "Enseada do Armador Perdido",
			short = "Escondida atrás de montanhas por três lados, a Enseada do Armador Perdido abriga o porto dos Piratas dos Mares do Sul no litoral de Tanaris, com seu estaleiro ocupado com uma nova embarcação em construção.",
			full = "Escondida atrás de montanhas por três lados, a Enseada do Armador Perdido abriga o porto dos Piratas dos Mares do Sul no litoral de Tanaris, com seu estaleiro ocupado com uma nova embarcação em construção.",
			source = "https://warcraft.wiki.gg/wiki/Lost_Rigger_Cove",
		},
		["noonshade ruins"] = {
			name = "Ruínas da Sombrassolar",
			short = "As Ruínas da Sombrassolar ficam a leste de Geringontzan, pedras gastas deixadas por trolls há muito desaparecidos. Que propósito as ruínas um dia tiveram, ou o que foi feito dos que as ergueram, as areias do deserto já não dizem.",
			full = "As Ruínas da Sombrassolar ficam a leste de Geringontzan, pedras gastas deixadas por trolls há muito desaparecidos. Que propósito as ruínas um dia tiveram, ou o que foi feito dos que as ergueram, as areias do deserto já não dizem.",
			source = "https://warcraft.wiki.gg/wiki/Noonshade_Ruins",
		},
		["noxious lair"] = {
			name = "Covil Nóxio",
			short = "O sudoeste de Tanaris guarda uma ferida na areia onde antes havia água. Algo largo e raso, um rio ou um lago, se estendia por este chão antes da chegada dos silitídeos, e o que o enxame Centipaar encontrou ali, ele esvaziou.",
			full = "O sudoeste de Tanaris guarda uma ferida na areia onde antes havia água. Algo largo e raso, um rio ou um lago, se estendia por este chão antes da chegada dos silitídeos, e o que o enxame Centipaar encontrou ali, ele esvaziou. O oeste de Tanaris ficou seco por isso.\n\nA superfície ainda mostra a forma do que se perdeu. A terra afunda, rebaixada e escavada, com vista para a Cratera Un'Goro, como se se lembrasse de ter sido uma margem. Aqui e ali, grandes garras se erguem eretas da areia, estremecendo, como se criaturas enterradas tivessem congelado no meio de um golpe. Ao redor de cada garra, o solo é negro e úmido de gosma silitídea, a única umidade que resta num lugar que um dia guardou um lago.\n\nSob a superfície, o Covil Nocivo é uma colmeia como qualquer outra que os Centipaar escavaram em Tanaris: úmida, quente, sinistra em sua quietude, com os túneis cobertos de ácido silitídeo.",
			source = "https://warcraft.wiki.gg/wiki/Noxious_Lair",
		},
		["sandsorrow watch"] = {
			name = "Posto Silitriste",
			short = "O Posto Silitriste se estende a oeste de Geringontzan pela bacia seca de Tanaris, dominado pelos trolls Farraki e pelos zumbis que eles ergueram de seus próprios mortos.",
			full = "O Posto Silitriste se estende a oeste de Geringontzan pela bacia seca de Tanaris, dominado pelos trolls Farraki e pelos zumbis que eles ergueram de seus próprios mortos.",
			source = "https://warcraft.wiki.gg/wiki/Sandsorrow_Watch",
		},
		["south seas"] = {
			name = "Mares do Sul",
			short = "As águas ao sul dos continentes conhecidos se abrem numa ampla extensão do Grande Mar, levando correntes para além de ilhas cujos nomes são conhecidos principalmente pelos marinheiros.",
			full = "As águas ao sul dos continentes conhecidos se abrem numa ampla extensão do Grande Mar, levando correntes para além de ilhas cujos nomes são conhecidos principalmente pelos marinheiros. Zandalar se ergue destas águas, antigo lar do império troll. Kezan também fica entre elas, uma ilha vulcânica que mantém seu próprio povo afastado das potências do continente.\n\nMais perto da Selva do Espinhaço, o mar fica traiçoeiro, com recifes e enseadas escondidas, o tipo de água em que um capitão ou conhece cada rocha pelo nome ou perde o navio. Pequenas ilhas pontilham este trecho, algumas nada mais que um banco de areia, outras guardando ruínas cujos construtores há muito desapareceram sob as ondas.\n\nO que torna este mar digno de nome é menos alguma batalha travada nele do que as coisas que ele engoliu e meio revelou de novo: templos submersos, costas afogadas, ruínas vistas através da água clara na maré baixa. É um mar de beiradas e de lugares intermediários, que banha as fronteiras do Espinhaço, de Tanaris e de Uldum, levando o que quer que as marés escolham trazer às praias que ele separa.",
			source = "https://warcraft.wiki.gg/wiki/South_Seas",
		},
		["southbreak shore"] = {
			name = "Costa Quebra-sul",
			short = "A Costa Quebra-sul repousa tranquila ao longo do limite sul de Tanaris, um trecho plano de praia quase vazio de vida. Tartarugas e gigantes do mar percorrem a arrebentação.",
			full = "A Costa Quebra-sul repousa tranquila ao longo do limite sul de Tanaris, um trecho plano de praia quase vazio de vida. Tartarugas e gigantes do mar percorrem a arrebentação.",
			source = "https://warcraft.wiki.gg/wiki/Southbreak_Shore",
		},
		["southmoon ruins"] = {
			name = "Ruínas de Lunassul",
			short = "As Ruínas de Lunassul são os restos de um antigo povoado troll no sul de Tanaris, com as pedras desgastadas e meio enterradas na areia do deserto.",
			full = "As Ruínas de Lunassul são os restos de um antigo povoado troll no sul de Tanaris, com as pedras desgastadas e meio enterradas na areia do deserto.",
			source = "https://warcraft.wiki.gg/wiki/Southmoon_Ruins",
		},
		["steamwheedle port"] = {
			name = "Porto de Bondebico",
			short = "O Porto de Bondebico fica na costa leste de Tanaris, com uma estrada que segue para o oeste até sua cidade-mãe, Geringontzan, e um cais que se estende em direção a Kezan.",
			full = "O Porto de Bondebico fica na costa leste de Tanaris, com uma estrada que segue para o oeste até sua cidade-mãe, Geringontzan, e um cais que se estende em direção a Kezan. Pertence ao Cartel Bondebico, goblins que negociam com qualquer um, desde que o ouro seja bom.\n\nEntre os moradores do porto está Yeh'kinya, cujos negócios contribuíram para o retorno de Hakkar, o Esfolalmas.",
			source = "https://warcraft.wiki.gg/wiki/Steamwheedle_Port",
		},
		["thistleshrub valley"] = {
			name = "Vale Moitagulhas",
			short = "O Vale Moitagulhas está repleto de cactos gigantes, algo estranho para um deserto tão árido sustentar vida vegetal.",
			full = "O Vale Moitagulhas está repleto de cactos gigantes, algo estranho para um deserto tão árido sustentar vida vegetal. As moitas-agulha que antes cresciam densas aqui rarearam nos últimos tempos, e agora é possível encontrar flores do deserto entre elas, embora apenas de forma esparsa.",
			source = "https://warcraft.wiki.gg/wiki/Thistleshrub_Valley",
		},
		["uldum"] = {
			name = "Uldum",
			short = "Uldum fica no litoral sul de Kalimdor, cercada pela Cratera Un'Goro ao norte, por Tanaris a leste e por Silithus a noroeste.",
			full = "Uldum fica no litoral sul de Kalimdor, cercada pela Cratera Un'Goro ao norte, por Tanaris a leste e por Silithus a noroeste. É um lugar rico em saberes dos titãs, com os desfiladeiros das montanhas encobertos para que nenhum olho mortal encontre o caminho de entrada.",
			source = "https://warcraft.wiki.gg/wiki/Uldum",
		},
		["valley of the watchers"] = {
			name = "Vale dos Vigilantes",
			short = "O Vale dos Vigilantes guarda o sul de Tanaris, onde um grande portão permanece impenetrável diante de Uldum. Gigantes das montanhas, os Esmagadores de Dunas, percorrem o vale como seus vigilantes.",
			full = "O Vale dos Vigilantes guarda o sul de Tanaris, onde um grande portão permanece impenetrável diante de Uldum. Gigantes das montanhas, os Esmagadores de Dunas, percorrem o vale como seus vigilantes.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_the_Watchers",
		},
		["waterspring field"] = {
			name = "Campo das Minas d'Água",
			short = "O Campo das Minas d'Água leva o nome das torres d'água que se erguem por ele, puxando água de reservas nas profundezas do subsolo.",
			full = "O Campo das Minas d'Água leva o nome das torres d'água que se erguem por ele, puxando água de reservas nas profundezas do subsolo. Os goblins de Geringontzan as construíram com a intenção de garantir água para suas operações no deserto de Tanaris.\n\nEsse plano não sobreviveu aos Wastewander. Os bandidos nômades invadiram o campo e simplesmente o tomaram, apoderando-se das torres sem pensar nos goblins que as ergueram. Continuam acampados ali, contentes o bastante com este terreno depois do que quer que tenham deixado para trás; não gostam de falar do acampamento de ogros que veio antes, só dizem que este é melhor.",
			source = "https://warcraft.wiki.gg/wiki/Waterspring_Field",
		},
		["wavestrider beach"] = {
			name = "Praia das Sete Ondas",
			short = "A Praia das Sete Ondas se estende pela costa leste de Tanaris, o trecho de areia entre o Porto de Bondebico e a Enseada do Armador Perdido.",
			full = "A Praia das Sete Ondas se estende pela costa leste de Tanaris, o trecho de areia entre o Porto de Bondebico e a Enseada do Armador Perdido. Rastejadores do Deserto correm pela praia aqui, ao lado das Tartarugas Queixo-de-aço que dividem o mesmo litoral.",
			source = "https://warcraft.wiki.gg/wiki/Wavestrider_Beach",
		},
		["zalashjis den"] = {
			name = "Covil de Zalashji",
			short = "O Covil de Zalashji ainda leva o nome de quem um dia se entocou aqui. Nada nas histórias que sobreviveram diz quem foi Zalashji, ou o que foi feito do lugar depois.",
			full = "O Covil de Zalashji ainda leva o nome de quem um dia se entocou aqui. Nada nas histórias que sobreviveram diz quem foi Zalashji, ou o que foi feito do lugar depois. Se Zalashji ainda vive, se morreu aqui ou em outro lugar, ninguém sabe dizer com certeza.",
			source = "https://warcraft.wiki.gg/wiki/Zalashji's_Den",
		},
		["zulfarrak"] = {
			name = "Zul'Farrak",
			short = "Zul'Farrak já foi uma cidade da selva, quando Tanaris ainda era floresta sob o Império Gurubashi.",
			full = "Zul'Farrak já foi uma cidade da selva, quando Tanaris ainda era floresta sob o Império Gurubashi. Quando a Grande Cisão despedaçou o mundo antigo, a selva queimou até virar deserto, e os trolls Farraki que haviam construído sua cidade aqui se viram isolados no meio da areia. Eles resistiram, endurecendo-se nos Fúria-da-areia, uma tribo conhecida até entre os trolls por sua crueldade e seu misticismo sombrio.\n\nDentro das muralhas castigadas pelo sol, a lenda troll fala de Sul'thraze, o Açoitador, uma lâmina que, dizem, incutia medo e fraqueza em qualquer inimigo que tocasse. Há muito tempo a espada foi partida em duas, e sussurra-se que as duas metades ainda estão em algum lugar dentro da cidade, perdidas entre seus pátios e templos.\n\nNo coração de Zul'Farrak fica um lago sagrado e, sob sua água parada, dizem que os Fúria-da-areia mantêm adormecido algo muito mais antigo que eles próprios: um semideus cujo despertar traria a ruína à cidade e a todos que nela vivem.",
			source = "https://warcraft.wiki.gg/wiki/Zul'Farrak",
		},
	},
	-- Azshara: 26 subzones
	[1447] = {
		["bay of storms"] = {
			name = "Baía das Tempestades",
			short = "A Baía das Tempestades fica ao largo do litoral leste de Azshara, com águas conhecidas pelos viajantes pelas tempestades que se formam ali. Ao longo de sua margem ficam a Caverna do Barbescama, o Ninho de Hetaera e o Templo de Arkkoran.",
			full = "A Baía das Tempestades fica ao largo do litoral leste de Azshara, com águas conhecidas pelos viajantes pelas tempestades que se formam ali. Ao longo de sua margem ficam a Caverna do Barbescama, o Ninho de Hetaera e o Templo de Arkkoran.",
			source = "https://warcraft.wiki.gg/wiki/Bay_of_Storms",
		},
		["bears head"] = {
			name = "Campo dos Ursos",
			short = "O Campo dos Ursos leva o nome das aldeias de furbolgs espalhadas pela terra, pequenos postos que vigiam os acessos ao Domínio dos Presamatos e a Ursolan, mais ao norte.",
			full = "O Campo dos Ursos leva o nome das aldeias de furbolgs espalhadas pela terra, pequenos postos que vigiam os acessos ao Domínio dos Presamatos e a Ursolan, mais ao norte.\n\nNum penhasco acima das aldeias fica a Torre de Tauriel, lar do Arquimago Tauriel, que vive na companhia de vários aprendizes e colaboradores que estudam e trabalham entre suas paredes.",
			source = "https://warcraft.wiki.gg/wiki/Bear's_Head",
		},
		["bitter reaches"] = {
			name = "Confins Amargos",
			short = "Os Confins Amargos ficam no nordeste de Azshara, repletos de hipogrifos, gosmas e quimeras. Ao longo da borda norte, gigantes das montanhas expulsaram os animais menores e tomaram o terreno para si.",
			full = "Os Confins Amargos ficam no nordeste de Azshara, repletos de hipogrifos, gosmas e quimeras. Ao longo da borda norte, gigantes das montanhas expulsaram os animais menores e tomaram o terreno para si.",
			source = "https://warcraft.wiki.gg/wiki/Bitter_Reaches",
		},
		["forlorn ridge"] = {
			name = "Cordilheira Esquecida",
			short = "A Cordilheira Esquecida se ergue sobre o oeste de Azshara, dominando a terra por quilômetros ao redor.",
			full = "A Cordilheira Esquecida se ergue sobre o oeste de Azshara, dominando a terra por quilômetros ao redor. Fortificações se erguem em suas encostas em pares correspondentes, obras da Aliança e da Horda erguidas à vista umas das outras, construídas para uma batalha que nunca veio, e vazias.",
			source = "https://warcraft.wiki.gg/wiki/Forlorn_Ridge",
		},
		["haldarr encampment"] = {
			name = "Assentamento Haldarr",
			short = "O Assentamento Haldarr está repleto de sátiros no oeste de Azshara, uma hoste corrompida de demônios com pernas de bode, cujas fogueiras ardem a nordeste da Ermida Cantonegro e a sudoeste da antiga Valormok.",
			full = "O Assentamento Haldarr está repleto de sátiros no oeste de Azshara, uma hoste corrompida de demônios com pernas de bode, cujas fogueiras ardem a nordeste da Ermida Cantonegro e a sudoeste da antiga Valormok.",
			source = "https://warcraft.wiki.gg/wiki/Haldarr_Encampment",
		},
		["hetaeras clutch"] = {
			name = "Ninho de Hetaera",
			short = "Sob a Baía das Tempestades, ao largo de Azshara, fica o Ninho de Hetaera, um templo, agora lar de hidras.",
			full = "Sob a Baía das Tempestades, ao largo de Azshara, fica o Ninho de Hetaera, um templo, agora lar de hidras.",
			source = "https://warcraft.wiki.gg/wiki/Hetaera's_Clutch",
		},
		["jagged reef"] = {
			name = "Costa Rasgada",
			short = "A Costa Rasgada é o litoral norte de Azshara, uma praia arenosa interrompida vez após vez por jatos de pedra e pequenas enseadas do mar. Rochas e baixios se escondem sob a superfície, tornando a costa perigosa de percorrer.",
			full = "A Costa Rasgada é o litoral norte de Azshara, uma praia arenosa interrompida vez após vez por jatos de pedra e pequenas enseadas do mar. Rochas e baixios se escondem sob a superfície, tornando a costa perigosa de percorrer. Murlocs, hidras e makruras dominam esta costa, nadando nos baixios ou arrastando-se pela areia em busca de comida.",
			source = "https://warcraft.wiki.gg/wiki/Jagged_Reef",
		},
		["lake mennar"] = {
			name = "Lago Mennar",
			short = "As águas do Lago Mennar repousam imóveis em seu centro, embora o terreno de todos os lados pertença aos dracônidas.",
			full = "As águas do Lago Mennar repousam imóveis em seu centro, embora o terreno de todos os lados pertença aos dracônidas. Quem atravessa esse perímetro encontra o próprio lago livre de perigos, um lugar de sossego e descanso em meio às margens vigiadas.\n\nEste é um dos poucos lugares do mundo, fora de Nortúndria, onde a revoada azul se fez notar. Só Mazthoril, em Hibérnia, se compara. Jovens dragonetes azuis são uma visão comum perto destas águas.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Mennar",
		},
		["legash encampment"] = {
			name = "Assentamento Legash",
			short = "Os sátiros Legashi mantêm seu acampamento no norte de Azshara, a leste de Ursolan.",
			full = "Os sátiros Legashi mantêm seu acampamento no norte de Azshara, a leste de Ursolan.\n\nAqui o Arquimago Tauriel certa vez encontrou um grimório, uma descoberta que chamou a atenção para este acampamento de criaturas tocadas pela energia vil, que de resto não tem nada de notável.",
			source = "https://warcraft.wiki.gg/wiki/Legash_Encampment",
		},
		["ravencrest monument"] = {
			name = "Monumento a Cristacorvo",
			short = "Os penhascos do extremo sul de Azshara guardam os restos de um colosso, embora pouco reste agora que justifique a palavra.",
			full = "Os penhascos do extremo sul de Azshara guardam os restos de um colosso, embora pouco reste agora que justifique a palavra. Apenas as pernas quebradas ainda estão de pé, fincadas acima do mar, enquanto o resto da grande figura jaz espalhado pela pedra ao redor ou escorregou para baixo das ondas.\n\nOs nagas Spitelash ocupam as ruínas agora. O lugar não pode ser alcançado pela água; quem o procura precisa vir por terra e atravessar a ponte que passa pelas Ruínas de Eldarath, para ficar sob as pernas tombadas de algo que um dia foi, sem dúvida, impressionante de se ver.",
			source = "https://warcraft.wiki.gg/wiki/Ravencrest_Monument",
		},
		["rethress sanctum"] = {
			name = "Sacrário de Rethress",
			short = "O Sacrário de Rethress está em ruínas entre os Confins Arruinados, a sudoeste do Monumento a Cristacorvo. Ninguém cuida dele agora. Murlocs e makruras vagam por suas pedras caídas, os únicos que chegam a vir aqui.",
			full = "O Sacrário de Rethress está em ruínas entre os Confins Arruinados, a sudoeste do Monumento a Cristacorvo. Ninguém cuida dele agora. Murlocs e makruras vagam por suas pedras caídas, os únicos que chegam a vir aqui.",
			source = "https://warcraft.wiki.gg/wiki/Rethress_Sanctum",
		},
		["ruined reaches"] = {
			name = "Profundezas Devastadas",
			short = "O litoral sul de Azshara exibe sua ruína abertamente. Penhascos e praias se partem em enseadas, e a água esconde baixios que já pegaram mais cascos do que qualquer marinheiro gosta de contar.",
			full = "O litoral sul de Azshara exibe sua ruína abertamente. Penhascos e praias se partem em enseadas, e a água esconde baixios que já pegaram mais cascos do que qualquer marinheiro gosta de contar. Navios naufragados jazem meio enterrados na areia ao lado de ruínas mais antigas e estranhas, cujos construtores já se foram. Murlocs, hidras e makruras assombram o litoral, e até os que conhecem a costa pisam com cuidado ao longo dela.\n\nNa costa oeste, acima da praia, uma construção gnômica fica numa colina, acessível apenas por uma trilha íngreme que vem do interior. Blimo e Jubie Gadgetspring fizeram ali seu lar e seu comércio. No andar de cima, em seus aposentos particulares, há uma terceira cama. Ninguém sabe a quem ela pertence, nem se alguém chega a dormir nela.",
			source = "https://warcraft.wiki.gg/wiki/Ruined_Reaches",
		},
		["ruins of eldarath"] = {
			name = "Ruínas de Eldarath",
			short = "Antes de o mundo se partir, Eldarath se erguia como um dos grandes bastiões dos Bem-nascidos, uma cidade de saber arcano onde os magos mais poderosos gravavam runas e tábuas na pedra e as deixavam em lugares públicos, para que qualquer um que passasse pudesse refletir sobre suas percepções do arcano.",
			full = "Antes de o mundo se partir, Eldarath se erguia como um dos grandes bastiões dos Bem-nascidos, uma cidade de saber arcano onde os magos mais poderosos gravavam runas e tábuas na pedra e as deixavam em lugares públicos, para que qualquer um que passasse pudesse refletir sobre suas percepções do arcano.\n\nA cidade não caiu em silêncio. Durante a Guerra dos Antigos, a Resistência Kaldorei resistiu aqui contra a Legião Ardente. Quando a Grande Cisão despedaçou o mundo, Eldarath não aguentou: a maior parte da cidade desmoronou e afundou nas águas da Baía das Tempestades, lá embaixo.\n\nO que resta se agarra aos penhascos do leste, um aglomerado partido de torres há muito evitado pelos elfos noturnos que um dia o chamaram de lar. Os nagas tomaram as ruínas agora, e o Senhor da Guerra Krellian governa o que resta a partir do Templo de Zin-Malor. Entre os destroços, as tábuas rúnicas dos antigos Bem-nascidos ainda estão de pé, com sua sabedoria arcana intocada pelas eras que se passaram.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Eldarath",
		},
		["scalebeards cave"] = {
			name = "Caverna do Barbescama",
			short = "Uma caverna numa ilhota da Baía das Tempestades leva o nome de Barbescama, uma velha tartaruga rara. É o lar dele, embora raramente seu lugar de descanso, pois ele prefere caçar longe, no Grande Mar, deixando a toca vazia.",
			full = "Uma caverna numa ilhota da Baía das Tempestades leva o nome de Barbescama, uma velha tartaruga rara. É o lar dele, embora raramente seu lugar de descanso, pois ele prefere caçar longe, no Grande Mar, deixando a toca vazia.",
			source = "https://warcraft.wiki.gg/wiki/Scalebeard's_Cave",
		},
		["shadowsong shrine"] = {
			name = "Ermida Cantonegro",
			short = "Uma colina coberta de ruínas no oeste de Azshara, a Ermida Cantonegro não guarda nenhum registro claro de por que leva esse nome.",
			full = "Uma colina coberta de ruínas no oeste de Azshara, a Ermida Cantonegro não guarda nenhum registro claro de por que leva esse nome. Ela compartilha o nome com Jarod Cantonegro, que liderou a resistência na Guerra dos Antigos, e com sua irmã Maiev, a vigia lembrada por manter Illidan Tempesfúria cativo depois de sua traição no Monte Hyjal. O que qualquer um dos dois tem a ver com esta colina, ninguém sabe dizer.\n\nO que se pode dizer é o que caminha por ali. Fantasmas dos Bem-nascidos se demoram entre as pedras, famintos por qualquer coisa viva que se aproxime.",
			source = "https://warcraft.wiki.gg/wiki/Shadowsong_Shrine",
		},
		["shattered strand"] = {
			name = "Areal Despedaçado",
			short = "O Areal Despedaçado se estende pelo lado norte da Baía das Tempestades, em Azshara, repleto de hidras, gigantes do mar, makruras e murlocs, cada um ocupando seu próprio trecho de areia.",
			full = "O Areal Despedaçado se estende pelo lado norte da Baía das Tempestades, em Azshara, repleto de hidras, gigantes do mar, makruras e murlocs, cada um ocupando seu próprio trecho de areia. O Templo de Arkkoran e a Torre de Eldara se erguem da praia apesar da aglomeração de garras e tentáculos.\n\nGoblins também fincaram suas reivindicações ao longo desta costa, especulando com os terrenos à beira-mar em meio a todos os dentes e marés.",
			source = "https://warcraft.wiki.gg/wiki/Shattered_Strand",
		},
		["southfury river"] = {
			name = "Rio Furiaustral",
			short = "O Furiaustral nasce no alto do Monte Hyjal, despejando-se de um lago de montanha numa queda que despenca trovejante nas terras baixas.",
			full = "O Furiaustral nasce no alto do Monte Hyjal, despejando-se de um lago de montanha numa queda que despenca trovejante nas terras baixas. Dali ele corre largo e veloz, cortando a terra em duas: marca onde o Vale Gris dá lugar a Azshara e, mais ao sul, onde terminam os Sertões e começa Durotar. Na foz, o rio se lança numa última cascata no Grande Mar, logo a nordeste do porto goblin de Vila Catraca.\n\nPontes cruzam seu curso, uma ligando Azshara ao Vale Gris, outra unindo Durotar aos Sertões.\n\nO rio ainda alimenta os campos ao longo de suas margens e ainda deixa verde o solo por onde passa.",
			source = "https://warcraft.wiki.gg/wiki/Southfury_River",
		},
		["southridge beach"] = {
			name = "Praia do Recife Sul",
			short = "A Praia do Recife Sul margeia o limite sul da Baía das Tempestades, com as areias cobertas de ruínas da outrora grandiosa cidade de Eldarath.",
			full = "A Praia do Recife Sul margeia o limite sul da Baía das Tempestades, com as areias cobertas de ruínas da outrora grandiosa cidade de Eldarath. Os nagas agora dominam a praia, dividindo-a com makruras, hidras, murlocs e um ou outro gigante do mar vindo de águas mais profundas.",
			source = "https://warcraft.wiki.gg/wiki/Southridge_Beach",
		},
		["storm cliffs"] = {
			name = "Penhascos Tempestuosos",
			short = "Os Penhascos Tempestuosos se erguem em Azshara, tomados pelos nagas Spitelash que vivem entre as rochas. Na extremidade leste dos penhascos fica o Monumento a Cristacorvo, um marco solitário que domina a pedra ocupada pelos nagas.",
			full = "Os Penhascos Tempestuosos se erguem em Azshara, tomados pelos nagas Spitelash que vivem entre as rochas. Na extremidade leste dos penhascos fica o Monumento a Cristacorvo, um marco solitário que domina a pedra ocupada pelos nagas.",
			source = "https://warcraft.wiki.gg/wiki/Storm_Cliffs",
		},
		["talrendis point"] = {
			name = "Campo Talrendis",
			short = "O Campo Talrendis fica no sudoeste de Azshara, com suas duas torres de guarda vigiando a fronteira com o Vale Gris, e um poço lunar ainda rega o terreno do sul.",
			full = "O Campo Talrendis fica no sudoeste de Azshara, com suas duas torres de guarda vigiando a fronteira com o Vale Gris, e um poço lunar ainda rega o terreno do sul.\n\nO Campo começou como nada mais que um pequeno acampamento dos elfos noturnos, uma vigília mantida na borda da floresta.",
			source = "https://warcraft.wiki.gg/wiki/Talrendis_Point",
		},
		["temple of arkkoran"] = {
			name = "Templo de Arkkoran",
			short = "O Templo de Arkkoran um dia pertenceu ao culto de Eluna, com suas pedras erguidas nas margens do nordeste de Azshara. Essa santidade há muito se foi.",
			full = "O Templo de Arkkoran um dia pertenceu ao culto de Eluna, com suas pedras erguidas nas margens do nordeste de Azshara. Essa santidade há muito se foi. O gigante do mar Arkkoroc agora vive em seu topo, guardado por murlocs e makruras que caem sobre qualquer um que se aproxime. A costa ao redor, o Areal Despedaçado, não oferece passagem mais segura, vigiada por hidras e gigantes do mar tão agressivos quanto o próprio Arkkoroc.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Arkkoran",
		},
		["temple of zin malor"] = {
			name = "Templo de Zin-Malor",
			short = "O Templo de Zin-Malor fica entre as Ruínas de Eldarath, com as pedras moldadas à semelhança do vizinho Templo de Arkkoran e do Templo da Lua erguido mais tarde em Darnassus.",
			full = "O Templo de Zin-Malor fica entre as Ruínas de Eldarath, com as pedras moldadas à semelhança do vizinho Templo de Arkkoran e do Templo da Lua erguido mais tarde em Darnassus. Foi construído em devoção a Eluna, nos dias anteriores à adesão dos elfos noturnos à magia arcana.\n\nDentro dele repousava o Cristal de Zin-Malor, um presente destinado a levar aos Bem-nascidos uma mensagem: a de que eles não tinham nenhuma necessidade real da magia arcana. O cristal já não está ali, levado há muito tempo.\n\nO templo caiu desde então nas mãos da tribo de nagas Spitelash. O Senhor da Guerra Krellian governa ali agora, tomando para si o lugar de honra antes reservado ao culto da deusa.",
			source = "https://warcraft.wiki.gg/wiki/Temple_of_Zin-Malor",
		},
		["thalassian base camp"] = {
			name = "Base Darnassiana",
			short = "A colina acima dos acampamentos Legash pertence a elfos sangrentos, com as encostas divididas em pequenos postos fortificados sob o comando da Maga Rimtori.",
			full = "A colina acima dos acampamentos Legash pertence a elfos sangrentos, com as encostas divididas em pequenos postos fortificados sob o comando da Maga Rimtori. Ela fez um acordo com a Horda, prometendo uma parte de tudo o que sua expedição desenterrasse em troca de ouro e aço para protegê-la. O acordo não se sustentou. Rimtori pegou o financiamento e não devolveu nada, e a notícia da traição se espalhou até que se diz que há uma vingança devida a ela e a seus seguidores na mesma moeda.\n\nA própria Rimtori raramente está no acampamento, dedicada a explorar Azshara sob uma escolta escolhida por ela, deixando o Magíster Hawkhelm para defender a colina em sua ausência. O que os dois realmente buscam não é ouro. Num dos cumes do acampamento jaz um Tomo Kaldorei de Invocação, algo capaz de trazer demônios ao mundo, e sua presença ali revela a expedição pelo que ela é: não uma caça ao tesouro, mas algo mais sombrio disfarçado de uma.",
			source = "https://warcraft.wiki.gg/wiki/Thalassian_Base_Camp",
		},
		["tower of eldara"] = {
			name = "Torre de Eldara",
			short = "A Torre de Eldara fica na extremidade nordeste da terra acima da Baía das Tempestades, com sua praia arenosa patrulhada por murlocs, makruras e hidras.",
			full = "A Torre de Eldara fica na extremidade nordeste da terra acima da Baía das Tempestades, com sua praia arenosa patrulhada por murlocs, makruras e hidras. Ela um dia pertenceu à civilização dos elfos noturnos que se espalhou por esta costa, mas a torre está fechada e abandonada agora.",
			source = "https://warcraft.wiki.gg/wiki/Tower_of_Eldara",
		},
		["ursolan"] = {
			name = "Ursolan",
			short = "Ursolan leva o nome de Ursol, o semideus urso reverenciado pela raça dos furbolgs. Hoje é o local de um extenso povoado de furbolgs Presamatos, que se estende para o sul, passando pelo Domínio, até o Campo dos Ursos.",
			full = "Ursolan leva o nome de Ursol, o semideus urso reverenciado pela raça dos furbolgs. Hoje é o local de um extenso povoado de furbolgs Presamatos, que se estende para o sul, passando pelo Domínio, até o Campo dos Ursos.",
			source = "https://warcraft.wiki.gg/wiki/Ursolan",
		},
		["valormok"] = {
			name = "Valormok",
			short = "Valormok é um posto avançado da Horda em Azshara, no noroeste, ao norte do Assentamento Haldarr. Os guerreiros destacados ali enfrentam tempos difíceis, mas se agarram à esperança.",
			full = "Valormok é um posto avançado da Horda em Azshara, no noroeste, ao norte do Assentamento Haldarr. Os guerreiros destacados ali enfrentam tempos difíceis, mas se agarram à esperança.\n\nEssa esperança foi traída por dentro. Belgrom Pedramalho havia enviado a Maga Rimtori, uma elfa sangrenta, com uma companhia de guerreiros orcs para encontrar riquezas e artefatos poderosos na região. Rimtori encontrou o que buscava e, em vez de dividir a descoberta, voltou-se contra os guerreiros que a haviam escoltado, matando-os e tomando o espólio para si. Ag'tor Punho de Sangue, que lidera o acampamento, não deixará o massacre sem resposta. Ele procura guerreiros para vingar seus caídos e o orgulho ferido de Pedramalho, e para ver a Maga Rimtori morta em seu acampamento próximo.",
			source = "https://warcraft.wiki.gg/wiki/Valormok",
		},
	},
	-- Selva Maleva: 18 subzones
	[1448] = {
		["bloodvenom falls"] = {
			name = "Salto da Peçonha",
			short = "O Salto da Peçonha despenca dos lugares altos da Selva Maleva, com as águas contaminadas desde a nascente.",
			full = "O Salto da Peçonha despenca dos lugares altos da Selva Maleva, com as águas contaminadas desde a nascente. Daqui nasce o Rio Peçonha, levando a mácula para baixo até desaguar na Costa Negra como o adoecido Rio Crenado.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Falls",
		},
		["bloodvenom post"] = {
			name = "Posto Peçonha",
			short = "O Posto Peçonha fica nos altos penhascos acima da Costa Negra, onde o Rio Peçonha corta a Selva Maleva.",
			full = "O Posto Peçonha fica nos altos penhascos acima da Costa Negra, onde o Rio Peçonha corta a Selva Maleva. Sua arquitetura e os taurens que o guardam o marcam como uma fundação tauren, um pequeno ponto de apoio da Horda que vigia a costa lá embaixo.\n\nChega-se a ele por uma trilha escura que segue a margem sul do rio para o oeste, a partir do caminho de pedra que atravessa a Selva Maleva, contornando a encosta até o próprio posto.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_Post",
		},
		["bloodvenom river"] = {
			name = "Rio Peçonha",
			short = "O Rio Peçonha corre negro pela Selva Maleva, com sua corrupção se espalhando além da região até reaparecer como o Rio Crenado, na Costa Negra.",
			full = "O Rio Peçonha corre negro pela Selva Maleva, com sua corrupção se espalhando além da região até reaparecer como o Rio Crenado, na Costa Negra. Gosmas nocivas rastejam por suas margens, e os animais das redondezas se tornaram venenosos. Ninguém bebe dele, e ninguém nada nele.",
			source = "https://warcraft.wiki.gg/wiki/Bloodvenom_River",
		},
		["deadwood village"] = {
			name = "Vila da Lenha Morta",
			short = "Os furbolgs Lenha Morta construíram sua aldeia no sul da Selva Maleva atrás de muralhas de madeira pesada, com estruturas mais robustas erguidas lá dentro.",
			full = "Os furbolgs Lenha Morta construíram sua aldeia no sul da Selva Maleva atrás de muralhas de madeira pesada, com estruturas mais robustas erguidas lá dentro. Como seus parentes por toda a floresta corrompida, eles sucumbiram à mácula da Selva Maleva, tornando-se hostis e retorcidos.",
			source = "https://warcraft.wiki.gg/wiki/Deadwood_Village",
		},
		["emerald sanctuary"] = {
			name = "Santuário Esmeralda",
			short = "O Santuário Esmeralda fica no sudeste da Selva Maleva, um acampamento dos druidas do Círculo Esmeralda. Daqui eles vigiam Jaedenar, trabalhando para extinguir a corrupção demoníaca que se espalha dali antes que ela consuma mais terra.",
			full = "O Santuário Esmeralda fica no sudeste da Selva Maleva, um acampamento dos druidas do Círculo Esmeralda. Daqui eles vigiam Jaedenar, trabalhando para extinguir a corrupção demoníaca que se espalha dali antes que ela consuma mais terra.",
			source = "https://warcraft.wiki.gg/wiki/Emerald_Sanctuary",
		},
		["felpaw village"] = {
			name = "Aldeia Patavil",
			short = "A Aldeia Patavil fica no limite norte da Selva Maleva, perto da entrada do Domínio dos Presamatos.",
			full = "A Aldeia Patavil fica no limite norte da Selva Maleva, perto da entrada do Domínio dos Presamatos. Ela pertence aos Lenha Morta, furbolgs cuja corrupção os afastou de seus parentes, e sua mácula ainda marca o chão que ocupam.",
			source = "https://warcraft.wiki.gg/wiki/Felpaw_Village",
		},
		["irontree cavern"] = {
			name = "Caverna Ferrárbol",
			short = "No fundo da caverna, a madeira retorcida dos Madeiraversos criou raízes, dando origem a Retalhadores e Esfolamusgos que rondam a escuridão no lugar de qualquer guardião vivo.",
			full = "No fundo da caverna, a madeira retorcida dos Madeiraversos criou raízes, dando origem a Retalhadores e Esfolamusgos que rondam a escuridão no lugar de qualquer guardião vivo.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Cavern",
		},
		["irontree woods"] = {
			name = "Floresta Ferrárbol",
			short = "A Floresta Ferrárbol já foi uma clareira pacífica no norte da Selva Maleva, antes que a corrupção da Legião Ardente a transformasse em outra coisa.",
			full = "A Floresta Ferrárbol já foi uma clareira pacífica no norte da Selva Maleva, antes que a corrupção da Legião Ardente a transformasse em outra coisa. Três grandes Anciãos dos elfos noturnos viviam aqui, árvores vivas chamadas Hastat, Stoma e Vartrus. A corrupção não os poupou: os três foram petrificados onde estavam e continuam sepultados na floresta, mortos em meio à praga que os matou.\n\nAinda assim, algo se recusou a continuar morto. Água de poço lunar derramada no coração da floresta deu origem a uma muda. Cuidada e crescida, ela floresceu e depois voltou ao chão onde nasceu, enraizada entre os mortos petrificados, esperando para se erguer como um Ancião no lugar deles.",
			source = "https://warcraft.wiki.gg/wiki/Irontree_Woods",
		},
		["jadefire glen"] = {
			name = "Grota Flamejade",
			short = "Na floresta corrompida do sul da Selva Maleva, a Grota Flamejade abriga um acampamento de sátiros, criaturas demoníacas que tomaram para si o vale contaminado, prosperando em meio à sua podridão e espalhando ainda mais a corrupção pelas árvores ao redor.",
			full = "Na floresta corrompida do sul da Selva Maleva, a Grota Flamejade abriga um acampamento de sátiros, criaturas demoníacas que tomaram para si o vale contaminado, prosperando em meio à sua podridão e espalhando ainda mais a corrupção pelas árvores ao redor.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Glen",
		},
		["jadefire run"] = {
			name = "Aldeia Flamejade",
			short = "No norte da Selva Maleva fica a Aldeia Flamejade, lar dos sátiros mais poderosos da região. É preciso cautela para quem se aventura por perto.",
			full = "No norte da Selva Maleva fica a Aldeia Flamejade, lar dos sátiros mais poderosos da região. É preciso cautela para quem se aventura por perto. Suas estruturas seguem um projeto demoníaco, e não mortal.",
			source = "https://warcraft.wiki.gg/wiki/Jadefire_Run",
		},
		["jaedenar"] = {
			name = "Jaedenar",
			short = "Jaedenar se ergue de um chão que um dia pertenceu aos elfos noturnos, com pedras mais antigas que a corrupção que agora as domina.",
			full = "Jaedenar se ergue de um chão que um dia pertenceu aos elfos noturnos, com pedras mais antigas que a corrupção que agora as domina. Sob suas ruínas ficam duas grutas druídicas, antes sagradas, e foi sobre essa base profanada que o Conselho das Sombras construiu seu domínio, dando ao próprio lugar um nome em adoração a Kil'jaeden, o Enganador.\n\nDepois da Terceira Guerra, as ruínas passaram para as mãos do Lorde Banehollow e do Conselho das Sombras que ele liderava. Bruxos orcs e Renegados encheram seus salões, e não vieram sozinhos: súcubos, caçadores vis, guardas vis e sátiros circulavam entre eles. Em seu coração fica a Fortaleza do Concílio das Sombras, a sede do poder do Conselho em Azeroth, e ao lado dela o Santuário do Embusteiro, erguido em nome de Kil'jaeden.",
			source = "https://warcraft.wiki.gg/wiki/Jaedenar",
		},
		["morlosaran"] = {
			name = "Morlos'Aran",
			short = "Morlos'Aran já foi um grande povoado dos elfos noturnos, erguido antes que a Grande Cisão despedaçasse o mundo.",
			full = "Morlos'Aran já foi um grande povoado dos elfos noturnos, erguido antes que a Grande Cisão despedaçasse o mundo. Agora jaz em ruínas no limite sul da Selva Maleva, um entre vários lugares assim, como Ameth'Aran, Bashal'Aran, Ordil'Aran e Tethris'Aran, todos um dia cidades prósperas, todos agora apenas pedra e lembrança de uma era dourada há muito perdida.",
			source = "https://warcraft.wiki.gg/wiki/Morlos'Aran",
		},
		["ruins of constellas"] = {
			name = "Ruínas de Constellas",
			short = "As colunas quebradas daqui um dia pertenceram a um povoado dos elfos noturnos perto do Monte Hyjal. Um poço lunar ainda repousa em seu coração, mas já não guarda uma luz pura.",
			full = "As colunas quebradas daqui um dia pertenceram a um povoado dos elfos noturnos perto do Monte Hyjal. Um poço lunar ainda repousa em seu coração, mas já não guarda uma luz pura. A corrupção vil se infiltrou em suas águas, e o sátiro Xavathras agora cuida dele em nome de Xavaric, cultivando a corrupção como um jardim destinado a envenenar. Mais para dentro das ruínas, uma parede de fogo bloqueia o caminho até ele.\n\nOs parentes druidas não deixaram os demônios sem resposta, atacando-os num esforço para arrancar o lugar de volta da energia vil que nele criou raízes.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Constellas",
		},
		["shadow hold"] = {
			name = "Fortaleza do Concílio das Sombras",
			short = "Sob Jaedenar, no oeste da Selva Maleva, fica um labirinto que um dia foi uma gruta dos elfos noturnos. O Conselho das Sombras o tomou há muito tempo, e agora bruxos e seus familiares demoníacos percorrem seus túneis.",
			full = "Sob Jaedenar, no oeste da Selva Maleva, fica um labirinto que um dia foi uma gruta dos elfos noturnos. O Conselho das Sombras o tomou há muito tempo, e agora bruxos e seus familiares demoníacos percorrem seus túneis. O sátiro Príncipe Xavalis e o senhor do medo Lorde Banehollow vivem ambos lá dentro.\n\nO paladino Trey Forjaleve e a elfa noturna Arko'narin Starshade se aventuraram pela Selva Maleva em busca de sinais da ação do Conselho das Sombras. Os cultistas capturaram os dois e os enjaularam dentro da Fortaleza do Concílio das Sombras. Trey foi torturado até a morte ali, com o espírito retorcido e corrompido por seus captores. Arko'narin continua enjaulada nas profundezas, vigiada por seus torturadores, à espera de um resgate que ainda não veio.",
			source = "https://warcraft.wiki.gg/wiki/Shadow_Hold",
		},
		["shatter scar vale"] = {
			name = "Vale das Escaras Pungentes",
			short = "O Vale das Escaras Pungentes é onde os infernais caíram quando a Legião Ardente devastou a Selva Maleva durante a Terceira Guerra. As crateras que deixaram ainda fumegam, marcando a terra, e demônios ainda vagam entre elas.",
			full = "O Vale das Escaras Pungentes é onde os infernais caíram quando a Legião Ardente devastou a Selva Maleva durante a Terceira Guerra. As crateras que deixaram ainda fumegam, marcando a terra, e demônios ainda vagam entre elas.",
			source = "https://warcraft.wiki.gg/wiki/Shatter_Scar_Vale",
		},
		["shrine of the deceiver"] = {
			name = "Santuário do Embusteiro",
			short = "O Santuário do Embusteiro, uma gruta corrompida em Jaedenar, na Selva Maleva, leva o nome de Kil'jaeden, o Enganador, senhor da Legião Ardente.",
			full = "O Santuário do Embusteiro, uma gruta corrompida em Jaedenar, na Selva Maleva, leva o nome de Kil'jaeden, o Enganador, senhor da Legião Ardente. Bruxos do Conselho das Sombras enchem suas profundezas, tornando-o um lugar perigoso para os despreparados.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_the_Deceiver",
		},
		["talonbranch glade"] = {
			name = "Clareira da Galhaça",
			short = "A Clareira da Galhaça fica no norte da Selva Maleva, ao sul do Domínio dos Presamatos, ao longo do caminho que segue para a Clareira da Lua e Hibérnia.",
			full = "A Clareira da Galhaça fica no norte da Selva Maleva, ao sul do Domínio dos Presamatos, ao longo do caminho que segue para a Clareira da Lua e Hibérnia.",
			source = "https://warcraft.wiki.gg/wiki/Talonbranch_Glade",
		},
		["timbermaw hold"] = {
			name = "Domínio dos Presamatos",
			short = "O Domínio dos Presamatos, no nordeste da Selva Maleva, é a capital da tribo de furbolgs Presamatos. Seus túneis abrem uma passagem até a Clareira da Lua e Hibérnia.",
			full = "O Domínio dos Presamatos, no nordeste da Selva Maleva, é a capital da tribo de furbolgs Presamatos. Seus túneis abrem uma passagem até a Clareira da Lua e Hibérnia.\n\nQuando a corrupção da Legião Ardente se infiltrou nas florestas sagradas de Kalimdor, os furbolgs caíram sob sua influência e foram levados à loucura. Apenas a tribo Presamatos escapou dessa escuridão, abrigando-se em seu domínio enquanto a floresta que amavam era transformada numa perversão purulenta de si mesma. Mesmo muito depois de o líder dos demônios ter sido abatido, a mácula sobre as matas permaneceu.\n\nOs furbolgs do Domínio dos Presamatos desconfiam de todos os estranhos, com medo de serem confundidos com seus parentes corrompidos e atacados à primeira vista. Ainda assim, sabem que não podem resistir sozinhos, e aqueles em quem passam a confiar descobrem que os Presamatos valorizam a amizade acima de tudo. Acima de tudo, desejam apenas pôr fim ao sofrimento de seus irmãos corrompidos e encontrar alguma cura para a ferida em que a Selva Maleva se transformou.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Cratera Un'Goro: 9 subzones
	[1449] = {
		["fire plume ridge"] = {
			name = "Pico Penacho de Fogo",
			short = "O Pico Penacho de Fogo se ergue no coração da Cratera Un'Goro, uma montanha de rocha calcinada onde a lava escorre pelas encostas e elementais do fogo se agitam no calor.",
			full = "O Pico Penacho de Fogo se ergue no coração da Cratera Un'Goro, uma montanha de rocha calcinada onde a lava escorre pelas encostas e elementais do fogo se agitam no calor. Veios rasos de magma correm sob o fundo da cratera, alimentando as poças de vapor e os gêiseres que sibilam por toda Un'Goro, de modo que a bacia inteira parece respirar com o fogo da montanha.\n\nNuma caverna no pico vive Chamarredio, o mais forte dos elementais do fogo que assombram o pico, senhor do coração ardente da montanha. Os espíritos do fogo que tremulam e dançam aqui falam de séculos passados ardendo, apagando-se até virar brasa e reacendendo, vez após vez, sem fim.\n\nNem todos os que vêm ao pico o dominam. Um andarilho chamado Ringo veio explorar suas encostas e se perdeu, e a exaustão pelo calor o dominou. Ele ainda pode ser encontrado na caverna do sul, sem nunca ter conseguido sair.",
			source = "https://warcraft.wiki.gg/wiki/Fire_Plume_Ridge",
		},
		["fungal rock"] = {
			name = "Pedra do Limo",
			short = "A Pedra do Limo se abre na parede nordeste da Cratera Un'Goro, uma caverna onde gorilas vivem entre os cogumelos-fantasma que crescem em sua escuridão.",
			full = "A Pedra do Limo se abre na parede nordeste da Cratera Un'Goro, uma caverna onde gorilas vivem entre os cogumelos-fantasma que crescem em sua escuridão. Do lado de fora, uma pequena lagoa se forma sob uma cachoeira, e ali fica o macaco mecânico de Karna Trilheiro, A-Me 01.",
			source = "https://warcraft.wiki.gg/wiki/Fungal_Rock",
		},
		["golakka hot springs"] = {
			name = "Fontes Termais Golakka",
			short = "O vapor sobe sem parar das Fontes Termais Golakka, onde o coração vulcânico da Cratera Un'Goro verte calor em poças e gêiseres no oeste da cratera.",
			full = "O vapor sobe sem parar das Fontes Termais Golakka, onde o coração vulcânico da Cratera Un'Goro verte calor em poças e gêiseres no oeste da cratera. Elementais da fúria nascidos desse vapor e fogo rondam as margens, arrancados da terra pelas mesmas forças que mantêm as fontes fervendo.\n\nGualter veio aqui certa vez para descobrir o que ligava as fontes termais aos fogos do vizinho Pico Penacho de Fogo, antes que sua busca o levasse a outro lugar.",
			source = "https://warcraft.wiki.gg/wiki/Golakka_Hot_Springs",
		},
		["ironstone plateau"] = {
			name = "Platô Petraferro",
			short = "A rocha nua rompe o verde de Un'Goro ao longo de sua parede nordeste. O Platô Petraferro é tranquilo em comparação com o resto da cratera, em grande parte vazio de predadores.",
			full = "A rocha nua rompe o verde de Un'Goro ao longo de sua parede nordeste. O Platô Petraferro é tranquilo em comparação com o resto da cratera, em grande parte vazio de predadores. Filhotes de pterrordax se aninham aqui, e a quietude do platô o distingue do crescimento inquieto de Un'Goro.",
			source = "https://warcraft.wiki.gg/wiki/Ironstone_Plateau",
		},
		["lakkari tar pits"] = {
			name = "Poços de Piche Lakkari",
			short = "Os lagos negros ao norte do Refúgio do Marshal repousam espessos e malcheirosos em meio ao verde de Un'Goro. Ossos despontam da superfície às centenas, restos de feras que pisaram ali esperando chão firme e não o encontraram.",
			full = "Os lagos negros ao norte do Refúgio do Marshal repousam espessos e malcheirosos em meio ao verde de Un'Goro. Ossos despontam da superfície às centenas, restos de feras que pisaram ali esperando chão firme e não o encontraram. Carniceiros se demoram nas bordas, esperando que o piche termine o que começou, enquanto feras de piche se ergueram dos próprios poços.",
			source = "https://warcraft.wiki.gg/wiki/Lakkari_Tar_Pits",
		},
		["marshals refuge"] = {
			name = "Refúgio do Marshal",
			short = "O Refúgio do Marshal fica no limite norte da Cratera Un'Goro, erguido pelas Expedições Marshal sob o comando de Williden e Hol'anyee Marshal.",
			full = "O Refúgio do Marshal fica no limite norte da Cratera Un'Goro, erguido pelas Expedições Marshal sob o comando de Williden e Hol'anyee Marshal. Sua incursão na cratera não estava preparada para o que encontrou; as feras de Un'Goro se mostraram selvagens demais, e os acampamentos-base da expedição foram tomados um a um. O que restou da trupe fugiu para terras mais altas, escapando para cá, na borda da cratera.\n\nO refúgio é o que resultou dessa retirada, um ponto de apoio mal mantido, e não conquistado.",
			source = "https://warcraft.wiki.gg/wiki/Marshal's_Refuge",
		},
		["marshlands"] = {
			name = "Os Pântanos",
			short = "O pântano se estende pelo sudeste da Cratera Un'Goro, uma extensão baixa de água parada e vegetação densa que recebe a maioria dos que descem pela primeira vez à cratera vindos de Tanaris, já que qualquer outro acesso é traiçoeiro.",
			full = "O pântano se estende pelo sudeste da Cratera Un'Goro, uma extensão baixa de água parada e vegetação densa que recebe a maioria dos que descem pela primeira vez à cratera vindos de Tanaris, já que qualquer outro acesso é traiçoeiro. Raptores se movem pelos juncos em grande número, alguns com veneno na mordida.\n\nCristais de poder azuis podem ser encontrados aqui, e sua presença se infiltrou no próprio pântano, penetrando nos raptores que caçam pelo chão úmido e deixando sua marca neles.\n\nNum monte que se ergue da água, Torwa Mateiro monta vigília, tendo chegado ao local de canoa, vindo de outra parte da cratera.",
			source = "https://warcraft.wiki.gg/wiki/Marshlands",
		},
		["slithering scar"] = {
			name = "Fenda Coleante",
			short = "A Fenda Coleante se estende pelo sul da Cratera Un'Goro, uma colmeia da seita Gorishi.",
			full = "A Fenda Coleante se estende pelo sul da Cratera Un'Goro, uma colmeia da seita Gorishi.\n\nA colmeia já teve uma rainha, invocada ao se perturbar o Cristal Silitídeo Gorishi que há lá dentro.",
			source = "https://warcraft.wiki.gg/wiki/Slithering_Scar",
		},
		["terror run"] = {
			name = "Terroral",
			short = "No Terroral, a oeste da Fenda Coleante, cristais vermelhos brotam do chão como em nenhum outro lugar da Cratera Un'Goro. As feras do lugar absorveram seu poder, e isso se nota nelas.",
			full = "No Terroral, a oeste da Fenda Coleante, cristais vermelhos brotam do chão como em nenhum outro lugar da Cratera Un'Goro. As feras do lugar absorveram seu poder, e isso se nota nelas.",
			source = "https://warcraft.wiki.gg/wiki/Terror_Run",
		},
	},
	-- Clareira da Lua: 5 subzones
	[1450] = {
		["lake eluneara"] = {
			name = "Lago Eluna'ara",
			short = "Água cristalina enche o coração da Clareira da Lua, imóvel como vidro sob as árvores. Sob sua superfície jaz Omen, o semideus louco, derrotado há longos séculos e nunca de fato ausente destas profundezas.",
			full = "Água cristalina enche o coração da Clareira da Lua, imóvel como vidro sob as árvores. Sob sua superfície jaz Omen, o semideus louco, derrotado há longos séculos e nunca de fato ausente destas profundezas. O lago o mantém imóvel, um peso silencioso sob a água calma.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Elune'ara",
		},
		["nighthaven"] = {
			name = "Refúgio Noturno",
			short = "Nas margens do Lago Eluna'ara fica Refúgio Noturno, uma aldeia de cantaria dos elfos noturnos e poços lunares, lar dos druidas do Círculo Cenariano.",
			full = "Nas margens do Lago Eluna'ara fica Refúgio Noturno, uma aldeia de cantaria dos elfos noturnos e poços lunares, lar dos druidas do Círculo Cenariano. É um lugar tranquilo e recluso, fechado à maioria dos forasteiros, com seu povo dedicado ao druidismo e ao cuidado da natureza selvagem.\n\nSó uma vez por ano Refúgio Noturno abre seus portões, quando se celebra o Festival da Lua e fogos de artifício são acesos sobre o lago em tributo ao poder de Eluna, acolhendo estranhos que de outra forma jamais seriam bem-vindos ali.\n\nMas a aldeia já viu noites mais sombrias que qualquer festival. Foi aqui que o Guardião Remulos enfrentou o dragão do Pesadelo Eranikus, corrompido e voltado contra a aldeia. Criaturas do Pesadelo caíram sobre Refúgio Noturno, ameaçando destruí-la por completo, até que Tyrande Murmuréolo finalmente chegou e invocou a luz de Eluna para purificar o dragão da corrupção que o dominara. Os poços lunares ainda ardem com essa mesma luz.",
			source = "https://warcraft.wiki.gg/wiki/Nighthaven",
		},
		["shrine of remulos"] = {
			name = "Santuário de Remulos",
			short = "No oeste da Clareira da Lua fica o Santuário de Remulos, erguido em honra ao Guardião que vigia aquele lugar. Dentro dele vive o elfo noturno Tajarri, que orienta os jovens druidas que buscam aprender a forma aquática.",
			full = "No oeste da Clareira da Lua fica o Santuário de Remulos, erguido em honra ao Guardião que vigia aquele lugar. Dentro dele vive o elfo noturno Tajarri, que orienta os jovens druidas que buscam aprender a forma aquática.",
			source = "https://warcraft.wiki.gg/wiki/Shrine_of_Remulos",
		},
		["stormrage barrow dens"] = {
			name = "Templos de Tempesfúria",
			short = "Sob a relva tranquila da Clareira da Lua ficam as grutas, afundadas numa terra que muitos druidas elfos noturnos nunca deixam de verdade, com os corpos em repouso enquanto seus espíritos vagam pelo Sonho Esmeralda.",
			full = "Sob a relva tranquila da Clareira da Lua ficam as grutas, afundadas numa terra que muitos druidas elfos noturnos nunca deixam de verdade, com os corpos em repouso enquanto seus espíritos vagam pelo Sonho Esmeralda.\n\nFoi aqui que Malfurion Tempesfúria um dia dormiu, e por isso as grutas levam seu nome. Quando Tichondrius e seus senhores do medo vieram na Terceira Guerra, atacaram Malfurion onde ele jazia, quase destruindo sua gruta. Foi Tyrande Murmuréolo quem o despertou, chamando-o de volta ao mundo para enfrentar Archimonde e a Legião Ardente.\n\nDepois, quando o Círculo Cenariano falou em erguer uma segunda Árvore do Mundo, Malfurion voltou às grutas para meditar. Mais tarde, Tyrande veio procurá-lo e encontrou seu corpo imóvel, como se dormisse, sem que houvesse como despertá-lo. O Círculo julgou mais sensato não movê-lo: se seu espírito ainda vagasse pelo Sonho procurando o caminho de volta, precisaria encontrar o corpo onde o havia deixado. Assim ele ficou ali, vigiado pelo Círculo Cenariano e pela Irmandade de Eluna, com o corpo imóvel na gruta que leva seu nome.",
			source = "https://warcraft.wiki.gg/wiki/Stormrage_Barrow_Dens",
		},
		["timbermaw hold"] = {
			name = "Domínio dos Presamatos",
			short = "O Domínio dos Presamatos fica no nordeste da Selva Maleva, onde um túnel atravessa até a Clareira da Lua e Hibérnia. É a capital da tribo de furbolgs Presamatos.",
			full = "O Domínio dos Presamatos fica no nordeste da Selva Maleva, onde um túnel atravessa até a Clareira da Lua e Hibérnia. É a capital da tribo de furbolgs Presamatos.\n\nQuando a corrupção da Legião Ardente se infiltrou nas florestas sagradas de Kalimdor, os furbolgs caíram sob sua influência. Apenas a tribo Presamatos escapou dessa escuridão, abrigando-se em seu domínio enquanto assistia, impotente, à floresta que amava ser retorcida numa perversão purulenta de si mesma. Mesmo depois que a fonte dessa corrupção foi destruída, a mácula sobre as matas permaneceu.\n\nOs Presamatos agora desconfiam de todos os estranhos, com medo de serem confundidos com seus parentes corrompidos e atacados à primeira vista. Ainda assim, sabem que não podem resistir sozinhos, e aqueles que conquistam sua confiança descobrem que os Presamatos valorizam a amizade acima de tudo. Sua tradição xamânica persiste, rica na confecção de armaduras de couro e num antigo saber de cura. Acima de tudo, a tribo anseia por pôr fim ao sofrimento de seus parentes corrompidos, para que a floresta ancestral possa um dia ecoar de novo com os cânticos e as risadas que perdeu.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
	},
	-- Silithus: 19 subzones
	[1451] = {
		["bones of grakkarond"] = {
			name = "Ossos de Grakkarond",
			short = "No centro de Silithus jazem os enormes ossos do dragão Grakkarond, que tombou ali na Guerra das Areias Movediças.",
			full = "No centro de Silithus jazem os enormes ossos do dragão Grakkarond, que tombou ali na Guerra das Areias Movediças.",
			source = "https://warcraft.wiki.gg/wiki/Bones_of_Grakkarond",
		},
		["bronzebeard encampment"] = {
			name = "Acampamento Barbabronze",
			short = "O Acampamento Barbabronze fica no sul de Silithus, a leste da Muralha do Escaravelho.",
			full = "O Acampamento Barbabronze fica no sul de Silithus, a leste da Muralha do Escaravelho.",
			source = "https://warcraft.wiki.gg/wiki/Bronzebeard_Encampment",
		},
		["cenarion hold"] = {
			name = "Forte Cenariano",
			short = "O Forte Cenariano se ergueu em Silithus depois da Guerra das Areias Movediças, construído pelo Círculo Cenariano sobre um antigo povoado dos elfos noturnos.",
			full = "O Forte Cenariano se ergueu em Silithus depois da Guerra das Areias Movediças, construído pelo Círculo Cenariano sobre um antigo povoado dos elfos noturnos. É um dos grandes bastiões druídicos de Kalimdor, rivalizado em tamanho apenas pela própria Clareira da Lua, e seu propósito é único: segurar a linha contra os enxames silitídeos e vigiar a coisa enterrada sob as areias, o Deus Antigo aprisionado C'Thun, para que seus exércitos não voltem a se erguer.\n\nÉ um lugar duro e sitiado para se viver. Os silitídeos pressionam constantemente suas muralhas, e a região ao redor fica cada vez mais hostil. Mesmo assim, os mercadores do Forte mantêm suas barracas abertas, negociando com quem quer que faça a longa subida desde a Cratera Un'Goro, pois o comércio é escasso tão longe de tudo, e cada moeda importa.\n\nO caminho até ele serpenteia para o noroeste, saindo de Un'Goro, passando pela Pilha Musgosa e subindo por uma encosta íngreme de penhasco que volta sobre si mesma em zigue-zague antes de se abrir para os ermos escaldantes de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Hold",
		},
		["crystal vale"] = {
			name = "Vale de Cristal",
			short = "No extremo noroeste de Silithus fica o Vale de Cristal, um vale entregue a elementais da terra e do ar.",
			full = "No extremo noroeste de Silithus fica o Vale de Cristal, um vale entregue a elementais da terra e do ar. O tório corre farto sob sua pedra, mas o chão pertence primeiro aos espíritos que se agitam ali, inquietos e antigos. O Grão-lorde Dimitriano mantém um acampamento dentro do vale.\n\nÉ aqui que Trovejardus, o Perseguidor dos Ventos, pode ser invocado e preso de novo na lâmina que carrega sua fúria, uma obra de tempestade e vontade que poucos ousam tentar e menos ainda concluem.",
			source = "https://warcraft.wiki.gg/wiki/Crystal_Vale",
		},
		["hiveashi"] = {
			name = "Colme'Ashi",
			short = "A Colme'Ashi fica no norte de Silithus, com sua ninhada silitídea se espalhando para infestar o Pilar Enxameante, além de suas fronteiras.",
			full = "A Colme'Ashi fica no norte de Silithus, com sua ninhada silitídea se espalhando para infestar o Pilar Enxameante, além de suas fronteiras.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Ashi",
		},
		["hiveregal"] = {
			name = "Colme'Régia",
			short = "No sul de Silithus, os montes da Colme'Régia se erguem da areia, lar dos silitídeos, com túneis e quitina por toda parte em meio à poeira.",
			full = "No sul de Silithus, os montes da Colme'Régia se erguem da areia, lar dos silitídeos, com túneis e quitina por toda parte em meio à poeira.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Regal",
		},
		["hivezora"] = {
			name = "Colme'Zora",
			short = "A Colme'Zora é um ninho silitídeo escavado nas areias do oeste de Silithus.",
			full = "A Colme'Zora é um ninho silitídeo escavado nas areias do oeste de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Hive'Zora",
		},
		["ortells hideout"] = {
			name = "Esconderijo de Ortell",
			short = "No sudeste de Silithus, uma pequena caverna se abre nas encostas, lar de um eremita chamado Ortell.",
			full = "No sudeste de Silithus, uma pequena caverna se abre nas encostas, lar de um eremita chamado Ortell.",
			source = "https://warcraft.wiki.gg/wiki/Ortell's_Hideout",
		},
		["ravaged twilight camp"] = {
			name = "Acampamento Arrasado do Crepúsculo",
			short = "No Vale de Cristal, no noroeste de Silithus, fica um acampamento do Martelo do Crepúsculo, tomado pelo Grão-lorde Dimitriano.",
			full = "No Vale de Cristal, no noroeste de Silithus, fica um acampamento do Martelo do Crepúsculo, tomado pelo Grão-lorde Dimitriano.\n\nAqui Dimitriano permanece, mantendo este terreno para o culto.",
			source = "https://warcraft.wiki.gg/wiki/Ravaged_Twilight_Camp",
		},
		["scarab dais"] = {
			name = "Palanque do Escaravelho",
			short = "O Gongo do Escaravelho fica no Palanque do Escaravelho, a noroeste da Muralha do Escaravelho, diante de Ahn'Qiraj, no sul de Silithus.",
			full = "O Gongo do Escaravelho fica no Palanque do Escaravelho, a noroeste da Muralha do Escaravelho, diante de Ahn'Qiraj, no sul de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Dais",
		},
		["scarab wall"] = {
			name = "Muralha do Escaravelho",
			short = "A Muralha do Escaravelho se estende ao longo do limite sul de Silithus, isolando o deserto da cidade arruinada de Ahn'Qiraj, mais além.",
			full = "A Muralha do Escaravelho se estende ao longo do limite sul de Silithus, isolando o deserto da cidade arruinada de Ahn'Qiraj, mais além. Foi erguida da própria areia ao fim da Guerra das Areias Movediças, com sua massa de arenito subindo pelo menos trinta metros no céu. Acima dessa altura, onde a pedra não podia mais subir, a revoada bronze teceu sua magia numa barreira muitas vezes mais alta ainda.\n\nOs que a fizeram, elfos noturnos e dragões bronze juntos, deram-lhe o nome de Irana'ethil, Escudo contra a Sombra. O nome diz claramente para que ela servia: C'Thun e suas ninhadas silitídeas jaziam selados dentro de Ahn'Qiraj, e a muralha ficava entre esse horror e o resto do mundo.",
			source = "https://warcraft.wiki.gg/wiki/Scarab_Wall",
		},
		["southwind village"] = {
			name = "Vila do Vento Sul",
			short = "A Vila do Vento Sul foi um posto avançado dos elfos noturnos em Silithus. Não sobreviveu à Guerra das Areias Movediças.",
			full = "A Vila do Vento Sul foi um posto avançado dos elfos noturnos em Silithus. Não sobreviveu à Guerra das Areias Movediças.\n\nQuando os qirajis se ergueram em suas multidões fervilhantes, Valstann Guenelmo, filho de Fandral Guenelmo, liderou um destacamento do exército dos elfos noturnos para defender a vila. Suas tropas foram massacradas onde estavam, e o próprio Valstann foi capturado vivo pelo General Rajaxx enquanto a vila que fora enviado para defender era despedaçada às suas costas.\n\nO que os qirajis deixaram para trás não ficou vazio. Os espíritos dos druidas e das Sentinelas que caíram no massacre permanecem entre os destroços, vagando sem propósito, presos ao lugar de sua morte, seguindo a Sombra de Ambermoon. A Vila do Vento Sul continua de pé não como uma ruína silenciosa, mas como solo assombrado, com seus mortos ainda sem ter terminado com ela.",
			source = "https://warcraft.wiki.gg/wiki/Southwind_Village",
		},
		["staghelm point"] = {
			name = "Posto Guenelmo",
			short = "Uma torre dos elfos noturnos um dia coroou um pico no nordeste de Silithus. Aqui Ralo'shan, a Eterna Vigia, mantém seu posto, com um draco bronze da ninhada de Nozdormu circulando no céu acima dela.",
			full = "Uma torre dos elfos noturnos um dia coroou um pico no nordeste de Silithus. Aqui Ralo'shan, a Eterna Vigia, mantém seu posto, com um draco bronze da ninhada de Nozdormu circulando no céu acima dela. Estrada abaixo, a partir da torre, fica o Passeio do Crepúsculo, uma caverna que abriga cultistas do Crepúsculo, com um pequeno acampamento em sua entrada, uma ameaça com a qual a vigia precisa lidar.",
			source = "https://warcraft.wiki.gg/wiki/Staghelm_Point",
		},
		["swarming pillar"] = {
			name = "Pilar Enxameante",
			short = "O Pilar Enxameante se ergue ao sul do Forte Cenariano, um pico crivado de túneis silitídeos, com encostas que nunca ficam paradas.",
			full = "O Pilar Enxameante se ergue ao sul do Forte Cenariano, um pico crivado de túneis silitídeos, com encostas que nunca ficam paradas. Uma névoa de pequenos silitídeos circula a pedra a toda hora, uma nuvem viva que deu nome ao pilar, e sob a areia em seu sopé fica uma das câmaras da colmeia, o maior dos muitos ninhos que perfuram como favos o chão de Silithus.",
			source = "https://warcraft.wiki.gg/wiki/Swarming_Pillar",
		},
		["twilight base camp"] = {
			name = "Acampamento do Crepúsculo",
			short = "O Acampamento do Crepúsculo é um dos quatro acampamentos que o culto do Martelo do Crepúsculo ergueu pelos ermos de Silithus, um ponto de apoio para os que servem à vinda dos Deuses Antigos em meio à poeira e à ruína daquela terra varrida pelo vento.",
			full = "O Acampamento do Crepúsculo é um dos quatro acampamentos que o culto do Martelo do Crepúsculo ergueu pelos ermos de Silithus, um ponto de apoio para os que servem à vinda dos Deuses Antigos em meio à poeira e à ruína daquela terra varrida pelo vento.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Base_Camp",
		},
		["twilight outpost"] = {
			name = "Posto Avançado do Crepúsculo",
			short = "O Posto Avançado do Crepúsculo fica no extremo sudoeste de Silithus, perto da Muralha do Escaravelho, a oeste do Acampamento Barbabronze. É ocupado pelo culto do Martelo do Crepúsculo.",
			full = "O Posto Avançado do Crepúsculo fica no extremo sudoeste de Silithus, perto da Muralha do Escaravelho, a oeste do Acampamento Barbabronze. É ocupado pelo culto do Martelo do Crepúsculo.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Outpost",
		},
		["twilight post"] = {
			name = "Posto Crepúsculo",
			short = "O Posto Crepúsculo fica no noroeste de Silithus, a oeste do Forte Cenariano e a noroeste do Acampamento do Crepúsculo, um ponto de apoio reivindicado pelo Martelo do Crepúsculo naquela terra varrida pelo vento e coberta de areia.",
			full = "O Posto Crepúsculo fica no noroeste de Silithus, a oeste do Forte Cenariano e a noroeste do Acampamento do Crepúsculo, um ponto de apoio reivindicado pelo Martelo do Crepúsculo naquela terra varrida pelo vento e coberta de areia.",
			source = "https://warcraft.wiki.gg/wiki/Twilight_Post",
		},
		["twilights run"] = {
			name = "Passeio do Crepúsculo",
			short = "O Passeio do Crepúsculo fica escondido na rocha, na base do Posto Guenelmo, no norte de Silithus.",
			full = "O Passeio do Crepúsculo fica escondido na rocha, na base do Posto Guenelmo, no norte de Silithus. A boca de sua caverna não dá pista do que enche a escuridão mais além: câmara após câmara entregues ao Culto do Martelo do Crepúsculo, que fez desta cavidade na montanha sua morada, profunda e invisível, enquanto o vento do deserto varre a pedra acima deles.",
			source = "https://warcraft.wiki.gg/wiki/Twilight's_Run",
		},
		["valors rest"] = {
			name = "Repouso dos Valorosos",
			short = "O Repouso dos Valorosos é um pequeno acampamento na borda de Silithus, alcançado pela trilha que sobe do canto noroeste da Cratera Un'Goro, o primeiro chão que o viajante atravessa ao subir para as areias.",
			full = "O Repouso dos Valorosos é um pequeno acampamento na borda de Silithus, alcançado pela trilha que sobe do canto noroeste da Cratera Un'Goro, o primeiro chão que o viajante atravessa ao subir para as areias.\n\nO acampamento é cuidado por membros do Círculo Cenariano, que dividem o terreno com uma infestação de insetos que parece inquietantemente familiar. Tanto a Aliança quanto a Horda se abrigam aqui de passagem, e túmulos repousam em silêncio em sua borda.",
			source = "https://warcraft.wiki.gg/wiki/Valor's_Rest",
		},
	},
	-- Hibérnia: 18 subzones
	[1452] = {
		["banthallow barrow den"] = {
			name = "Gruta de Ban'Thallow",
			short = "Atrás da Aldeia Chuva Estelar, em Hibérnia, fica a Gruta de Ban'Thallow, um labirinto de túneis que guarda relíquias abençoadas estimadas pela aldeia.",
			full = "Atrás da Aldeia Chuva Estelar, em Hibérnia, fica a Gruta de Ban'Thallow, um labirinto de túneis que guarda relíquias abençoadas estimadas pela aldeia.",
			source = "https://warcraft.wiki.gg/wiki/Ban'Thallow_Barrow_Den",
		},
		["darkwhisper gorge"] = {
			name = "Garganta do Sussurro Sombrio",
			short = "A Garganta do Sussurro Sombrio fica no sul de Hibérnia.",
			full = "A Garganta do Sussurro Sombrio fica no sul de Hibérnia.\n\nQuando o exército da Legião Ardente se despedaçou no Monte Hyjal na Terceira Guerra e Archimonde caiu, os demônios que sobreviveram não desapareceram do mundo. Fugiram para a Garganta do Sussurro Sombrio e se refugiaram ali, remanescentes de uma hoste que quase destruíra o mundo, deixados para apodrecer na escuridão.",
			source = "https://warcraft.wiki.gg/wiki/Darkwhisper_Gorge",
		},
		["dun mandarr"] = {
			name = "Dun Mandarr",
			short = "Dun Mandarr fica perto de uma caverna gelada no sudeste de Hibérnia, com um nome que denuncia mãos anãs. Luniscos ferozes tomaram o acampamento agora, e pouco mais resta de quem o ergueu.",
			full = "Dun Mandarr fica perto de uma caverna gelada no sudeste de Hibérnia, com um nome que denuncia mãos anãs. Luniscos ferozes tomaram o acampamento agora, e pouco mais resta de quem o ergueu.",
			source = "https://warcraft.wiki.gg/wiki/Dun_Mandarr",
		},
		["everlook"] = {
			name = "Visteterna",
			short = "Visteterna fica onde as rotas comerciais de Hibérnia se cruzam, um posto goblin do Cartel Bondebico, com seu laboratório escondido entre as construções.",
			full = "Visteterna fica onde as rotas comerciais de Hibérnia se cruzam, um posto goblin do Cartel Bondebico, com seu laboratório escondido entre as construções.\n\nA Aurora Argêntea enviou Gregor Pedragris para cá, para falar por seus interesses diante do governo local do Cartel.",
			source = "https://warcraft.wiki.gg/wiki/Everlook",
		},
		["frostfire hot springs"] = {
			name = "Fontes Termais de Fogofrio",
			short = "O vapor sobe de uma cadeia de poças no extremo oeste de Hibérnia, água quente demais para a terra congelada ao redor. Ninguém explicou por que as fontes ardem quentes sob a neve e o gelo.",
			full = "O vapor sobe de uma cadeia de poças no extremo oeste de Hibérnia, água quente demais para a terra congelada ao redor. Ninguém explicou por que as fontes ardem quentes sob a neve e o gelo. Bruna Covaneve, acampada ali perto, se pergunta se alguma mácula demoníaca que escorre para o norte desde a Garganta do Sussurro Sombrio não teria encontrado caminho até aqui para aquecer a pedra.\n\nA poça mais próxima do Domínio dos Presamatos nunca se livrou do domínio da tribo Invernosos. Eles ainda a ocupam, e os furbolgs não estão dispostos a dividir o calor que conquistaram.",
			source = "https://warcraft.wiki.gg/wiki/Frostfire_Hot_Springs",
		},
		["frostsaber rock"] = {
			name = "Pedra Sabre-de-gelo",
			short = "No alto da Pedra Sabre-de-gelo está Ripárion Glaciares, guardião do vínculo entre os sabres-de-gelo e aqueles que desejam montá-los.",
			full = "No alto da Pedra Sabre-de-gelo está Ripárion Glaciares, guardião do vínculo entre os sabres-de-gelo e aqueles que desejam montá-los. Ele ensina os amigos da Aliança que o merecem a domar e montar os grandes felinos brancos que rondam a pedra gelada lá embaixo.",
			source = "https://warcraft.wiki.gg/wiki/Frostsaber_Rock",
		},
		["frostwhisper gorge"] = {
			name = "Garganta dos Sussurros Gelados",
			short = "A Garganta dos Sussurros Gelados corta o sul de Hibérnia, com o fundo e as cristas pontilhados de ruínas dos elfos noturnos. Entre essas pedras antigas vivem os gigantes Frostmaul e seus imensos Preservadores.",
			full = "A Garganta dos Sussurros Gelados corta o sul de Hibérnia, com o fundo e as cristas pontilhados de ruínas dos elfos noturnos. Entre essas pedras antigas vivem os gigantes Frostmaul e seus imensos Preservadores.",
			source = "https://warcraft.wiki.gg/wiki/Frostwhisper_Gorge",
		},
		["hidden grove"] = {
			name = "Bosque Oculto",
			short = "O Bosque Oculto fica afundado numa cratera em Hibérnia, cercado por todos os lados por penhascos íngremes.",
			full = "O Bosque Oculto fica afundado numa cratera em Hibérnia, cercado por todos os lados por penhascos íngremes. Apenas uma única caverna, aberta na crista sudeste, oferece passagem, e descer das alturas lá de cima é um caminho que poucos ousariam.\n\nUm dia esta cavidade não abrigava nada mais temível que lebres brancas, prosperando sem ser perturbadas em seu abrigo. Isso mudou. O bosque agora está tomado por luniscos, hostis a qualquer um que entre, e sua presença fechou o lugar tão bem quanto seus penhascos jamais fizeram.",
			source = "https://warcraft.wiki.gg/wiki/Hidden_Grove",
		},
		["ice thistle hills"] = {
			name = "Serra Cardo de Gelo",
			short = "A Serra Cardo de Gelo se ergue a sudeste de Visteterna, lar dos yetis Cardo de Gelo, que se entocam numa caverna que sobe pela encosta e percorrem as encostas ao redor.",
			full = "A Serra Cardo de Gelo se ergue a sudeste de Visteterna, lar dos yetis Cardo de Gelo, que se entocam numa caverna que sobe pela encosta e percorrem as encostas ao redor. Sua pelagem espessa e seus chifres claros são valorizados pelos que enfrentam o frio para obtê-los.\n\nCapas-de-gelo crescem pelas encostas abertas, e dentro da caverna veios de tório correm pela rocha. O mais raro de tudo, bem na borda da caverna, dizem que às vezes floresce um lótus negro, frágil e estranho em meio ao território dos yetis.",
			source = "https://warcraft.wiki.gg/wiki/Ice_Thistle_Hills",
		},
		["lake keltheril"] = {
			name = "Lago Kel'Theril",
			short = "As águas congeladas do Lago Kel'Theril repousam imóveis no coração de Hibérnia, cercadas pelas ruínas que levam o mesmo nome.",
			full = "As águas congeladas do Lago Kel'Theril repousam imóveis no coração de Hibérnia, cercadas pelas ruínas que levam o mesmo nome. As ruínas são obra antiga dos Bem-nascidos, e os que um dia viveram ali não partiram quando seus salões caíram. Seus espíritos ainda se demoram, atormentados, vagando pelo gelo e pelas pedras quebradas.",
			source = "https://warcraft.wiki.gg/wiki/Lake_Kel'Theril",
		},
		["mazthoril"] = {
			name = "Mazthoril",
			short = "No fundo do gelo de Hibérnia, perto do Lago Kel'Theril, a caverna de Mazthoril se abre sob a terra, fria, vasta e repleta de magia.",
			full = "No fundo do gelo de Hibérnia, perto do Lago Kel'Theril, a caverna de Mazthoril se abre sob a terra, fria, vasta e repleta de magia. Aqui vive uma ninhada de dragões azuis, jurados a Malygos, e aqui sua matriarca mantém sua vigília solitária.\n\nHaleh raramente assume qualquer forma que o mundo chamaria de verdadeira, mostrando-se apenas como uma alta elfa de pé no ponto mais alto da caverna, alcançado por uma runa de passagem incrustada no chão, bem lá embaixo. Poucos que não são de sua espécie chegam a ver seu rosto.\n\nAo seu redor, ela pôs uma guarda à altura de seu isolamento. Quatro dracos poderosos respondem somente a ela. Magibocarra faz um circuito lento e ininterrupto por um terço das regiões baixas de Hibérnia, enquanto Manágarra e Vidente guardam as runas nos fundos da caverna como sentinelas diante de uma porta trancada.",
			source = "https://warcraft.wiki.gg/wiki/Mazthoril",
		},
		["moon horror den"] = {
			name = "Antro Lunorror",
			short = "A uma curta caminhada a nordeste dos portões de Visteterna, o chão sobe em direção a uma pequena caverna conhecida como Antro Lunorror, lar de ferozes Corujudos Enfurecidos.",
			full = "A uma curta caminhada a nordeste dos portões de Visteterna, o chão sobe em direção a uma pequena caverna conhecida como Antro Lunorror, lar de ferozes Corujudos Enfurecidos. Uma montanha fica entre o antro e a Aldeia dos Invernosos ao sul, por mais próximos que os dois lugares pareçam, de modo que nenhum caminho direto os liga, apenas uma longa volta em torno das terras altas.",
			source = "https://warcraft.wiki.gg/wiki/Moon_Horror_Den",
		},
		["owl wing thicket"] = {
			name = "Matagal da Asa da Coruja",
			short = "As cavernas do Matagal da Asa da Coruja cortam o sul de Hibérnia, lar de corujudos enfurecidos, tocados pela lua e enlouquecidos.",
			full = "As cavernas do Matagal da Asa da Coruja cortam o sul de Hibérnia, lar de corujudos enfurecidos, tocados pela lua e enlouquecidos. Dizem que os antigos Guardiões de Eluna contam aqui como os luniscos surgiram no mundo, uma história guardada por Ranshalla.",
			source = "https://warcraft.wiki.gg/wiki/Owl_Wing_Thicket",
		},
		["ruins of keltheril"] = {
			name = "Ruínas de Kel'Theril",
			short = "As Ruínas de Kel'Theril jazem partidas nas margens do lago que leva seu nome, tudo o que resta de uma grande cidade dos elfos noturnos.",
			full = "As Ruínas de Kel'Theril jazem partidas nas margens do lago que leva seu nome, tudo o que resta de uma grande cidade dos elfos noturnos. Ela caiu durante a Grande Cisão, quando o próprio mundo foi despedaçado, e nunca mais se reergueu.\n\nO que permanece ali agora é o luto tornado inquieto. Os Bem-nascidos que morreram quando Kel'Theril caiu não partiram; seus espíritos permanecem entre as colunas caídas das ruínas do norte, atormentados, incapazes de largar o que perderam. Fantasmas de altos elfos assombram a parte leste, entre eles patrulheiros traídos e um arquimago.\n\nUm cristal chamado Zin-Malor está ligado à queda deste lugar, preso a uma destruição que engoliu geração após geração de elfos aqui. Essa história pertence à própria Kel'Theril, às pedras caídas e aos fantasmas que ainda caminham entre elas.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Kel'Theril",
		},
		["starfall village"] = {
			name = "Aldeia Chuva Estelar",
			short = "A Aldeia Chuva Estelar fica ao longo da estrada que atravessa Hibérnia, o único lugar daquela terra fria onde a Aliança mantém um ponto de apoio.",
			full = "A Aldeia Chuva Estelar fica ao longo da estrada que atravessa Hibérnia, o único lugar daquela terra fria onde a Aliança mantém um ponto de apoio. Um pavilhão dos elfos noturnos e uma casa menor formam o povoado, e perto dali fica a Gruta de Ban'Thallow, afundada na terra como os túmulos de que tira seu nome.",
			source = "https://warcraft.wiki.gg/wiki/Starfall_Village",
		},
		["timbermaw hold"] = {
			name = "Domínio dos Presamatos",
			short = "O Domínio dos Presamatos fica nos túneis do norte da Selva Maleva, a passagem que se abre para a Clareira da Lua e Hibérnia, e é o último bastião da tribo de furbolgs Presamatos.",
			full = "O Domínio dos Presamatos fica nos túneis do norte da Selva Maleva, a passagem que se abre para a Clareira da Lua e Hibérnia, e é o último bastião da tribo de furbolgs Presamatos.\n\nQuando a corrupção da Legião Ardente se infiltrou nas florestas sagradas de Kalimdor, os furbolgs daquela terra caíram sob ela, retorcidos em algo selvagem e cruel. Apenas a tribo Presamatos escapou desse destino, mantendo-se em seus túneis enquanto a floresta que amava era transformada ao seu redor numa perversão purulenta de si mesma. Mesmo depois que a fonte da corrupção foi destruída, a mácula sobre as matas não se desfez.\n\nOs Presamatos continuam desconfiados de todos os estranhos, com medo de serem confundidos com seus parentes corrompidos e abatidos antes de poderem provar o contrário. Ainda assim, sabem que não podem resistir sozinhos e, com aqueles que conquistam sua confiança, são generosos: mantêm os velhos costumes xamânicos e compartilham livremente o saber de cura que guardam. O que mais desejam é o fim do sofrimento de seus irmãos corrompidos e uma cura para as feridas que a Selva Maleva sofreu.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Hold",
		},
		["timbermaw post"] = {
			name = "Posto Presamatos",
			short = "O Posto Presamatos mantém um nome que já não lhe cabe.",
			full = "O Posto Presamatos mantém um nome que já não lhe cabe. O acampamento um dia pertenceu à tribo Presamatos, mas agora responde aos furbolgs Invernosos corrompidos, que o ocupam por completo, a sudeste das Fontes Termais de Fogofrio e a oeste do Lago Kel'Theril.",
			source = "https://warcraft.wiki.gg/wiki/Timbermaw_Post",
		},
		["winterfall village"] = {
			name = "Aldeia dos Invernosos",
			short = "A Aldeia dos Invernosos sobe pelas encostas do leste de Hibérnia, perto de Visteterna, com seus furbolgs há muito corrompidos. No topo fica uma pequena caverna, a sede do Grão-chefe Invernoso, que governa o povoado de lá.",
			full = "A Aldeia dos Invernosos sobe pelas encostas do leste de Hibérnia, perto de Visteterna, com seus furbolgs há muito corrompidos. No topo fica uma pequena caverna, a sede do Grão-chefe Invernoso, que governa o povoado de lá.",
			source = "https://warcraft.wiki.gg/wiki/Winterfall_Village",
		},
	},
	-- Ventobravo: 3 subzones
	[1453] = {
		["champions hall"] = {
			name = "Salão dos Campeões",
			short = "No sul da Cidade Velha de Ventobravo fica o Salão dos Campeões, onde os oficiais da Aliança ficam aquartelados, separados dentro da cidade antiga como convém à sua posição.",
			full = "No sul da Cidade Velha de Ventobravo fica o Salão dos Campeões, onde os oficiais da Aliança ficam aquartelados, separados dentro da cidade antiga como convém à sua posição.",
			source = "https://warcraft.wiki.gg/wiki/Champions'_Hall",
		},
		["deeprun tram"] = {
			name = "Metrô Correfundo",
			short = "O Rei Magni Barbabronze não construiu o Metrô Correfundo por conforto.",
			full = "O Rei Magni Barbabronze não construiu o Metrô Correfundo por conforto. Nos anos seguintes à Segunda Guerra, enquanto Ventobravo trabalhava para se reconstruir das ruínas, Magni se impacientou com a lentidão com que a ajuda de Altaforja chegava a seus aliados humanos e se inquietou com a lentidão com que os soldados anões poderiam alcançá-los caso a guerra voltasse. Recorreu ao Grão-faz-tudo Gelbin Mekkatorque, o engenheiro mais respeitado de Azeroth, e o pôs para resolver o problema. A resposta de Mekkatorque foi uma ferrovia aberta sob a própria terra, ligando diretamente as duas capitais.\n\nOs construtores encontraram um lago subterrâneo no caminho do túnel e não o contornaram. O metrô ainda passa por ele, com seus trilhos fechados correndo por baixo da água, e não ao lado dela.\n\nGnomos cuidam do metrô todos os dias, mantendo seus dois conjuntos de três vagões correndo rápidos e suaves entre Altaforja e Ventobravo, de graça para todos que passam pelas plataformas subterrâneas.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["valley of heroes"] = {
			name = "Vale dos Heróis",
			short = "Uma ponte de pedra clara leva todo viajante sobre o fosso diante do portão sul de Ventobravo, até um vale verde ladeado de estátuas erguidas tanto pelo luto quanto pela glória.",
			full = "Uma ponte de pedra clara leva todo viajante sobre o fosso diante do portão sul de Ventobravo, até um vale verde ladeado de estátuas erguidas tanto pelo luto quanto pela glória.\n\nDepois da Segunda Guerra, quando Ventobravo foi reconstruída das ruínas, a cidade homenageou os que lideraram a Expedição da Aliança pelo Portal Negro para selá-lo do outro lado. Kurdran Martelo Feroz e o Arquimago Khadgar estão à esquerda da estrada; o Comandante de Tropas Danath Matatroll e a Capitã-patrulheira Alleria Correventos, à direita; e no fim da estrada, onde ela se bifurca para entrar na cidade propriamente dita, está o General Turalyon, que liderou todos eles. Nenhum dos cinco jamais voltou.\n\nAnos depois, Arator, filho de Alleria e Turalyon, foi levado a uma cerimônia no vale, carregado nos ombros de um Cavaleiro do Punho de Prata. Ele olhou para a semelhança em pedra de sua mãe, um rosto de que não tinha lembrança. Algo dela o alcançou ali, pois o menino sorriu e estendeu a mão em direção à estátua. Ele voltaria vez após vez enquanto crescia, para ficar diante do rosto dela e saber, sem se lembrar dela, que ela o havia amado.",
			source = "https://warcraft.wiki.gg/wiki/Valley_of_Heroes",
		},
	},
	-- Orgrimmar: 2 subzones
	[1454] = {
		["hall of legends"] = {
			name = "Salão dos Lendários",
			short = "O Salão dos Lendários fica no Vale da Força, em Orgrimmar, o quartel onde os oficiais da Horda se reúnem em conselho.",
			full = "O Salão dos Lendários fica no Vale da Força, em Orgrimmar, o quartel onde os oficiais da Horda se reúnem em conselho.\n\nEm seu centro, uma mesa está coberta de mapas de Azeroth.",
			source = "https://warcraft.wiki.gg/wiki/Hall_of_Legends",
		},
		["ragefire chasm"] = {
			name = "Cavernas Ígneas",
			short = "Sob Orgrimmar, a terra se abre num abismo ardente, com túneis sufocados por lava e fumaça. Troggs começaram a subir das profundezas aqui, um clã que a Horda passou a chamar de troggs Ígneos.",
			full = "Sob Orgrimmar, a terra se abre num abismo ardente, com túneis sufocados por lava e fumaça. Troggs começaram a subir das profundezas aqui, um clã que a Horda passou a chamar de troggs Ígneos. Magatha, a Vidente, dos taurens, tentou fazer as pazes com eles, na esperança de afastá-los da cidade lá em cima. Foi recebida apenas com hostilidade. Ficou claro que essas criaturas não tinham interesse em diplomacia e que, se não fossem contidas, poderiam sobrepujar a Horda por completo.\n\nPior ainda, a trama chegou à própria Orgrimmar. Neeru Fireblade, que escondia sua verdadeira lealdade como líder da Lâmina Ardente, atraiu os próprios seguidores leais de Thrall para dentro do abismo, entregando-os a uma seita de cultistas sombrios abrigados ali, tanto para se livrar deles quanto para testar se os cultistas eram confiáveis. Thrall sabe mais da traição do que deixa transparecer, mas os líderes cultistas ainda dominam as cavernas que tomaram para si.",
			source = "https://warcraft.wiki.gg/wiki/Ragefire_Chasm",
		},
	},
	-- Altaforja: 2 subzones
	[1455] = {
		["deeprun tram"] = {
			name = "Metrô Correfundo",
			short = "O Rei Magni Barbabronze não construiu o Metrô Correfundo por conforto.",
			full = "O Rei Magni Barbabronze não construiu o Metrô Correfundo por conforto. Nos anos seguintes à Segunda Guerra, enquanto Ventobravo trabalhava para se reconstruir das ruínas, Magni se impacientou com a lentidão com que a ajuda de Altaforja chegava a seus aliados humanos e se inquietou com a lentidão com que os soldados anões poderiam alcançá-los caso a guerra voltasse. Recorreu ao Grão-faz-tudo Gelbin Mekkatorque, o engenheiro mais respeitado de Azeroth, e o pôs para resolver o problema. A resposta de Mekkatorque foi uma ferrovia aberta sob a própria terra, ligando diretamente as duas capitais.\n\nOs construtores encontraram um lago subterrâneo no caminho do túnel e não o contornaram. O metrô ainda passa por ele, com seus trilhos fechados correndo por baixo da água, e não ao lado dela.\n\nGnomos cuidam do metrô todos os dias, mantendo seus dois conjuntos de três vagões correndo rápidos e suaves entre Altaforja e Ventobravo, de graça para todos que passam pelas plataformas subterrâneas.",
			source = "https://warcraft.wiki.gg/wiki/Deeprun_Tram",
		},
		["gates of ironforge"] = {
			name = "Portões de Altaforja",
			short = "Os Portões de Altaforja se erguem onde a grande rampa de Dun Morogh sobe para encontrar a montanha, visíveis a quilômetros de distância sobre a neve antes que o viajante chegue até eles.",
			full = "Os Portões de Altaforja se erguem onde a grande rampa de Dun Morogh sobe para encontrar a montanha, visíveis a quilômetros de distância sobre a neve antes que o viajante chegue até eles. São o limiar entre as terras abertas dos anões e a própria Altaforja.\n\nAo atravessá-los, fica-se sob o olhar de uma enorme estátua erguida ao Grão-rei Modimus Sidermar, posta para vigiar logo depois da entrada, de modo que ninguém entre na cidade sem antes passar sob seus olhos.",
			source = "https://warcraft.wiki.gg/wiki/Gates_of_Ironforge",
		},
	},
	-- Penhasco do Trovão: 4 subzones
	[1456] = {
		["elder rise"] = {
			name = "Platô dos Anciãos",
			short = "O Platô dos Anciãos fica a leste do penhasco central, alcançado por pontes de corda que levam ao platô alto e ao platô do meio.",
			full = "O Platô dos Anciãos fica a leste do penhasco central, alcançado por pontes de corda que levam ao platô alto e ao platô do meio. Aqui o Círculo Cenariano tem sua sede, onde druidas e sacerdotes taurens se reúnem, e onde reside o Arquidruida Hamuul Runa Totem. O Conselho dos Anciãos também exerce seu governo aqui.\n\nEntre as duas pontes fica uma cabana tomada por Magatha Temível Totem, líder da tribo Temível Totem.",
			source = "https://warcraft.wiki.gg/wiki/Elder_Rise",
		},
		["hunter rise"] = {
			name = "Platô dos Caçadores",
			short = "O platô sul do Penhasco do Trovão pertence aos que lutam e aos que caçam.",
			full = "O platô sul do Penhasco do Trovão pertence aos que lutam e aos que caçam. Aqui fica o Salão dos Caçadores, onde os taurens treinam seus guerreiros e caçadores, e onde armadilheiros, rastreadores e curtidores se dedicam a seus ofícios. Pontes de corda ligam o platô aos caminhos de cima e de baixo, integrando-o ao resto do penhasco.",
			source = "https://warcraft.wiki.gg/wiki/Hunter_Rise",
		},
		["pools of vision"] = {
			name = "Poços das Visões",
			short = "Abaixo do topo do Platô dos Espíritos, um túnel se abre para águas escuras e paradas conhecidas como Poços das Visões.",
			full = "Abaixo do topo do Platô dos Espíritos, um túnel se abre para águas escuras e paradas conhecidas como Poços das Visões. Os Renegados mantêm aqui um ponto de apoio, no fundo do território tauren, um centro para seus magos e sacerdotes, com um emissário dos Profanadores Renegados recrutando combatentes para a batalha entre os poços.",
			source = "https://warcraft.wiki.gg/wiki/Pools_of_Vision",
