		["spirit rise"] = {
			name = "Platô dos Espíritos",
			short = "O Platô dos Espíritos fica a noroeste do penhasco central, dedicado aos estudos xamânicos entre os taurens. A tribo Persegue-céus exerce seu domínio aqui.",
			full = "O Platô dos Espíritos fica a noroeste do penhasco central, dedicado aos estudos xamânicos entre os taurens. A tribo Persegue-céus exerce seu domínio aqui. Sob a superfície da mesa ficam os Poços das Visões, com águas aquecidas por vapor escondido. Pontes de corda descem até os platôs de baixo e do meio, unindo as alturas.",
