	-- Darnassus: 5 subzones
	[1457] = {
		["cenarion enclave"] = {
			name = "Enclave Cenariano",
			short = "O Enclave Cenariano fica no noroeste de Darnassus, um bosque circular onde carvalhos e freixos se erguem mais altos que os salões de pedra do resto da cidade.",
			full = "O Enclave Cenariano fica no noroeste de Darnassus, um bosque circular onde carvalhos e freixos se erguem mais altos que os salões de pedra do resto da cidade. Cada árvore aqui traz runas que não foram entalhadas, mas cresceram da própria casca viva, e os pontos de encontro do bosque são eles mesmos formados de madeira e pedra trabalhadas juntas, como se tivessem sido cultivados em vez de construídos.\n\nEste sempre foi o lugar dos druidas da cidade, assim como o Templo da Lua é o lugar de seus sacerdotes. O Arquidruida Fandral Guenelmo os lidera dos galhos do Enclave, e a maior de suas estruturas vivas, no coração do bosque, é sua própria residência.\n\nO bosque ainda serve à ordem que se reúne sob ele: druidas vêm aqui para aprender os velhos costumes, caçadores treinam em sua árvore mais a leste, e ao pé da grande árvore do Enclave pode-se aprender a montar os sabres-noturnos que levam os cavaleiros de Darnassus pelos ermos. Sob o chão, escondida no galho mais a oeste, uma guilda secreta de ladinos mantém seus aposentos, conhecidos apenas por quem já sabe onde procurar.",
			source = "https://warcraft.wiki.gg/wiki/Cenarion_Enclave",
		},
		["craftsmens terrace"] = {
			name = "Terraço dos Artesãos",
			short = "O Terraço dos Artesãos fica no norte de Darnassus, dedicado ao comércio, e não à guerra ou à adoração. Aqui os artesãos da cidade mantêm suas lojas, e os viajantes cansados podem se abrigar numa das estalagens de Darnassus.",
			full = "O Terraço dos Artesãos fica no norte de Darnassus, dedicado ao comércio, e não à guerra ou à adoração. Aqui os artesãos da cidade mantêm suas lojas, e os viajantes cansados podem se abrigar numa das estalagens de Darnassus. Uma embaixada da Aurora Argêntea também fica aqui, uma presença estrangeira que recebeu um lugar dentro da cidade élfica.\n\nO terraço faz divisa com o Terraço dos Guerreiros ao sul e com o Enclave Cenariano a oeste.",
			source = "https://warcraft.wiki.gg/wiki/Craftsmen's_Terrace",
		},
		["temple gardens"] = {
			name = "Jardins do Templo",
			short = "No coração de Darnassus ficam os Jardins do Templo, uma ampla extensão de água, passarelas e pequenas ilhas que levam o nome do grande Templo da Lua, que se ergue logo ao sul.",
			full = "No coração de Darnassus ficam os Jardins do Templo, uma ampla extensão de água, passarelas e pequenas ilhas que levam o nome do grande Templo da Lua, que se ergue logo ao sul. Pontes se estendem em todas as direções, ligando o Enclave Cenariano ao norte, os Terraços dos Artesãos, dos Guerreiros e dos Mercadores a leste, e o Templo da Lua ao sul, de modo que todos os caminhos da cidade parecem se reunir aqui.\n\nA maior ilha abriga o banco da cidade, e um portal na borda oeste dos jardins oferece passagem até a Vila de Rut'theran, na base da Árvore do Mundo, fazendo deste tranquilo centro de água e pedra também o limiar entre Darnassus e o mundo lá fora.",
			source = "https://warcraft.wiki.gg/wiki/Temple_Gardens",
		},
		["tradesmens terrace"] = {
			name = "Terraço dos Mercadores",
			short = "O Terraço dos Mercadores fica no sul de Darnassus, onde os lojistas mantêm suas barracas e os comerciantes se reúnem para negociar, fazendo dele o coração do comércio de toda a cidade.",
			full = "O Terraço dos Mercadores fica no sul de Darnassus, onde os lojistas mantêm suas barracas e os comerciantes se reúnem para negociar, fazendo dele o coração do comércio de toda a cidade. Ao norte, ele se abre para o Terraço dos Guerreiros e, a oeste, os caminhos levam ao Templo da Lua e aos Jardins do Templo.\n\nSuas construções são feitas de madeira cultivada, à maneira dos elfos noturnos, coisas leves e graciosas.",
			source = "https://warcraft.wiki.gg/wiki/Tradesmen's_Terrace",
		},
		["warriors terrace"] = {
			name = "Terraço dos Guerreiros",
			short = "O Terraço dos Guerreiros abriga o portão leste de Darnassus, onde a cidade se abre para os ermos de Teldrassil.",
			full = "O Terraço dos Guerreiros abriga o portão leste de Darnassus, onde a cidade se abre para os ermos de Teldrassil. Aqui as Sentinelas mantêm seu posto, e qualquer elfo noturno que queira pegar em armas a serviço da cidade vem a este terraço para isso, treinando nos campos de tiro ao alvo e nas arenas de duelo até que sua habilidade esteja pronta para a guerra.\n\nCavaleiros montados em sabres-noturnos vigiam os portões, e o terraço é o escudo da cidade contra qualquer violência que suba pela estrada vinda da floresta.\n\nEle faz divisa com o Terraço dos Artesãos ao norte, com o Terraço dos Mercadores ao sul e com os Jardins do Templo a oeste, de modo que um guerreiro que treina aqui está ao alcance da voz dos artesãos, dos mercadores e dos sacerdotes da cidade.",
			source = "https://warcraft.wiki.gg/wiki/Warrior's_Terrace",
		},
	},
	-- Cidade Baixa: 1 subzones
	[1458] = {
		["ruins of lordaeron"] = {
			name = "Ruínas de Lordaeron",
			short = "Acima da cidade soterrada, o palácio de Lordaeron ainda está de pé, com seus salões abertos para o céu e seus jardins em ruínas. Aqui morreu o grande reino da Aliança, e aqui seus fantasmas nunca partiram de todo.",
			full = "Acima da cidade soterrada, o palácio de Lordaeron ainda está de pé, com seus salões abertos para o céu e seus jardins em ruínas. Aqui morreu o grande reino da Aliança, e aqui seus fantasmas nunca partiram de todo.\n\nFoi Arthas Menethil quem pôs fim a ele. O príncipe voltou para casa à frente de um exército erguido contra seu próprio povo, recebido por estes portões com sinos e aplausos antes que alguém entendesse no que ele havia se transformado. Encontrou seu pai, o Rei Terenas, à sua espera na sala do trono e o matou ali mesmo. De pé sobre o corpo, pronunciou palavras que ainda ecoam naquela sala para quem se demora ali: que o reino cairia e que, de suas cinzas, uma nova ordem surgiria para abalar o mundo. Não era bravata. Em poucos dias, a cidade e seu povo foram massacrados, e Lordaeron passou a pertencer ao Flagelo.\n\nDizem que quem ainda caminha pelo pátio pode ouvir o que a pedra se lembra: vozes abafadas, o repicar dos sinos de boas-vindas, um murmúrio vindo da sala do trono que nunca se apaga de todo. Os que conseguem ver além do véu dizem que os cidadãos de Lordaeron ainda caminham por ali, sem saber que seu reino já não existe.",
			source = "https://warcraft.wiki.gg/wiki/Ruins_of_Lordaeron",
		},
	},
}

